// Découpe sémantique intelligente préservant la structure du code

import type { ContextChunk, SemanticChunkingConfig } from '../types';

export class SemanticChunker {
  private config: SemanticChunkingConfig;

  constructor(config?: Partial<SemanticChunkingConfig>) {
    this.config = {
      maxChunkSize: 2000, // tokens
      minChunkSize: 100,
      preserveBoundaries: true,
      includeDependencies: true,
      maxDependencyDepth: 2,
      ...config,
    };
  }

  async chunk(
    content: string,
    filePath: string,
    language?: string
  ): Promise<ContextChunk[]> {
    const chunks: ContextChunk[] = [];

    // Détecte le langage si non fourni
    if (!language) {
      language = this.detectLanguage(filePath);
    }

    switch (language) {
      case 'typescript':
      case 'javascript':
        return this.chunkTypeScript(content, filePath);
      case 'python':
        return this.chunkPython(content, filePath);
      case 'rust':
        return this.chunkRust(content, filePath);
      default:
        return this.chunkGeneric(content, filePath, language);
    }
  }

  private detectLanguage(filePath: string): string {
    const ext = filePath.split('.').pop()?.toLowerCase();
    const languageMap: Record<string, string> = {
      ts: 'typescript',
      tsx: 'typescript',
      js: 'javascript',
      jsx: 'javascript',
      py: 'python',
      rs: 'rust',
      go: 'go',
      java: 'java',
      cpp: 'cpp',
      c: 'c',
    };
    return languageMap[ext || ''] || 'text';
  }

  private chunkTypeScript(content: string, filePath: string): ContextChunk[] {
    const chunks: ContextChunk[] = [];
    const lines = content.split('\n');
    const blockParser = new TypeScriptBlockParser();

    for (let i = 0; i < lines.length; i++) {
      const result = blockParser.parseLine(lines[i], i);

      if (result.shouldCreateChunk) {
        chunks.push(this.createChunk(result.lines, result.startLine, filePath, result.metadata));
      }
    }

    // Ajoute le dernier chunk si nécessaire
    if (blockParser.hasRemainingContent()) {
      const finalChunk = blockParser.getFinalChunk();
      chunks.push(this.createChunk(finalChunk.lines, finalChunk.startLine, filePath));
    }

    return chunks;
  }
}

/**
 * Helper class pour parser les blocs TypeScript
 */
class TypeScriptBlockParser {
  private currentChunk: string[] = [];
  private currentStartLine = 0;
  private inBlock = false;
  private blockType: 'function' | 'class' | 'interface' | 'type' | null = null;
  private blockName: string | null = null;
  private braceCount = 0;

  parseLine(line: string, lineNumber: number): {
    shouldCreateChunk: boolean;
    lines: string[];
    startLine: number;
    metadata?: any;
  } {
    const trimmed = line.trim();

    if (!this.inBlock) {
      this.detectBlockStart(trimmed, lineNumber);
    }

    this.currentChunk.push(line);
    this.updateBraceCount(line);

    if (this.shouldEndBlock(trimmed)) {
      return this.createChunkResult();
    }

    return { shouldCreateChunk: false, lines: [], startLine: 0 };
  }

  private detectBlockStart(trimmed: string, lineNumber: number): void {
    const patterns = {
      function: /(?:export\s+)?(?:async\s+)?function\s+(\w+)/,
      class: /(?:export\s+)?class\s+(\w+)/,
      interface: /(?:export\s+)?interface\s+(\w+)/,
      type: /(?:export\s+)?type\s+(\w+)/
    };

    for (const [type, pattern] of Object.entries(patterns)) {
      const match = trimmed.match(pattern);
      if (match) {
        this.startNewBlock(type as any, match[1], lineNumber);
        break;
      }
    }
  }

  private startNewBlock(type: 'function' | 'class' | 'interface' | 'type', name: string, lineNumber: number): void {
    if (this.currentChunk.length > 0) {
      // Will be handled by caller
    }
    this.blockType = type;
    this.blockName = name;
    this.currentStartLine = lineNumber;
    this.inBlock = true;
  }

  private updateBraceCount(line: string): void {
    if (this.inBlock) {
      for (const char of line) {
        if (char === '{') this.braceCount++;
        if (char === '}') this.braceCount--;
      }
    }
  }

  private shouldEndBlock(trimmed: string): boolean {
    return this.inBlock && this.braceCount === 0 && trimmed.includes('}');
  }

  private createChunkResult(): {
    shouldCreateChunk: boolean;
    lines: string[];
    startLine: number;
    metadata?: any;
  } {
    const result = {
      shouldCreateChunk: true,
      lines: [...this.currentChunk],
      startLine: this.currentStartLine,
      metadata: {
        functionName: this.blockType === 'function' ? this.blockName : undefined,
        className: this.blockType === 'class' ? this.blockName : undefined,
      }
    };

    this.resetBlock();
    return result;
  }

  private resetBlock(): void {
    this.currentChunk = [];
    this.inBlock = false;
    this.blockType = null;
    this.blockName = null;
    this.braceCount = 0;
  }

  hasRemainingContent(): boolean {
    return this.currentChunk.length > 0;
  }

  getFinalChunk(): { lines: string[]; startLine: number } {
    return {
      lines: this.currentChunk,
      startLine: this.currentStartLine
    };
  }
