          inBlock = true;
        }
      }

      currentChunk.push(line);

      // Compte les accolades pour détecter la fin du bloc
      if (inBlock) {
        for (const char of line) {
          if (char === '{') braceCount++;
          if (char === '}') braceCount--;
        }

        if (braceCount === 0 && trimmed.includes('}')) {
          // Fin du bloc
          chunks.push(
            this.createChunk(currentChunk, currentStartLine, filePath, {
              functionName: blockType === 'function' ? blockName : undefined,
              className: blockType === 'class' ? blockName : undefined,
            })
          );
          currentChunk = [];
          inBlock = false;
          blockType = null;
          blockName = null;
          currentStartLine = i + 1;
        }
      }

      // Crée un chunk si on atteint la taille max
      const chunkContent = currentChunk.join('\n');
      if (
        this.estimateTokens(chunkContent) >= this.config.maxChunkSize &&
        !inBlock
      ) {
        if (currentChunk.length > 0) {
          chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
          currentChunk = [];
          currentStartLine = i + 1;
        }
      }
    }

    // Ajoute le dernier chunk
    if (currentChunk.length > 0) {
      chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
    }

    return chunks;
  }

  private chunkPython(content: string, filePath: string): ContextChunk[] {
    const chunks: ContextChunk[] = [];
    const lines = content.split('\n');
    let currentChunk: string[] = [];
    let currentStartLine = 0;
    let inBlock = false;
    let blockType: 'function' | 'class' | null = null;
    let blockName: string | null = null;
    let indentLevel = 0;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trim();

      // Détecte le début d'un bloc
      if (!inBlock) {
        const functionMatch = trimmed.match(/^def\s+(\w+)/);
        const classMatch = trimmed.match(/^class\s+(\w+)/);

        if (functionMatch) {
          if (currentChunk.length > 0) {
            chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
            currentChunk = [];
          }
          blockType = 'function';
          blockName = functionMatch[1];
          currentStartLine = i;
          inBlock = true;
          indentLevel = line.search(/\S/);
        } else if (classMatch) {
          if (currentChunk.length > 0) {
            chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
            currentChunk = [];
          }
          blockType = 'class';
          blockName = classMatch[1];
          currentStartLine = i;
          inBlock = true;
          indentLevel = line.search(/\S/);
        }
      }

      currentChunk.push(line);

      // Détecte la fin du bloc (retour au niveau d'indentation initial)
      if (inBlock && trimmed && line.search(/\S/) <= indentLevel && i > currentStartLine) {
        currentChunk.pop(); // Retire la ligne qui appartient au prochain bloc
        chunks.push(
          this.createChunk(currentChunk, currentStartLine, filePath, {
            functionName: blockType === 'function' ? blockName : undefined,
            className: blockType === 'class' ? blockName : undefined,
          })
        );
        currentChunk = [line];
        inBlock = false;
        blockType = null;
        blockName = null;
        currentStartLine = i;
      }
    }

    // Ajoute le dernier chunk
    if (currentChunk.length > 0) {
      chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
    }

    return chunks;
  }

  private chunkRust(content: string, filePath: string): ContextChunk[] {
    const chunks: ContextChunk[] = [];
    const lines = content.split('\n');
    let currentChunk: string[] = [];
    let currentStartLine = 0;
    let inBlock = false;
    let blockName: string | null = null;
    let braceCount = 0;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trim();

      if (!inBlock) {
        const fnMatch = trimmed.match(/(?:pub\s+)?fn\s+(\w+)/);
        const structMatch = trimmed.match(/(?:pub\s+)?struct\s+(\w+)/);
        const implMatch = trimmed.match(/impl(?:<[^>]+>)?\s+(\w+)/);

        if (fnMatch || structMatch || implMatch) {
          if (currentChunk.length > 0) {
            chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
            currentChunk = [];
          }
          blockName = (fnMatch || structMatch || implMatch)![1];
          currentStartLine = i;
          inBlock = true;
        }
      }

      currentChunk.push(line);

      if (inBlock) {
        for (const char of line) {
          if (char === '{') braceCount++;
          if (char === '}') braceCount--;
        }

        if (braceCount === 0 && trimmed.includes('}')) {
          chunks.push(
            this.createChunk(currentChunk, currentStartLine, filePath, {
              functionName: blockName || undefined,
            })
          );
          currentChunk = [];
          inBlock = false;
          blockName = null;
          currentStartLine = i + 1;
        }
      }
    }

    if (currentChunk.length > 0) {
      chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
    }

    return chunks;
  }

  private chunkGeneric(
    content: string,
    filePath: string,
    language: string
  ): ContextChunk[] {
    const chunks: ContextChunk[] = [];
    const lines = content.split('\n');
    const targetSize = this.config.maxChunkSize;
    let currentChunk: string[] = [];
    let currentStartLine = 0;

    for (let i = 0; i < lines.length; i++) {
      currentChunk.push(lines[i]);

      const chunkContent = currentChunk.join('\n');
      if (this.estimateTokens(chunkContent) >= targetSize) {
        chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
        currentChunk = [];
        currentStartLine = i + 1;
      }
    }

    if (currentChunk.length > 0) {
      chunks.push(this.createChunk(currentChunk, currentStartLine, filePath));
    }

    return chunks;
  }

  private createChunk(
    lines: string[],
    startLine: number,
    filePath: string,
    metadata?: { functionName?: string; className?: string }
  ): ContextChunk {
    const content = lines.join('\n');
    const tokens = this.estimateTokens(content);

    return {
      id: `${filePath}:${startLine}`,
      content,
      tokens,
      type: 'code',
      metadata: {
        filePath,
        startLine,
        endLine: startLine + lines.length - 1,
        functionName: metadata?.functionName,
        className: metadata?.className,
        lastModified: new Date(),
        importance: 0.5,
      },
    };
  }

  private estimateTokens(content: string): number {
    return Math.ceil(content.length / 4);
  }

  buildDependencyGraph(chunks: ContextChunk[]): Map<string, Set<string>> {
    const graph = new Map<string, Set<string>>();

    for (const chunk of chunks) {
      graph.set(chunk.id, new Set());

      // Analyse les imports/dépendances dans le contenu
      const imports = this.extractImports(chunk.content);
      const references = this.extractReferences(chunk.content);

      for (const other of chunks) {
        if (other.id === chunk.id) continue;

        // Vérifie si ce chunk référence l'autre
        if (
          other.metadata.functionName &&
          references.has(other.metadata.functionName)
        ) {
          graph.get(chunk.id)!.add(other.id);
        }
        if (
          other.metadata.className &&
          references.has(other.metadata.className)
        ) {
          graph.get(chunk.id)!.add(other.id);
        }
      }
    }

    return graph;
  }

  private extractImports(content: string): Set<string> {
    const imports = new Set<string>();
    const importRegex = /import\s+.*?from\s+['"]([^'"]+)['"]/g;
    let match;

    while ((match = importRegex.exec(content)) !== null) {
      imports.add(match[1]);
    }

    return imports;
  }

  private extractReferences(content: string): Set<string> {
    const references = new Set<string>();
    // Capture les identifiants (fonctions, classes, variables)
    const identifierRegex = /\b([A-Z][a-zA-Z0-9]*|[a-z][a-zA-Z0-9]*)\b/g;
    let match;

    while ((match = identifierRegex.exec(content)) !== null) {
      references.add(match[1]);
    }

    return references;
  }
}

