export class GrokProvider extends AIProvider {
  readonly id = 'grok';
  readonly name = 'Grok';
  private baseUrl: string;
  private maxRetries: number;
  private retryDelay: number;

  constructor(config: ProviderConfig) {
    super(config);
    if (!config.apiKey) {
      throw new Error('Grok API key is required');
    }
    this.baseUrl = config.baseUrl || 'https://api.openlux.ai/v1';
    this.maxRetries = config.maxRetries || 3;
    this.retryDelay = config.retryDelay || 1000;
  }

  private async fetchWithRetry(url: string, options: RequestInit, attempt = 1): Promise<Response> {
    try {
      const response = await fetch(url, options);

      // Retry on 5xx errors or 429 (rate limit)
      if ((response.status >= 500 || response.status === 429) && attempt < this.maxRetries) {
        const delay = this.retryDelay * Math.pow(2, attempt - 1); // Exponential backoff
        await new Promise(resolve => setTimeout(resolve, delay));
        return this.fetchWithRetry(url, options, attempt + 1);
      }

      return response;
    } catch (error) {
      if (attempt < this.maxRetries) {
        const delay = this.retryDelay * Math.pow(2, attempt - 1);
        await new Promise(resolve => setTimeout(resolve, delay));
        return this.fetchWithRetry(url, options, attempt + 1);
      }
      throw error;
    }
  }

  async chat(messages: Message[], options?: ChatOptions): Promise<ChatResponse> {
    try {
      const response = await this.fetchWithRetry(`${this.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${this.config.apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: options?.model || this.config.defaultModel || 'claude-opus-5:stable',
          messages: messages as GrokMessage[],
          temperature: options?.temperature,
          max_tokens: options?.maxTokens,
          top_p: options?.topP,
          stop: options?.stop,
        }),
      });

      if (!response.ok) {
        const error: any = await response.json().catch(() => ({ 
          error: { message: response.statusText } 
        }));
        throw new Error(error.error?.message || error.error || 'Request failed');
      }

      const data: GrokResponse = await response.json() as GrokResponse;
      const choice = data.choices[0];

      return {
        content: choice.message.content || '',
        model: data.model,
        usage: {
          inputTokens: data.usage.prompt_tokens,
          outputTokens: data.usage.completion_tokens,
          totalTokens: data.usage.total_tokens,
        },
        finishReason: choice.finish_reason || undefined,
      };
    } catch (error) {
      this.handleError(error, 'chat failed');
    }
  }

  async *stream(messages: Message[], options?: ChatOptions): AsyncIterableIterator<StreamChunk> {
    try {
      const response = await this.fetchWithRetry(`${this.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${this.config.apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: options?.model || this.config.defaultModel || 'claude-opus-5:stable',
          messages: messages as GrokMessage[],
          temperature: options?.temperature,
          max_tokens: options?.maxTokens,
          top_p: options?.topP,
          stop: options?.stop,
          stream: true,
        }),
      });

      if (!response.ok) {
        const error: any = await response.json().catch(() => ({ 
          error: { message: response.statusText } 
        }));
        throw new Error(error.error?.message || error.error || 'Request failed');
      }

      if (!response.body) {
        throw new Error('Response body is null');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6);
            if (data === '[DONE]') {
              yield { content: '', done: true };
              return;
            }

            try {
              const parsed: GrokStreamChunk = JSON.parse(data);
              const delta = parsed.choices[0]?.delta;
              const content = delta?.content || '';
              const done = parsed.choices[0]?.finish_reason !== null;

              if (content || done) {
                yield { content, done };
              }
            } catch {
              // Ignorer les lignes mal formées
            }
          }
        }
      }
    } catch (error) {
      this.handleError(error, 'stream failed');
    }
  }

  async isAvailable(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/models`, {
        headers: {
          'Authorization': `Bearer ${this.config.apiKey}`,
        },
      });
      return response.ok;
    } catch {
      return false;
    }
  }
}

