  private baseUrl: string;

  constructor(config: ProviderConfig) {
    super(config);
    this.baseUrl = config.baseUrl || 'http://localhost:11434';
  }

  async chat(messages: Message[], options?: ChatOptions): Promise<ChatResponse> {
    try {
      const response = await fetch(`${this.baseUrl}/api/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: options?.model || this.config.defaultModel || 'llama3.1',
          messages: messages as OllamaMessage[],
          options: {
            temperature: options?.temperature,
            num_predict: options?.maxTokens,
            top_p: options?.topP,
            stop: options?.stop,
          },
          stream: false,
        }),
      });

      if (!response.ok) {
        const error: any = await response.json().catch(() => ({ error: response.statusText }));
        throw new Error(error.error || 'Request failed');
      }

      const data: OllamaResponse = await response.json() as OllamaResponse;

      return {
        content: data.message.content,
        model: data.model,
        usage: {
          inputTokens: data.prompt_eval_count || 0,
          outputTokens: data.eval_count || 0,
          totalTokens: (data.prompt_eval_count || 0) + (data.eval_count || 0),
        },
        finishReason: data.done ? 'stop' : undefined,
      };
    } catch (error) {
      this.handleError(error, 'chat failed');
    }
  }

  async *stream(messages: Message[], options?: ChatOptions): AsyncIterableIterator<StreamChunk> {
    try {
      const response = await fetch(`${this.baseUrl}/api/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model: options?.model || this.config.defaultModel || 'llama3.1',
          messages: messages as OllamaMessage[],
          options: {
            temperature: options?.temperature,
            num_predict: options?.maxTokens,
            top_p: options?.topP,
            stop: options?.stop,
          },
          stream: true,
        }),
      });

      if (!response.ok) {
        const error: any = await response.json().catch(() => ({ error: response.statusText }));
        throw new Error(error.error || 'Request failed');
      }

      if (!response.body) {
        throw new Error('Response body is null');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.trim()) {
            try {
              const parsed: OllamaStreamChunk = JSON.parse(line);
              const content = parsed.message?.content || '';

              yield { content, done: parsed.done };

              if (parsed.done) {
                return;
              }
            } catch {
              // Ignorer les lignes mal formées
            }
          }
        }
      }
    } catch (error) {
      this.handleError(error, 'stream failed');
    }
  }

  async isAvailable(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/api/tags`);
      return response.ok;
    } catch {
      return false;
    }
  }
}

