    const session: AgentSession = {
      id,
      messages,
      status: 'active',
      provider: config.provider,
      model: config.model,
      temperature: config.temperature,
      maxTokens: config.maxTokens,
      createdAt: new Date(),
      updatedAt: new Date(),
      metadata: config.metadata,
    };

