        if (chunk.done) {
          finishReason = 'stop';
        }
      }

      // Add assistant response to history
      if (fullContent) {
        const assistantMessage: Message = {
          role: 'assistant',
          content: fullContent,
        };
        session.messages.push(assistantMessage);
