function createBetterSqlite3Adapter(db: any): DatabaseAdapter {
  return {
    prepare(sql: string): StatementAdapter {
      const stmt = db.prepare(sql);
      return {
        run(...params: any[]) {
          return stmt.run(...params);
        },
        get(...params: any[]) {
          return stmt.get(...params);
        },
        all(...params: any[]) {
          return stmt.all(...params);
        },
      };
    },
    exec(sql: string) {
      db.exec(sql);
    },
    pragma(pragma: string, options?: { simple?: boolean }) {
      return db.pragma(pragma, options);
    },
    close() {
      db.close();
    },
    get open() {
      return db.open;
    },
    transaction<T>(fn: () => T): () => T {
      return db.transaction(fn);
    },
  };
}

/**
 * Database error handling utilities
 * Provides robust error handling for database operations
 */

import type { DatabaseAdapter } from './adapter.js';

export class DatabaseError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly originalError?: unknown
  ) {
    super(message);
    this.name = 'DatabaseError';
  }
}

export class DatabaseConnectionError extends DatabaseError {
  constructor(message: string, originalError?: unknown) {
    super(message, 'DB_CONNECTION_ERROR', originalError);
    this.name = 'DatabaseConnectionError';
  }
}

export class DatabaseConstraintError extends DatabaseError {
  constructor(message: string, originalError?: unknown) {
    super(message, 'DB_CONSTRAINT_ERROR', originalError);
    this.name = 'DatabaseConstraintError';
  }
}

export class DatabaseNotFoundError extends DatabaseError {
  constructor(message: string, originalError?: unknown) {
    super(message, 'DB_NOT_FOUND', originalError);
    this.name = 'DatabaseNotFoundError';
  }
}

export class DatabaseMigrationError extends DatabaseError {
  constructor(message: string, originalError?: unknown) {
    super(message, 'DB_MIGRATION_ERROR', originalError);
    this.name = 'DatabaseMigrationError';
  }
}

/**
 * Wrap database operations with error handling
 */
export function wrapDatabaseOperation<T>(
  operation: () => T,
  context: string
): T {
  try {
    return operation();
  } catch (error) {
    throw handleDatabaseError(error, context);
  }
}

/**
 * Wrap async database operations with error handling
 */
export async function wrapAsyncDatabaseOperation<T>(
  operation: () => Promise<T>,
  context: string
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    throw handleDatabaseError(error, context);
  }
}

/**
 * Handle and classify database errors
 */
export function handleDatabaseError(error: unknown, context: string): DatabaseError {
  if (error instanceof DatabaseError) {
    return error;
  }

  if (error instanceof Error) {
    const message = error.message.toLowerCase();

    // SQLite constraint errors
    if (
      message.includes('unique constraint') ||
      message.includes('foreign key constraint') ||
      message.includes('check constraint') ||
      message.includes('not null constraint')
    ) {
      return new DatabaseConstraintError(
        `${context}: Constraint violation - ${error.message}`,
        error
      );
    }

    // Connection errors
    if (
      message.includes('database is locked') ||
      message.includes('unable to open database') ||
      message.includes('database disk image is malformed')
    ) {
      return new DatabaseConnectionError(
        `${context}: Connection error - ${error.message}`,
        error
      );
    }

    // Not found errors
    if (message.includes('no such table') || message.includes('no such column')) {
      return new DatabaseNotFoundError(
        `${context}: Schema error - ${error.message}`,
        error
      );
    }

    // Generic error
    return new DatabaseError(
      `${context}: ${error.message}`,
      'DB_ERROR',
      error
    );
  }

  // Unknown error type
  return new DatabaseError(
    `${context}: Unknown error occurred`,
    'DB_UNKNOWN_ERROR',
    error
  );
}

/**
 * Validate database connection
 */
export function validateDatabaseConnection(db: DatabaseAdapter): void {
  try {
    db.prepare('SELECT 1').get();
  } catch (error) {
    throw new DatabaseConnectionError(
      'Failed to validate database connection',
      error
    );
  }
}

/**
 * Check if database file is corrupted
 */
export function checkDatabaseIntegrity(db: DatabaseAdapter): {
  ok: boolean;
  errors: string[];
} {
  try {
    const result = db.pragma('integrity_check') as Array<{ integrity_check: string }>;
    const errors = result
      .filter(row => row.integrity_check !== 'ok')
      .map(row => row.integrity_check);

    return {
      ok: errors.length === 0,
      errors,
    };
  } catch (error) {
    return {
      ok: false,
      errors: ['Failed to check integrity: ' + (error instanceof Error ? error.message : 'Unknown error')],
    };
  }
}

/**
 * Safely close database connection
 */
export function closeDatabaseSafely(db: DatabaseAdapter): void {
  try {
    if (db.open) {
      // Checkpoint WAL file
      db.pragma('wal_checkpoint(TRUNCATE)');
      db.close();
    }
  } catch (error) {
    console.error('Error closing database:', error);
  }
}

/**
 * Create a transaction wrapper with error handling
 */
export function createTransaction<T>(
  db: DatabaseAdapter,
  fn: () => T
): () => T {
  return db.transaction(() => {
    try {
      return fn();
    } catch (error) {
      throw handleDatabaseError(error, 'Transaction failed');
    }
  });
}

/**
 * Database usage example
 * Demonstrates how to use the database layer in Cortex IDE
 */

import { DatabaseManager } from './index.js';
import { join } from 'node:path';
import { homedir } from 'node:os';

async function main() {
  console.log('Cortex IDE Database Example');
  console.log('='.repeat(60));

  // Initialize database
  const dbPath = join(homedir(), '.cortex-ide', 'cortex-ide.db');
  console.log('\n📦 Initializing database at:', dbPath);

  const db = await DatabaseManager.create(dbPath);
  await db.initialize();

  console.log('✓ Database ready\n');

  // Create a workspace
  console.log('1️⃣ Creating workspace...');
  const workspace = db.createWorkspace({
    name: 'Example Project',
    path: join(homedir(), 'projects', 'example'),
    settings: {
      theme: 'dark',
      editor: {
        fontSize: 14,
        tabSize: 2,
        wordWrap: true,
      },
      git: {
        autoFetch: true,
        defaultBranch: 'main',
      },
    },
  });
  console.log(`   ✓ Created workspace: ${workspace.name}`);

  // Create a session
  console.log('\n2️⃣ Creating AI session...');
  const session = db.createSession({
    workspace_id: workspace.id,
    title: 'Build authentication system',
    model: 'gpt-4',
    metadata: {
      provider: 'openai',
      temperature: 0.7,
      maxTokens: 4000,
    },
  });
  console.log(`   ✓ Created session: ${session.title}`);

  // Add messages to session
  console.log('\n3️⃣ Adding messages...');
  const userMsg = db.createMessage({
    session_id: session.id,
    role: 'user',
    content: 'How do I implement JWT authentication in Express.js?',
  });
  console.log(`   ✓ User message: ${userMsg.content.substring(0, 50)}...`);

  const assistantMsg = db.createMessage({
    session_id: session.id,
    role: 'assistant',
    content: 'To implement JWT authentication in Express.js, you need to...',
    metadata: {
      tokens: {
        input: 18,
        output: 245,
      },
    },
  });
  console.log(`   ✓ Assistant message: ${assistantMsg.content.substring(0, 50)}...`);

  // Track usage
  console.log('\n4️⃣ Logging usage...');
  const usageLog = db.createUsageLog({
    session_id: session.id,
    provider: 'openai',
    model: 'gpt-4',
    tokens_input: 18,
    tokens_output: 245,
    cost: 0.0079,
  });
  console.log(`   ✓ Logged usage: $${usageLog.cost?.toFixed(4)}`);

  // Create a mission
  console.log('\n5️⃣ Creating mission...');
  const mission = db.createMission({
    workspace_id: workspace.id,
    status: 'running',
    state: {
      name: 'Implement JWT Authentication',
      description: 'Add JWT-based authentication to the Express API',
      steps: [
        {
          id: 'step-1',
          name: 'Install dependencies (jsonwebtoken, bcrypt)',
          status: 'completed',
          startedAt: Date.now() - 300000,
          completedAt: Date.now() - 240000,
        },
        {
          id: 'step-2',
          name: 'Create auth middleware',
          status: 'running',
          startedAt: Date.now() - 60000,
        },
        {
          id: 'step-3',
          name: 'Add login/register routes',
          status: 'pending',
        },
      ],
      currentStep: 1,
    },
  });
  console.log(`   ✓ Mission started: ${mission.state.name}`);

  // Create an automation
  console.log('\n6️⃣ Creating automation...');
  const automation = db.createAutomation({
    workspace_id: workspace.id,
    name: 'Auto-format TypeScript files',
    enabled: true,
    trigger: {
      type: 'file_watch',
      config: {
        pattern: '**/*.ts',
        event: 'save',
      },
    },
    actions: [
      {
        type: 'run_script',
        config: {
          command: 'prettier --write',
        },
      },
    ],
  });
  console.log(`   ✓ Automation created: ${automation.name}`);

  // Query data
  console.log('\n7️⃣ Querying database...');
  const allWorkspaces = db.listWorkspaces();
  const allSessions = db.listSessions(workspace.id);
  const messages = db.listMessages(session.id);
  const missions = db.listMissions(workspace.id, 'running');
  const automations = db.listAutomations(workspace.id, true);

  console.log(`   ✓ Workspaces: ${allWorkspaces.length}`);
  console.log(`   ✓ Sessions: ${allSessions.length}`);
  console.log(`   ✓ Messages: ${messages.length}`);
  console.log(`   ✓ Running missions: ${missions.length}`);
  console.log(`   ✓ Enabled automations: ${automations.length}`);

  // Get usage statistics
  console.log('\n8️⃣ Usage statistics...');
  const stats = db.getUsageStats();
  console.log(`   ✓ Total tokens: ${stats.totalTokensInput + stats.totalTokensOutput}`);
  console.log(`   ✓ Total cost: $${stats.totalCost.toFixed(4)}`);
  console.log(`   ✓ Providers: ${Object.keys(stats.byProvider).join(', ')}`);

  // Update mission status
  console.log('\n9️⃣ Updating mission...');
  db.updateMission(mission.id, {
    status: 'running',
    state: {
      ...mission.state,
      currentStep: 2,
      steps: mission.state.steps?.map((step, i) =>
        i === 1
          ? { ...step, status: 'completed' as const, completedAt: Date.now() }
          : i === 2
          ? { ...step, status: 'running' as const, startedAt: Date.now() }
          : step
      ),
    },
  });
  console.log('   ✓ Mission updated to next step');

  // Close database
  console.log('\n🔒 Closing database connection...');
  db.close();
  console.log('   ✓ Database closed');

  console.log('\n' + '='.repeat(60));
  console.log('✓ Example completed successfully!');
  console.log('='.repeat(60));
}

main().catch((error) => {
  console.error('Error:', error);
  process.exit(1);
});

/**
 * Database manager for Cortex IDE
 * Provides CRUD operations for all database entities
 */

import { randomUUID } from 'node:crypto';
import { createDatabaseAdapter, type DatabaseAdapter } from './adapter.js';
import { MigrationManager } from './migration-manager.js';
import type {
  Workspace,
  WorkspaceRow,
  Session,
  SessionRow,
  Message,
  MessageRow,
  Mission,
  MissionRow,
  UsageLog,
  UsageLogRow,
  Automation,
  AutomationRow,
} from './types.js';

export class DatabaseManager {
  private db: DatabaseAdapter;
  private migrationManager: MigrationManager;
  private initialized: boolean = false;

  private constructor(db: DatabaseAdapter) {
    this.db = db;

    // Enable WAL mode for better concurrency
    this.db.pragma('journal_mode = WAL');
    this.db.pragma('foreign_keys = ON');

    this.migrationManager = new MigrationManager(this.db);
  }

  /**
   * Create a new database manager instance
   */
  static async create(dbPath: string): Promise<DatabaseManager> {
    const db = await createDatabaseAdapter(dbPath);
    return new DatabaseManager(db);
  }

  /**
   * Initialize database and run migrations
   */
  async initialize(): Promise<void> {
    if (this.initialized) return;
    await this.migrationManager.migrate();
    this.initialized = true;
  }

  /**
   * Close database connection
   */
  close(): void {
    this.db.close();
  }

  /**
   * Get database instance (for advanced operations)
   */
  getDb(): DatabaseAdapter {
    return this.db;
  }

  /**
   * Get migration manager
   */
  getMigrationManager(): MigrationManager {
    return this.migrationManager;
  }

  // ============================================================================
  // WORKSPACE METHODS
  // ============================================================================

  createWorkspace(data: Omit<Workspace, 'id' | 'created_at' | 'updated_at'>): Workspace {
    const now = Date.now();
    const workspace: Workspace = {
      id: randomUUID(),
      ...data,
      created_at: now,
      updated_at: now,
    };

    this.db
      .prepare(
        `INSERT INTO workspaces (id, name, path, created_at, updated_at, settings)
         VALUES (?, ?, ?, ?, ?, ?)`
      )
      .run(
        workspace.id,
        workspace.name,
        workspace.path,
        workspace.created_at,
        workspace.updated_at,
        workspace.settings ? JSON.stringify(workspace.settings) : null
      );

    return workspace;
  }

  getWorkspace(id: string): Workspace | null {
    const row = this.db
      .prepare('SELECT * FROM workspaces WHERE id = ?')
      .get(id) as WorkspaceRow | undefined;

    return row ? this.deserializeWorkspace(row) : null;
  }

  getWorkspaceByPath(path: string): Workspace | null {
    const row = this.db
      .prepare('SELECT * FROM workspaces WHERE path = ?')
      .get(path) as WorkspaceRow | undefined;

    return row ? this.deserializeWorkspace(row) : null;
  }

  listWorkspaces(): Workspace[] {
    const rows = this.db
      .prepare('SELECT * FROM workspaces ORDER BY updated_at DESC')
      .all() as WorkspaceRow[];

    return rows.map(row => this.deserializeWorkspace(row));
  }

  updateWorkspace(id: string, data: Partial<Omit<Workspace, 'id' | 'created_at'>>): void {
    const updates: string[] = [];
    const values: any[] = [];

    if (data.name !== undefined) {
      updates.push('name = ?');
      values.push(data.name);
    }
    if (data.path !== undefined) {
      updates.push('path = ?');
      values.push(data.path);
    }
    if (data.settings !== undefined) {
      updates.push('settings = ?');
      values.push(JSON.stringify(data.settings));
    }

    updates.push('updated_at = ?');
    values.push(Date.now());

    values.push(id);

    this.db
      .prepare(`UPDATE workspaces SET ${updates.join(', ')} WHERE id = ?`)
      .run(...values);
  }

  deleteWorkspace(id: string): void {
    this.db.prepare('DELETE FROM workspaces WHERE id = ?').run(id);
  }

  // ============================================================================
  // SESSION METHODS
  // ============================================================================

  createSession(data: Omit<Session, 'id' | 'created_at' | 'updated_at'>): Session {
    const now = Date.now();
    const session: Session = {
      id: randomUUID(),
      ...data,
      created_at: now,
      updated_at: now,
    };

    this.db
      .prepare(
        `INSERT INTO sessions (id, workspace_id, title, model, created_at, updated_at, metadata)
         VALUES (?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        session.id,
        session.workspace_id,
        session.title,
        session.model,
        session.created_at,
        session.updated_at,
        session.metadata ? JSON.stringify(session.metadata) : null
      );

    return session;
  }

  getSession(id: string): Session | null {
    const row = this.db
      .prepare('SELECT * FROM sessions WHERE id = ?')
      .get(id) as SessionRow | undefined;

    return row ? this.deserializeSession(row) : null;
  }

  listSessions(workspaceId?: string): Session[] {
    let query = 'SELECT * FROM sessions';
    const params: any[] = [];

    if (workspaceId) {
      query += ' WHERE workspace_id = ?';
      params.push(workspaceId);
    }

    query += ' ORDER BY updated_at DESC';

    const rows = this.db.prepare(query).all(...params) as SessionRow[];
    return rows.map(row => this.deserializeSession(row));
  }

  updateSession(id: string, data: Partial<Omit<Session, 'id' | 'created_at'>>): void {
    const updates: string[] = [];
    const values: any[] = [];

    if (data.title !== undefined) {
      updates.push('title = ?');
      values.push(data.title);
    }
    if (data.model !== undefined) {
      updates.push('model = ?');
      values.push(data.model);
    }
    if (data.metadata !== undefined) {
      updates.push('metadata = ?');
      values.push(JSON.stringify(data.metadata));
    }

    updates.push('updated_at = ?');
    values.push(Date.now());

    values.push(id);

    this.db
      .prepare(`UPDATE sessions SET ${updates.join(', ')} WHERE id = ?`)
      .run(...values);
  }

  deleteSession(id: string): void {
    this.db.prepare('DELETE FROM sessions WHERE id = ?').run(id);
  }

  // ============================================================================
  // MESSAGE METHODS
  // ============================================================================

  createMessage(data: Omit<Message, 'id' | 'created_at'>): Message {
    const message: Message = {
      id: randomUUID(),
      ...data,
      created_at: Date.now(),
    };

    this.db
      .prepare(
        `INSERT INTO messages (id, session_id, role, content, created_at, metadata)
         VALUES (?, ?, ?, ?, ?, ?)`
      )
      .run(
        message.id,
        message.session_id,
        message.role,
        message.content,
        message.created_at,
        message.metadata ? JSON.stringify(message.metadata) : null
      );

    return message;
  }

  getMessage(id: string): Message | null {
    const row = this.db
      .prepare('SELECT * FROM messages WHERE id = ?')
      .get(id) as MessageRow | undefined;

    return row ? this.deserializeMessage(row) : null;
  }

  listMessages(sessionId: string): Message[] {
    const rows = this.db
      .prepare('SELECT * FROM messages WHERE session_id = ? ORDER BY created_at ASC')
      .all(sessionId) as MessageRow[];

    return rows.map(row => this.deserializeMessage(row));
  }

  deleteMessage(id: string): void {
    this.db.prepare('DELETE FROM messages WHERE id = ?').run(id);
  }

  // ============================================================================
  // MISSION METHODS
  // ============================================================================

  createMission(data: Omit<Mission, 'id' | 'created_at' | 'updated_at'>): Mission {
    const now = Date.now();
    const mission: Mission = {
      id: randomUUID(),
      ...data,
      created_at: now,
      updated_at: now,
    };

    this.db
      .prepare(
        `INSERT INTO missions (id, workspace_id, status, created_at, updated_at, state)
         VALUES (?, ?, ?, ?, ?, ?)`
      )
      .run(
        mission.id,
        mission.workspace_id,
        mission.status,
        mission.created_at,
        mission.updated_at,
        JSON.stringify(mission.state)
      );

    return mission;
  }

  getMission(id: string): Mission | null {
    const row = this.db
      .prepare('SELECT * FROM missions WHERE id = ?')
      .get(id) as MissionRow | undefined;

    return row ? this.deserializeMission(row) : null;
  }

  listMissions(workspaceId?: string, status?: Mission['status']): Mission[] {
    let query = 'SELECT * FROM missions WHERE 1=1';
    const params: any[] = [];

    if (workspaceId) {
      query += ' AND workspace_id = ?';
      params.push(workspaceId);
    }

    if (status) {
      query += ' AND status = ?';
      params.push(status);
    }

    query += ' ORDER BY updated_at DESC';

    const rows = this.db.prepare(query).all(...params) as MissionRow[];
    return rows.map(row => this.deserializeMission(row));
  }

  updateMission(id: string, data: Partial<Omit<Mission, 'id' | 'created_at'>>): void {
    const updates: string[] = [];
    const values: any[] = [];

    if (data.status !== undefined) {
      updates.push('status = ?');
      values.push(data.status);
    }
    if (data.state !== undefined) {
      updates.push('state = ?');
      values.push(JSON.stringify(data.state));
    }

    updates.push('updated_at = ?');
    values.push(Date.now());

    values.push(id);

    this.db
      .prepare(`UPDATE missions SET ${updates.join(', ')} WHERE id = ?`)
      .run(...values);
  }

  deleteMission(id: string): void {
    this.db.prepare('DELETE FROM missions WHERE id = ?').run(id);
  }

  // ============================================================================
  // USAGE LOG METHODS
  // ============================================================================

  createUsageLog(data: Omit<UsageLog, 'id' | 'created_at'>): UsageLog {
    const log: UsageLog = {
      id: randomUUID(),
      ...data,
      created_at: Date.now(),
    };

    this.db
      .prepare(
        `INSERT INTO usage_logs (id, session_id, provider, model, tokens_input, tokens_output, cost, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        log.id,
        log.session_id,
        log.provider,
        log.model,
        log.tokens_input,
        log.tokens_output,
        log.cost,
        log.created_at
      );

    return log;
  }

  listUsageLogs(sessionId?: string, provider?: string): UsageLog[] {
    let query = 'SELECT * FROM usage_logs WHERE 1=1';
    const params: any[] = [];

    if (sessionId) {
      query += ' AND session_id = ?';
      params.push(sessionId);
    }

    if (provider) {
      query += ' AND provider = ?';
      params.push(provider);
    }

    query += ' ORDER BY created_at DESC';

    const rows = this.db.prepare(query).all(...params) as UsageLogRow[];
    return rows.map(row => this.deserializeUsageLog(row));
  }

  getUsageStats(startDate?: number, endDate?: number): {
    totalTokensInput: number;
    totalTokensOutput: number;
    totalCost: number;
    byProvider: Record<string, { tokens_input: number; tokens_output: number; cost: number }>;
  } {
    let query = 'SELECT provider, SUM(tokens_input) as tokens_input, SUM(tokens_output) as tokens_output, SUM(cost) as cost FROM usage_logs WHERE 1=1';
    const params: any[] = [];

    if (startDate) {
      query += ' AND created_at >= ?';
      params.push(startDate);
    }

    if (endDate) {
      query += ' AND created_at <= ?';
      params.push(endDate);
    }

    query += ' GROUP BY provider';

    const rows = this.db.prepare(query).all(...params) as Array<{
      provider: string;
      tokens_input: number;
      tokens_output: number;
      cost: number;
    }>;

    const byProvider: Record<string, { tokens_input: number; tokens_output: number; cost: number }> = {};
    let totalTokensInput = 0;
    let totalTokensOutput = 0;
    let totalCost = 0;

    for (const row of rows) {
      byProvider[row.provider] = {
        tokens_input: row.tokens_input || 0,
        tokens_output: row.tokens_output || 0,
        cost: row.cost || 0,
      };
      totalTokensInput += row.tokens_input || 0;
      totalTokensOutput += row.tokens_output || 0;
      totalCost += row.cost || 0;
    }

    return {
      totalTokensInput,
      totalTokensOutput,
      totalCost,
      byProvider,
    };
  }

  // ============================================================================
  // AUTOMATION METHODS
  // ============================================================================

  createAutomation(data: Omit<Automation, 'id' | 'created_at' | 'updated_at'>): Automation {
    const now = Date.now();
    const automation: Automation = {
      id: randomUUID(),
      ...data,
      created_at: now,
      updated_at: now,
    };

    this.db
      .prepare(
        `INSERT INTO automations (id, workspace_id, name, enabled, trigger, actions, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      )
      .run(
        automation.id,
        automation.workspace_id,
        automation.name,
        automation.enabled ? 1 : 0,
        JSON.stringify(automation.trigger),
        JSON.stringify(automation.actions),
        automation.created_at,
        automation.updated_at
      );

    return automation;
  }

  getAutomation(id: string): Automation | null {
    const row = this.db
      .prepare('SELECT * FROM automations WHERE id = ?')
      .get(id) as AutomationRow | undefined;

    return row ? this.deserializeAutomation(row) : null;
  }

  listAutomations(workspaceId?: string, enabledOnly?: boolean): Automation[] {
    let query = 'SELECT * FROM automations WHERE 1=1';
    const params: any[] = [];

    if (workspaceId) {
      query += ' AND workspace_id = ?';
      params.push(workspaceId);
    }

    if (enabledOnly) {
      query += ' AND enabled = 1';
    }

    query += ' ORDER BY updated_at DESC';

    const rows = this.db.prepare(query).all(...params) as AutomationRow[];
    return rows.map(row => this.deserializeAutomation(row));
  }

  updateAutomation(id: string, data: Partial<Omit<Automation, 'id' | 'created_at'>>): void {
    const updates: string[] = [];
    const values: any[] = [];

    if (data.name !== undefined) {
      updates.push('name = ?');
      values.push(data.name);
    }
    if (data.enabled !== undefined) {
      updates.push('enabled = ?');
      values.push(data.enabled ? 1 : 0);
    }
    if (data.trigger !== undefined) {
      updates.push('trigger = ?');
      values.push(JSON.stringify(data.trigger));
    }
    if (data.actions !== undefined) {
      updates.push('actions = ?');
      values.push(JSON.stringify(data.actions));
    }

    updates.push('updated_at = ?');
    values.push(Date.now());

    values.push(id);

    this.db
      .prepare(`UPDATE automations SET ${updates.join(', ')} WHERE id = ?`)
      .run(...values);
  }

  deleteAutomation(id: string): void {
    this.db.prepare('DELETE FROM automations WHERE id = ?').run(id);
  }

  // ============================================================================
  // DESERIALIZATION HELPERS
  // ============================================================================

  private deserializeWorkspace(row: WorkspaceRow): Workspace {
    return {
      ...row,
      settings: row.settings ? JSON.parse(row.settings) : undefined,
    };
  }

  private deserializeSession(row: SessionRow): Session {
    return {
      ...row,
      metadata: row.metadata ? JSON.parse(row.metadata) : undefined,
    };
  }

  private deserializeMessage(row: MessageRow): Message {
    return {
      ...row,
      role: row.role as 'user' | 'assistant' | 'system',
      metadata: row.metadata ? JSON.parse(row.metadata) : undefined,
    };
  }

  private deserializeMission(row: MissionRow): Mission {
    return {
      ...row,
      status: row.status as Mission['status'],
      state: JSON.parse(row.state),
    };
  }

  private deserializeUsageLog(row: UsageLogRow): UsageLog {
    return row;
  }

  private deserializeAutomation(row: AutomationRow): Automation {
    return {
      ...row,
      enabled: row.enabled === 1,
      trigger: JSON.parse(row.trigger),
      actions: JSON.parse(row.actions),
    };
  }
}

