  handler: (request: TRequest, event: IpcMainInvokeEvent) => Promise<TResponse>
) {
  return async (event: IpcMainInvokeEvent, request: unknown): Promise<IPCResponse<TResponse>> => {
    try {
      // Validation Zod
      const validatedRequest = schema.parse(request);

      // Exécution du handler
      const data = await handler(validatedRequest, event);

      return { success: true, data };
    } catch (error) {
      // Gestion d'erreurs unifiée
      if (error instanceof z.ZodError) {
        return {
          success: false,
          error: {
            code: ErrorCode.VALIDATION_ERROR,
            message: 'Validation failed',
            details: error.issues,
          },
        };
      }

      if (error instanceof Error) {
        const code = getErrorCode(error);
        return {
          success: false,
          error: {
            code,
            message: error.message,
            details: { stack: error.stack },
          },
        };
      }

      return {
        success: false,
        error: {
          code: ErrorCode.UNKNOWN_ERROR,
          message: 'An unknown error occurred',
          details: error,
        },
      };
    }
  };
}

/**
 * Détermine le code d'erreur approprié
 */
function getErrorCode(error: Error): ErrorCode {
  const message = error.message.toLowerCase();

  if (message.includes('enoent') || message.includes('not found')) {
    return ErrorCode.FILE_NOT_FOUND;
  }

  if (message.includes('eacces') || message.includes('permission')) {
    return ErrorCode.PERMISSION_DENIED;
  }

  if (message.includes('git')) {
    return ErrorCode.GIT_ERROR;
  }

  if (message.includes('automation')) {
    return ErrorCode.AUTOMATION_ERROR;
  }

  return ErrorCode.UNKNOWN_ERROR;
}

/**
 * Détecte le langage d'un fichier par son extension
 */
function detectLanguage(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();

  const languageMap: Record<string, string> = {
    '.js': 'javascript',
    '.jsx': 'javascript',
    '.ts': 'typescript',
    '.tsx': 'typescript',
    '.py': 'python',
    '.rb': 'ruby',
    '.go': 'go',
    '.rs': 'rust',
    '.java': 'java',
    '.c': 'c',
    '.cpp': 'cpp',
    '.h': 'c',
    '.hpp': 'cpp',
    '.cs': 'csharp',
    '.php': 'php',
    '.html': 'html',
    '.css': 'css',
    '.scss': 'scss',
    '.sass': 'sass',
    '.json': 'json',
    '.xml': 'xml',
    '.yaml': 'yaml',
    '.yml': 'yaml',
    '.md': 'markdown',
    '.sh': 'shell',
    '.bash': 'shell',
    '.zsh': 'shell',
    '.sql': 'sql',
  };

  return languageMap[ext] || 'plaintext';
}

