const handleReadFile = createHandler<ReadFileRequest, ReadFileResponse>(
  ReadFileRequestSchema,
  async (request) => {
    const content = await fs.readFile(request.path, { encoding: request.encoding || 'utf-8' });
    const stats = await fs.stat(request.path);

    return {
      content,
      stats: {
        size: stats.size,
        mtime: stats.mtimeMs,
        ctime: stats.ctimeMs,
      },
    };
  }
);

const handleWriteFile = createHandler<WriteFileRequest, WriteFileResponse>(
  WriteFileRequestSchema,
  async (request) => {
    await fs.writeFile(request.path, request.content, { encoding: request.encoding || 'utf-8' });

    return {
      success: true,
      bytesWritten: Buffer.byteLength(request.content, request.encoding || 'utf-8'),
    };
  }
);

const handleReadDir = createHandler<ReadDirRequest, ReadDirResponse>(
  ReadDirRequestSchema,
  async (request) => {
    const entries: FileEntry[] = [];

    async function readDirectory(dirPath: string, recursive: boolean) {
      const items = await fs.readdir(dirPath, { withFileTypes: true });

      for (const item of items) {
        const fullPath = path.join(dirPath, item.name);
        const stats = await fs.stat(fullPath);

        entries.push({
          name: item.name,
          path: fullPath,
          type: item.isDirectory() ? 'directory' : item.isSymbolicLink() ? 'symlink' : 'file',
          size: stats.size,
          mtime: stats.mtimeMs,
        });

        if (recursive && item.isDirectory()) {
          await readDirectory(fullPath, recursive);
        }
      }
    }

    await readDirectory(request.path, request.recursive || false);

    return { entries };
  }
);

