/**
 * AI Stream Handler - Main Process
 * Gère le streaming des réponses AI via WebSocket/IPC
 */

import { ipcMain, IpcMainInvokeEvent, WebContents } from 'electron';
import { getAIService, StreamEventData } from '../../services/ai-service';
import { IPC_CHANNELS, StreamResponseRequest, StreamChunk } from '@cortex-ide/shared';
import { StreamResponseRequestSchema } from '@cortex-ide/shared';
import { z } from 'zod';

interface ActiveStream {
  sessionId: string;
  webContents: WebContents;
  aborted: boolean;
}

const activeStreams = new Map<string, ActiveStream>();

/**
 * Enregistre le handler pour le streaming AI
 */
export function registerAIStreamHandler() {
  ipcMain.handle(IPC_CHANNELS.AI_STREAM_RESPONSE, handleStreamResponse);

  // Écouter les événements du service AI
  const aiService = getAIService();

  aiService.on('stream:chunk', (data: StreamEventData) => {
    const stream = activeStreams.get(data.sessionId);
    if (stream && !stream.aborted) {
      const chunk: StreamChunk = {
        type: data.chunk.done ? 'done' : 'chunk',
        content: data.chunk.content,
      };

      stream.webContents.send(`ai:stream:${data.sessionId}`, chunk);
    }
  });

  aiService.on('error', ({ sessionId, error }: { sessionId: string; error: Error }) => {
    const stream = activeStreams.get(sessionId);
    if (stream) {
      const chunk: StreamChunk = {
        type: 'error',
        error: error.message,
      };

      stream.webContents.send(`ai:stream:${sessionId}`, chunk);
      activeStreams.delete(sessionId);
    }
  });

  console.log('[IPC] AI stream handler registered');
}

/**
 * Handler pour les requêtes de streaming
 */
async function handleStreamResponse(
  event: IpcMainInvokeEvent,
  request: unknown
): Promise<{ success: true; streamId: string } | { success: false; error: any }> {
  try {
    // Validation
    const validatedRequest = StreamResponseRequestSchema.parse(request) as StreamResponseRequest;

    const aiService = getAIService();
    const { sessionId, message } = validatedRequest;

    // Enregistrer le stream actif
    activeStreams.set(sessionId, {
      sessionId,
      webContents: event.sender,
      aborted: false,
    });

    // Démarrer le streaming en arrière-plan
    (async () => {
      try {
        for await (const _chunk of aiService.streamMessage(sessionId, message)) {
          const stream = activeStreams.get(sessionId);
          if (!stream || stream.aborted) {
            break;
          }
        }
      } catch (error) {
        console.error('[AI Stream] Error:', error);
        // L'erreur sera émise via l'événement 'error' du service
      } finally {
        activeStreams.delete(sessionId);
      }
    })();

    return { success: true, streamId: sessionId };
  } catch (error) {
    if (error instanceof z.ZodError) {
      return {
        success: false,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Validation failed',
          details: error.issues,
        },
      };
    }

    return {
      success: false,
      error: {
        code: 'AI_ERROR',
        message: error instanceof Error ? error.message : 'Unknown error',
      },
    };
  }
}

/**
 * Annule un stream en cours
 */
export function abortStream(sessionId: string): void {
  const stream = activeStreams.get(sessionId);
  if (stream) {
    stream.aborted = true;
    activeStreams.delete(sessionId);
  }
}

/**
 * Nettoie tous les streams actifs
 */
export function cleanupAIStreamHandler(): void {
  activeStreams.clear();
  ipcMain.removeHandler(IPC_CHANNELS.AI_STREAM_RESPONSE);
  console.log('[IPC] AI stream handler cleaned up');
}

/**
 * Terminal IPC Handlers
 */

import { ipcMain, BrowserWindow } from 'electron';
import { randomUUID } from 'crypto';
import { getTerminalService } from '../../services/terminal-service';
import {
  IPC_CHANNELS,
  CreateTerminalRequest,
  CreateTerminalResponse,
  TerminalInputRequest,
  TerminalResizeRequest,
  IPCResponse,
} from '@cortex-ide/shared/types/ipc';

/**
 * Enregistre les handlers IPC pour les terminaux
 */
export function registerTerminalHandlers() {
  const terminalService = getTerminalService();

  // Gestionnaire: Créer un terminal
  ipcMain.handle(
    IPC_CHANNELS.TERMINAL_CREATE,
    async (_, request: CreateTerminalRequest): Promise<IPCResponse<CreateTerminalResponse>> => {
      try {
        const terminalId = randomUUID();

        const terminal = terminalService.createTerminal(terminalId, {
          cwd: request.cwd,
          env: request.env,
          shell: request.shell,
        });

        return {
          success: true,
          data: {
            terminalId,
            pid: terminal.pid,
          },
        };
      } catch (error) {
        console.error('Failed to create terminal:', error);
        return {
          success: false,
          error: {
            code: 'TERMINAL_CREATE_FAILED',
            message: error instanceof Error ? error.message : 'Unknown error',
            details: error,
          },
        };
      }
    }
  );

  // Gestionnaire: Input terminal
  ipcMain.handle(
    IPC_CHANNELS.TERMINAL_INPUT,
    async (_, request: TerminalInputRequest): Promise<IPCResponse<void>> => {
      try {
        terminalService.writeToTerminal(request.terminalId, request.data);
        return { success: true, data: undefined };
      } catch (error) {
        console.error('Failed to write to terminal:', error);
        return {
          success: false,
          error: {
            code: 'TERMINAL_INPUT_FAILED',
            message: error instanceof Error ? error.message : 'Unknown error',
            details: error,
          },
        };
      }
    }
  );

  // Gestionnaire: Resize terminal
  ipcMain.handle(
    IPC_CHANNELS.TERMINAL_RESIZE,
    async (_, request: TerminalResizeRequest): Promise<IPCResponse<void>> => {
      try {
        terminalService.resizeTerminal(request.terminalId, request.cols, request.rows);
        return { success: true, data: undefined };
      } catch (error) {
        console.error('Failed to resize terminal:', error);
        return {
          success: false,
          error: {
            code: 'TERMINAL_RESIZE_FAILED',
            message: error instanceof Error ? error.message : 'Unknown error',
            details: error,
          },
        };
      }
    }
  );

  // Gestionnaire: Kill terminal
  ipcMain.handle(
    IPC_CHANNELS.TERMINAL_KILL,
    async (_, terminalId: string): Promise<IPCResponse<void>> => {
      try {
        terminalService.killTerminal(terminalId);
        return { success: true, data: undefined };
      } catch (error) {
        console.error('Failed to kill terminal:', error);
        return {
          success: false,
          error: {
            code: 'TERMINAL_KILL_FAILED',
            message: error instanceof Error ? error.message : 'Unknown error',
            details: error,
          },
        };
      }
    }
  );

  // Événements: Terminal data
  terminalService.on('data', (terminalId: string, data: string) => {
    const windows = BrowserWindow.getAllWindows();
    windows.forEach((win) => {
      win.webContents.send(IPC_CHANNELS.EVENT_TERMINAL_DATA, {
        type: 'terminal-data',
        terminalId,
        data,
      });
    });
  });

  // Événements: Terminal exit
  terminalService.on('exit', (terminalId: string, exitCode: number) => {
    const windows = BrowserWindow.getAllWindows();
    windows.forEach((win) => {
      win.webContents.send(IPC_CHANNELS.EVENT_TERMINAL_EXIT, {
        type: 'terminal-exit',
        terminalId,
        exitCode,
      });
    });
  });
}

/**
 * Désenregistre les handlers IPC pour les terminaux
 */
export function unregisterTerminalHandlers() {
  ipcMain.removeHandler(IPC_CHANNELS.TERMINAL_CREATE);
  ipcMain.removeHandler(IPC_CHANNELS.TERMINAL_INPUT);
  ipcMain.removeHandler(IPC_CHANNELS.TERMINAL_RESIZE);
  ipcMain.removeHandler(IPC_CHANNELS.TERMINAL_KILL);

  // Cleanup terminal service
  const terminalService = getTerminalService();
  terminalService.cleanup();
  terminalService.removeAllListeners();
}

/**
 * Database Performance Optimizer - Optimise les requêtes SQLite
 */

import { Database } from 'better-sqlite3';

export interface PreparedStatementCache {
  get(sql: string): any;
  set(sql: string, stmt: any): void;
  clear(): void;
  size(): number;
}

class DatabaseOptimizer {
  private preparedStatements = new Map<string, any>();
  private maxCacheSize = 200;
  private batchOperations: Array<() => void> = [];
  private isBatching = false;

  /**
   * Get or create a prepared statement
   */
  getPreparedStatement(db: Database, sql: string): any {
    let stmt = this.preparedStatements.get(sql);

    if (!stmt) {
      stmt = db.prepare(sql);
      this.preparedStatements.set(sql, stmt);

      // Limit cache size
      if (this.preparedStatements.size > this.maxCacheSize) {
        const firstKey = this.preparedStatements.keys().next().value;
        const firstStmt = this.preparedStatements.get(firstKey);
        if (firstStmt && typeof firstStmt.finalize === 'function') {
          firstStmt.finalize();
        }
        this.preparedStatements.delete(firstKey);
      }
    }

    return stmt;
  }

  /**
   * Start a batch operation
   */
  startBatch() {
    this.isBatching = true;
    this.batchOperations = [];
  }

  /**
   * Add operation to batch
   */
  addToBatch(operation: () => void) {
    if (this.isBatching) {
      this.batchOperations.push(operation);
    } else {
      operation();
    }
  }

  /**
   * Execute all batched operations in a transaction
   */
  executeBatch(db: Database) {
    if (!this.isBatching || this.batchOperations.length === 0) return;

    const transaction = db.transaction(() => {
      for (const operation of this.batchOperations) {
        operation();
      }
    });

    transaction();

    this.batchOperations = [];
    this.isBatching = false;
  }

  /**
   * Cancel current batch
   */
  cancelBatch() {
    this.batchOperations = [];
    this.isBatching = false;
  }

  /**
   * Clear prepared statement cache
   */
  clearCache() {
    for (const stmt of this.preparedStatements.values()) {
      if (stmt && typeof stmt.finalize === 'function') {
        stmt.finalize();
      }
    }
    this.preparedStatements.clear();
  }

  /**
   * Get cache statistics
   */
  getCacheStats() {
    return {
      size: this.preparedStatements.size,
      maxSize: this.maxCacheSize,
      batchSize: this.batchOperations.length,
      isBatching: this.isBatching
    };
  }

  /**
   * Optimize database with pragmas
   */
  optimizeDatabase(db: Database) {
    // Already set in migration-manager, but ensure they're active
    db.pragma('journal_mode = WAL');
    db.pragma('synchronous = NORMAL');
    db.pragma('cache_size = -64000'); // 64MB cache
    db.pragma('temp_store = MEMORY');
    db.pragma('mmap_size = 30000000000'); // 30GB memory-mapped I/O
    db.pragma('page_size = 4096');
    db.pragma('auto_vacuum = INCREMENTAL');
  }

  /**
   * Create indexes for common queries
   */
  createOptimalIndexes(db: Database) {
    const indexes = [
      // AI Sessions indexes
      'CREATE INDEX IF NOT EXISTS idx_sessions_created_at ON ai_sessions(created_at DESC)',
      'CREATE INDEX IF NOT EXISTS idx_sessions_model ON ai_sessions(model)',
      'CREATE INDEX IF NOT EXISTS idx_sessions_status ON ai_sessions(status)',

      // Messages indexes
      'CREATE INDEX IF NOT EXISTS idx_messages_session_id ON ai_messages(session_id)',
      'CREATE INDEX IF NOT EXISTS idx_messages_created_at ON ai_messages(created_at)',
      'CREATE INDEX IF NOT EXISTS idx_messages_role ON ai_messages(role)',

      // Automations indexes
      'CREATE INDEX IF NOT EXISTS idx_automations_enabled ON automations(enabled)',
      'CREATE INDEX IF NOT EXISTS idx_automations_created_at ON automations(created_at)',

      // Executions indexes
      'CREATE INDEX IF NOT EXISTS idx_executions_automation_id ON automation_executions(automation_id)',
      'CREATE INDEX IF NOT EXISTS idx_executions_status ON automation_executions(status)',
      'CREATE INDEX IF NOT EXISTS idx_executions_started_at ON automation_executions(started_at DESC)',

      // MCP indexes
      'CREATE INDEX IF NOT EXISTS idx_mcp_servers_enabled ON mcp_servers(enabled)',
      'CREATE INDEX IF NOT EXISTS idx_mcp_tools_server_id ON mcp_tools(server_id)',
      'CREATE INDEX IF NOT EXISTS idx_mcp_tools_name ON mcp_tools(name)'
    ];

    for (const indexSql of indexes) {
      try {
        db.exec(indexSql);
      } catch (error) {
        // Index might already exist, that's fine
        console.warn('[DatabaseOptimizer] Index creation warning:', error);
      }
    }
  }

  /**
   * Analyze database for query planner
   */
  analyzeDatabase(db: Database) {
    db.exec('ANALYZE');
  }

  /**
   * Vacuum database (should be done periodically, not frequently)
   */
  vacuumDatabase(db: Database) {
    db.exec('VACUUM');
  }

  /**
   * Get database statistics
   */
  getDatabaseStats(db: Database) {
    const pageCount = db.pragma('page_count', { simple: true }) as number;
    const pageSize = db.pragma('page_size', { simple: true }) as number;
    const freelistCount = db.pragma('freelist_count', { simple: true }) as number;

    return {
      totalPages: pageCount,
      pageSize,
      totalSize: pageCount * pageSize,
      freePages: freelistCount,
      usedSize: (pageCount - freelistCount) * pageSize,
      cacheSize: db.pragma('cache_size', { simple: true }),
      journalMode: db.pragma('journal_mode', { simple: true }),
      synchronous: db.pragma('synchronous', { simple: true })
    };
  }
}

export const dbOptimizer = new DatabaseOptimizer();

/**
 * IPC Optimizer - Optimise les communications IPC avec batching et streaming
 */

import { EventEmitter } from 'events';
import { BrowserWindow } from 'electron';
import { profiler } from './profiler';

interface BatchedMessage {
  channel: string;
  data: any;
  timestamp: number;
}

interface StreamChunk {
  id: string;
  index: number;
  data: any;
  isLast: boolean;
}

class IPCOptimizer extends EventEmitter {
  private batchQueue = new Map<string, BatchedMessage[]>();
  private batchInterval: NodeJS.Timeout | null = null;
  private batchDelayMs = 16; // ~60fps
  private maxBatchSize = 100;
  private activeStreams = new Map<string, any[]>();

  constructor() {
    super();
  }

  /**
   * Start IPC optimization
   */
  start() {
    this.startBatching();
  }

  /**
   * Stop IPC optimization
   */
  stop() {
    this.stopBatching();
  }

  /**
   * Send a message with batching
   */
  sendBatched(window: BrowserWindow, channel: string, data: any) {
    if (!this.batchQueue.has(channel)) {
      this.batchQueue.set(channel, []);
    }

    const queue = this.batchQueue.get(channel)!;
    queue.push({
      channel,
      data,
      timestamp: Date.now()
    });

    // If queue is full, flush immediately
    if (queue.length >= this.maxBatchSize) {
      this.flushBatch(window, channel);
    }
  }

  /**
   * Start a stream for large data transfer
   */
  startStream(window: BrowserWindow, streamId: string, data: any[], chunkSize = 1000) {
    profiler.start(`stream:${streamId}`, 'ipc', { chunkSize, totalSize: data.length });

    this.activeStreams.set(streamId, data);

    const chunks = Math.ceil(data.length / chunkSize);

    for (let i = 0; i < chunks; i++) {
      const start = i * chunkSize;
      const end = Math.min(start + chunkSize, data.length);
      const chunk: StreamChunk = {
        id: streamId,
        index: i,
        data: data.slice(start, end),
        isLast: i === chunks - 1
      };

      window.webContents.send('ipc:stream-chunk', chunk);
    }

    profiler.end(`stream:${streamId}`);
    this.activeStreams.delete(streamId);
  }

  /**
   * Send large data efficiently
   */
  async sendLargeData(window: BrowserWindow, channel: string, data: any) {
    const serialized = JSON.stringify(data);
    const sizeInBytes = Buffer.byteLength(serialized);

    // If data is small, send directly
    if (sizeInBytes < 100 * 1024) { // < 100KB
      window.webContents.send(channel, data);
      return;
    }

    // For large data, use streaming
    const streamId = `${channel}-${Date.now()}`;

    if (Array.isArray(data)) {
      this.startStream(window, streamId, data);
    } else {
      // For objects, split into chunks
      const entries = Object.entries(data);
      const chunks = [];
      const chunkSize = 100;

      for (let i = 0; i < entries.length; i += chunkSize) {
        chunks.push(Object.fromEntries(entries.slice(i, i + chunkSize)));
      }

      this.startStream(window, streamId, chunks);
    }

    window.webContents.send(channel, { streamId, streaming: true });
  }

  /**
   * Flush a specific batch
   */
  private flushBatch(window: BrowserWindow, channel: string) {
    const queue = this.batchQueue.get(channel);
    if (!queue || queue.length === 0) return;

    profiler.start(`batch:${channel}`, 'ipc', { count: queue.length });

    window.webContents.send('ipc:batch', {
      channel,
      messages: queue.map(m => m.data),
      count: queue.length
    });

    profiler.end(`batch:${channel}`);
    this.batchQueue.set(channel, []);

    this.emit('batch:flushed', { channel, count: queue.length });
  }

  /**
   * Flush all batches
   */
  flushAll(window: BrowserWindow) {
    for (const channel of this.batchQueue.keys()) {
      this.flushBatch(window, channel);
    }
  }

  /**
   * Start automatic batching
   */
  private startBatching() {
    if (this.batchInterval) return;

    this.batchInterval = setInterval(() => {
      const windows = BrowserWindow.getAllWindows();
      if (windows.length > 0) {
        this.flushAll(windows[0]);
      }
    }, this.batchDelayMs);
  }

  /**
   * Stop automatic batching
   */
  private stopBatching() {
    if (this.batchInterval) {
      clearInterval(this.batchInterval);
      this.batchInterval = null;
    }
  }

  /**
   * Get statistics
   */
  getStats() {
    return {
      batchQueues: this.batchQueue.size,
      activeStreams: this.activeStreams.size,
      queuedMessages: Array.from(this.batchQueue.values()).reduce((sum, q) => sum + q.length, 0)
    };
  }

  /**
   * Set batch delay
   */
  setBatchDelay(ms: number) {
    this.batchDelayMs = ms;
    if (this.batchInterval) {
      this.stopBatching();
      this.startBatching();
    }
  }

  /**
   * Set max batch size
   */
  setMaxBatchSize(size: number) {
    this.maxBatchSize = size;
  }
}

export const ipcOptimizer = new IPCOptimizer();

/**
 * Performance Profiler - Mesure et analyse les performances de l'application
 */

import { EventEmitter } from 'events';
import { app } from 'electron';
import * as fs from 'fs/promises';
import * as path from 'path';

export interface PerformanceMetric {
  name: string;
  category: 'ipc' | 'database' | 'render' | 'memory' | 'cpu' | 'startup' | 'custom';
  startTime: number;
  endTime?: number;
  duration?: number;
  metadata?: Record<string, any>;
}

export interface MemorySnapshot {
  timestamp: number;
  heapUsed: number;
  heapTotal: number;
  external: number;
  rss: number;
}

export interface PerformanceReport {
  timestamp: number;
  uptime: number;
  metrics: PerformanceMetric[];
  memorySnapshots: MemorySnapshot[];
  summary: {
    avgIpcLatency: number;
    avgDatabaseQuery: number;
    avgRenderTime: number;
    peakMemory: number;
    totalMetrics: number;
  };
}

class PerformanceProfiler extends EventEmitter {
  private metrics: Map<string, PerformanceMetric> = new Map();
  private completedMetrics: PerformanceMetric[] = [];
  private memorySnapshots: MemorySnapshot[] = [];
  private memorySnapshotInterval: NodeJS.Timeout | null = null;
  private maxMetricsHistory = 10000;
  private maxMemorySnapshots = 1000;
  private enabled = process.env.NODE_ENV === 'development';

  constructor() {
    super();
  }

  /**
   * Enable/disable profiler
   */
  setEnabled(enabled: boolean) {
    this.enabled = enabled;
    if (enabled) {
      this.startMemoryMonitoring();
    } else {
      this.stopMemoryMonitoring();
    }
  }

  /**
   * Start a performance measurement
   */
  start(name: string, category: PerformanceMetric['category'], metadata?: Record<string, any>): string {
    if (!this.enabled) return name;

    const metric: PerformanceMetric = {
      name,
      category,
      startTime: performance.now(),
      metadata
    };

    this.metrics.set(name, metric);
    return name;
  }

  /**
   * End a performance measurement
   */
  end(name: string, metadata?: Record<string, any>): number | null {
    if (!this.enabled) return null;

    const metric = this.metrics.get(name);
    if (!metric) {
      console.warn(`[Profiler] Metric "${name}" not found`);
      return null;
    }

    metric.endTime = performance.now();
    metric.duration = metric.endTime - metric.startTime;

    if (metadata) {
      metric.metadata = { ...metric.metadata, ...metadata };
    }

    this.metrics.delete(name);
    this.completedMetrics.push(metric);

    // Limit history
    if (this.completedMetrics.length > this.maxMetricsHistory) {
      this.completedMetrics.shift();
    }

    this.emit('metric:completed', metric);

    // Warn sur les métriques lentes
    if (metric.duration > 100) {
      this.emit('metric:slow', metric);
    }

    return metric.duration;
  }

  /**
   * Measure a function execution
   */
  async measure<T>(
    name: string,
    category: PerformanceMetric['category'],
    fn: () => T | Promise<T>,
    metadata?: Record<string, any>
  ): Promise<T> {
    if (!this.enabled) {
      return fn();
    }

    this.start(name, category, metadata);
    try {
      const result = await fn();
      this.end(name);
      return result;
    } catch (error) {
      this.end(name, { error: error instanceof Error ? error.message : String(error) });
      throw error;
    }
  }

  /**
   * Take a memory snapshot
   */
  takeMemorySnapshot(): MemorySnapshot {
    const mem = process.memoryUsage();
    const snapshot: MemorySnapshot = {
      timestamp: Date.now(),
      heapUsed: mem.heapUsed,
      heapTotal: mem.heapTotal,
      external: mem.external,
      rss: mem.rss
    };

    this.memorySnapshots.push(snapshot);

    // Limit snapshots
    if (this.memorySnapshots.length > this.maxMemorySnapshots) {
      this.memorySnapshots.shift();
    }

    this.emit('memory:snapshot', snapshot);
    return snapshot;
  }

  /**
   * Start automatic memory monitoring
   */
  startMemoryMonitoring(intervalMs = 10000) {
    if (this.memorySnapshotInterval) return;

    this.memorySnapshotInterval = setInterval(() => {
      this.takeMemorySnapshot();
    }, intervalMs);
  }

  /**
   * Stop automatic memory monitoring
   */
  stopMemoryMonitoring() {
    if (this.memorySnapshotInterval) {
      clearInterval(this.memorySnapshotInterval);
      this.memorySnapshotInterval = null;
    }
  }

  /**
   * Get performance report
   */
  getReport(): PerformanceReport {
    const ipcMetrics = this.completedMetrics.filter(m => m.category === 'ipc');
    const dbMetrics = this.completedMetrics.filter(m => m.category === 'database');
    const renderMetrics = this.completedMetrics.filter(m => m.category === 'render');

    const avgIpcLatency = ipcMetrics.length > 0
      ? ipcMetrics.reduce((sum, m) => sum + (m.duration || 0), 0) / ipcMetrics.length
      : 0;

    const avgDatabaseQuery = dbMetrics.length > 0
      ? dbMetrics.reduce((sum, m) => sum + (m.duration || 0), 0) / dbMetrics.length
      : 0;

    const avgRenderTime = renderMetrics.length > 0
      ? renderMetrics.reduce((sum, m) => sum + (m.duration || 0), 0) / renderMetrics.length
      : 0;

    const peakMemory = this.memorySnapshots.length > 0
      ? Math.max(...this.memorySnapshots.map(s => s.heapUsed))
      : 0;

    return {
      timestamp: Date.now(),
      uptime: process.uptime(),
      metrics: [...this.completedMetrics],
      memorySnapshots: [...this.memorySnapshots],
      summary: {
        avgIpcLatency,
        avgDatabaseQuery,
        avgRenderTime,
        peakMemory,
        totalMetrics: this.completedMetrics.length
      }
    };
  }

  /**
   * Export report to file
   */
  async exportReport(outputPath?: string): Promise<string> {
    const report = this.getReport();
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const filename = outputPath || path.join(
      app.getPath('userData'),
      'performance',
      `performance-report-${timestamp}.json`
    );

    await fs.mkdir(path.dirname(filename), { recursive: true });
    await fs.writeFile(filename, JSON.stringify(report, null, 2));

    return filename;
  }

  /**
   * Clear all metrics
   */
  clear() {
    this.metrics.clear();
    this.completedMetrics = [];
    this.memorySnapshots = [];
  }

  /**
   * Get metrics by category
   */
  getMetricsByCategory(category: PerformanceMetric['category']): PerformanceMetric[] {
    return this.completedMetrics.filter(m => m.category === category);
  }

  /**
   * Get slow metrics (> threshold ms)
   */
  getSlowMetrics(thresholdMs = 100): PerformanceMetric[] {
    return this.completedMetrics.filter(m => (m.duration || 0) > thresholdMs);
  }

  /**
   * Get statistics for a metric name
   */
  getMetricStats(name: string): {
    count: number;
    min: number;
    max: number;
    avg: number;
    median: number;
  } | null {
    const metrics = this.completedMetrics
      .filter(m => m.name === name && m.duration !== undefined)
      .map(m => m.duration!);

    if (metrics.length === 0) return null;

    const sorted = [...metrics].sort((a, b) => a - b);
    const median = sorted.length % 2 === 0
      ? (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
      : sorted[Math.floor(sorted.length / 2)];

    return {
      count: metrics.length,
      min: Math.min(...metrics),
      max: Math.max(...metrics),
      avg: metrics.reduce((sum, m) => sum + m, 0) / metrics.length,
      median
    };
  }
}

// Singleton instance
export const profiler = new PerformanceProfiler();

/**
 * V8 Code Caching - Améliore le temps de démarrage en cachant le code compilé
 */

import { app } from 'electron';
import * as fs from 'fs/promises';
import * as path from 'path';
import * as crypto from 'crypto';

interface CachedScript {
  path: string;
  hash: string;
  cachedData: Buffer;
  timestamp: number;
}

class V8CodeCache {
  private cacheDir: string;
  private maxCacheAge = 7 * 24 * 60 * 60 * 1000; // 7 days

  constructor() {
    this.cacheDir = path.join(app.getPath('userData'), 'v8-cache');
  }

  /**
   * Initialize cache directory
   */
  async initialize(): Promise<void> {
    try {
      await fs.mkdir(this.cacheDir, { recursive: true });
      await this.cleanOldCache();
    } catch (error) {
      console.error('[V8Cache] Failed to initialize:', error);
    }
  }

  /**
   * Get cache path for a script
   */
  private getCachePath(scriptPath: string): string {
    const hash = crypto.createHash('sha256').update(scriptPath).digest('hex');
    return path.join(this.cacheDir, `${hash}.cache`);
  }

  /**
   * Calculate file hash
   */
  private async calculateHash(filePath: string): Promise<string> {
    const content = await fs.readFile(filePath);
    return crypto.createHash('sha256').update(content).digest('hex');
  }

  /**
   * Get cached data for a script
   */
  async getCachedData(scriptPath: string): Promise<Buffer | null> {
    try {
      const cachePath = this.getCachePath(scriptPath);
      const cacheExists = await fs.access(cachePath).then(() => true).catch(() => false);

      if (!cacheExists) return null;

      const cacheContent = await fs.readFile(cachePath, 'utf-8');
      const cached: CachedScript = JSON.parse(cacheContent);

      // Verify hash
      const currentHash = await this.calculateHash(scriptPath);
      if (cached.hash !== currentHash) {
        await fs.unlink(cachePath);
        return null;
      }

      // Check age
      if (Date.now() - cached.timestamp > this.maxCacheAge) {
        await fs.unlink(cachePath);
        return null;
      }

      return Buffer.from(cached.cachedData);
    } catch (error) {
      return null;
    }
  }

  /**
   * Save cached data for a script
   */
  async saveCachedData(scriptPath: string, cachedData: Buffer): Promise<void> {
    try {
      const cachePath = this.getCachePath(scriptPath);
      const hash = await this.calculateHash(scriptPath);

      const cached: CachedScript = {
        path: scriptPath,
        hash,
        cachedData: cachedData as any, // Will be serialized
        timestamp: Date.now()
      };

      await fs.writeFile(cachePath, JSON.stringify(cached));
    } catch (error) {
      console.error('[V8Cache] Failed to save cache:', error);
    }
  }

  /**
   * Clean old cache files
   */
  async cleanOldCache(): Promise<void> {
    try {
      const files = await fs.readdir(this.cacheDir);
      const now = Date.now();

      for (const file of files) {
        const filePath = path.join(this.cacheDir, file);
        try {
          const content = await fs.readFile(filePath, 'utf-8');
          const cached: CachedScript = JSON.parse(content);

          if (now - cached.timestamp > this.maxCacheAge) {
            await fs.unlink(filePath);
          }
        } catch {
          // Invalid cache file, delete it
          await fs.unlink(filePath);
        }
      }
    } catch (error) {
      console.error('[V8Cache] Failed to clean cache:', error);
    }
  }

  /**
   * Clear all cache
   */
  async clearCache(): Promise<void> {
    try {
      const files = await fs.readdir(this.cacheDir);
      await Promise.all(
        files.map(file => fs.unlink(path.join(this.cacheDir, file)))
      );
    } catch (error) {
      console.error('[V8Cache] Failed to clear cache:', error);
    }
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<{
    totalFiles: number;
    totalSize: number;
    oldestFile: number;
    newestFile: number;
  }> {
    try {
      const files = await fs.readdir(this.cacheDir);
      let totalSize = 0;
      let oldestFile = Date.now();
      let newestFile = 0;

      for (const file of files) {
        const filePath = path.join(this.cacheDir, file);
        const stats = await fs.stat(filePath);
        totalSize += stats.size;

        try {
          const content = await fs.readFile(filePath, 'utf-8');
          const cached: CachedScript = JSON.parse(content);
          oldestFile = Math.min(oldestFile, cached.timestamp);
          newestFile = Math.max(newestFile, cached.timestamp);
        } catch {
          // Ignore invalid files
        }
      }

      return {
        totalFiles: files.length,
        totalSize,
        oldestFile: oldestFile === Date.now() ? 0 : oldestFile,
        newestFile
      };
    } catch (error) {
      return {
        totalFiles: 0,
        totalSize: 0,
        oldestFile: 0,
        newestFile: 0
      };
    }
  }
}

