/**
 * Security configuration and utilities for Cortex IDE
 */

import { app, session } from 'electron';

/**
 * Permissions whitelist
 */
const ALLOWED_PERMISSIONS = [
  'clipboard-read',
  'clipboard-write',
  'media',
  'notifications',
] as const;

/**
 * Safe domains for external navigation
 */
const SAFE_DOMAINS = [
  'github.com',
  'www.github.com',
  'docs.github.com',
  'api.github.com',
  'cortex-ide.com',
  'www.cortex-ide.com',
] as const;

/**
 * Initialize security settings for the application
 */
export function initializeSecurity(): void {
  // Set permission request handler
  session.defaultSession.setPermissionRequestHandler(
    (webContents, permission, callback) => {
      const allowed = ALLOWED_PERMISSIONS.includes(permission as any);

      if (!allowed) {
        console.warn(`[Security] Denied permission request: ${permission}`);
      }

      callback(allowed);
    }
  );

  // Set permission check handler
  session.defaultSession.setPermissionCheckHandler(
    (webContents, permission, requestingOrigin, details) => {
      const allowed = ALLOWED_PERMISSIONS.includes(permission as any);

      if (!allowed) {
        console.warn(
          `[Security] Denied permission check: ${permission} from ${requestingOrigin}`
        );
      }

      return allowed;
    }
  );

  // Disable navigation to external URLs
  app.on('web-contents-created', (event, contents) => {
    contents.on('will-navigate', (event, navigationUrl) => {
      const parsedUrl = new URL(navigationUrl);

      // Allow same-origin navigation
      if (parsedUrl.protocol === 'file:') {
        return;
      }

      // Block external navigation
      console.warn(`[Security] Blocked navigation to: ${navigationUrl}`);
      event.preventDefault();
    });

    // Prevent new window creation
    contents.setWindowOpenHandler(({ url }) => {
      console.warn(`[Security] Blocked window.open to: ${url}`);
      return { action: 'deny' };
    });
  });
}

/**
 * Validate if a URL is safe to open externally
 */
export function isSafeExternalUrl(url: string): boolean {
  try {
    const parsed = new URL(url);

    // Only allow https
    if (parsed.protocol !== 'https:') {
      return false;
    }

    // Check against whitelist
    return SAFE_DOMAINS.some(domain => 
      parsed.hostname === domain || parsed.hostname.endsWith(`.${domain}`)
    );
  } catch {
    return false;
  }
}

/**
 * Safely open an external URL
 */
export async function openExternalSafe(url: string): Promise<boolean> {
  const { shell } = await import('electron');

  if (!isSafeExternalUrl(url)) {
    console.error(`[Security] Blocked unsafe external URL: ${url}`);
    return false;
  }

  try {
    await shell.openExternal(url);
    return true;
  } catch (error) {
    console.error(`[Security] Failed to open external URL:`, error);
    return false;
  }
}

/**
 * AI Service - Main Process
 * Service backend pour gérer les sessions et communications avec les providers AI
 * Intégration MCP pour permettre aux agents d'utiliser des tools externes
 */

import { EventEmitter } from 'events';
import type { MCPToolInvocation } from './mcp-service';

// Placeholder types until ai-engine is implemented
interface Message {
  role: string;
  content: string;
  toolCalls?: ToolCall[];
}

interface ToolCall {
  id: string;
  type: 'mcp_tool';
  serverId: string;
  toolName: string;
  arguments: Record<string, any>;
}

interface ChatOptions {
  temperature?: number;
  maxTokens?: number;
  tools?: ToolDefinition[];
}

interface ToolDefinition {
  type: 'mcp_tool';
  serverId: string;
  toolName: string;
  description: string;
  inputSchema: any;
}

interface ChatResponse {
  content: string;
  usage?: any;
  toolCalls?: ToolCall[];
}

interface StreamChunk {
  content: string;
  done: boolean;
}

class AIProviderError extends Error {}

class AIProviderRegistry {
  getProvider(id: string): any {
    throw new Error('AI providers not yet implemented');
  }
}

export interface AISession {
  id: string;
  providerId: string;
  model?: string;
  messages: Message[];
  createdAt: number;
  updatedAt: number;
  mcpEnabled?: boolean;
  availableTools?: ToolDefinition[];
}

export interface StreamEventData {
  sessionId: string;
  chunk: StreamChunk;
}

export class AIService extends EventEmitter {
  private registry: AIProviderRegistry;
  private sessions = new Map<string, AISession>();
  private mcpService: any; // Will be imported from mcp-service

  constructor(registry?: AIProviderRegistry, mcpService?: any) {
    super();
    this.registry = registry || AIProviderRegistry.fromEnv();
    this.mcpService = mcpService;
    this.validateRegistry();
  }

  /**
   * Définit le service MCP pour l'intégration des tools
   */
  setMCPService(mcpService: any): void {
    this.mcpService = mcpService;
  }

  /**
   * Active MCP pour une session et charge les tools disponibles
   */
  async enableMCPForSession(sessionId: string, serverIds?: string[]): Promise<void> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    if (!this.mcpService) {
      throw new Error('MCP service not configured');
    }

    // Récupérer les tools disponibles depuis les serveurs MCP
    const availableTools: ToolDefinition[] = [];

    const servers = serverIds 
      ? serverIds.map(id => this.mcpService.getServer(id)).filter(Boolean)
      : this.mcpService.getAllServers().filter((s: any) => s.status === 'running');

    for (const server of servers) {
      if (server.tools) {
        for (const tool of server.tools) {
          availableTools.push({
            type: 'mcp_tool',
            serverId: server.id,
            toolName: tool.name,
            description: tool.description,
            inputSchema: tool.inputSchema,
          });
        }
      }
    }

    session.mcpEnabled = true;
    session.availableTools = availableTools;
    session.updatedAt = Date.now();

    this.emit('session:mcp-enabled', { sessionId, toolCount: availableTools.length });
  }

  /**
   * Invoque un tool MCP depuis une session AI
   */
  async invokeMCPTool(sessionId: string, toolCall: ToolCall): Promise<any> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    if (!session.mcpEnabled) {
      throw new Error('MCP not enabled for this session');
    }

    if (!this.mcpService) {
      throw new Error('MCP service not configured');
    }

    // Vérifier que le tool est disponible pour cette session
    const toolDef = session.availableTools?.find(
      t => t.serverId === toolCall.serverId && t.toolName === toolCall.toolName
    );

    if (!toolDef) {
      throw new Error(`Tool ${toolCall.toolName} from server ${toolCall.serverId} not available in this session`);
    }

    // Invoquer le tool via MCP service
    const invocation: MCPToolInvocation = {
      serverId: toolCall.serverId,
      toolName: toolCall.toolName,
      arguments: toolCall.arguments,
    };

    const result = await this.mcpService.invokeTool(invocation);

    this.emit('tool:invoked', { sessionId, toolCall, result });

    return result;
  }

  /**
   * Traite les tool calls dans une réponse AI
   */
  private async processToolCalls(sessionId: string, toolCalls: ToolCall[]): Promise<Message[]> {
    const toolMessages: Message[] = [];

    for (const toolCall of toolCalls) {
      try {
        const result = await this.invokeMCPTool(sessionId, toolCall);

        toolMessages.push({
          role: 'tool',
          content: JSON.stringify(result),
          toolCalls: [toolCall],
        });
      } catch (error) {
        toolMessages.push({
          role: 'tool',
          content: JSON.stringify({ 
            error: error instanceof Error ? error.message : 'Unknown error',
            isError: true 
          }),
          toolCalls: [toolCall],
        });
      }
    }

    return toolMessages;
  }

  /**
   * Valide que le registry a au moins un provider configuré
   */
  private validateRegistry(): void {
    if (!this.registry.hasProviders()) {
      console.warn('[AIService] No AI providers configured. Set environment variables:');
      console.warn('  - OPENAI_API_KEY for OpenAI');
      console.warn('  - ANTHROPIC_API_KEY for Anthropic');
      console.warn('  - OPENROUTER_API_KEY for OpenRouter');
      console.warn('  - OLLAMA_HOST or OLLAMA_ENABLED=true for Ollama');
    }
  }

  /**
   * Crée une nouvelle session
   */
  async createSession(providerId?: string, model?: string): Promise<AISession> {
    const provider = providerId
      ? this.registry.getProvider(providerId)
      : this.registry.getDefault();

    if (!provider) {
      throw new Error(
        providerId
          ? `Provider "${providerId}" not found`
          : 'No default AI provider configured'
      );
    }

    // Vérifier la disponibilité du provider
    const available = await provider.isAvailable();
    if (!available) {
      throw new Error(`Provider "${provider.id}" is not available`);
    }

    const session: AISession = {
      id: this.generateSessionId(),
      providerId: provider.id,
      model,
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };

    this.sessions.set(session.id, session);
    this.emit('session:created', session);

    return session;
  }

  /**
   * Récupère une session existante
   */
  getSession(sessionId: string): AISession | undefined {
    return this.sessions.get(sessionId);
  }

  /**
   * Liste toutes les sessions
   */
  getAllSessions(): AISession[] {
    return Array.from(this.sessions.values());
  }

  /**
   * Supprime une session
   */
  deleteSession(sessionId: string): boolean {
    const deleted = this.sessions.delete(sessionId);
    if (deleted) {
      this.emit('session:deleted', sessionId);
    }
    return deleted;
  }

  /**
   * Envoie un message et attend la réponse complète
   */
  async sendMessage(
    sessionId: string,
    content: string,
    options?: ChatOptions
  ): Promise<ChatResponse> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    const provider = this.registry.getProvider(session.providerId);
    if (!provider) {
      throw new Error(`Provider "${session.providerId}" not found`);
    }

    // Ajouter le message utilisateur
    const userMessage: Message = { role: 'user', content };
    session.messages.push(userMessage);
    session.updatedAt = Date.now();

    try {
      // Envoyer au provider avec le modèle de la session si défini
      const chatOptions: ChatOptions = {
        ...options,
        model: session.model || options?.model,
      };

      const response = await provider.chat(session.messages, chatOptions);

      // Ajouter la réponse de l'assistant
      const assistantMessage: Message = {
        role: 'assistant',
        content: response.content,
      };
      session.messages.push(assistantMessage);
      session.updatedAt = Date.now();

      this.emit('message:sent', { sessionId, message: userMessage });
      this.emit('message:received', { sessionId, message: assistantMessage, response });

      return response;
    } catch (error) {
      // Retirer le message utilisateur en cas d'erreur
      session.messages.pop();

      if (error instanceof AIProviderError) {
        this.emit('error', { sessionId, error });
        throw error;
      }

      throw new Error(`Failed to send message: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Envoie un message en mode streaming
   */
  async *streamMessage(
    sessionId: string,
    content: string,
    options?: ChatOptions
  ): AsyncIterableIterator<StreamChunk> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    const provider = this.registry.getProvider(session.providerId);
    if (!provider) {
      throw new Error(`Provider "${session.providerId}" not found`);
    }

    // Ajouter le message utilisateur
    const userMessage: Message = { role: 'user', content };
    session.messages.push(userMessage);
    session.updatedAt = Date.now();

    this.emit('message:sent', { sessionId, message: userMessage });

    let fullResponse = '';

    try {
      // Stream depuis le provider avec le modèle de la session si défini
      const chatOptions: ChatOptions = {
        ...options,
        model: session.model || options?.model,
      };

      for await (const chunk of provider.stream(session.messages, chatOptions)) {
        fullResponse += chunk.content;

        // Émettre l'événement pour l'IPC
        this.emit('stream:chunk', { sessionId, chunk });

        yield chunk;
      }

      // Ajouter la réponse complète de l'assistant
      const assistantMessage: Message = {
        role: 'assistant',
        content: fullResponse,
      };
      session.messages.push(assistantMessage);
      session.updatedAt = Date.now();

      this.emit('message:received', { sessionId, message: assistantMessage });
    } catch (error) {
      // Retirer le message utilisateur en cas d'erreur
      session.messages.pop();

      if (error instanceof AIProviderError) {
        this.emit('error', { sessionId, error });
        throw error;
      }

      throw new Error(`Failed to stream message: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Ajoute un message système à la session
   */
  addSystemMessage(sessionId: string, content: string): void {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    const systemMessage: Message = { role: 'system', content };
    session.messages.unshift(systemMessage); // Ajouter au début
    session.updatedAt = Date.now();

    this.emit('message:added', { sessionId, message: systemMessage });
  }

  /**
   * Récupère les providers disponibles
   */
  getAvailableProviders(): Array<{ id: string; name: string }> {
    return this.registry.getAllProviders().map(p => ({
      id: p.id,
      name: p.name,
    }));
  }

  /**
   * Vérifie quels providers sont actuellement disponibles
   */
  async checkAvailableProviders(): Promise<string[]> {
    return this.registry.getAvailableProviders();
  }

  /**
   * Change le provider d'une session existante
   */
  async switchProvider(sessionId: string, providerId: string): Promise<void> {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    const provider = this.registry.getProvider(providerId);
    if (!provider) {
      throw new Error(`Provider "${providerId}" not found`);
    }

    const available = await provider.isAvailable();
    if (!available) {
      throw new Error(`Provider "${providerId}" is not available`);
    }

    session.providerId = providerId;
    session.updatedAt = Date.now();

    this.emit('session:updated', session);
  }

  /**
   * Efface l'historique des messages d'une session
   */
  clearSessionHistory(sessionId: string, keepSystemMessages = true): void {
    const session = this.sessions.get(sessionId);
    if (!session) {
      throw new Error(`Session "${sessionId}" not found`);
    }

    if (keepSystemMessages) {
      session.messages = session.messages.filter(m => m.role === 'system');
    } else {
      session.messages = [];
    }

    session.updatedAt = Date.now();
    this.emit('session:cleared', sessionId);
  }

  /**
   * Génère un ID unique pour les sessions
   */
  private generateSessionId(): string {
    return `session_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
  }

  /**
   * Nettoie toutes les sessions
   */
  cleanup(): void {
    this.sessions.clear();
    this.removeAllListeners();
  }
}

// Instance singleton
let aiServiceInstance: AIService | null = null;

/**
 * Récupère ou crée l'instance du service AI
 */
export function getAIService(): AIService {
  if (!aiServiceInstance) {
    aiServiceInstance = new AIService();
  }
  return aiServiceInstance;
}

/**
 * Réinitialise l'instance du service AI
 */
export function resetAIService(): void {
  if (aiServiceInstance) {
    aiServiceInstance.cleanup();
    aiServiceInstance = null;
  }
}

/**
 * Automation Service - Main Process
 * Gestion complète du système d'automations avec triggers et actions
 */

import { watch, FSWatcher } from 'chokidar';
import { schedule, ScheduledTask } from 'node-cron';
import { EventEmitter } from 'events';
import { gitService } from './git-service';
import { getAIService } from './ai-service';

// ============================================================================
// Types
// ============================================================================

export type TriggerType = 'file_watch' | 'git_hook' | 'schedule' | 'manual';
export type ActionType = 'run_script' | 'ai_task' | 'git_operation' | 'notification';
export type AutomationStatus = 'idle' | 'running' | 'success' | 'error';

export interface FileTrigger {
  type: 'file_watch';
  patterns: string[];
  events: ('add' | 'change' | 'unlink')[];
  workspacePath: string;
}

export interface GitTrigger {
  type: 'git_hook';
  hook: 'pre-commit' | 'post-commit' | 'pre-push' | 'post-merge';
  repoPath: string;
}

export interface ScheduleTrigger {
  type: 'schedule';
  cron: string;
  timezone?: string;
}

export interface ManualTrigger {
  type: 'manual';
}

export type Trigger = FileTrigger | GitTrigger | ScheduleTrigger | ManualTrigger;

export interface ScriptAction {
  type: 'run_script';
  script: string;
  shell?: string;
  cwd?: string;
  env?: Record<string, string>;
}

export interface AITaskAction {
  type: 'ai_task';
  prompt: string;
  model: string;
  provider: 'openai' | 'anthropic' | 'openrouter' | 'ollama' | 'grok';
  context?: {
    files?: string[];
    workspacePath?: string;
  };
}

export interface GitOperationAction {
  type: 'git_operation';
  operation: 'commit' | 'push' | 'pull' | 'branch';
  repoPath: string;
  params?: Record<string, unknown>;
}

export interface NotificationAction {
  type: 'notification';
  title: string;
  message: string;
  level: 'info' | 'warning' | 'error' | 'success';
}

export type Action = ScriptAction | AITaskAction | GitOperationAction | NotificationAction;

export interface Automation {
  id: string;
  workspaceId: string;
  name: string;
  enabled: boolean;
  trigger: Trigger;
  actions: Action[];
  createdAt: number;
  updatedAt: number;
}

export interface AutomationLog {
  id: string;
  automationId: string;
  status: AutomationStatus;
  startedAt: number;
  completedAt?: number;
  error?: string;
  output?: string;
  actionResults: Array<{
    action: Action;
    status: 'success' | 'error';
    output?: string;
    error?: string;
    duration: number;
  }>;
}

// ============================================================================
// Automation Service
// ============================================================================

export class AutomationService extends EventEmitter {
  private automations: Map<string, Automation> = new Map();
  private watchers: Map<string, FSWatcher> = new Map();
  private schedulers: Map<string, ScheduledTask> = new Map();
  private logs: Map<string, AutomationLog[]> = new Map();
  private runningAutomations: Set<string> = new Set();

  constructor() {
    super();
  }

  /**
   * Crée une nouvelle automation
   */
  async createAutomation(automation: Omit<Automation, 'id' | 'createdAt' | 'updatedAt'>): Promise<Automation> {
    const id = `automation_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const now = Date.now();

    const newAutomation: Automation = {
      id,
      ...automation,
      createdAt: now,
      updatedAt: now,
    };

    this.automations.set(id, newAutomation);

    // Active l'automation si enabled
    if (newAutomation.enabled) {
      await this.activateAutomation(id);
    }

    this.emit('automation:created', newAutomation);

    return newAutomation;
  }

  /**
   * Met à jour une automation
   */
  async updateAutomation(id: string, updates: Partial<Omit<Automation, 'id' | 'createdAt'>>): Promise<Automation> {
    const automation = this.automations.get(id);
    if (!automation) {
      throw new Error(`Automation ${id} not found`);
    }

    // Désactive l'ancienne automation
    await this.deactivateAutomation(id);

    // Applique les mises à jour
    const updated: Automation = {
      ...automation,
      ...updates,
      updatedAt: Date.now(),
    };

    this.automations.set(id, updated);

    // Réactive si enabled
    if (updated.enabled) {
      await this.activateAutomation(id);
    }

    this.emit('automation:updated', updated);

    return updated;
  }

  /**
   * Supprime une automation
   */
  async deleteAutomation(id: string): Promise<void> {
    const automation = this.automations.get(id);
    if (!automation) {
      throw new Error(`Automation ${id} not found`);
    }

    await this.deactivateAutomation(id);
    this.automations.delete(id);
    this.logs.delete(id);

    this.emit('automation:deleted', id);
  }

  /**
   * Liste toutes les automations
   */
  listAutomations(workspaceId?: string): Automation[] {
    const automations = Array.from(this.automations.values());

    if (workspaceId) {
      return automations.filter(a => a.workspaceId === workspaceId);
    }

    return automations;
  }

  /**
   * Récupère une automation par ID
   */
  getAutomation(id: string): Automation | undefined {
    return this.automations.get(id);
  }

  /**
   * Active/désactive une automation
   */
  async toggleAutomation(id: string, enabled: boolean): Promise<Automation> {
    return await this.updateAutomation(id, { enabled });
  }

  /**
   * Exécute manuellement une automation
   */
  async runAutomation(id: string, triggerData?: unknown): Promise<AutomationLog> {
    const automation = this.automations.get(id);
    if (!automation) {
      throw new Error(`Automation ${id} not found`);
    }

    return await this.executeAutomation(automation, triggerData);
  }

  /**
   * Récupère les logs d'une automation
   */
  getAutomationLogs(automationId: string, limit: number = 50): AutomationLog[] {
    const logs = this.logs.get(automationId) || [];
    return logs.slice(-limit);
  }

  /**
   * Active une automation (setup triggers)
   */
  private async activateAutomation(id: string): Promise<void> {
    const automation = this.automations.get(id);
    if (!automation) return;

    const { trigger } = automation;

    switch (trigger.type) {
      case 'file_watch':
        this.setupFileWatcher(automation);
        break;

      case 'schedule':
        this.setupScheduler(automation);
        break;

      case 'git_hook':
        // Git hooks sont gérés différemment (fichiers .git/hooks)
        // Pour l'instant, on log juste
        console.log(`[Automation] Git hook trigger for ${id} (not yet implemented)`);
        break;

      case 'manual':
        // Manual triggers n'ont pas besoin d'activation
        break;
    }
  }

  /**
   * Désactive une automation (cleanup triggers)
   */
  private async deactivateAutomation(id: string): Promise<void> {
    // Stop file watcher
    const watcher = this.watchers.get(id);
    if (watcher) {
      await watcher.close();
      this.watchers.delete(id);
    }

    // Stop scheduler
    const scheduler = this.schedulers.get(id);
    if (scheduler) {
      scheduler.stop();
      this.schedulers.delete(id);
    }
  }

  /**
   * Setup file watcher trigger
   */
  private setupFileWatcher(automation: Automation): void {
    const trigger = automation.trigger as FileTrigger;

    const watcher = watch(trigger.patterns, {
      cwd: trigger.workspacePath,
      persistent: true,
      ignoreInitial: true,
      ignored: /(^|[\/\\])\../, // Ignore dotfiles
    });

    // Register events
    trigger.events.forEach(event => {
      watcher.on(event, async (path: string) => {
        console.log(`[Automation] File ${event}: ${path}`);

        // Execute automation
        try {
          await this.executeAutomation(automation, { event, path });
        } catch (error) {
          console.error(`[Automation] Error executing automation ${automation.id}:`, error);
        }
      });
    });

    this.watchers.set(automation.id, watcher);
  }

  /**
   * Setup schedule trigger
   */
  private setupScheduler(automation: Automation): void {
    const trigger = automation.trigger as ScheduleTrigger;

    const task = schedule(
      trigger.cron,
      async () => {
        console.log(`[Automation] Schedule triggered: ${automation.name}`);

        try {
          await this.executeAutomation(automation);
        } catch (error) {
          console.error(`[Automation] Error executing automation ${automation.id}:`, error);
        }
      },
      {
        timezone: trigger.timezone,
      }
    );

    this.schedulers.set(automation.id, task);
  }

  /**
   * Exécute une automation
   */
  private async executeAutomation(automation: Automation, triggerData?: unknown): Promise<AutomationLog> {
    // Empêche les exécutions concurrentes
    if (this.runningAutomations.has(automation.id)) {
      throw new Error(`Automation ${automation.id} is already running`);
    }

    this.runningAutomations.add(automation.id);

    const logId = `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const startedAt = Date.now();

    const log: AutomationLog = {
      id: logId,
      automationId: automation.id,
      status: 'running',
      startedAt,
      actionResults: [],
    };

    // Ajoute le log
    if (!this.logs.has(automation.id)) {
      this.logs.set(automation.id, []);
    }
    this.logs.get(automation.id)!.push(log);

    this.emit('automation:started', { automation, log });

    try {
      // Exécute chaque action
      for (const action of automation.actions) {
        const actionStart = Date.now();

        try {
          const output = await this.executeAction(action, triggerData);

          log.actionResults.push({
            action,
            status: 'success',
            output,
            duration: Date.now() - actionStart,
          });
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : String(error);

          log.actionResults.push({
            action,
            status: 'error',
            error: errorMessage,
            duration: Date.now() - actionStart,
          });

          // Stop sur erreur
          throw error;
        }
      }

      // Succès
      log.status = 'success';
      log.completedAt = Date.now();

      this.emit('automation:completed', { automation, log });

      return log;

    } catch (error) {
      // Erreur
      log.status = 'error';
      log.error = error instanceof Error ? error.message : String(error);
      log.completedAt = Date.now();

      this.emit('automation:failed', { automation, log, error });

      return log;

    } finally {
      this.runningAutomations.delete(automation.id);
    }
  }

  /**
   * Exécute une action
   */
  private async executeAction(action: Action, triggerData?: unknown): Promise<string> {
    switch (action.type) {
      case 'run_script':
        return await this.executeScriptAction(action);

      case 'ai_task':
        return await this.executeAITaskAction(action, triggerData);

      case 'git_operation':
        return await this.executeGitOperationAction(action);

      case 'notification':
        return await this.executeNotificationAction(action);

      default:
        throw new Error(`Unknown action type: ${(action as Action).type}`);
    }
  }

  /**
   * Exécute une action script
   */
  private async executeScriptAction(action: ScriptAction): Promise<string> {
    const { spawn } = await import('child_process');
    const { promisify } = await import('util');

    return new Promise((resolve, reject) => {
      const shell = action.shell || (process.platform === 'win32' ? 'cmd.exe' : '/bin/bash');
      const child = spawn(shell, ['-c', action.script], {
        cwd: action.cwd || process.cwd(),
        env: { ...process.env, ...action.env },
      });

      let stdout = '';
      let stderr = '';

      child.stdout?.on('data', (data) => {
        stdout += data.toString();
      });

      child.stderr?.on('data', (data) => {
        stderr += data.toString();
      });

      child.on('close', (code) => {
        if (code === 0) {
          resolve(stdout);
        } else {
          reject(new Error(`Script exited with code ${code}\n${stderr}`));
        }
      });

      child.on('error', reject);
    });
  }

  /**
   * Exécute une action AI
   */
  private async executeAITaskAction(action: AITaskAction, triggerData?: unknown): Promise<string> {
    const aiService = getAIService();

    // Crée une session temporaire
    const session = await aiService.createSession(action.provider, action.model);

    try {
      // Prépare le prompt avec contexte
      let fullPrompt = action.prompt;

      if (triggerData) {
        fullPrompt += `\n\nTrigger data: ${JSON.stringify(triggerData, null, 2)}`;
      }

      // Envoie le message
      const response = await aiService.sendMessage(session.id, fullPrompt);

      return response.content;
    } finally {
      // Nettoie la session
      // TODO: Implémenter cleanup session
    }
  }

  /**
   * Exécute une opération Git
   */
  private async executeGitOperationAction(action: GitOperationAction): Promise<string> {
    const { operation, repoPath, params = {} } = action;

    switch (operation) {
      case 'commit': {
        const message = params.message as string || 'Automated commit';
        const files = params.files as string[] | undefined;
        const result = await gitService.commit(repoPath, message, files);
        return `Committed: ${result.hash.slice(0, 7)} - ${result.message}`;
      }

      case 'push': {
        const remote = params.remote as string | undefined;
        const branch = params.branch as string | undefined;
        const result = await gitService.push(repoPath, remote, branch);
        return `Pushed ${result.pushed} commit(s)`;
      }

      case 'pull': {
        const remote = params.remote as string | undefined;
        const branch = params.branch as string | undefined;
        await gitService.pull(repoPath, remote, branch);
        return 'Pull completed';
      }

      case 'branch': {
        const branchName = params.branchName as string;
        const checkout = params.checkout as boolean | undefined;
        await gitService.createBranch(repoPath, branchName, checkout);
        return `Branch ${branchName} created`;
      }

      default:
        throw new Error(`Unknown git operation: ${operation}`);
    }
  }

  /**
   * Exécute une action notification
   */
  private async executeNotificationAction(action: NotificationAction): Promise<string> {
    // Émet un événement pour que le renderer affiche la notification
    this.emit('notification', {
      title: action.title,
      message: action.message,
      level: action.level,
    });

    return `Notification sent: ${action.title}`;
  }

  /**
   * Nettoie toutes les ressources
   */
  async cleanup(): Promise<void> {
    // Stop all watchers
    for (const watcher of this.watchers.values()) {
      await watcher.close();
    }
    this.watchers.clear();

    // Stop all schedulers
    for (const scheduler of this.schedulers.values()) {
      scheduler.stop();
    }
    this.schedulers.clear();

    this.automations.clear();
    this.logs.clear();
    this.runningAutomations.clear();
  }
}

// Instance singleton
export const automationService = new AutomationService();

/**
 * Git Service - Main Process
 * Gestion complète Git avec simple-git
 */

import simpleGit, { SimpleGit, StatusResult, DefaultLogFields, LogResult, BranchSummary } from 'simple-git';
import {
  GitStatusResponse,
  GitFileStatus,
  GitCommitResponse,
  GitPushResponse,
  GitDiffResponse,
} from '@cortex-ide/shared';

export class GitService {
  private gitInstances: Map<string, SimpleGit> = new Map();

  /**
   * Récupère ou crée une instance Git pour un repo
   */
  private getGit(repoPath: string): SimpleGit {
    if (!this.gitInstances.has(repoPath)) {
      const git = simpleGit({
        baseDir: repoPath,
        binary: 'git',
        maxConcurrentProcesses: 6,
        trimmed: false,
      });
      this.gitInstances.set(repoPath, git);
    }
    return this.gitInstances.get(repoPath)!;
  }

  /**
   * Récupère le statut Git du repo
   */
  async status(repoPath: string): Promise<GitStatusResponse> {
    const git = this.getGit(repoPath);
    const status: StatusResult = await git.status();
    const files = this.parseStatusFiles(status);

    return {
      branch: status.current || 'unknown',
      ahead: status.ahead,
      behind: status.behind,
      files,
      isClean: status.isClean(),
    };
  }

  /**
   * Parse les fichiers du statut Git
   */
  private parseStatusFiles(status: StatusResult): GitFileStatus[] {
    const files: GitFileStatus[] = [];

    this.addStagedFiles(files, status);
    this.addModifiedFiles(files, status);
    this.addUntrackedFiles(files, status);

    return files;
  }

  private addStagedFiles(files: GitFileStatus[], status: StatusResult): void {
    status.staged.forEach(file => {
      files.push({ path: file, status: 'modified', staged: true });
    });

    status.created.forEach(file => {
      files.push({ path: file, status: 'added', staged: true });
    });

    status.deleted.forEach(file => {
      files.push({ path: file, status: 'deleted', staged: true });
    });

    status.renamed.forEach(file => {
      files.push({ path: file.to || file.from, status: 'renamed', staged: true });
    });
  }

  private addModifiedFiles(files: GitFileStatus[], status: StatusResult): void {
    status.modified.forEach(file => {
      if (!files.find(f => f.path === file && f.staged)) {
        files.push({ path: file, status: 'modified', staged: false });
      }
    });
  }

  private addUntrackedFiles(files: GitFileStatus[], status: StatusResult): void {
    status.not_added.forEach(file => {
      files.push({ path: file, status: 'untracked', staged: false });
    });
  }

  /**
   * Crée un commit
   */
  async commit(repoPath: string, message: string, files?: string[]): Promise<GitCommitResponse> {
    const git = this.getGit(repoPath);

    // Stage les fichiers si spécifiés, sinon stage tout
    if (files && files.length > 0) {
      await git.add(files);
    } else {
      await git.add('.');
    }

    // Commit
    const result = await git.commit(message);

    // Récupère les infos du dernier commit
    const log = await git.log({ maxCount: 1 });
    const latestCommit = log.latest;

    if (!latestCommit) {
      throw new Error('Failed to retrieve commit information');
    }

    return {
      hash: latestCommit.hash,
      message: latestCommit.message,
      author: latestCommit.author_name,
      timestamp: new Date(latestCommit.date).getTime(),
    };
  }

  /**
   * Push vers remote
   */
  async push(repoPath: string, remote: string = 'origin', branch?: string): Promise<GitPushResponse> {
    const git = this.getGit(repoPath);

    // Détermine la branche actuelle si non spécifiée
    if (!branch) {
      const status = await git.status();
      branch = status.current || 'main';
    }

    // Push
    const result = await git.push(remote, branch);

    return {
      success: true,
      pushed: result.pushed?.length || 0,
    };
  }

  /**
   * Pull depuis remote
   */
  async pull(repoPath: string, remote: string = 'origin', branch?: string): Promise<void> {
    const git = this.getGit(repoPath);

    if (branch) {
      await git.pull(remote, branch);
    } else {
      await git.pull(remote);
    }
  }

  /**
   * Récupère les diffs
   */
  async diff(repoPath: string, path?: string, staged: boolean = false): Promise<GitDiffResponse> {
    const git = this.getGit(repoPath);

    let diffResult: string;

    if (staged) {
      // Diff des fichiers staged
      diffResult = path 
        ? await git.diff(['--cached', path])
        : await git.diff(['--cached']);
    } else {
      // Diff des fichiers non staged
      diffResult = path
        ? await git.diff([path])
        : await git.diff();
    }

    // Parse le diff pour extraire les changements par fichier
    const diffs = this.parseDiff(diffResult);

    return { diffs };
  }

  /**
   * Liste les branches
   */
  async branches(repoPath: string): Promise<BranchSummary> {
    const git = this.getGit(repoPath);
    return await git.branch();
  }

  /**
   * Crée une nouvelle branche
   */
  async createBranch(repoPath: string, branchName: string, checkout: boolean = true): Promise<void> {
    const git = this.getGit(repoPath);

    if (checkout) {
      await git.checkoutLocalBranch(branchName);
    } else {
      await git.branch([branchName]);
    }
  }

  /**
   * Change de branche
   */
  async checkout(repoPath: string, branchName: string): Promise<void> {
    const git = this.getGit(repoPath);
    await git.checkout(branchName);
  }

  /**
   * Récupère l'historique des commits
   */
  async log(repoPath: string, maxCount: number = 50): Promise<LogResult<DefaultLogFields>> {
    const git = this.getGit(repoPath);
    return await git.log({ maxCount });
  }

  /**
   * Annule les modifications d'un fichier
   */
  async discard(repoPath: string, filePath: string): Promise<void> {
    const git = this.getGit(repoPath);
    await git.checkout(['--', filePath]);
  }

  /**
   * Stage un fichier
   */
  async stage(repoPath: string, filePath: string): Promise<void> {
    const git = this.getGit(repoPath);
    await git.add(filePath);
  }

  /**
   * Unstage un fichier
   */
  async unstage(repoPath: string, filePath: string): Promise<void> {
    const git = this.getGit(repoPath);
    await git.reset(['HEAD', filePath]);
  }

  /**
   * Parse un diff Git en structure
   */
  private parseDiff(diffText: string): Array<{
    path: string;
    diff: string;
    additions: number;
    deletions: number;
  }> {
    const diffs: Array<{
      path: string;
      diff: string;
      additions: number;
      deletions: number;
    }> = [];

    if (!diffText || diffText.trim().length === 0) {
      return diffs;
    }

    // Split par fichier (commence par "diff --git")
    const fileDiffs = diffText.split(/(?=diff --git)/);

    for (const fileDiff of fileDiffs) {
      if (!fileDiff.trim()) continue;

      // Extrait le nom du fichier
      const pathMatch = fileDiff.match(/diff --git a\/(.*?) b\/(.*?)$/m);
      if (!pathMatch) continue;

      const path = pathMatch[2];

      // Compte les additions et deletions
      const lines = fileDiff.split('\n');
      let additions = 0;
      let deletions = 0;

      for (const line of lines) {
        if (line.startsWith('+') && !line.startsWith('+++')) {
          additions++;
        } else if (line.startsWith('-') && !line.startsWith('---')) {
          deletions++;
        }
      }

      diffs.push({
        path,
        diff: fileDiff,
        additions,
        deletions,
      });
    }

    return diffs;
  }

  /**
   * Nettoie les instances Git en cache
   */
  clearCache(repoPath?: string): void {
    if (repoPath) {
      this.gitInstances.delete(repoPath);
    } else {
      this.gitInstances.clear();
    }
  }
}

// Instance singleton
export const gitService = new GitService();

/**
 * MCP Service - Main Process
 * Service backend pour gérer les serveurs MCP (Model Context Protocol)
 * Découverte, installation, configuration et invocation de tools MCP
 */

import { EventEmitter } from 'events';
import { spawn, ChildProcess } from 'child_process';
import * as path from 'path';
import * as fs from 'fs/promises';
import * as os from 'os';

// ============================================================================
// Types
// ============================================================================

export type MCPServerStatus = 'installed' | 'available' | 'running' | 'error' | 'stopped';

export interface MCPServer {
  id: string;
  name: string;
  description: string;
  version?: string;
  author?: string;
  homepage?: string;
  status: MCPServerStatus;
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  transport: 'stdio' | 'http';
  tools?: MCPTool[];
  installedAt?: number;
  lastError?: string;
}

export interface MCPTool {
  name: string;
  description: string;
  inputSchema: {
    type: 'object';
    properties: Record<string, any>;
    required?: string[];
  };
}

export interface MCPToolInvocation {
  serverId: string;
  toolName: string;
  arguments: Record<string, any>;
}

export interface MCPToolResult {
  content: Array<{
    type: 'text' | 'image' | 'resource';
    text?: string;
    data?: string;
    mimeType?: string;
  }>;
  isError?: boolean;
}

export interface MCPPermission {
  serverId: string;
  toolName: string;
  granted: boolean;
  grantedAt?: number;
  grantedBy?: string;
}

interface MCPProcess {
  serverId: string;
  process: ChildProcess;
  messageId: number;
  pendingRequests: Map<number, {
    resolve: (value: any) => void;
    reject: (error: Error) => void;
  }>;
}

// ============================================================================
// MCP Registry
// ============================================================================

/**
 * Registry des serveurs MCP installés et disponibles
 */
class MCPRegistry {
  private servers = new Map<string, MCPServer>();
  private configPath: string;

  constructor(configPath?: string) {
    this.configPath = configPath || path.join(os.homedir(), '.cortex-ide', 'mcp-servers.json');
  }

  /**
   * Charge la configuration des serveurs MCP
   */
  async load(): Promise<void> {
    try {
      const data = await fs.readFile(this.configPath, 'utf-8');
      const config = JSON.parse(data);

      for (const server of config.servers || []) {
        this.servers.set(server.id, server);
      }

      console.log(`[MCPRegistry] Loaded ${this.servers.size} servers from config`);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        console.log('[MCPRegistry] No config file found, starting fresh');
        await this.save();
      } else {
        console.error('[MCPRegistry] Failed to load config:', error);
      }
    }
  }

  /**
   * Sauvegarde la configuration des serveurs MCP
   */
  async save(): Promise<void> {
    try {
      const configDir = path.dirname(this.configPath);
      await fs.mkdir(configDir, { recursive: true });

      const config = {
        version: '1.0.0',
        servers: Array.from(this.servers.values()),
      };

      await fs.writeFile(this.configPath, JSON.stringify(config, null, 2), 'utf-8');
      console.log('[MCPRegistry] Config saved');
    } catch (error) {
      console.error('[MCPRegistry] Failed to save config:', error);
      throw error;
    }
  }

  /**
   * Enregistre un nouveau serveur MCP
   */
  register(server: MCPServer): void {
    this.servers.set(server.id, server);
  }

  /**
   * Récupère un serveur par ID
   */
  getServer(id: string): MCPServer | undefined {
    return this.servers.get(id);
  }

  /**
   * Liste tous les serveurs
   */
  getAllServers(): MCPServer[] {
    return Array.from(this.servers.values());
  }

  /**
   * Liste les serveurs par statut
   */
  getServersByStatus(status: MCPServerStatus): MCPServer[] {
    return this.getAllServers().filter(s => s.status === status);
  }

  /**
   * Met à jour un serveur
   */
  updateServer(id: string, updates: Partial<MCPServer>): void {
    const server = this.servers.get(id);
    if (server) {
      this.servers.set(id, { ...server, ...updates });
    }
  }

  /**
   * Supprime un serveur
   */
  deleteServer(id: string): boolean {
    return this.servers.delete(id);
  }
}

// ============================================================================
// MCP Service
// ============================================================================

export class MCPService extends EventEmitter {
  private registry: MCPRegistry;
  private processes = new Map<string, MCPProcess>();
  private permissions = new Map<string, MCPPermission>();
  private permissionsPath: string;

  constructor(configPath?: string) {
    super();
    this.registry = new MCPRegistry(configPath);
    this.permissionsPath = path.join(os.homedir(), '.cortex-ide', 'mcp-permissions.json');
  }

  /**
   * Initialise le service MCP
   */
  async initialize(): Promise<void> {
    await this.registry.load();
    await this.loadPermissions();
    console.log('[MCPService] Initialized');
  }

  /**
   * Charge les permissions des tools MCP
   */
  private async loadPermissions(): Promise<void> {
    try {
      const data = await fs.readFile(this.permissionsPath, 'utf-8');
      const perms = JSON.parse(data);

      for (const perm of perms.permissions || []) {
        const key = `${perm.serverId}:${perm.toolName}`;
        this.permissions.set(key, perm);
      }

      console.log(`[MCPService] Loaded ${this.permissions.size} permissions`);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
        console.error('[MCPService] Failed to load permissions:', error);
      }
    }
  }

  /**
   * Sauvegarde les permissions
   */
  private async savePermissions(): Promise<void> {
    try {
      const configDir = path.dirname(this.permissionsPath);
      await fs.mkdir(configDir, { recursive: true });

      const config = {
        version: '1.0.0',
        permissions: Array.from(this.permissions.values()),
      };

      await fs.writeFile(this.permissionsPath, JSON.stringify(config, null, 2), 'utf-8');
    } catch (error) {
      console.error('[MCPService] Failed to save permissions:', error);
    }
  }

  /**
   * Installe un nouveau serveur MCP
   */
  async installServer(server: Omit<MCPServer, 'status' | 'installedAt'>): Promise<MCPServer> {
    const fullServer: MCPServer = {
      ...server,
      status: 'installed',
      installedAt: Date.now(),
    };

    this.registry.register(fullServer);
    await this.registry.save();

    this.emit('server:installed', fullServer);
    return fullServer;
  }

  /**
   * Démarre un serveur MCP
   */
  async startServer(serverId: string): Promise<void> {
    const server = this.registry.getServer(serverId);
    if (!server) {
      throw new Error(`Server ${serverId} not found`);
    }

    if (this.processes.has(serverId)) {
      console.log(`[MCPService] Server ${serverId} already running`);
      return;
    }

    if (!server.command) {
      throw new Error(`Server ${serverId} has no command configured`);
    }

    try {
      const process = spawn(server.command, server.args || [], {
        env: { ...process.env, ...server.env },
        stdio: ['pipe', 'pipe', 'pipe'],
      });

      const mcpProcess: MCPProcess = {
        serverId,
        process,
        messageId: 0,
        pendingRequests: new Map(),
      };

      this.processes.set(serverId, mcpProcess);

      // Setup JSON-RPC communication
      let buffer = '';
      process.stdout?.on('data', (data) => {
        buffer += data.toString();
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.trim()) {
            try {
              const message = JSON.parse(line);
              this.handleServerMessage(serverId, message, mcpProcess);
            } catch (error) {
              console.error(`[MCPService] Failed to parse message from ${serverId}:`, error);
            }
          }
        }
      });

      process.stderr?.on('data', (data) => {
        console.error(`[MCPService] ${serverId} stderr:`, data.toString());
      });

      process.on('error', (error) => {
        console.error(`[MCPService] ${serverId} process error:`, error);
        this.registry.updateServer(serverId, { status: 'error', lastError: error.message });
        this.processes.delete(serverId);
        this.emit('server:error', { serverId, error });
      });

      process.on('exit', (code) => {
        console.log(`[MCPService] ${serverId} exited with code ${code}`);
        this.processes.delete(serverId);
        this.registry.updateServer(serverId, { status: 'stopped' });
        this.emit('server:stopped', serverId);
      });

      // Initialize the server
      await this.sendServerRequest(mcpProcess, 'initialize', {
        protocolVersion: '2024-11-05',
        capabilities: {
          tools: {},
        },
        clientInfo: {
          name: 'Cortex IDE',
          version: '1.0.0',
        },
      });

      // Discover tools
      const toolsResponse = await this.sendServerRequest(mcpProcess, 'tools/list', {});
      if (toolsResponse.tools) {
        this.registry.updateServer(serverId, { 
          status: 'running',
          tools: toolsResponse.tools 
        });
      }

      this.emit('server:started', serverId);
      console.log(`[MCPService] Server ${serverId} started successfully`);
    } catch (error) {
      this.registry.updateServer(serverId, { 
        status: 'error',
        lastError: error instanceof Error ? error.message : 'Unknown error'
      });
      throw error;
    }
  }

  /**
   * Arrête un serveur MCP
   */
  async stopServer(serverId: string): Promise<void> {
    const mcpProcess = this.processes.get(serverId);
    if (!mcpProcess) {
      console.log(`[MCPService] Server ${serverId} not running`);
      return;
    }

    try {
      // Send shutdown request
      await this.sendServerRequest(mcpProcess, 'shutdown', {});
      mcpProcess.process.kill('SIGTERM');

      // Wait for graceful shutdown
      await new Promise<void>((resolve) => {
        const timeout = setTimeout(() => {
          mcpProcess.process.kill('SIGKILL');
          resolve();
        }, 5000);

        mcpProcess.process.once('exit', () => {
          clearTimeout(timeout);
          resolve();
        });
      });

      this.processes.delete(serverId);
      this.registry.updateServer(serverId, { status: 'stopped' });
      this.emit('server:stopped', serverId);
    } catch (error) {
      console.error(`[MCPService] Failed to stop server ${serverId}:`, error);
      throw error;
    }
  }

  /**
   * Envoie une requête JSON-RPC au serveur
   */
  private async sendServerRequest(
    mcpProcess: MCPProcess,
    method: string,
    params: any
  ): Promise<any> {
    return new Promise((resolve, reject) => {
      const id = ++mcpProcess.messageId;

      const request = {
        jsonrpc: '2.0',
        id,
        method,
        params,
      };

      mcpProcess.pendingRequests.set(id, { resolve, reject });

      const message = JSON.stringify(request) + '\n';
      mcpProcess.process.stdin?.write(message);

      // Timeout after 30 seconds
      setTimeout(() => {
        if (mcpProcess.pendingRequests.has(id)) {
          mcpProcess.pendingRequests.delete(id);
          reject(new Error(`Request ${method} timed out`));
        }
      }, 30000);
    });
  }

  /**
   * Gère les messages reçus du serveur
   */
  private handleServerMessage(serverId: string, message: any, mcpProcess: MCPProcess): void {
    if (message.id !== undefined && mcpProcess.pendingRequests.has(message.id)) {
      const { resolve, reject } = mcpProcess.pendingRequests.get(message.id)!;
      mcpProcess.pendingRequests.delete(message.id);

      if (message.error) {
        reject(new Error(message.error.message || 'Unknown error'));
      } else {
        resolve(message.result);
      }
    } else if (message.method) {
      // Handle notifications from server
      this.emit('server:notification', { serverId, method: message.method, params: message.params });
    }
  }

  /**
   * Invoque un tool MCP
   */
  async invokeTool(invocation: MCPToolInvocation): Promise<MCPToolResult> {
    const { serverId, toolName, arguments: args } = invocation;

    // Vérifier les permissions
    const permKey = `${serverId}:${toolName}`;
    const permission = this.permissions.get(permKey);

    if (!permission || !permission.granted) {
      throw new Error(`Permission denied for tool ${toolName} on server ${serverId}`);
    }

    // Vérifier que le serveur est en cours d'exécution
    let mcpProcess = this.processes.get(serverId);
    if (!mcpProcess) {
      // Démarrer le serveur si nécessaire
      await this.startServer(serverId);
      mcpProcess = this.processes.get(serverId);

      if (!mcpProcess) {
        throw new Error(`Failed to start server ${serverId}`);
      }
    }

    try {
      const result = await this.sendServerRequest(mcpProcess, 'tools/call', {
        name: toolName,
        arguments: args,
      });

      this.emit('tool:invoked', { serverId, toolName, result });
      return result;
    } catch (error) {
      console.error(`[MCPService] Tool invocation failed:`, error);
      throw error;
    }
  }

  /**
   * Découvre les tools disponibles sur un serveur
   */
  async discoverTools(serverId: string): Promise<MCPTool[]> {
    const mcpProcess = this.processes.get(serverId);
    if (!mcpProcess) {
      throw new Error(`Server ${serverId} not running`);
    }

    const response = await this.sendServerRequest(mcpProcess, 'tools/list', {});
    const tools = response.tools || [];

    this.registry.updateServer(serverId, { tools });
    await this.registry.save();

    return tools;
  }

  /**
   * Accorde une permission pour un tool
   */
  async grantPermission(serverId: string, toolName: string, grantedBy?: string): Promise<void> {
    const key = `${serverId}:${toolName}`;

    const permission: MCPPermission = {
      serverId,
      toolName,
      granted: true,
      grantedAt: Date.now(),
      grantedBy,
    };

    this.permissions.set(key, permission);
    await this.savePermissions();

    this.emit('permission:granted', permission);
  }

  /**
   * Révoque une permission pour un tool
   */
  async revokePermission(serverId: string, toolName: string): Promise<void> {
    const key = `${serverId}:${toolName}`;
    this.permissions.delete(key);
    await this.savePermissions();

    this.emit('permission:revoked', { serverId, toolName });
  }

  /**
   * Liste toutes les permissions
   */
  getAllPermissions(): MCPPermission[] {
    return Array.from(this.permissions.values());
  }

  /**
   * Vérifie si un tool a la permission
   */
  hasPermission(serverId: string, toolName: string): boolean {
    const key = `${serverId}:${toolName}`;
    const permission = this.permissions.get(key);
    return permission?.granted === true;
  }

  /**
   * Liste tous les serveurs
   */
  getAllServers(): MCPServer[] {
    return this.registry.getAllServers();
  }

  /**
   * Récupère un serveur par ID
   */
  getServer(serverId: string): MCPServer | undefined {
    return this.registry.getServer(serverId);
  }

  /**
   * Désinstalle un serveur
   */
  async uninstallServer(serverId: string): Promise<void> {
    // Arrêter le serveur s'il tourne
    if (this.processes.has(serverId)) {
      await this.stopServer(serverId);
    }

    // Supprimer toutes les permissions associées
    const permsToDelete = Array.from(this.permissions.keys())
      .filter(key => key.startsWith(`${serverId}:`));

    for (const key of permsToDelete) {
      this.permissions.delete(key);
    }
    await this.savePermissions();

    // Supprimer le serveur du registry
    this.registry.deleteServer(serverId);
    await this.registry.save();

    this.emit('server:uninstalled', serverId);
  }

  /**
   * Nettoie tous les processus
   */
  async cleanup(): Promise<void> {
    const serverIds = Array.from(this.processes.keys());

    for (const serverId of serverIds) {
      try {
        await this.stopServer(serverId);
      } catch (error) {
        console.error(`[MCPService] Failed to stop server ${serverId}:`, error);
      }
    }

    this.removeAllListeners();
  }
}

// ============================================================================
// Singleton Instance
// ============================================================================

let mcpServiceInstance: MCPService | null = null;

/**
 * Récupère ou crée l'instance du service MCP
 */
export function getMCPService(): MCPService {
  if (!mcpServiceInstance) {
    mcpServiceInstance = new MCPService();
  }
  return mcpServiceInstance;
}

/**
 * Réinitialise l'instance du service MCP
 */
export async function resetMCPService(): Promise<void> {
  if (mcpServiceInstance) {
    await mcpServiceInstance.cleanup();
    mcpServiceInstance = null;
  }
}

/**
 * Auto-update manager using electron-updater
 * Handles checking, downloading, and installing updates
 */

import { autoUpdater } from 'electron-updater';
import { BrowserWindow, dialog } from 'electron';
import log from 'electron-log';

// Configure logger
autoUpdater.logger = log;
log.transports.file.level = 'info';

export interface UpdaterConfig {
  checkOnStart: boolean;
  checkInterval: number; // in milliseconds
  autoDownload: boolean;
  autoInstallOnAppQuit: boolean;
}

const DEFAULT_CONFIG: UpdaterConfig = {
  checkOnStart: true,
  checkInterval: 4 * 60 * 60 * 1000, // 4 hours
  autoDownload: true,
  autoInstallOnAppQuit: true,
};

export class UpdateManager {
  private config: UpdaterConfig;
  private mainWindow: BrowserWindow | null = null;
  private checkIntervalId: NodeJS.Timeout | null = null;

  constructor(config: Partial<UpdaterConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.setupAutoUpdater();
  }

  /**
   * Initialize the update manager with the main window
   */
  initialize(window: BrowserWindow): void {
    this.mainWindow = window;

    if (this.config.checkOnStart) {
      // Check for updates 3 seconds after app start
      setTimeout(() => {
        this.checkForUpdates();
      }, 3000);
    }

    // Set up periodic checks
    if (this.config.checkInterval > 0) {
      this.checkIntervalId = setInterval(() => {
        this.checkForUpdates();
      }, this.config.checkInterval);
    }
  }

  /**
   * Setup auto-updater event handlers
   */
  private setupAutoUpdater(): void {
    // Configure auto-updater
    autoUpdater.autoDownload = this.config.autoDownload;
    autoUpdater.autoInstallOnAppQuit = this.config.autoInstallOnAppQuit;

    // When checking for updates
    autoUpdater.on('checking-for-update', () => {
      log.info('Checking for updates...');
      this.sendToRenderer('update:checking');
    });

    // When update is available
    autoUpdater.on('update-available', (info) => {
      log.info('Update available:', info.version);
      this.sendToRenderer('update:available', {
        version: info.version,
        releaseDate: info.releaseDate,
        releaseName: info.releaseName,
        releaseNotes: info.releaseNotes,
      });
    });

    // When no update is available
    autoUpdater.on('update-not-available', (info) => {
      log.info('Update not available. Current version:', info.version);
      this.sendToRenderer('update:not-available', {
        version: info.version,
      });
    });

    // When error occurs
    autoUpdater.on('error', (error) => {
      log.error('Error in auto-updater:', error);
      this.sendToRenderer('update:error', {
        message: error.message,
      });
    });

    // Download progress
    autoUpdater.on('download-progress', (progressObj) => {
      const logMessage = `Download speed: ${progressObj.bytesPerSecond} - Downloaded ${progressObj.percent}% (${progressObj.transferred}/${progressObj.total})`;
      log.info(logMessage);

      this.sendToRenderer('update:download-progress', {
        percent: Math.round(progressObj.percent),
        transferred: progressObj.transferred,
        total: progressObj.total,
        bytesPerSecond: progressObj.bytesPerSecond,
      });
    });

    // When update is downloaded
    autoUpdater.on('update-downloaded', (info) => {
      log.info('Update downloaded:', info.version);
      this.sendToRenderer('update:downloaded', {
        version: info.version,
        releaseDate: info.releaseDate,
        releaseName: info.releaseName,
      });

      // Show notification to user
      this.notifyUpdateDownloaded(info.version);
    });
  }

  /**
   * Manually check for updates
   */
  async checkForUpdates(): Promise<void> {
    if (process.env.NODE_ENV === 'development') {
      log.info('Skipping update check in development mode');
      return;
    }

    try {
      await autoUpdater.checkForUpdates();
    } catch (error) {
      log.error('Failed to check for updates:', error);
    }
  }

  /**
   * Download update manually
   */
  async downloadUpdate(): Promise<void> {
    try {
      await autoUpdater.downloadUpdate();
    } catch (error) {
      log.error('Failed to download update:', error);
      throw error;
    }
  }

  /**
   * Install update and restart app
   */
  quitAndInstall(): void {
    // setImmediate ensures the app quits after the event loop finishes
    setImmediate(() => {
      autoUpdater.quitAndInstall(false, true);
    });
  }

  /**
   * Show native dialog for update downloaded
   */
  private notifyUpdateDownloaded(version: string): void {
    if (!this.mainWindow) return;

    dialog
      .showMessageBox(this.mainWindow, {
        type: 'info',
        title: 'Update Available',
        message: `A new version (${version}) has been downloaded.`,
        detail: 'The update will be installed when you quit and restart the application.',
        buttons: ['Restart Now', 'Later'],
        defaultId: 1,
        cancelId: 1,
      })
      .then((result) => {
        if (result.response === 0) {
          this.quitAndInstall();
        }
      });
  }

  /**
   * Send update event to renderer process
   */
  private sendToRenderer(channel: string, data?: any): void {
    if (this.mainWindow && !this.mainWindow.isDestroyed()) {
      this.mainWindow.webContents.send(channel, data);
    }
  }

  /**
   * Clean up resources
   */
  destroy(): void {
    if (this.checkIntervalId) {
      clearInterval(this.checkIntervalId);
      this.checkIntervalId = null;
    }
    this.mainWindow = null;
  }
}

// Export singleton instance
export const updateManager = new UpdateManager();

