/**
 * Error Boundary - Catch and report React errors
 */

import * as React from 'react';
import { logger } from '@cortex-ide/shared/logger';
import type { ErrorReport } from '@cortex-ide/shared/types/debug';
import { Button } from './ui/button';
import { FiAlertTriangle, FiRefreshCw, FiCopy } from 'react-icons/fi';

interface ErrorBoundaryProps {
  children: React.ReactNode;
  fallback?: (error: Error, errorInfo: React.ErrorInfo, reset: () => void) => React.ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: React.ErrorInfo | null;
}

export class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null
    };
  }

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return {
      hasError: true,
      error
    };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    this.setState({ errorInfo });

    // Log error
    logger.error('react', 'Component error caught by boundary', {
      error: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack
    });

    // Report error
    this.reportError(error, errorInfo);
  }

  private reportError(error: Error, errorInfo: React.ErrorInfo) {
    const report: ErrorReport = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
      timestamp: Date.now(),
      message: error.message,
      stack: error.stack || '',
      componentStack: errorInfo.componentStack || undefined,
      source: 'renderer',
      context: {
        userAgent: navigator.userAgent,
        location: window.location.href
      },
      severity: 'high'
    };

    // Could send to error tracking service here (Sentry, etc.)
    console.error('Error Report:', report);
  }

  private handleReset = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null
    });
  };

  private handleCopyError = () => {
    const { error, errorInfo } = this.state;
    if (!error) return;

    const errorText = `
Error: ${error.message}

Stack Trace:
${error.stack}

Component Stack:
${errorInfo?.componentStack}
    `.trim();

    navigator.clipboard.writeText(errorText);
  };

  render() {
    const { hasError, error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (hasError && error) {
      if (fallback) {
        return fallback(error, errorInfo!, this.handleReset);
      }

      return (
        <div className="h-full flex items-center justify-center bg-background p-8">
          <div className="max-w-2xl w-full">
            <div className="bg-red-500/10 border-2 border-red-500/50 rounded-lg p-6">
              {/* Header */}
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 rounded-full bg-red-500/20 flex items-center justify-center flex-shrink-0">
                  <FiAlertTriangle className="w-6 h-6 text-red-500" />
                </div>
                <div className="flex-1">
                  <h2 className="text-xl font-bold text-red-500 mb-1">
                    Something went wrong
                  </h2>
                  <p className="text-sm text-text-secondary">
                    An unexpected error occurred in the application
                  </p>
                </div>
              </div>

              {/* Error Message */}
              <div className="bg-background rounded border border-border p-4 mb-4">
                <div className="text-sm font-medium text-red-400 mb-2">
                  {error.message}
                </div>
                {error.stack && (
                  <pre className="text-xs text-text-secondary overflow-auto max-h-40 font-mono">
                    {error.stack}
                  </pre>
                )}
              </div>

              {/* Component Stack */}
              {errorInfo?.componentStack && (
                <details className="mb-4">
                  <summary className="text-sm font-medium text-text cursor-pointer hover:text-accent">
                    Component Stack
                  </summary>
                  <pre className="mt-2 text-xs text-text-secondary overflow-auto max-h-40 bg-background rounded border border-border p-3 font-mono">
                    {errorInfo.componentStack}
                  </pre>
                </details>
              )}

              {/* Actions */}
              <div className="flex gap-2">
                <Button
                  variant="default"
                  onClick={this.handleReset}
                  className="flex-1"
                >
                  <FiRefreshCw className="w-4 h-4 mr-2" />
                  Try Again
                </Button>
                <Button
                  variant="outline"
                  onClick={this.handleCopyError}
                >
                  <FiCopy className="w-4 h-4 mr-2" />
                  Copy Error
                </Button>
              </div>

              <p className="text-xs text-text-secondary mt-4 text-center">
                If this problem persists, please report it to the development team
              </p>
            </div>
          </div>
        </div>
      );
    }

    return children;
  }
}

/**
 * Update Notification Component
 * Displays notifications for app updates
 */

import { useEffect, useState } from 'react';
import { Button } from './ui/button';
import { Progress } from './ui/progress';

interface UpdateInfo {
  version: string;
  releaseDate?: string;
  releaseName?: string;
  releaseNotes?: string;
}

interface DownloadProgress {
  percent: number;
  transferred: number;
  total: number;
  bytesPerSecond: number;
}

type UpdateState = 
  | { type: 'idle' }
  | { type: 'checking' }
  | { type: 'available'; info: UpdateInfo }
  | { type: 'downloading'; progress: DownloadProgress }
  | { type: 'downloaded'; info: UpdateInfo }
  | { type: 'error'; message: string };

export function UpdateNotification() {
  const [updateState, setUpdateState] = useState<UpdateState>({ type: 'idle' });
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    // Listen for update events from main process
    const handleChecking = () => {
      setUpdateState({ type: 'checking' });
      setDismissed(false);
    };

    const handleAvailable = (_: any, info: UpdateInfo) => {
      setUpdateState({ type: 'available', info });
      setDismissed(false);
    };

    const handleNotAvailable = () => {
      setUpdateState({ type: 'idle' });
    };

    const handleDownloadProgress = (_: any, progress: DownloadProgress) => {
      setUpdateState({ type: 'downloading', progress });
    };

    const handleDownloaded = (_: any, info: UpdateInfo) => {
      setUpdateState({ type: 'downloaded', info });
      setDismissed(false);
    };

    const handleError = (_: any, error: { message: string }) => {
      setUpdateState({ type: 'error', message: error.message });
    };

    // Register listeners
    window.electron.on('update:checking', handleChecking);
    window.electron.on('update:available', handleAvailable);
    window.electron.on('update:not-available', handleNotAvailable);
    window.electron.on('update:download-progress', handleDownloadProgress);
    window.electron.on('update:downloaded', handleDownloaded);
    window.electron.on('update:error', handleError);

    // Cleanup
    return () => {
      window.electron.removeListener('update:checking', handleChecking);
      window.electron.removeListener('update:available', handleAvailable);
      window.electron.removeListener('update:not-available', handleNotAvailable);
      window.electron.removeListener('update:download-progress', handleDownloadProgress);
      window.electron.removeListener('update:downloaded', handleDownloaded);
      window.electron.removeListener('update:error', handleError);
    };
  }, []);

  const handleCheckForUpdates = async () => {
    await window.electron.invoke('update:check');
  };

  const handleDownload = async () => {
    await window.electron.invoke('update:download');
  };

  const handleInstall = () => {
    window.electron.invoke('update:install');
  };

  const formatBytes = (bytes: number): string => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${(bytes / Math.pow(k, i)).toFixed(1)} ${sizes[i]}`;
  };

  const formatSpeed = (bytesPerSecond: number): string => {
    return `${formatBytes(bytesPerSecond)}/s`;
  };

  // Don't show if dismissed or idle
  if (dismissed || updateState.type === 'idle') {
    return null;
  }

  return (
    <div className="fixed bottom-6 right-6 z-50 max-w-md">
      <div className="rounded-lg border border-border bg-background/95 backdrop-blur shadow-lg">
        <div className="p-4">
          {updateState.type === 'checking' && (
            <div className="flex items-center gap-3">
              <div className="h-4 w-4 animate-spin rounded-full border-2 border-primary border-t-transparent" />
              <span className="text-sm text-muted-foreground">Checking for updates...</span>
            </div>
          )}

          {updateState.type === 'available' && (
            <div className="space-y-3">
              <div>
                <h4 className="font-medium">Update Available</h4>
                <p className="text-sm text-muted-foreground mt-1">
                  Version {updateState.info.version} is available
                </p>
                {updateState.info.releaseName && (
                  <p className="text-xs text-muted-foreground mt-1">
                    {updateState.info.releaseName}
                  </p>
                )}
              </div>
              <div className="flex gap-2">
                <Button size="sm" onClick={handleDownload}>
                  Download
                </Button>
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={() => setDismissed(true)}
                >
                  Later
                </Button>
              </div>
            </div>
          )}

          {updateState.type === 'downloading' && (
            <div className="space-y-3">
              <div>
                <h4 className="font-medium">Downloading Update</h4>
                <p className="text-sm text-muted-foreground mt-1">
                  {updateState.progress.percent}% complete
                </p>
              </div>
              <Progress value={updateState.progress.percent} className="h-2" />
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>{formatBytes(updateState.progress.transferred)} / {formatBytes(updateState.progress.total)}</span>
                <span>{formatSpeed(updateState.progress.bytesPerSecond)}</span>
              </div>
            </div>
          )}

          {updateState.type === 'downloaded' && (
            <div className="space-y-3">
              <div>
                <h4 className="font-medium">Update Ready</h4>
                <p className="text-sm text-muted-foreground mt-1">
                  Version {updateState.info.version} has been downloaded
                </p>
              </div>
              <div className="flex gap-2">
                <Button size="sm" onClick={handleInstall}>
                  Restart & Install
                </Button>
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={() => setDismissed(true)}
                >
                  Later
                </Button>
              </div>
            </div>
          )}

          {updateState.type === 'error' && (
            <div className="space-y-3">
              <div>
                <h4 className="font-medium text-destructive">Update Error</h4>
                <p className="text-sm text-muted-foreground mt-1">
                  {updateState.message}
                </p>
              </div>
              <div className="flex gap-2">
                <Button size="sm" variant="outline" onClick={handleCheckForUpdates}>
                  Retry
                </Button>
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={() => setDismissed(true)}
                >
                  Dismiss
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

