/**
 * Debug context provider - Manage debug mode state
 */

import * as React from 'react';
import type { DebugSettings } from '@cortex-ide/shared/types/debug';

interface DebugContextValue {
  enabled: boolean;
  settings: DebugSettings | null;
  toggleDebugMode: () => void;
  updateSettings: (settings: Partial<DebugSettings>) => Promise<void>;
  showDebugPanel: boolean;
  setShowDebugPanel: (show: boolean) => void;
}

const DebugContext = React.createContext<DebugContextValue | null>(null);

export function DebugProvider({ children }: { children: React.ReactNode }) {
  const [settings, setSettings] = React.useState<DebugSettings | null>(null);
  const [showDebugPanel, setShowDebugPanel] = React.useState(false);

  // Load initial settings
  React.useEffect(() => {
    loadSettings();
  }, []);

  // Persist debug panel state
  React.useEffect(() => {
    const stored = localStorage.getItem('debug:panel-visible');
    if (stored) {
      setShowDebugPanel(stored === 'true');
    }
  }, []);

  React.useEffect(() => {
    localStorage.setItem('debug:panel-visible', String(showDebugPanel));
  }, [showDebugPanel]);

  const loadSettings = async () => {
    try {
      const result = await window.electron.invoke('debug:get-settings');
      setSettings(result);
    } catch (error) {
      console.error('Failed to load debug settings:', error);
    }
  };

  const toggleDebugMode = async () => {
    if (!settings) return;

    const newEnabled = !settings.enabled;
    await updateSettings({ enabled: newEnabled });
  };

  const updateSettings = async (partial: Partial<DebugSettings>) => {
    if (!settings) return;

    try {
      await window.electron.invoke('debug:update-settings', partial);
      setSettings({ ...settings, ...partial });
    } catch (error) {
      console.error('Failed to update debug settings:', error);
      throw error;
    }
  };

  const value: DebugContextValue = {
    enabled: settings?.enabled || false,
    settings,
    toggleDebugMode,
    updateSettings,
    showDebugPanel,
    setShowDebugPanel
  };

  return (
    <DebugContext.Provider value={value}>
      {children}
    </DebugContext.Provider>
  );
}

export function useDebug(): DebugContextValue {
  const context = React.useContext(DebugContext);
  if (!context) {
    throw new Error('useDebug must be used within DebugProvider');
  }
  return context;
}

/**
 * Keyboard Shortcuts Hook - Global keyboard shortcuts handler
 */

import { useEffect } from 'react';
import { useEditorStore } from '../store/editor-store';

export const useKeyboardShortcuts = () => {
  const { closeTab, closeAllTabs, getActiveTab, hasUnsavedChanges } = useEditorStore();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
      const isCtrlOrCmd = isMac ? e.metaKey : e.ctrlKey;

      // Ctrl/Cmd + W - Close active tab
      if (isCtrlOrCmd && e.key === 'w') {
        e.preventDefault();
        const activeTab = getActiveTab();
        if (activeTab) {
          if (activeTab.isDirty) {
            const confirmed = confirm(
              `File "${activeTab.path}" has unsaved changes. Close anyway?`
            );
            if (!confirmed) return;
          }
          closeTab(activeTab.id);
        }
      }

      // Ctrl/Cmd + Shift + W - Close all tabs
      if (isCtrlOrCmd && e.shiftKey && e.key === 'W') {
        e.preventDefault();
        if (hasUnsavedChanges()) {
          const confirmed = confirm(
            'Some files have unsaved changes. Close all tabs anyway?'
          );
          if (!confirmed) return;
        }
        closeAllTabs();
      }

      // Ctrl/Cmd + S is handled in EditorView.tsx
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [closeTab, closeAllTabs, getActiveTab, hasUnsavedChanges]);
};

/**
 * React Performance Optimizations - Composants et hooks optimisés
 */

import React, { useCallback, useMemo, useRef, useEffect } from 'react';

/**
 * Virtual Scrolling Component - Pour listes longues
 */
interface VirtualListProps<T> {
  items: T[];
  itemHeight: number;
  containerHeight: number;
  renderItem: (item: T, index: number) => React.ReactNode;
  overscan?: number;
  className?: string;
}

export function VirtualList<T>({
  items,
  itemHeight,
  containerHeight,
  renderItem,
  overscan = 5,
  className = ''
}: VirtualListProps<T>) {
  const [scrollTop, setScrollTop] = React.useState(0);
  const scrollRef = useRef<HTMLDivElement>(null);

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  const { visibleItems, startIndex, offsetY } = useMemo(() => {
    const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
    const endIndex = Math.min(
      items.length - 1,
      Math.ceil((scrollTop + containerHeight) / itemHeight) + overscan
    );

    const visibleItems = items.slice(startIndex, endIndex + 1);
    const offsetY = startIndex * itemHeight;

    return { visibleItems, startIndex, offsetY };
  }, [items, itemHeight, containerHeight, scrollTop, overscan]);

  const totalHeight = items.length * itemHeight;

  return (
    <div
      ref={scrollRef}
      className={className}
      style={{ height: containerHeight, overflow: 'auto' }}
      onScroll={handleScroll}
    >
      <div style={{ height: totalHeight, position: 'relative' }}>
        <div style={{ transform: `translateY(${offsetY}px)` }}>
          {visibleItems.map((item, i) => (
            <div key={startIndex + i} style={{ height: itemHeight }}>
              {renderItem(item, startIndex + i)}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * Debounced value hook
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = React.useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

/**
 * Throttled callback hook
 */
export function useThrottle<T extends (...args: any[]) => any>(
  callback: T,
  delay: number
): T {
  const lastRun = useRef(Date.now());
  const timeoutRef = useRef<NodeJS.Timeout>();

  return useCallback(
    ((...args: any[]) => {
      const now = Date.now();
      const timeSinceLastRun = now - lastRun.current;

      if (timeSinceLastRun >= delay) {
        callback(...args);
        lastRun.current = now;
      } else {
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
        timeoutRef.current = setTimeout(() => {
          callback(...args);
          lastRun.current = Date.now();
        }, delay - timeSinceLastRun);
      }
    }) as T,
    [callback, delay]
  );
}

/**
 * Memoized component wrapper
 */
export const memo = React.memo;

/**
 * Web Worker Hook - Pour calculs intensifs
 */
export function useWebWorker<T, R>(
  workerFunction: (data: T) => R
): (data: T) => Promise<R> {
  const workerRef = useRef<Worker | null>(null);

  useEffect(() => {
    // Create worker from function
    const workerCode = `
      self.onmessage = function(e) {
        const result = (${workerFunction.toString()})(e.data);
        self.postMessage(result);
      };
    `;
    const blob = new Blob([workerCode], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(blob);
    workerRef.current = new Worker(workerUrl);

    return () => {
      if (workerRef.current) {
        workerRef.current.terminate();
        URL.revokeObjectURL(workerUrl);
      }
    };
  }, [workerFunction]);

  return useCallback(
    (data: T): Promise<R> => {
      return new Promise((resolve, reject) => {
        if (!workerRef.current) {
          reject(new Error('Worker not initialized'));
          return;
        }

        const handleMessage = (e: MessageEvent<R>) => {
          resolve(e.data);
          workerRef.current?.removeEventListener('message', handleMessage);
        };

        const handleError = (error: ErrorEvent) => {
          reject(error);
          workerRef.current?.removeEventListener('error', handleError);
        };

        workerRef.current.addEventListener('message', handleMessage);
        workerRef.current.addEventListener('error', handleError);
        workerRef.current.postMessage(data);
      });
    },
    []
  );
}

/**
 * Intersection Observer Hook - Pour lazy loading
 */
export function useIntersectionObserver(
  ref: React.RefObject<Element>,
  options?: IntersectionObserverInit
): boolean {
  const [isIntersecting, setIsIntersecting] = React.useState(false);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);
    }, options);

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, [ref, options]);

  return isIntersecting;
}

/**
 * Previous value hook
 */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T>();

  useEffect(() => {
    ref.current = value;
  }, [value]);

  return ref.current;
}

/**
 * Mounted state hook
 */
export function useIsMounted(): () => boolean {
  const isMountedRef = useRef(true);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  return useCallback(() => isMountedRef.current, []);
}

/**
 * Async effect hook with cleanup
 */
export function useAsyncEffect(
  effect: () => Promise<void | (() => void)>,
  deps: React.DependencyList
): void {
  useEffect(() => {
    let cleanup: void | (() => void);
    let cancelled = false;

    (async () => {
      if (!cancelled) {
        cleanup = await effect();
      }
    })();

    return () => {
      cancelled = true;
      if (typeof cleanup === 'function') {
        cleanup();
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

/**
 * Event listener hook
 */
export function useEventListener<K extends keyof WindowEventMap>(
  eventName: K,
  handler: (event: WindowEventMap[K]) => void,
  element: Window | Element = window,
  options?: boolean | AddEventListenerOptions
): void {
  const savedHandler = useRef(handler);

  useEffect(() => {
    savedHandler.current = handler;
  }, [handler]);

  useEffect(() => {
    const eventListener = (event: Event) => savedHandler.current(event as WindowEventMap[K]);
    element.addEventListener(eventName, eventListener, options);
    return () => {
      element.removeEventListener(eventName, eventListener, options);
    };
  }, [eventName, element, options]);
}

/**
 * Local storage hook with sync
 */
export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((val: T) => T)) => void] {
  const [storedValue, setStoredValue] = React.useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  const setValue = useCallback(
    (value: T | ((val: T) => T)) => {
      try {
        const valueToStore = value instanceof Function ? value(storedValue) : value;
        setStoredValue(valueToStore);
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      } catch (error) {
        console.error(error);
      }
    },
    [key, storedValue]
  );

  return [storedValue, setValue];
}

