// ============================================================================
// API Access
// ============================================================================

/**
 * Get the Cortex API from window object
 */
function getAPI(): CortexAPI {
  if (!window.cortex) {
    throw new Error('Cortex API not available. Make sure preload script is loaded.');
  }
  return window.cortex;
}

// ============================================================================
// Error Handling
// ============================================================================

export class IPCError extends Error {
  constructor(
    public code: string,
    message: string,
    public details?: unknown
  ) {
    super(message);
    this.name = 'IPCError';
  }
}

/**
 * Unwrap IPC response and throw on error
 */
function unwrapResponse<T>(response: IPCResponse<T>): T {
  if (response.success) {
    return response.data;
  }

  throw new IPCError(
    response.error.code,
    response.error.message,
    response.error.details
  );
}

// ============================================================================
// Filesystem API
// ============================================================================

export const filesystem = {
  /**
   * Read file contents
   */
  async readFile(path: string, encoding?: BufferEncoding): Promise<ReadFileResponse> {
    const api = getAPI();
    const response = await api.fs.readFile({ path, encoding });
    return unwrapResponse(response);
  },

  /**
   * Write file contents
   */
  async writeFile(path: string, content: string, encoding?: BufferEncoding): Promise<WriteFileResponse> {
    const api = getAPI();
    const response = await api.fs.writeFile({ path, content, encoding });
    return unwrapResponse(response);
  },

  /**
   * Read directory contents
   */
  async readDir(path: string, recursive?: boolean): Promise<ReadDirResponse> {
    const api = getAPI();
    const response = await api.fs.readDir({ path, recursive });
    return unwrapResponse(response);
  },

  /**
   * Watch file/directory for changes
   */
  async watch(path: string, watchId: string): Promise<void> {
    const api = getAPI();
    await api.fs.watch(path, watchId);
  },

  /**
   * Stop watching file/directory
   */
  async unwatch(watchId: string): Promise<void> {
    const api = getAPI();
    await api.fs.unwatch(watchId);
  },

  /**
   * Listen to file change events
   */
  onFileChange(callback: (event: FileChangeEvent) => void): () => void {
    const api = getAPI();
    return api.fs.onFileChange(callback);
  },
};

