export const git = {
  /**
   * Get repository status
   */
  async status(repoPath: string): Promise<GitStatusResponse> {
    const api = getAPI();
    const response = await api.git.status({ repoPath });
    return unwrapResponse(response);
  },

  /**
   * Commit changes
   */
