// Usage Limit Card Component
interface UsageLimitCardProps {
  title: string;
  current: number;
  limit: number;
  unit: string;
  format?: (n: number) => string;
}

const UsageLimitCard: React.FC<UsageLimitCardProps> = ({
  title,
  current,
  limit,
  unit,
  format = (n) => n.toLocaleString(),
}) => {
  const percentage = (current / limit) * 100;
  const isWarning = percentage >= 80;
  const isDanger = percentage >= 95;

  return (
    <div className="border border-border rounded-sm p-4 bg-elevated space-y-3">
      <div className="flex items-center justify-between">
        <h4 className="text-xs font-medium text-text-secondary">{title}</h4>
        {isWarning && (
          <AlertTriangle
            className={cn('w-4 h-4', isDanger ? 'text-red' : 'text-orange')}
          />
        )}
      </div>
      <div>
        <p className="text-2xl font-semibold text-text">{format(current)}</p>
        <p className="text-xs text-text-tertiary mt-1">
          of {format(limit)} {unit}
        </p>
      </div>
      <Progress
        value={percentage}
        className={cn(
          'h-2',
          isDanger && '[&>div]:bg-red',
          isWarning && !isDanger && '[&>div]:bg-orange',
          !isWarning && '[&>div]:bg-green'
        )}
      />
      <p
        className={cn(
          'text-xs font-medium',
          isDanger && 'text-red',
          isWarning && !isDanger && 'text-orange',
          !isWarning && 'text-green'
        )}
      >
        {percentage.toFixed(1)}% used
      </p>
    </div>
  );
};

