// Feature Cell Component
const FeatureCell: React.FC<{ value: boolean | string }> = ({ value }) => {
  if (typeof value === 'boolean') {
    return value ? (
      <Check className="w-5 h-5 text-green inline-block" />
    ) : (
      <X className="w-5 h-5 text-text-tertiary inline-block" />
    );
  }

  return <span className="text-sm text-text font-medium">{value}</span>;
};

