// Helper: Format duration
function formatDuration(ms: number): string {
  const seconds = Math.floor(ms / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);

  if (hours > 0) return `${hours}h ${minutes % 60}m`;
  if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
  return `${seconds}s`;
}

/**
 * ChatView - Main chat interface with AI agent
 * Supports streaming responses, code blocks with syntax highlighting, and stop generation
 */

import React, { useState, useRef, useEffect } from 'react';
import { cn } from '../../lib/utils';
import { Button } from '../../components/ui/button';
import { Textarea } from '../../components/ui/textarea';
import { Badge } from '../../components/ui/badge';
import { Spinner } from '../../components/ui/spinner';
import { StopCircle, Send, User, Sparkles } from 'lucide-react';
import Prism from 'prismjs';
import DOMPurify from 'dompurify';
import 'prismjs/themes/prism-tomorrow.css';
import 'prismjs/components/prism-typescript';
import 'prismjs/components/prism-javascript';
import 'prismjs/components/prism-python';
import 'prismjs/components/prism-rust';
import 'prismjs/components/prism-json';

interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: number;
  isStreaming?: boolean;
}

interface ChatViewProps {
  sessionId: string;
  model: string;
  onClose?: () => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ sessionId, model, onClose }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamingMessageId, setStreamingMessageId] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  // Auto-scroll to bottom
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Load session messages
  useEffect(() => {
    loadMessages();
  }, [sessionId]);

  const loadMessages = async () => {
    try {
      const response = await window.cortex.db.query<{
        id: string;
        role: string;
        content: string;
        created_at: number;
      }>({
        query: 'SELECT * FROM messages WHERE session_id = ? ORDER BY created_at ASC',
        params: [sessionId],
      });

      if (response.success && response.data) {
        setMessages(
          response.data.rows.map((row) => ({
            id: row.id,
            role: row.role as 'user' | 'assistant' | 'system',
            content: row.content,
            timestamp: row.created_at,
          }))
        );
      }
    } catch (error) {
      console.error('Failed to load messages:', error);
    }
  };

  // Handle send message
  const handleSend = async () => {
    if (!input.trim() || isStreaming) return;

    const userMessage: Message = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: input.trim(),
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setInput('');

    // Resize textarea
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }

    // Start streaming
    const assistantMessageId = `assistant-${Date.now()}`;
    const assistantMessage: Message = {
      id: assistantMessageId,
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
      isStreaming: true,
    };

    setMessages((prev) => [...prev, assistantMessage]);
    setIsStreaming(true);
    setStreamingMessageId(assistantMessageId);

    try {
      abortControllerRef.current = new AbortController();

      // Stream response via IPC
      const response = await window.cortex.ai.streamResponse({
        sessionId,
        message: userMessage.content,
      });

      // Handle streaming chunks
      window.electron.ipcRenderer.on('ai:stream-chunk', (_event, chunk) => {
        if (chunk.type === 'chunk' && chunk.content) {
          setMessages((prev) =>
            prev.map((msg) =>
              msg.id === assistantMessageId
                ? { ...msg, content: msg.content + chunk.content }
                : msg
            )
          );
        } else if (chunk.type === 'done') {
          setMessages((prev) =>
            prev.map((msg) =>
              msg.id === assistantMessageId
                ? { ...msg, isStreaming: false }
                : msg
            )
          );
          setIsStreaming(false);
          setStreamingMessageId(null);
        } else if (chunk.type === 'error') {
          console.error('Stream error:', chunk.error);
          setIsStreaming(false);
          setStreamingMessageId(null);
        }
      });
    } catch (error) {
      console.error('Failed to send message:', error);
      setIsStreaming(false);
      setStreamingMessageId(null);
    }
  };

  // Handle stop generation
  const handleStop = async () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }

    try {
      await window.cortex.ai.stopStream({ sessionId });
      setIsStreaming(false);
      setStreamingMessageId(null);

      // Mark last message as complete
      setMessages((prev) =>
        prev.map((msg) =>
          msg.id === streamingMessageId
            ? { ...msg, isStreaming: false }
            : msg
        )
      );
    } catch (error) {
      console.error('Failed to stop stream:', error);
    }
  };

  // Auto-resize textarea
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    e.target.style.height = 'auto';
    e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
  };

  // Handle Enter key
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-page">
      {/* Header */}
      <div className="h-[52px] border-b border-border-soft flex items-center justify-between px-5">
        <div className="flex items-center gap-3">
          <Sparkles className="w-4 h-4 text-accent" />
          <div>
            <h2 className="text-sm font-medium text-text">Chat Session</h2>
            <p className="text-xs text-text-secondary">{model}</p>
          </div>
        </div>
        {onClose && (
          <Button variant="ghost" size="sm" onClick={onClose}>
            Close
          </Button>
        )}
      </div>

      {/* Messages List */}
      <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4">
        {messages.length === 0 ? (
          <div className="flex items-center justify-center h-full">
            <div className="text-center space-y-2">
              <Sparkles className="w-12 h-12 text-text-tertiary mx-auto" />
              <p className="text-sm text-text-secondary">Start a conversation</p>
            </div>
          </div>
        ) : (
          messages.map((message) => (
            <MessageBubble key={message.id} message={message} />
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="border-t border-border-soft p-4 space-y-3">
        {isStreaming && (
          <div className="flex items-center justify-between px-3 py-2 bg-tint rounded-sm">
            <div className="flex items-center gap-2 text-sm text-text-secondary">
              <Spinner size="sm" />
