// Message Bubble Component
interface MessageBubbleProps {
  message: Message;
}

const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const isAssistant = message.role === 'assistant';

  // Parse code blocks for syntax highlighting
  const renderContent = () => {
    const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g;
    const parts: React.ReactNode[] = [];
    let lastIndex = 0;
    let match;

    while ((match = codeBlockRegex.exec(message.content)) !== null) {
      // Add text before code block
      if (match.index > lastIndex) {
        parts.push(
          <p key={`text-${lastIndex}`} className="whitespace-pre-wrap">
            {message.content.slice(lastIndex, match.index)}
          </p>
        );
      }

      // Add code block
      const language = match[1] || 'text';
      const code = match[2].trim();
      const highlighted = Prism.highlight(
        code,
        Prism.languages[language] || Prism.languages.text,
        language
      );

      // Sanitize highlighted HTML to prevent XSS
      const sanitized = DOMPurify.sanitize(highlighted, {
        ALLOWED_TAGS: ['span'],
        ALLOWED_ATTR: ['class', 'style'],
        ALLOW_DATA_ATTR: false,
      });

      parts.push(
        <div key={`code-${match.index}`} className="my-3">
          <div className="flex items-center justify-between px-3 py-1.5 bg-elevated border-b border-border-dark rounded-t-sm">
            <Badge variant="secondary" className="text-xs font-mono">
              {language}
            </Badge>
          </div>
          <pre className="!mt-0 !rounded-t-none overflow-x-auto">
            <code
              className={`language-${language}`}
              dangerouslySetInnerHTML={{ __html: sanitized }}
            />
          </pre>
        </div>
      );

      lastIndex = match.index + match[0].length;
    }

    // Add remaining text
    if (lastIndex < message.content.length) {
      parts.push(
        <p key={`text-${lastIndex}`} className="whitespace-pre-wrap">
          {message.content.slice(lastIndex)}
        </p>
      );
    }

    return parts.length > 0 ? parts : <p className="whitespace-pre-wrap">{message.content}</p>;
  };

  return (
    <div className={cn('flex gap-3', isUser && 'flex-row-reverse')}>
      {/* Avatar */}
      <div
        className={cn(
          'w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0',
          isUser ? 'bg-accent text-white' : 'bg-tint text-text'
        )}
      >
        {isUser ? (
          <User className="w-4 h-4" />
        ) : (
          <Sparkles className="w-4 h-4" />
        )}
      </div>

      {/* Content */}
      <div
        className={cn(
          'flex-1 max-w-[80%] rounded-lg px-4 py-3',
          isUser ? 'bg-tint' : 'bg-elevated border border-border'
        )}
      >
        <div className="text-sm text-text space-y-2">
          {renderContent()}
          {message.isStreaming && (
            <span className="inline-block w-2 h-4 bg-accent animate-pulse" />
          )}
        </div>
        <p className="text-xs text-text-tertiary mt-2">
          {new Date(message.timestamp).toLocaleTimeString()}
        </p>
      </div>
    </div>
  );
};

/**
 * SessionList - Sidebar with historical chat sessions
 * Features: search, filters, new chat, delete/archive sessions
 * Performance: React.memo, virtual scrolling, debounced search
 */

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { cn } from '../../lib/utils';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Badge } from '../../components/ui/badge';
import {
  Plus,
  Search,
  Clock,
  Calendar,
  MessageSquare,
  MoreVertical,
  Trash2,
  Archive,
} from 'lucide-react';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '../../components/ui/popover';
import { VirtualList, useDebounce } from '../../hooks/use-performance';

interface Session {
  id: string;
  title: string | null;
  model: string | null;
  created_at: number;
  updated_at: number;
  messageCount?: number;
}

interface SessionListProps {
  activeSessionId?: string;
  onSessionSelect: (sessionId: string) => void;
  onNewSession: () => void;
}

export const SessionList: React.FC<SessionListProps> = React.memo(({
  activeSessionId,
  onSessionSelect,
  onNewSession,
}) => {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterPeriod, setFilterPeriod] = useState<'all' | 'today' | 'week' | 'month'>('all');
  const [isLoading, setIsLoading] = useState(true);

  // Debounce search query
  const debouncedSearchQuery = useDebounce(searchQuery, 300);

  // Load sessions
  useEffect(() => {
    loadSessions();
  }, []);

  const loadSessions = useCallback(async () => {
    setIsLoading(true);
    try {
      const response = await window.cortex.db.query<Session>({
        query: `
          SELECT 
            s.*,
            (SELECT COUNT(*) FROM messages WHERE session_id = s.id) as messageCount
          FROM sessions s
          ORDER BY s.updated_at DESC
        `,
      });

      if (response.success && response.data) {
        setSessions(response.data.rows);
      }
    } catch (error) {
      console.error('Failed to load sessions:', error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // Filter sessions with useMemo for performance
  const filteredSessions = useMemo(() => {
    return sessions.filter((session) => {
      // Search filter
      if (debouncedSearchQuery) {
        const query = debouncedSearchQuery.toLowerCase();
        const title = session.title?.toLowerCase() || '';
        const model = session.model?.toLowerCase() || '';
        if (!title.includes(query) && !model.includes(query)) {
          return false;
        }
      }

      // Time period filter
      if (filterPeriod !== 'all') {
        const now = Date.now();
        const sessionDate = session.updated_at;
        const dayMs = 24 * 60 * 60 * 1000;

        switch (filterPeriod) {
          case 'today':
            if (now - sessionDate > dayMs) return false;
            break;
          case 'week':
            if (now - sessionDate > 7 * dayMs) return false;
            break;
          case 'month':
            if (now - sessionDate > 30 * dayMs) return false;
            break;
        }
      }

      return true;
    });
  }, [sessions, debouncedSearchQuery, filterPeriod]);

  // Group sessions by date with useMemo
  const groupedSessions = useMemo(() => groupSessionsByDate(filteredSessions), [filteredSessions]);

  // Handle delete session
  const handleDelete = useCallback(async (sessionId: string) => {
    try {
      await window.cortex.db.execute({
        statements: [
          { query: 'DELETE FROM messages WHERE session_id = ?', params: [sessionId] },
          { query: 'DELETE FROM sessions WHERE id = ?', params: [sessionId] },
        ],
      });
      loadSessions();
    } catch (error) {
      console.error('Failed to delete session:', error);
    }
  }, [loadSessions]);

  // Handle archive session (soft delete)
  const handleArchive = useCallback(async (sessionId: string) => {
    try {
      await window.cortex.db.execute({
        statements: [
          {
            query: 'UPDATE sessions SET metadata = json_set(metadata, "$.archived", 1) WHERE id = ?',
            params: [sessionId],
          },
        ],
      });
      loadSessions();
    } catch (error) {
      console.error('Failed to archive session:', error);
    }
  }, [loadSessions]);

  return (
    <div className="flex flex-col h-full w-[378px] bg-wash border-r border-border-soft">
      {/* Header */}
      <div className="p-4 space-y-3 border-b border-border-soft">
        <div className="flex items-center justify-between">
          <h2 className="text-sm font-semibold text-text">Sessions</h2>
          <Button size="sm" onClick={onNewSession} className="gap-2">
            <Plus className="w-4 h-4" />
            New Chat
          </Button>
        </div>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-tertiary" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search sessions..."
            className="pl-9"
          />
        </div>

        {/* Filters */}
        <div className="flex gap-2">
          {(['all', 'today', 'week', 'month'] as const).map((period) => (
            <Button
              key={period}
              variant={filterPeriod === period ? 'secondary' : 'ghost'}
              size="sm"
              onClick={() => setFilterPeriod(period)}
              className="flex-1 text-xs"
            >
              {period === 'all' ? 'All' : period.charAt(0).toUpperCase() + period.slice(1)}
            </Button>
          ))}
        </div>
      </div>

      {/* Sessions List */}
      <div className="flex-1 overflow-y-auto">
        {isLoading ? (
          <div className="flex items-center justify-center h-32">
            <p className="text-sm text-text-secondary">Loading sessions...</p>
          </div>
        ) : filteredSessions.length === 0 ? (
          <div className="flex items-center justify-center h-32">
            <div className="text-center space-y-2">
              <MessageSquare className="w-8 h-8 text-text-tertiary mx-auto" />
              <p className="text-sm text-text-secondary">No sessions found</p>
            </div>
          </div>
        ) : (
          <div className="py-2">
            {Object.entries(groupedSessions).map(([date, dateSessions]) => (
              <div key={date} className="mb-4">
                <div className="px-4 py-2">
                  <p className="text-xs font-medium text-text-secondary">{date}</p>
                </div>
                <div className="space-y-1 px-2">
                  {dateSessions.map((session) => (
                    <SessionItem
                      key={session.id}
                      session={session}
                      isActive={session.id === activeSessionId}
                      onSelect={() => onSessionSelect(session.id)}
                      onDelete={() => handleDelete(session.id)}
                      onArchive={() => handleArchive(session.id)}
                    />
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="p-4 border-t border-border-soft">
        <p className="text-xs text-text-tertiary">
          {filteredSessions.length} session{filteredSessions.length !== 1 ? 's' : ''}
        </p>
      </div>
    </div>
  );
});

