}, (prevProps, nextProps) => {
  // Custom comparison for React.memo
  return (
    prevProps.session.id === nextProps.session.id &&
    prevProps.isActive === nextProps.isActive &&
    prevProps.session.updated_at === nextProps.session.updated_at
  );
});

// Helper: Group sessions by date
function groupSessionsByDate(sessions: Session[]): Record<string, Session[]> {
  const groups: Record<string, Session[]> = {};
  const now = Date.now();
  const dayMs = 24 * 60 * 60 * 1000;

  sessions.forEach((session) => {
    const diff = now - session.updated_at;
    let label: string;

    if (diff < dayMs) {
      label = 'Today';
    } else if (diff < 2 * dayMs) {
      label = 'Yesterday';
    } else if (diff < 7 * dayMs) {
      label = 'This Week';
    } else if (diff < 30 * dayMs) {
      label = 'This Month';
    } else {
      label = 'Older';
    }

    if (!groups[label]) {
      groups[label] = [];
    }
    groups[label].push(session);
  });

  return groups;
}

// Helper: Format relative time
function formatRelativeTime(timestamp: number): string {
  const now = Date.now();
  const diff = now - timestamp;
  const minutes = Math.floor(diff / (60 * 1000));
  const hours = Math.floor(diff / (60 * 60 * 1000));
  const days = Math.floor(diff / (24 * 60 * 60 * 1000));

  if (minutes < 1) return 'Just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  if (days < 7) return `${days}d ago`;

  return new Date(timestamp).toLocaleDateString();
}

/**
 * UsageTracking - Dashboard for monitoring AI usage and costs
 * Features: usage graphs by provider/model, cumulative costs, real-time statistics
 */

import React, { useState, useEffect } from 'react';
import { cn } from '../../lib/utils';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import { Progress } from '../../components/ui/progress';
import {
  TrendingUp,
  DollarSign,
  Zap,
  Clock,
  BarChart3,
  PieChart,
  Calendar,
  RefreshCw,
  Download,
} from 'lucide-react';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../../components/ui/select';

interface UsageStats {
  totalCost: number;
  totalTokens: number;
  totalSessions: number;
  avgResponseTime: number;
  byProvider: ProviderUsage[];
  byModel: ModelUsage[];
  timeline: TimelineEntry[];
}

interface ProviderUsage {
  provider: string;
  cost: number;
  tokens: number;
  percentage: number;
}

interface ModelUsage {
  model: string;
  provider: string;
  cost: number;
  tokens: number;
  sessions: number;
  percentage: number;
}

interface TimelineEntry {
  date: string;
  cost: number;
  tokens: number;
  sessions: number;
}

export const UsageTracking: React.FC = () => {
  const [stats, setStats] = useState<UsageStats | null>(null);
  const [timeRange, setTimeRange] = useState<'day' | 'week' | 'month' | 'all'>('week');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadUsageStats();
  }, [timeRange]);

  const loadUsageStats = async () => {
    setIsLoading(true);
    try {
      const now = Date.now();
      const rangeMs = getTimeRangeMs(timeRange);
      const startTime = timeRange === 'all' ? 0 : now - rangeMs;

      // Get total stats
      const totalResponse = await window.cortex.db.query<{
        total_cost: number;
        total_tokens: number;
        total_sessions: number;
      }>({
        query: `
          SELECT 
            SUM(cost) as total_cost,
            SUM(tokens_input + tokens_output) as total_tokens,
            COUNT(DISTINCT session_id) as total_sessions
          FROM usage_logs
          WHERE created_at >= ?
        `,
        params: [startTime],
      });

      // Get usage by provider
      const providerResponse = await window.cortex.db.query<{
        provider: string;
        cost: number;
        tokens: number;
      }>({
        query: `
          SELECT 
            provider,
            SUM(cost) as cost,
            SUM(tokens_input + tokens_output) as tokens
          FROM usage_logs
          WHERE created_at >= ?
          GROUP BY provider
          ORDER BY cost DESC
        `,
        params: [startTime],
      });

      // Get usage by model
      const modelResponse = await window.cortex.db.query<{
        model: string;
        provider: string;
        cost: number;
        tokens: number;
        sessions: number;
      }>({
        query: `
          SELECT 
            model,
            provider,
            SUM(cost) as cost,
            SUM(tokens_input + tokens_output) as tokens,
            COUNT(DISTINCT session_id) as sessions
          FROM usage_logs
          WHERE created_at >= ?
          GROUP BY model, provider
          ORDER BY cost DESC
        `,
        params: [startTime],
      });

      // Get timeline data
      const timelineResponse = await window.cortex.db.query<{
        date: string;
        cost: number;
        tokens: number;
        sessions: number;
      }>({
        query: `
          SELECT 
            DATE(created_at / 1000, 'unixepoch') as date,
            SUM(cost) as cost,
            SUM(tokens_input + tokens_output) as tokens,
            COUNT(DISTINCT session_id) as sessions
          FROM usage_logs
          WHERE created_at >= ?
          GROUP BY date
          ORDER BY date ASC
        `,
        params: [startTime],
      });

      if (
        totalResponse.success &&
        totalResponse.data?.rows[0] &&
        providerResponse.success &&
        modelResponse.success &&
        timelineResponse.success
      ) {
        const total = totalResponse.data.rows[0];
        const totalCost = total.total_cost || 0;

        setStats({
          totalCost,
          totalTokens: total.total_tokens || 0,
          totalSessions: total.total_sessions || 0,
          avgResponseTime: 2500, // Mock data - would need to track this separately
          byProvider: providerResponse.data.rows.map((row) => ({
            provider: row.provider,
            cost: row.cost,
            tokens: row.tokens,
            percentage: totalCost > 0 ? (row.cost / totalCost) * 100 : 0,
          })),
          byModel: modelResponse.data.rows.map((row) => ({
            model: row.model,
            provider: row.provider,
            cost: row.cost,
            tokens: row.tokens,
            sessions: row.sessions,
            percentage: totalCost > 0 ? (row.cost / totalCost) * 100 : 0,
          })),
          timeline: timelineResponse.data.rows,
        });
      }
    } catch (error) {
      console.error('Failed to load usage stats:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = async () => {
    // Export usage data as CSV
    try {
      const csvData = generateCSV(stats);
      const blob = new Blob([csvData], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `usage-report-${timeRange}-${Date.now()}.csv`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Failed to export data:', error);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-sm text-text-secondary">Loading usage data...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-page">
      {/* Header */}
      <div className="h-[40px] border-b border-border-soft flex items-center justify-between px-5">
        <div className="flex items-center gap-3">
          <BarChart3 className="w-4 h-4 text-accent" />
          <h2 className="text-sm font-semibold text-text">Usage & Billing</h2>
        </div>
        <div className="flex items-center gap-2">
          <Select value={timeRange} onValueChange={(v: any) => setTimeRange(v)}>
            <SelectTrigger className="w-32 h-8">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="day">Last 24h</SelectItem>
              <SelectItem value="week">Last Week</SelectItem>
              <SelectItem value="month">Last Month</SelectItem>
              <SelectItem value="all">All Time</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="ghost" size="sm" onClick={loadUsageStats} className="gap-2">
            <RefreshCw className="w-4 h-4" />
          </Button>
          <Button variant="outline" size="sm" onClick={handleExport} className="gap-2">
            <Download className="w-4 h-4" />
            Export
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-5 space-y-6">
        {/* Summary Cards */}
        <div className="grid grid-cols-4 gap-4">
          <StatCard
            icon={DollarSign}
            label="Total Cost"
            value={`$${(stats?.totalCost || 0).toFixed(2)}`}
            change="+12.5%"
            variant="primary"
          />
          <StatCard
            icon={Zap}
            label="Total Tokens"
            value={(stats?.totalTokens || 0).toLocaleString()}
            change="+8.3%"
            variant="success"
          />
          <StatCard
            icon={TrendingUp}
            label="Sessions"
            value={(stats?.totalSessions || 0).toString()}
            change="+15.2%"
            variant="warning"
          />
          <StatCard
            icon={Clock}
            label="Avg Response"
            value={`${((stats?.avgResponseTime || 0) / 1000).toFixed(1)}s`}
            change="-5.1%"
            variant="info"
          />
        </div>

        {/* Charts Row */}
        <div className="grid grid-cols-2 gap-4">
          {/* Usage by Provider */}
          <div className="border border-border rounded-sm">
            <div className="px-4 py-3 border-b border-border-dark bg-elevated">
              <div className="flex items-center gap-2">
                <PieChart className="w-4 h-4 text-accent" />
