// Simple Line Chart Component
interface SimpleLineChartProps {
  data: TimelineEntry[];
}

const SimpleLineChart: React.FC<SimpleLineChartProps> = ({ data }) => {
  if (data.length === 0) {
    return (
      <div className="flex items-center justify-center h-32">
        <p className="text-sm text-text-secondary">No data available</p>
      </div>
    );
  }

  const maxCost = Math.max(...data.map((d) => d.cost));
  const chartHeight = 120;

  return (
    <div className="space-y-2">
      <div className="flex items-end justify-between h-[120px] gap-1">
        {data.map((entry, index) => {
          const height = maxCost > 0 ? (entry.cost / maxCost) * chartHeight : 0;
          return (
            <div
              key={index}
              className="flex-1 flex flex-col items-center gap-1"
            >
              <div
                className="w-full bg-accent rounded-t-sm transition-all hover:opacity-80"
                style={{ height: `${height}px` }}
                title={`$${entry.cost.toFixed(2)}`}
              />
            </div>
          );
        })}
      </div>
      <div className="flex justify-between text-xs text-text-tertiary">
        <span>{data[0]?.date}</span>
        <span>{data[data.length - 1]?.date}</span>
      </div>
    </div>
  );
};

// Helpers
function getTimeRangeMs(range: 'day' | 'week' | 'month' | 'all'): number {
  const dayMs = 24 * 60 * 60 * 1000;
  switch (range) {
    case 'day':
      return dayMs;
    case 'week':
      return 7 * dayMs;
    case 'month':
      return 30 * dayMs;
    case 'all':
      return Number.MAX_SAFE_INTEGER;
  }
}

function generateCSV(stats: UsageStats | null): string {
  if (!stats) return '';

  const lines: string[] = [
    'Model,Provider,Cost,Tokens,Sessions',
    ...stats.byModel.map(
      (m) => `${m.model},${m.provider},${m.cost},${m.tokens},${m.sessions}`
    ),
  ];

  return lines.join('\n');
}

