      console.error('Failed to resume agent:', error);
    }
  };

  const handleCancelAgent = async (agentId: string) => {
    try {
      // TODO: Call IPC to cancel agent
      console.log('Cancelling agent:', agentId);
    } catch (error) {
      console.error('Failed to cancel agent:', error);
    }
  };

  const filteredAgents = agents.filter((agent) => {
    if (filterStatus !== 'all' && agent.status !== filterStatus) return false;
    if (filterPriority !== 'all' && agent.priority !== filterPriority) return false;
    return true;
  });

  return (
    <div className="flex flex-col h-full bg-page">
      {/* Header */}
      <div className="h-[40px] border-b border-border-soft flex items-center justify-between px-5">
        <div className="flex items-center gap-3">
          <h2 className="text-sm font-semibold text-text">Background Agents</h2>
          <Badge variant="secondary" className="text-xs">
            {agents.length} active
          </Badge>
        </div>
        <div className="flex items-center gap-2">
          <Select value={filterStatus} onValueChange={setFilterStatus}>
            <SelectTrigger className="h-7 w-[120px] text-xs">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="queued">Queued</SelectItem>
              <SelectItem value="running">Running</SelectItem>
              <SelectItem value="paused">Paused</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
              <SelectItem value="failed">Failed</SelectItem>
            </SelectContent>
          </Select>
          <Select value={filterPriority} onValueChange={setFilterPriority}>
            <SelectTrigger className="h-7 w-[120px] text-xs">
              <SelectValue placeholder="Priority" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Priority</SelectItem>
              <SelectItem value="high">High</SelectItem>
              <SelectItem value="normal">Normal</SelectItem>
              <SelectItem value="low">Low</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="ghost" size="sm" onClick={loadAgents} className="h-7 gap-2">
            <RefreshCw className="w-3.5 h-3.5" />
            Refresh
          </Button>
        </div>
      </div>

      {/* Agent List */}
      <div className="flex-1 overflow-y-auto p-5 space-y-3">
        {isLoading ? (
          <div className="flex items-center justify-center h-full">
            <p className="text-sm text-text-secondary">Loading agents...</p>
          </div>
        ) : filteredAgents.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full gap-2">
            <ListFilter className="w-8 h-8 text-text-tertiary" />
            <p className="text-sm text-text-secondary">No agents found</p>
          </div>
        ) : (
          filteredAgents.map((agent) => (
            <AgentCard
              key={agent.agentId}
              agent={agent}
              onPause={handlePauseAgent}
              onResume={handleResumeAgent}
              onCancel={handleCancelAgent}
              onView={onViewAgent}
            />
          ))
        )}
      </div>
    </div>
  );
};

// Agent Card Component
interface AgentCardProps {
  agent: AgentState;
  onPause: (agentId: string) => void;
  onResume: (agentId: string) => void;
  onCancel: (agentId: string) => void;
  onView?: (agentId: string) => void;
}

const AgentCard: React.FC<AgentCardProps> = ({ agent, onPause, onResume, onCancel, onView }) => {
  const statusConfig = {
    queued: { icon: Clock, color: 'text-blue', bg: 'bg-blue/10', label: 'Queued' },
    running: { icon: Loader, color: 'text-green', bg: 'bg-green/10', label: 'Running' },
    paused: { icon: Pause, color: 'text-orange', bg: 'bg-orange/10', label: 'Paused' },
    completed: { icon: CheckCircle, color: 'text-green', bg: 'bg-green/10', label: 'Completed' },
    failed: { icon: AlertCircle, color: 'text-red', bg: 'bg-red/10', label: 'Failed' },
    cancelled: { icon: X, color: 'text-text-tertiary', bg: 'bg-wash', label: 'Cancelled' },
  };

  const priorityConfig = {
    high: { color: 'text-red', bg: 'bg-red/10' },
    normal: { color: 'text-blue', bg: 'bg-blue/10' },
    low: { color: 'text-text-tertiary', bg: 'bg-wash' },
  };

  const status = statusConfig[agent.status];
  const priority = priorityConfig[agent.priority];
  const StatusIcon = status.icon;

  const formatTime = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  return (
    <div className="border border-border rounded-sm bg-elevated hover:bg-tint transition-colors">
      {/* Header */}
      <div className="px-4 py-3 border-b border-border-dark">
        <div className="flex items-start justify-between">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <Badge className={cn('text-xs', priority.bg, priority.color)}>
                {agent.priority}
              </Badge>
              <Badge className={cn('text-xs', status.bg, status.color)}>
                <StatusIcon className="w-3 h-3 mr-1" />
                {status.label}
              </Badge>
            </div>
            <h3 className="text-sm font-semibold text-text truncate">
              {agent.config.featureId}
            </h3>
            <p className="text-xs text-text-secondary truncate">
              Mission: {agent.config.missionId}
            </p>
          </div>
          <div className="flex items-center gap-1 ml-3">
            {agent.status === 'running' && (
              <Button
                variant="ghost"
                size="icon"
                onClick={() => onPause(agent.agentId)}
                className="h-7 w-7"
                title="Pause"
              >
                <Pause className="w-3.5 h-3.5" />
              </Button>
            )}
            {agent.status === 'paused' && (
              <Button
                variant="ghost"
                size="icon"
                onClick={() => onResume(agent.agentId)}
                className="h-7 w-7"
                title="Resume"
              >
                <Play className="w-3.5 h-3.5" />
              </Button>
            )}
            {(agent.status === 'running' || agent.status === 'queued' || agent.status === 'paused') && (
              <Button
                variant="ghost"
                size="icon"
                onClick={() => onCancel(agent.agentId)}
                className="h-7 w-7 text-red hover:text-red"
                title="Cancel"
              >
                <X className="w-3.5 h-3.5" />
              </Button>
            )}
            {onView && (
              <Button
                variant="ghost"
                size="icon"
                onClick={() => onView(agent.agentId)}
                className="h-7 w-7"
                title="View Details"
              >
                <Eye className="w-3.5 h-3.5" />
              </Button>
            )}
          </div>
        </div>
      </div>

      {/* Progress */}
      {agent.status === 'running' && (
        <div className="px-4 py-3 space-y-2">
          <div className="flex items-center justify-between text-xs">
            <span className="text-text-secondary">
              {agent.progress.message || 'In progress...'}
            </span>
            <span className="text-text font-mono">{agent.progress.percentage}%</span>
          </div>
          <Progress value={agent.progress.percentage} className="h-1.5" />
        </div>
      )}

      {/* Metrics */}
      <div className="px-4 py-3 border-t border-border-dark">
        <div className="grid grid-cols-3 gap-4">
          <MetricItem
            icon={Clock}
            label="Time"
            value={agent.startedAt ? formatTime(agent.resourceUsage.timeElapsedMs) : '-'}
          />
          <MetricItem
            icon={Zap}
            label="Tokens"
            value={agent.resourceUsage.tokensUsed.toLocaleString()}
          />
          <MetricItem
            icon={AlertCircle}
            label="Memory"
            value={`${agent.resourceUsage.memoryMB}MB`}
          />
        </div>
      </div>
    </div>
  );
};

