/**
 * QueueViewer - UI component for viewing agent queue with priorities
 * Shows queued agents, their positions, and allows reordering
 */

import React, { useState, useEffect } from 'react';
import { cn } from '../../../lib/utils';
import { Button } from '../../../components/ui/button';
import { Badge } from '../../../components/ui/badge';
import {
  ArrowUp,
  ArrowDown,
  X,
  ListOrdered,
  RefreshCw,
  ChevronUp,
  ChevronDown,
} from 'lucide-react';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '../../../components/ui/collapsible';

interface QueuedAgent {
  agentId: string;
  priority: 'high' | 'normal' | 'low';
  config: {
    missionId: string;
    featureId: string;
  };
  enqueuedAt: number;
  position: number;
}

interface QueueStats {
  total: number;
  byPriority: {
    high: number;
    normal: number;
    low: number;
  };
}

export const QueueViewer: React.FC = () => {
  const [queuedAgents, setQueuedAgents] = useState<QueuedAgent[]>([]);
  const [stats, setStats] = useState<QueueStats>({
    total: 0,
    byPriority: { high: 0, normal: 0, low: 0 },
  });
  const [expandedPriorities, setExpandedPriorities] = useState<Set<string>>(
    new Set(['high', 'normal', 'low'])
  );

  useEffect(() => {
    loadQueue();
    const interval = setInterval(loadQueue, 2000);
    return () => clearInterval(interval);
  }, []);

  const loadQueue = async () => {
    try {
      // TODO: Call IPC to get queue state
      // For now, mock data
      setStats({
        total: queuedAgents.length,
        byPriority: {
          high: queuedAgents.filter((a) => a.priority === 'high').length,
          normal: queuedAgents.filter((a) => a.priority === 'normal').length,
          low: queuedAgents.filter((a) => a.priority === 'low').length,
        },
      });
    } catch (error) {
      console.error('Failed to load queue:', error);
    }
  };

  const handleRemoveFromQueue = async (agentId: string) => {
    try {
      // TODO: Call IPC to remove from queue
      console.log('Removing from queue:', agentId);
    } catch (error) {
      console.error('Failed to remove from queue:', error);
    }
  };

  const handleChangePriority = async (agentId: string, newPriority: string) => {
    try {
      // TODO: Call IPC to update priority
      console.log('Changing priority:', agentId, newPriority);
    } catch (error) {
      console.error('Failed to change priority:', error);
    }
  };

  const togglePriority = (priority: string) => {
    setExpandedPriorities((prev) => {
      const next = new Set(prev);
      if (next.has(priority)) {
        next.delete(priority);
      } else {
        next.add(priority);
      }
      return next;
    });
  };

  const groupedByPriority = {
    high: queuedAgents.filter((a) => a.priority === 'high'),
    normal: queuedAgents.filter((a) => a.priority === 'normal'),
    low: queuedAgents.filter((a) => a.priority === 'low'),
  };

  const priorityConfig = {
    high: { color: 'text-red', bg: 'bg-red/10', label: 'High Priority' },
    normal: { color: 'text-blue', bg: 'bg-blue/10', label: 'Normal Priority' },
    low: { color: 'text-text-tertiary', bg: 'bg-wash', label: 'Low Priority' },
  };

  return (
    <div className="flex flex-col h-full bg-page">
      {/* Header */}
      <div className="h-[40px] border-b border-border-soft flex items-center justify-between px-5">
        <div className="flex items-center gap-3">
          <ListOrdered className="w-4 h-4 text-accent" />
          <h2 className="text-sm font-semibold text-text">Agent Queue</h2>
          <Badge variant="secondary" className="text-xs">
            {stats.total} queued
          </Badge>
        </div>
        <Button variant="ghost" size="sm" onClick={loadQueue} className="h-7 gap-2">
          <RefreshCw className="w-3.5 h-3.5" />
          Refresh
        </Button>
      </div>

      {/* Queue Stats */}
      <div className="px-5 py-3 border-b border-border-soft bg-elevated">
        <div className="grid grid-cols-3 gap-4">
          <StatCard
            label="High"
            value={stats.byPriority.high}
            color="text-red"
            bg="bg-red/10"
          />
          <StatCard
            label="Normal"
            value={stats.byPriority.normal}
            color="text-blue"
            bg="bg-blue/10"
          />
          <StatCard
            label="Low"
            value={stats.byPriority.low}
            color="text-text-tertiary"
            bg="bg-wash"
          />
        </div>
      </div>

      {/* Queue List */}
      <div className="flex-1 overflow-y-auto p-5 space-y-3">
        {stats.total === 0 ? (
          <div className="flex flex-col items-center justify-center h-full gap-2">
            <ListOrdered className="w-8 h-8 text-text-tertiary" />
            <p className="text-sm text-text-secondary">Queue is empty</p>
          </div>
        ) : (
          <>
            {(['high', 'normal', 'low'] as const).map((priority) => (
              <Collapsible
                key={priority}
                open={expandedPriorities.has(priority)}
                onOpenChange={() => togglePriority(priority)}
              >
                <div className="border border-border rounded-sm bg-elevated">
                  <CollapsibleTrigger className="w-full px-4 py-3 flex items-center justify-between hover:bg-tint transition-colors">
                    <div className="flex items-center gap-3">
                      <Badge
                        className={cn(
                          'text-xs',
                          priorityConfig[priority].bg,
                          priorityConfig[priority].color
                        )}
                      >
                        {priorityConfig[priority].label}
                      </Badge>
                      <span className="text-xs text-text-secondary">
                        {groupedByPriority[priority].length} agents
                      </span>
                    </div>
                    {expandedPriorities.has(priority) ? (
                      <ChevronUp className="w-4 h-4 text-text-secondary" />
                    ) : (
                      <ChevronDown className="w-4 h-4 text-text-secondary" />
                    )}
                  </CollapsibleTrigger>
                  <CollapsibleContent>
                    <div className="border-t border-border-dark">
                      {groupedByPriority[priority].length === 0 ? (
                        <div className="px-4 py-6 text-center">
                          <p className="text-xs text-text-secondary">No agents in this queue</p>
                        </div>
                      ) : (
                        <div className="divide-y divide-border-dark">
                          {groupedByPriority[priority].map((agent, index) => (
                            <QueueItem
                              key={agent.agentId}
                              agent={agent}
                              position={index + 1}
                              onRemove={handleRemoveFromQueue}
                              onChangePriority={handleChangePriority}
                            />
                          ))}
                        </div>
                      )}
                    </div>
                  </CollapsibleContent>
                </div>
              </Collapsible>
            ))}
          </>
        )}
      </div>
    </div>
  );
};

