/**
 * ResourceMonitor - Real-time monitoring of system resources
 * Shows CPU, memory, tokens usage across all agents and worker pool
 */

import React, { useState, useEffect } from 'react';
import { cn } from '../../../lib/utils';
import { Button } from '../../../components/ui/button';
import { Badge } from '../../../components/ui/badge';
import { Progress } from '../../../components/ui/progress';
import {
  Cpu,
  MemoryStick,
  Zap,
  Activity,
  TrendingUp,
  TrendingDown,
  Minus,
  RefreshCw,
  AlertTriangle,
} from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';

interface WorkerPoolStats {
  maxWorkers: number;
  activeWorkers: number;
  idleWorkers: number;
  totalTasksProcessed: number;
  averageTaskDurationMs: number;
  cpuUsagePercent: number;
  memoryUsageMB: number;
}

interface ResourceSnapshot {
  timestamp: number;
  cpuPercent: number;
  memoryMB: number;
  tokensPerSecond: number;
  activeAgents: number;
}

export const ResourceMonitor: React.FC = () => {
  const [poolStats, setPoolStats] = useState<WorkerPoolStats>({
    maxWorkers: 10,
    activeWorkers: 0,
    idleWorkers: 10,
    totalTasksProcessed: 0,
    averageTaskDurationMs: 0,
    cpuUsagePercent: 0,
    memoryUsageMB: 0,
  });

  const [history, setHistory] = useState<ResourceSnapshot[]>([]);
  const [isAutoRefresh, setIsAutoRefresh] = useState(true);

  useEffect(() => {
    loadStats();
    if (isAutoRefresh) {
      const interval = setInterval(() => {
        loadStats();
      }, 2000);
      return () => clearInterval(interval);
    }
  }, [isAutoRefresh]);

  const loadStats = async () => {
    try {
      // TODO: Call IPC to get resource stats
      // For now, mock data
      const snapshot: ResourceSnapshot = {
        timestamp: Date.now(),
        cpuPercent: poolStats.cpuUsagePercent,
        memoryMB: poolStats.memoryUsageMB,
        tokensPerSecond: Math.floor(Math.random() * 100),
        activeAgents: poolStats.activeWorkers,
      };

      setHistory((prev) => {
        const updated = [...prev, snapshot];
        // Keep only last 30 snapshots (1 minute of data)
        return updated.slice(-30);
      });
    } catch (error) {
      console.error('Failed to load resource stats:', error);
    }
  };

  const getTrend = (current: number, previous: number): 'up' | 'down' | 'stable' => {
    const diff = current - previous;
    if (Math.abs(diff) < 2) return 'stable';
    return diff > 0 ? 'up' : 'down';
  };

  const prevSnapshot = history.length >= 2 ? history[history.length - 2] : null;
  const currentSnapshot = history.length > 0 ? history[history.length - 1] : null;

  const cpuTrend = prevSnapshot && currentSnapshot 
    ? getTrend(currentSnapshot.cpuPercent, prevSnapshot.cpuPercent)
    : 'stable';
  const memoryTrend = prevSnapshot && currentSnapshot
    ? getTrend(currentSnapshot.memoryMB, prevSnapshot.memoryMB)
    : 'stable';

  const cpuWarning = poolStats.cpuUsagePercent > 80;
  const memoryWarning = poolStats.memoryUsageMB > 4096; // 4GB

  return (
    <div className="flex flex-col h-full bg-page">
      {/* Header */}
      <div className="h-[40px] border-b border-border-soft flex items-center justify-between px-5">
        <div className="flex items-center gap-3">
          <Activity className="w-4 h-4 text-accent" />
          <h2 className="text-sm font-semibold text-text">Resource Monitor</h2>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant={isAutoRefresh ? 'default' : 'ghost'}
            size="sm"
            onClick={() => setIsAutoRefresh(!isAutoRefresh)}
            className="h-7 gap-2"
          >
            <RefreshCw className={cn('w-3.5 h-3.5', isAutoRefresh && 'animate-spin')} />
            Auto-refresh
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-5 space-y-6">
        {/* Worker Pool Status */}
        <div className="border border-border rounded-sm">
          <div className="px-4 py-3 border-b border-border-dark bg-elevated">
            <h3 className="text-sm font-semibold text-text">Worker Pool</h3>
          </div>
          <div className="p-4">
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div>
                <p className="text-xs text-text-secondary mb-1">Active Workers</p>
                <div className="flex items-baseline gap-2">
                  <span className="text-2xl font-semibold text-text">
                    {poolStats.activeWorkers}
                  </span>
                  <span className="text-sm text-text-secondary">
                    / {poolStats.maxWorkers}
                  </span>
                </div>
              </div>
              <div>
                <p className="text-xs text-text-secondary mb-1">Tasks Processed</p>
                <span className="text-2xl font-semibold text-text">
                  {poolStats.totalTasksProcessed.toLocaleString()}
                </span>
              </div>
            </div>
            <div className="space-y-2">
              <div className="flex items-center justify-between text-xs">
                <span className="text-text-secondary">Utilization</span>
                <span className="text-text font-mono">
                  {Math.round((poolStats.activeWorkers / poolStats.maxWorkers) * 100)}%
                </span>
              </div>
              <Progress
                value={(poolStats.activeWorkers / poolStats.maxWorkers) * 100}
                className="h-2"
              />
            </div>
          </div>
        </div>

        {/* Resource Metrics */}
        <div className="grid grid-cols-2 gap-4">
          <ResourceCard
            icon={Cpu}
            label="CPU Usage"
            value={`${poolStats.cpuUsagePercent}%`}
            progress={poolStats.cpuUsagePercent}
            trend={cpuTrend}
            warning={cpuWarning}
