// Resource Card Component
interface ResourceCardProps {
  icon: React.ElementType;
  label: string;
  value: string;
  progress: number;
  trend: 'up' | 'down' | 'stable';
  warning?: boolean;
}

const ResourceCard: React.FC<ResourceCardProps> = ({
  icon: Icon,
  label,
  value,
  progress,
  trend,
  warning,
}) => {
  const TrendIcon =
    trend === 'up' ? TrendingUp : trend === 'down' ? TrendingDown : Minus;

  return (
    <div className={cn(
      'border rounded-sm p-4',
      warning ? 'border-red bg-red/5' : 'border-border bg-elevated'
    )}>
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center gap-2">
          <Icon className={cn('w-4 h-4', warning ? 'text-red' : 'text-accent')} />
          <span className="text-sm font-medium text-text">{label}</span>
        </div>
        {warning && <AlertTriangle className="w-4 h-4 text-red" />}
      </div>
      <div className="flex items-baseline gap-2 mb-2">
        <span className="text-2xl font-semibold text-text">{value}</span>
        <TrendIcon
          className={cn(
            'w-4 h-4',
            trend === 'up' ? 'text-red' : trend === 'down' ? 'text-green' : 'text-text-tertiary'
          )}
        />
      </div>
      <Progress value={progress} className="h-1.5" />
      {warning && (
        <p className="text-xs text-red mt-2">High usage detected</p>
      )}
    </div>
  );
};

// Helper: Format duration
function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  const seconds = Math.floor(ms / 1000);
  const minutes = Math.floor(seconds / 60);
  if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
  return `${seconds}s`;
}

