/**
 * Automation Editor View
 * Éditeur d'automation avec Monaco pour scripts
 */

import React, { useState, useRef, useEffect } from 'react';
import Editor from '@monaco-editor/react';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { TriggerConfig } from './TriggerConfig';
import { ActionConfig } from './ActionConfig';
import type { Automation, Trigger, Action } from '@cortex-ide/shared';
import { Save, X, Plus } from 'lucide-react';

interface AutomationEditorProps {
  automation?: Automation;
  workspaceId: string;
  onSave: (data: Partial<Automation>) => void;
  onCancel: () => void;
}

export const AutomationEditor: React.FC<AutomationEditorProps> = ({
  automation,
  workspaceId,
  onSave,
  onCancel,
}) => {
  const [name, setName] = useState(automation?.name || '');
  const [enabled, setEnabled] = useState(automation?.enabled ?? true);
  const [trigger, setTrigger] = useState<Trigger>(
    automation?.trigger || {
      type: 'manual',
    }
  );
  const [actions, setActions] = useState<Action[]>(
    automation?.actions || []
  );
  const [selectedActionIndex, setSelectedActionIndex] = useState<number | null>(null);

  const handleSave = () => {
    if (!name.trim()) {
      alert('Name is required');
      return;
    }

    if (actions.length === 0) {
      alert('At least one action is required');
      return;
    }

    onSave({
      workspaceId,
      name: name.trim(),
      enabled,
      trigger,
      actions,
    });
  };

  const addAction = () => {
    const newAction: Action = {
      type: 'run_script',
      script: '#!/bin/bash\necho "Hello World"',
    };
    setActions([...actions, newAction]);
    setSelectedActionIndex(actions.length);
  };

  const updateAction = (index: number, action: Action) => {
    const updated = [...actions];
    updated[index] = action;
    setActions(updated);
  };

  const removeAction = (index: number) => {
    setActions(actions.filter((_, i) => i !== index));
    if (selectedActionIndex === index) {
      setSelectedActionIndex(null);
    } else if (selectedActionIndex !== null && selectedActionIndex > index) {
      setSelectedActionIndex(selectedActionIndex - 1);
    }
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-border">
        <h2 className="text-lg font-semibold">
          {automation ? 'Edit Automation' : 'New Automation'}
        </h2>
        <div className="flex items-center gap-2">
          <Button size="sm" variant="ghost" onClick={onCancel}>
            <X className="w-4 h-4 mr-2" />
            Cancel
          </Button>
          <Button size="sm" onClick={handleSave}>
            <Save className="w-4 h-4 mr-2" />
            Save
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-auto p-4 space-y-6">
        {/* Basic Info */}
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Name</label>
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="My Automation"
            />
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="enabled"
              checked={enabled}
              onChange={(e) => setEnabled(e.target.checked)}
              className="rounded border-border"
            />
            <label htmlFor="enabled" className="text-sm">
              Enabled
            </label>
          </div>
        </div>

        {/* Trigger Configuration */}
        <div>
          <h3 className="text-sm font-semibold mb-3">Trigger</h3>
          <TriggerConfig
            trigger={trigger}
            onChange={setTrigger}
            workspaceId={workspaceId}
          />
        </div>

        {/* Actions */}
        <div>
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-semibold">Actions</h3>
            <Button size="sm" variant="outline" onClick={addAction}>
              <Plus className="w-4 h-4 mr-2" />
              Add Action
            </Button>
          </div>

          {actions.length === 0 ? (
            <div className="text-center p-8 border border-dashed border-border rounded-md">
              <p className="text-sm text-muted-foreground mb-3">
                No actions configured
              </p>
              <Button size="sm" onClick={addAction}>
                Add your first action
              </Button>
            </div>
          ) : (
            <div className="space-y-3">
              {actions.map((action, index) => (
                <ActionConfig
                  key={index}
                  action={action}
                  index={index}
                  selected={selectedActionIndex === index}
                  onSelect={() => setSelectedActionIndex(index)}
                  onChange={(updated) => updateAction(index, updated)}
                  onRemove={() => removeAction(index)}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/**
 * Automation List View
 * Liste des automations avec statut, enable/disable toggle, last run
 */

import React, { useEffect, useState } from 'react';
import { ipc } from '../../lib/api';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import type { Automation, AutomationLog } from '@cortex-ide/shared';
import { Play, Square, Trash2, Edit, Plus } from 'lucide-react';

interface AutomationListProps {
  workspaceId: string;
  onEdit: (automation: Automation) => void;
  onCreate: () => void;
  onViewLogs: (automation: Automation) => void;
}

export const AutomationList: React.FC<AutomationListProps> = ({
  workspaceId,
  onEdit,
  onCreate,
  onViewLogs,
}) => {
  const [automations, setAutomations] = useState<Automation[]>([]);
  const [loading, setLoading] = useState(true);
  const [runningIds, setRunningIds] = useState<Set<string>>(new Set());
  const [lastRuns, setLastRuns] = useState<Map<string, AutomationLog>>(new Map());

  // Charger les automations
  useEffect(() => {
    loadAutomations();
  }, [workspaceId]);

  // Écouter les événements d'automation
  useEffect(() => {
    const unsubscribeStarted = ipc.automation.onStarted((event) => {
      setRunningIds((prev) => new Set(prev).add(event.automation.id));
    });

    const unsubscribeCompleted = ipc.automation.onCompleted((event) => {
      setRunningIds((prev) => {
        const next = new Set(prev);
        next.delete(event.automation.id);
        return next;
      });
      setLastRuns((prev) => new Map(prev).set(event.automation.id, event.log));
    });

    const unsubscribeFailed = ipc.automation.onFailed((event) => {
      setRunningIds((prev) => {
        const next = new Set(prev);
        next.delete(event.automation.id);
        return next;
      });
      setLastRuns((prev) => new Map(prev).set(event.automation.id, event.log));
    });

    return () => {
      unsubscribeStarted();
      unsubscribeCompleted();
      unsubscribeFailed();
    };
  }, []);

  const loadAutomations = async () => {
    try {
      setLoading(true);
      const list = await ipc.automation.list(workspaceId);
      setAutomations(list);

      // Charger les derniers logs pour chaque automation
      for (const automation of list) {
        const logs = await ipc.automation.getLogs(automation.id, 1);
        if (logs.length > 0) {
          setLastRuns((prev) => new Map(prev).set(automation.id, logs[0]));
        }
      }
    } catch (error) {
      console.error('Failed to load automations:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleToggle = async (automation: Automation) => {
    try {
      const updated = await ipc.automation.toggle(automation.id, !automation.enabled);
      setAutomations((prev) =>
        prev.map((a) => (a.id === updated.id ? updated : a))
      );
    } catch (error) {
      console.error('Failed to toggle automation:', error);
    }
  };

  const handleRun = async (automation: Automation) => {
    try {
      await ipc.automation.run(automation.id);
    } catch (error) {
      console.error('Failed to run automation:', error);
    }
  };

  const handleDelete = async (automation: Automation) => {
    if (!confirm(`Delete automation "${automation.name}"?`)) return;

    try {
      await ipc.automation.delete(automation.id);
      setAutomations((prev) => prev.filter((a) => a.id !== automation.id));
    } catch (error) {
      console.error('Failed to delete automation:', error);
    }
  };

  const getTriggerLabel = (trigger: Automation['trigger']): string => {
    switch (trigger.type) {
      case 'file_watch':
        return `File: ${trigger.patterns.join(', ')}`;
      case 'git_hook':
        return `Git: ${trigger.hook}`;
      case 'schedule':
        return `Schedule: ${trigger.cron}`;
      case 'manual':
        return 'Manual';
    }
  };

  const getStatusBadge = (automation: Automation) => {
    const isRunning = runningIds.has(automation.id);
    const lastRun = lastRuns.get(automation.id);

    if (isRunning) {
      return <Badge variant="default">Running</Badge>;
    }

    if (!automation.enabled) {
      return <Badge variant="secondary">Disabled</Badge>;
    }

    if (lastRun) {
      switch (lastRun.status) {
        case 'success':
          return <Badge className="bg-green-500">Success</Badge>;
        case 'error':
          return <Badge className="bg-red-500">Error</Badge>;
        default:
          return <Badge variant="secondary">Idle</Badge>;
      }
    }

    return <Badge variant="secondary">Never run</Badge>;
  };

  const formatTimestamp = (timestamp: number): string => {
    const date = new Date(timestamp);
    const now = Date.now();
    const diff = now - timestamp;

    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`;
    return date.toLocaleDateString();
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-muted-foreground">Loading automations...</div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-border">
        <h2 className="text-lg font-semibold">Automations</h2>
        <Button size="sm" onClick={onCreate}>
          <Plus className="w-4 h-4 mr-2" />
          New Automation
        </Button>
      </div>

      {/* List */}
      <div className="flex-1 overflow-auto">
        {automations.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-8">
            <p className="text-muted-foreground mb-4">No automations yet</p>
            <Button onClick={onCreate}>Create your first automation</Button>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {automations.map((automation) => {
              const lastRun = lastRuns.get(automation.id);
              const isRunning = runningIds.has(automation.id);

              return (
                <div
                  key={automation.id}
                  className="p-4 hover:bg-accent/50 transition-colors"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1 min-w-0">
                      {/* Name & Status */}
                      <div className="flex items-center gap-2 mb-2">
                        <h3 className="font-medium truncate">{automation.name}</h3>
                        {getStatusBadge(automation)}
                      </div>

                      {/* Trigger */}
                      <div className="text-sm text-muted-foreground mb-2">
                        {getTriggerLabel(automation.trigger)}
                      </div>

                      {/* Actions count */}
                      <div className="text-xs text-muted-foreground">
                        {automation.actions.length} action
                        {automation.actions.length !== 1 ? 's' : ''}
                      </div>

                      {/* Last run */}
                      {lastRun && (
                        <div className="text-xs text-muted-foreground mt-1">
                          Last run: {formatTimestamp(lastRun.startedAt)}
                          {lastRun.completedAt && (
                            <span className="ml-2">
                              ({Math.round((lastRun.completedAt - lastRun.startedAt) / 1000)}s)
                            </span>
                          )}
                        </div>
                      )}
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-2 ml-4">
                      {/* Toggle */}
                      <button
                        onClick={() => handleToggle(automation)}
                        className={`
                          relative inline-flex h-6 w-11 items-center rounded-full
                          transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2
                          ${automation.enabled ? 'bg-primary' : 'bg-muted'}
                        `}
                        aria-label={automation.enabled ? 'Disable' : 'Enable'}
                      >
                        <span
                          className={`
                            inline-block h-4 w-4 transform rounded-full bg-white transition-transform
                            ${automation.enabled ? 'translate-x-6' : 'translate-x-1'}
                          `}
                        />
                      </button>

                      {/* Run */}
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleRun(automation)}
                        disabled={isRunning}
                      >
                        {isRunning ? (
                          <Square className="w-4 h-4" />
                        ) : (
                          <Play className="w-4 h-4" />
                        )}
                      </Button>

                      {/* Edit */}
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => onEdit(automation)}
                      >
                        <Edit className="w-4 h-4" />
                      </Button>

                      {/* Logs */}
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => onViewLogs(automation)}
                      >
                        Logs
                      </Button>

                      {/* Delete */}
                      <Button
                        size="sm"
                        variant="ghost"
                        onClick={() => handleDelete(automation)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Logs Viewer Component
 * Affichage de l'historique d'exécution des automations
 */

import React, { useEffect, useState } from 'react';
import { ipc } from '../../lib/api';
import { Badge } from '../../components/ui/badge';
import type { Automation, AutomationLog } from '@cortex-ide/shared';
import { ChevronDown, ChevronRight, Clock, CheckCircle, XCircle } from 'lucide-react';

interface LogsViewerProps {
  automation: Automation;
}

export const LogsViewer: React.FC<LogsViewerProps> = ({ automation }) => {
  const [logs, setLogs] = useState<AutomationLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedLogs, setExpandedLogs] = useState<Set<string>>(new Set());

  useEffect(() => {
    loadLogs();
  }, [automation.id]);

  const loadLogs = async () => {
    try {
      setLoading(true);
      const logs = await ipc.automation.getLogs(automation.id, 50);
      setLogs(logs);
    } catch (error) {
      console.error('Failed to load logs:', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleLogExpanded = (logId: string) => {
    setExpandedLogs((prev) => {
      const next = new Set(prev);
      if (next.has(logId)) {
        next.delete(logId);
      } else {
        next.add(logId);
      }
      return next;
    });
  };

  const formatTimestamp = (timestamp: number): string => {
    const date = new Date(timestamp);
    return date.toLocaleString();
  };

  const formatDuration = (startedAt: number, completedAt?: number): string => {
    if (!completedAt) return 'Running...';
    const duration = Math.round((completedAt - startedAt) / 1000);
    return `${duration}s`;
  };

  const getStatusIcon = (status: AutomationLog['status']) => {
    switch (status) {
      case 'running':
        return <Clock className="w-4 h-4 text-blue-500 animate-spin" />;
      case 'success':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'error':
        return <XCircle className="w-4 h-4 text-red-500" />;
      default:
        return <Clock className="w-4 h-4 text-muted-foreground" />;
    }
  };

  const getStatusBadge = (status: AutomationLog['status']) => {
    switch (status) {
      case 'running':
        return <Badge variant="default">Running</Badge>;
      case 'success':
        return <Badge className="bg-green-500">Success</Badge>;
      case 'error':
        return <Badge className="bg-red-500">Error</Badge>;
      default:
        return <Badge variant="secondary">Idle</Badge>;
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-muted-foreground">Loading logs...</div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="p-4 border-b border-border">
        <h3 className="text-lg font-semibold">Execution Logs</h3>
        <p className="text-sm text-muted-foreground">
          {automation.name} - {logs.length} execution(s)
        </p>
      </div>

      {/* Logs List */}
      <div className="flex-1 overflow-auto">
        {logs.length === 0 ? (
          <div className="flex items-center justify-center h-full">
            <p className="text-muted-foreground">No logs yet</p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {logs.map((log) => {
              const isExpanded = expandedLogs.has(log.id);

              return (
                <div key={log.id} className="p-4">
                  {/* Log Header */}
                  <div
                    className="flex items-start justify-between cursor-pointer hover:bg-accent/50 -m-2 p-2 rounded"
                    onClick={() => toggleLogExpanded(log.id)}
                  >
                    <div className="flex items-start gap-3 flex-1">
                      {isExpanded ? (
                        <ChevronDown className="w-4 h-4 mt-1" />
                      ) : (
                        <ChevronRight className="w-4 h-4 mt-1" />
                      )}
                      {getStatusIcon(log.status)}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          {getStatusBadge(log.status)}
                          <span className="text-sm text-muted-foreground">
                            {formatTimestamp(log.startedAt)}
                          </span>
                        </div>
                        <div className="text-sm text-muted-foreground">
                          Duration: {formatDuration(log.startedAt, log.completedAt)}
                        </div>
                        {log.error && (
                          <div className="text-sm text-red-500 mt-1">
                            Error: {log.error}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Log Details */}
                  {isExpanded && (
                    <div className="mt-4 ml-9 space-y-3">
                      {/* Action Results */}
                      <div>
                        <h4 className="text-sm font-semibold mb-2">
                          Action Results ({log.actionResults.length})
                        </h4>
                        <div className="space-y-2">
                          {log.actionResults.map((result, index) => (
                            <div
                              key={index}
                              className="border border-border rounded-md p-3"
                            >
                              <div className="flex items-center justify-between mb-2">
                                <div className="flex items-center gap-2">
                                  {result.status === 'success' ? (
                                    <CheckCircle className="w-4 h-4 text-green-500" />
                                  ) : (
                                    <XCircle className="w-4 h-4 text-red-500" />
                                  )}
                                  <span className="text-sm font-medium">
                                    Action {index + 1}: {result.action.type}
                                  </span>
                                </div>
                                <span className="text-xs text-muted-foreground">
                                  {result.duration}ms
                                </span>
                              </div>

                              {result.output && (
                                <div className="mt-2">
                                  <div className="text-xs text-muted-foreground mb-1">
                                    Output:
                                  </div>
                                  <pre className="text-xs bg-accent/50 p-2 rounded overflow-x-auto">
                                    {result.output}
                                  </pre>
                                </div>
                              )}

                              {result.error && (
                                <div className="mt-2">
                                  <div className="text-xs text-red-500 mb-1">
                                    Error:
                                  </div>
                                  <pre className="text-xs bg-red-500/10 p-2 rounded overflow-x-auto text-red-500">
                                    {result.error}
                                  </pre>
                                </div>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* Global Output */}
                      {log.output && (
                        <div>
                          <h4 className="text-sm font-semibold mb-2">Output</h4>
                          <pre className="text-xs bg-accent/50 p-3 rounded overflow-x-auto">
                            {log.output}
                          </pre>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

/**
 * Trigger Configuration Component
 * Configuration des triggers d'automation
 */

import React from 'react';
import { Input } from '../../components/ui/input';
import { Select } from '../../components/ui/select';
import { Textarea } from '../../components/ui/textarea';
import type { Trigger, FileTrigger, GitTrigger, ScheduleTrigger } from '@cortex-ide/shared';

interface TriggerConfigProps {
  trigger: Trigger;
  onChange: (trigger: Trigger) => void;
  workspaceId: string;
}

export const TriggerConfig: React.FC<TriggerConfigProps> = ({
  trigger,
  onChange,
  workspaceId,
}) => {
  const handleTypeChange = (type: Trigger['type']) => {
    switch (type) {
      case 'file_watch':
        onChange({
          type: 'file_watch',
          patterns: ['**/*.ts'],
          events: ['change'],
          workspacePath: '/path/to/workspace',
        });
        break;
      case 'git_hook':
        onChange({
          type: 'git_hook',
          hook: 'pre-commit',
          repoPath: '/path/to/repo',
        });
        break;
      case 'schedule':
        onChange({
          type: 'schedule',
          cron: '0 0 * * *',
        });
        break;
      case 'manual':
        onChange({
          type: 'manual',
        });
        break;
    }
  };

  return (
    <div className="space-y-4 p-4 border border-border rounded-md">
      {/* Type Selector */}
      <div>
        <label className="block text-sm font-medium mb-2">Trigger Type</label>
        <select
          value={trigger.type}
          onChange={(e) => handleTypeChange(e.target.value as Trigger['type'])}
          className="w-full px-3 py-2 border border-border rounded-md bg-background"
        >
          <option value="manual">Manual</option>
          <option value="file_watch">File Watch</option>
          <option value="git_hook">Git Hook</option>
          <option value="schedule">Schedule (Cron)</option>
        </select>
      </div>

      {/* File Watch Config */}
      {trigger.type === 'file_watch' && (
        <>
          <div>
            <label className="block text-sm font-medium mb-2">
              Patterns (one per line)
            </label>
            <Textarea
              value={(trigger as FileTrigger).patterns.join('\n')}
              onChange={(e) =>
                onChange({
                  ...trigger,
                  patterns: e.target.value.split('\n').filter((p) => p.trim()),
                } as FileTrigger)
              }
              placeholder="**/*.ts&#10;**/*.tsx&#10;src/**/*.js"
              rows={4}
            />
            <p className="text-xs text-muted-foreground mt-1">
              Glob patterns to watch
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Events</label>
            <div className="space-y-2">
              {(['add', 'change', 'unlink'] as const).map((event) => (
                <label key={event} className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={(trigger as FileTrigger).events.includes(event)}
                    onChange={(e) => {
                      const events = (trigger as FileTrigger).events;
                      onChange({
                        ...trigger,
                        events: e.target.checked
                          ? [...events, event]
                          : events.filter((ev) => ev !== event),
                      } as FileTrigger);
                    }}
                    className="rounded border-border"
                  />
                  <span className="text-sm capitalize">{event}</span>
                </label>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Workspace Path
            </label>
            <Input
              value={(trigger as FileTrigger).workspacePath}
              onChange={(e) =>
                onChange({
                  ...trigger,
                  workspacePath: e.target.value,
                } as FileTrigger)
              }
              placeholder="/path/to/workspace"
            />
          </div>
        </>
      )}

      {/* Git Hook Config */}
      {trigger.type === 'git_hook' && (
        <>
          <div>
            <label className="block text-sm font-medium mb-2">Hook Type</label>
            <select
              value={(trigger as GitTrigger).hook}
              onChange={(e) =>
                onChange({
                  ...trigger,
                  hook: e.target.value as GitTrigger['hook'],
                } as GitTrigger)
              }
              className="w-full px-3 py-2 border border-border rounded-md bg-background"
            >
              <option value="pre-commit">Pre-commit</option>
              <option value="post-commit">Post-commit</option>
              <option value="pre-push">Pre-push</option>
              <option value="post-merge">Post-merge</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Repository Path
            </label>
            <Input
              value={(trigger as GitTrigger).repoPath}
              onChange={(e) =>
                onChange({
                  ...trigger,
                  repoPath: e.target.value,
                } as GitTrigger)
              }
              placeholder="/path/to/repo"
            />
          </div>
        </>
      )}

      {/* Schedule Config */}
      {trigger.type === 'schedule' && (
        <>
          <div>
            <label className="block text-sm font-medium mb-2">
              Cron Expression
            </label>
            <Input
              value={(trigger as ScheduleTrigger).cron}
              onChange={(e) =>
                onChange({
                  ...trigger,
                  cron: e.target.value,
                } as ScheduleTrigger)
              }
              placeholder="0 0 * * *"
            />
            <p className="text-xs text-muted-foreground mt-1">
              Examples: "0 0 * * *" (daily at midnight), "*/15 * * * *" (every
              15 min)
            </p>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">
              Timezone (optional)
            </label>
            <Input
              value={(trigger as ScheduleTrigger).timezone || ''}
              onChange={(e) =>
                onChange({
                  ...trigger,
                  timezone: e.target.value || undefined,
                } as ScheduleTrigger)
              }
              placeholder="America/New_York"
            />
          </div>
        </>
      )}

      {/* Manual Config */}
      {trigger.type === 'manual' && (
        <p className="text-sm text-muted-foreground">
          This automation will only run when triggered manually.
        </p>
      )}
    </div>
  );
};

/**
 * Console Panel - Display all logs from main and renderer
 */

import * as React from 'react';
import type { LogEntry, LogLevel } from '@cortex-ide/shared/types/debug';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Select } from '../../components/ui/select';
import { FiTrash2, FiFilter, FiSearch } from 'react-icons/fi';

export function ConsolePanel() {
  const [logs, setLogs] = React.useState<LogEntry[]>([]);
  const [filter, setFilter] = React.useState({
    level: 'all',
    category: '',
    source: 'all',
    search: ''
  });
  const scrollRef = React.useRef<HTMLDivElement>(null);
  const [autoScroll, setAutoScroll] = React.useState(true);

  // Load initial logs
  React.useEffect(() => {
    loadLogs();
    const interval = setInterval(loadLogs, 2000);
    return () => clearInterval(interval);
  }, []);

  // Auto scroll
  React.useEffect(() => {
    if (autoScroll && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs, autoScroll]);

  const loadLogs = async () => {
    try {
      const result = await window.electron.invoke('debug:get-logs', 1000);
      setLogs(result);
    } catch (error) {
      console.error('Failed to load logs:', error);
    }
  };

  const handleClear = async () => {
    try {
      await window.electron.invoke('debug:clear-logs');
      setLogs([]);
    } catch (error) {
      console.error('Failed to clear logs:', error);
    }
  };

  const filteredLogs = React.useMemo(() => {
    return logs.filter(log => {
      if (filter.level !== 'all' && log.level !== filter.level) return false;
      if (filter.source !== 'all' && log.source !== filter.source) return false;
      if (filter.category && !log.category.includes(filter.category)) return false;
      if (filter.search) {
        const searchLower = filter.search.toLowerCase();
        return (
          log.message.toLowerCase().includes(searchLower) ||
          log.category.toLowerCase().includes(searchLower)
        );
      }
      return true;
    });
  }, [logs, filter]);

  const getLevelColor = (level: LogLevel): string => {
    switch (level) {
      case 'debug': return 'text-gray-400';
      case 'info': return 'text-blue-400';
      case 'warn': return 'text-yellow-400';
      case 'error': return 'text-red-400';
      default: return 'text-text';
    }
  };

  const getLevelBg = (level: LogLevel): string => {
    switch (level) {
      case 'debug': return 'bg-gray-500/10';
      case 'info': return 'bg-blue-500/10';
      case 'warn': return 'bg-yellow-500/10';
      case 'error': return 'bg-red-500/10';
      default: return 'bg-surface';
    }
  };

  return (
    <div className="h-full flex flex-col">
      {/* Toolbar */}
      <div className="h-12 border-b border-border flex items-center gap-2 px-3 bg-background">
        <div className="flex items-center gap-2 flex-1">
          <FiSearch className="w-4 h-4 text-text-secondary" />
          <Input
            placeholder="Search logs..."
            value={filter.search}
            onChange={(e) => setFilter({ ...filter, search: e.target.value })}
            className="h-8 w-64"
          />
        </div>

        <select
          value={filter.level}
          onChange={(e) => setFilter({ ...filter, level: e.target.value })}
          className="h-8 px-2 text-sm bg-surface border border-border rounded-sm"
        >
          <option value="all">All Levels</option>
          <option value="debug">Debug</option>
          <option value="info">Info</option>
          <option value="warn">Warn</option>
          <option value="error">Error</option>
        </select>

        <select
          value={filter.source}
          onChange={(e) => setFilter({ ...filter, source: e.target.value })}
          className="h-8 px-2 text-sm bg-surface border border-border rounded-sm"
        >
          <option value="all">All Sources</option>
          <option value="main">Main</option>
          <option value="renderer">Renderer</option>
        </select>

        <Button variant="ghost" size="sm" onClick={handleClear} className="h-8">
          <FiTrash2 className="w-4 h-4" />
        </Button>

        <label className="flex items-center gap-2 text-xs">
          <input
            type="checkbox"
            checked={autoScroll}
            onChange={(e) => setAutoScroll(e.target.checked)}
            className="w-4 h-4"
          />
          Auto-scroll
        </label>
      </div>

      {/* Logs */}
      <div ref={scrollRef} className="flex-1 overflow-auto font-mono text-xs">
        {filteredLogs.map((log) => (
          <div
            key={log.id}
            className={`px-3 py-1 border-b border-border/50 hover:bg-surface/50 ${getLevelBg(log.level)}`}
          >
            <div className="flex items-start gap-2">
              <span className="text-text-secondary whitespace-nowrap">
                {new Date(log.timestamp).toLocaleTimeString()}
              </span>
              <span className={`font-semibold uppercase whitespace-nowrap ${getLevelColor(log.level)}`}>
                {log.level}
              </span>
              <span className="text-accent whitespace-nowrap">
                [{log.category}]
              </span>
              <span className="text-text-secondary text-[10px] whitespace-nowrap">
                {log.source}
              </span>
              <span className="flex-1 text-text break-all">
                {log.message}
              </span>
            </div>
            {log.data && (
              <div className="mt-1 ml-32 text-text-secondary">
                {JSON.stringify(log.data, null, 2)}
              </div>
            )}
            {log.stack && (
              <div className="mt-1 ml-32 text-red-400 text-[10px] whitespace-pre-wrap">
                {log.stack}
              </div>
            )}
          </div>
        ))}
        {filteredLogs.length === 0 && (
          <div className="flex items-center justify-center h-full text-text-secondary">
            No logs to display
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="h-8 border-t border-border flex items-center justify-between px-3 text-xs text-text-secondary bg-background">
        <span>{filteredLogs.length} logs</span>
        <span>{logs.length} total</span>
      </div>
    </div>
  );
}

