/**
 * IPC Inspector - Monitor all IPC messages in real-time
 */

import * as React from 'react';
import type { IPCMessage } from '@cortex-ide/shared/types/debug';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { FiTrash2, FiSearch, FiChevronDown, FiChevronRight } from 'react-icons/fi';

export function IPCInspector() {
  const [messages, setMessages] = React.useState<IPCMessage[]>([]);
  const [stats, setStats] = React.useState<Record<string, { count: number; avgDuration: number }>>({});
  const [filter, setFilter] = React.useState({
    channel: '',
    direction: 'all'
  });
  const [expandedMessages, setExpandedMessages] = React.useState<Set<string>>(new Set());
  const scrollRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    loadMessages();
    loadStats();
    const interval = setInterval(() => {
      loadMessages();
      loadStats();
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const loadMessages = async () => {
    try {
      const result = await window.electron.invoke('debug:get-ipc-messages', 500);
      setMessages(result);
    } catch (error) {
      console.error('Failed to load IPC messages:', error);
    }
  };

  const loadStats = async () => {
    try {
      const result = await window.electron.invoke('debug:get-ipc-stats');
      setStats(result);
    } catch (error) {
      console.error('Failed to load IPC stats:', error);
    }
  };

  const handleClear = async () => {
    try {
      await window.electron.invoke('debug:clear-ipc');
      setMessages([]);
      setStats({});
    } catch (error) {
      console.error('Failed to clear IPC messages:', error);
    }
  };

  const toggleExpand = (id: string) => {
    const newExpanded = new Set(expandedMessages);
    if (newExpanded.has(id)) {
      newExpanded.delete(id);
    } else {
      newExpanded.add(id);
    }
    setExpandedMessages(newExpanded);
  };

  const filteredMessages = React.useMemo(() => {
    return messages.filter(msg => {
      if (filter.channel && !msg.channel.includes(filter.channel)) return false;
      if (filter.direction !== 'all' && msg.direction !== filter.direction) return false;
      return true;
    });
  }, [messages, filter]);

  return (
    <div className="h-full flex">
      {/* Messages List */}
      <div className="flex-1 flex flex-col border-r border-border">
        {/* Toolbar */}
        <div className="h-12 border-b border-border flex items-center gap-2 px-3 bg-background">
          <FiSearch className="w-4 h-4 text-text-secondary" />
          <Input
            placeholder="Filter by channel..."
            value={filter.channel}
            onChange={(e) => setFilter({ ...filter, channel: e.target.value })}
            className="h-8 flex-1"
          />

          <select
            value={filter.direction}
            onChange={(e) => setFilter({ ...filter, direction: e.target.value })}
            className="h-8 px-2 text-sm bg-surface border border-border rounded-sm"
          >
            <option value="all">All Directions</option>
            <option value="renderer->main">Renderer → Main</option>
            <option value="main->renderer">Main → Renderer</option>
          </select>

          <Button variant="ghost" size="sm" onClick={handleClear} className="h-8">
            <FiTrash2 className="w-4 h-4" />
          </Button>
        </div>

        {/* Messages */}
        <div ref={scrollRef} className="flex-1 overflow-auto font-mono text-xs">
          {filteredMessages.map((msg) => {
            const isExpanded = expandedMessages.has(msg.id);
            return (
              <div
                key={msg.id}
                className="border-b border-border/50 hover:bg-surface/50"
              >
                <div
                  className="px-3 py-2 cursor-pointer flex items-start gap-2"
                  onClick={() => toggleExpand(msg.id)}
                >
                  {isExpanded ? (
                    <FiChevronDown className="w-4 h-4 mt-0.5 flex-shrink-0" />
                  ) : (
                    <FiChevronRight className="w-4 h-4 mt-0.5 flex-shrink-0" />
                  )}
                  <span className="text-text-secondary whitespace-nowrap">
                    {new Date(msg.timestamp).toLocaleTimeString()}
                  </span>
                  <span className={`font-semibold whitespace-nowrap ${
                    msg.direction === 'renderer->main' ? 'text-blue-400' : 'text-green-400'
                  }`}>
                    {msg.direction === 'renderer->main' ? '→' : '←'}
                  </span>
                  <span className="flex-1 text-accent truncate">
                    {msg.channel}
                  </span>
                  {msg.duration !== undefined && (
                    <span className="text-text-secondary whitespace-nowrap">
                      {msg.duration.toFixed(1)}ms
                    </span>
                  )}
                </div>
                {isExpanded && (
                  <div className="px-3 pb-2 pl-11 text-text-secondary">
                    <pre className="text-[10px] whitespace-pre-wrap">
                      {JSON.stringify(msg.data, null, 2)}
                    </pre>
                  </div>
                )}
              </div>
            );
          })}
          {filteredMessages.length === 0 && (
            <div className="flex items-center justify-center h-full text-text-secondary">
              No IPC messages
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="h-8 border-t border-border flex items-center justify-between px-3 text-xs text-text-secondary bg-background">
          <span>{filteredMessages.length} messages</span>
        </div>
      </div>

      {/* Stats Sidebar */}
      <div className="w-80 flex flex-col bg-surface">
        <div className="h-12 border-b border-border flex items-center px-3 bg-background">
          <span className="text-sm font-medium">Channel Statistics</span>
        </div>
        <div className="flex-1 overflow-auto">
          <table className="w-full text-xs">
            <thead className="sticky top-0 bg-background border-b border-border">
              <tr>
                <th className="text-left p-2 font-medium">Channel</th>
                <th className="text-right p-2 font-medium">Count</th>
                <th className="text-right p-2 font-medium">Avg (ms)</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(stats)
                .sort((a, b) => b[1].count - a[1].count)
                .map(([channel, data]) => (
                  <tr key={channel} className="border-b border-border/50 hover:bg-background/50">
                    <td className="p-2 truncate font-mono" title={channel}>
                      {channel}
                    </td>
                    <td className="p-2 text-right text-accent">{data.count}</td>
                    <td className="p-2 text-right text-text-secondary">
                      {data.avgDuration.toFixed(1)}
                    </td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/**
 * Memory Panel - Real-time memory usage visualization
 */

import * as React from 'react';
import type { MemorySnapshot } from '@cortex-ide/shared/types/debug';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Button } from '../../components/ui/button';
import { FiTrash2 } from 'react-icons/fi';

export function MemoryPanel() {
  const [snapshots, setSnapshots] = React.useState<MemorySnapshot[]>([]);
  const [systemInfo, setSystemInfo] = React.useState<any>(null);

  React.useEffect(() => {
    loadSnapshots();
    loadSystemInfo();
    const interval = setInterval(loadSnapshots, 2000);
    return () => clearInterval(interval);
  }, []);

  const loadSnapshots = async () => {
    try {
      const result = await window.electron.invoke('debug:get-memory', 100);
      setSnapshots(result);
    } catch (error) {
      console.error('Failed to load memory snapshots:', error);
    }
  };

  const loadSystemInfo = async () => {
    try {
      const result = await window.electron.invoke('debug:get-system-info');
      setSystemInfo(result);
    } catch (error) {
      console.error('Failed to load system info:', error);
    }
  };

  const handleClear = async () => {
    try {
      await window.electron.invoke('debug:clear-metrics');
      setSnapshots([]);
    } catch (error) {
      console.error('Failed to clear memory data:', error);
    }
  };

  // Prepare chart data
  const chartData = React.useMemo(() => {
    return snapshots.map((snapshot, i) => ({
      index: i,
      heapUsed: snapshot.heapUsed / 1024 / 1024,
      heapTotal: snapshot.heapTotal / 1024 / 1024,
      external: snapshot.external / 1024 / 1024,
      rss: snapshot.rss / 1024 / 1024
    }));
  }, [snapshots]);

  // Latest snapshot
  const latest = snapshots[snapshots.length - 1];

  const formatBytes = (bytes: number): string => {
    const mb = bytes / 1024 / 1024;
    return mb >= 1000 ? `${(mb / 1024).toFixed(2)} GB` : `${mb.toFixed(2)} MB`;
  };

  return (
    <div className="h-full flex flex-col">
      {/* Toolbar */}
      <div className="h-12 border-b border-border flex items-center gap-2 px-3 bg-background">
        <span className="text-sm font-medium">Memory Usage</span>
        <div className="flex-1" />
        <Button variant="ghost" size="sm" onClick={handleClear} className="h-8">
          <FiTrash2 className="w-4 h-4" />
        </Button>
      </div>

      <div className="flex-1 flex">
        {/* Chart */}
        <div className="flex-1 p-4">
          {chartData.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                <XAxis dataKey="index" stroke="#666" />
                <YAxis stroke="#666" label={{ value: 'MB', angle: -90, position: 'insideLeft' }} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: '#1a1a1a',
                    border: '1px solid #333',
                    borderRadius: '4px'
                  }}
                  formatter={(value: number) => `${value.toFixed(2)} MB`}
                />
                <Legend />
                <Line
                  type="monotone"
                  dataKey="heapUsed"
                  stroke="#3b82f6"
                  name="Heap Used"
                  dot={false}
                  strokeWidth={2}
                />
                <Line
                  type="monotone"
                  dataKey="heapTotal"
                  stroke="#10b981"
                  name="Heap Total"
                  dot={false}
                  strokeWidth={2}
                />
                <Line
                  type="monotone"
                  dataKey="external"
                  stroke="#f59e0b"
                  name="External"
                  dot={false}
                  strokeWidth={2}
                />
                <Line
                  type="monotone"
                  dataKey="rss"
                  stroke="#ef4444"
                  name="RSS"
                  dot={false}
                  strokeWidth={2}
                />
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex items-center justify-center h-full text-text-secondary">
              No memory data
            </div>
          )}
        </div>

        {/* Stats Sidebar */}
        <div className="w-80 border-l border-border bg-surface overflow-auto">
          <div className="sticky top-0 h-12 border-b border-border flex items-center px-3 bg-background">
            <span className="text-sm font-medium">Current Memory</span>
          </div>

          {latest && (
            <div className="p-3 space-y-3">
              <div className="p-3 bg-background rounded border border-border">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-3 h-3 rounded-full bg-blue-500" />
                  <span className="text-sm font-medium">Heap Used</span>
                </div>
                <div className="text-2xl font-bold text-accent">
                  {formatBytes(latest.heapUsed)}
                </div>
                <div className="text-xs text-text-secondary mt-1">
                  {((latest.heapUsed / latest.heapTotal) * 100).toFixed(1)}% of heap
                </div>
              </div>

              <div className="p-3 bg-background rounded border border-border">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-3 h-3 rounded-full bg-green-500" />
                  <span className="text-sm font-medium">Heap Total</span>
                </div>
                <div className="text-2xl font-bold text-text">
                  {formatBytes(latest.heapTotal)}
