                  <span className="text-text">{systemInfo.platform}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-text-secondary">Arch:</span>
                  <span className="text-text">{systemInfo.arch}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-text-secondary">Electron:</span>
                  <span className="text-text">{systemInfo.electron}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-text-secondary">Chrome:</span>
                  <span className="text-text">{systemInfo.chrome}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-text-secondary">Node:</span>
                  <span className="text-text">{systemInfo.node}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-text-secondary">V8:</span>
                  <span className="text-text">{systemInfo.v8}</span>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * Performance Panel - Real-time performance metrics
 */

import * as React from 'react';
import type { PerformanceMetric } from '@cortex-ide/shared/types/debug';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Button } from '../../components/ui/button';
import { FiTrash2 } from 'react-icons/fi';

export function PerformancePanel() {
  const [metrics, setMetrics] = React.useState<PerformanceMetric[]>([]);
  const [selectedCategory, setSelectedCategory] = React.useState('timing');

  React.useEffect(() => {
    loadMetrics();
    const interval = setInterval(loadMetrics, 2000);
    return () => clearInterval(interval);
  }, []);

  const loadMetrics = async () => {
    try {
      const result = await window.electron.invoke('debug:get-metrics', undefined, 500);
      setMetrics(result);
    } catch (error) {
      console.error('Failed to load metrics:', error);
    }
  };

  const handleClear = async () => {
    try {
      await window.electron.invoke('debug:clear-metrics');
      setMetrics([]);
    } catch (error) {
      console.error('Failed to clear metrics:', error);
    }
  };

  // Group metrics by category
  const categories = React.useMemo(() => {
    const cats = new Set(metrics.map(m => m.category));
    return Array.from(cats);
  }, [metrics]);

  // Prepare chart data
  const chartData = React.useMemo(() => {
    const filtered = metrics.filter(m => m.category === selectedCategory);

    // Group by name
    const byName = new Map<string, PerformanceMetric[]>();
    for (const metric of filtered) {
      if (!byName.has(metric.name)) {
        byName.set(metric.name, []);
      }
      byName.get(metric.name)!.push(metric);
    }

    // Take last 50 data points per metric
    const names = Array.from(byName.keys());
    const data: any[] = [];

    const maxLength = Math.max(...Array.from(byName.values()).map(m => m.length));
    const limit = Math.min(maxLength, 50);

    for (let i = Math.max(0, maxLength - limit); i < maxLength; i++) {
      const point: any = { index: i };
      for (const name of names) {
        const metricData = byName.get(name)!;
        if (i < metricData.length) {
          point[name] = metricData[i].value;
        }
      }
      data.push(point);
    }

    return { data, names };
  }, [metrics, selectedCategory]);

  // Calculate stats
  const stats = React.useMemo(() => {
    const result: Record<string, { min: number; max: number; avg: number; count: number }> = {};

    const filtered = metrics.filter(m => m.category === selectedCategory);
    const byName = new Map<string, number[]>();

    for (const metric of filtered) {
      if (!byName.has(metric.name)) {
        byName.set(metric.name, []);
      }
      byName.get(metric.name)!.push(metric.value);
    }

    for (const [name, values] of byName) {
      result[name] = {
        min: Math.min(...values),
        max: Math.max(...values),
        avg: values.reduce((a, b) => a + b, 0) / values.length,
        count: values.length
      };
    }

    return result;
  }, [metrics, selectedCategory]);

  const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

  return (
    <div className="h-full flex flex-col">
      {/* Toolbar */}
      <div className="h-12 border-b border-border flex items-center gap-2 px-3 bg-background">
        <span className="text-sm text-text-secondary">Category:</span>
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value)}
          className="h-8 px-2 text-sm bg-surface border border-border rounded-sm"
        >
          {categories.map(cat => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>

        <div className="flex-1" />

        <Button variant="ghost" size="sm" onClick={handleClear} className="h-8">
          <FiTrash2 className="w-4 h-4" />
        </Button>
      </div>

      <div className="flex-1 flex">
        {/* Chart */}
        <div className="flex-1 p-4">
          {chartData.data.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={chartData.data}>
                <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                <XAxis dataKey="index" stroke="#666" />
                <YAxis stroke="#666" />
                <Tooltip
                  contentStyle={{
                    backgroundColor: '#1a1a1a',
                    border: '1px solid #333',
                    borderRadius: '4px'
                  }}
                />
                <Legend />
                {chartData.names.map((name, i) => (
                  <Line
                    key={name}
                    type="monotone"
                    dataKey={name}
                    stroke={colors[i % colors.length]}
                    dot={false}
                    strokeWidth={2}
                  />
                ))}
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="flex items-center justify-center h-full text-text-secondary">
              No performance data
            </div>
          )}
        </div>

        {/* Stats Sidebar */}
        <div className="w-80 border-l border-border bg-surface overflow-auto">
          <div className="sticky top-0 h-12 border-b border-border flex items-center px-3 bg-background">
