/**
 * EditorView - Main editor component with Monaco Editor integration
 */

import React, { useEffect, useRef, useState } from 'react';
import Editor from '@monaco-editor/react';
import type { editor } from 'monaco-editor';
import { Monaco, OnMount } from '@monaco-editor/react';
import { useEditorStore } from '../../store/editor-store';
import { TabManager } from './TabManager';
import { useTheme } from '../../hooks/use-theme';
import { Spinner } from '../../components/ui/spinner';

export const EditorView: React.FC = () => {
  const { 
    activeTabId, 
    updateTabContent, 
    markTabDirty,
    updateCursorPosition,
    updateScrollPosition,
    getActiveTab 
  } = useEditorStore();

  const { theme } = useTheme();
  const editorRef = useRef<editor.IStandaloneCodeEditor | null>(null);
  const monacoRef = useRef<Monaco | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const activeTab = getActiveTab();

  // Configure Monaco Editor on mount
  const handleEditorMount: OnMount = (editor, monaco) => {
    editorRef.current = editor;
    monacoRef.current = monaco;
    setIsLoading(false);

    // Configure editor options
    editor.updateOptions({
      fontSize: 14,
      fontFamily: "'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace",
      fontLigatures: true,
      lineHeight: 24,
      minimap: {
        enabled: true,
        scale: 1,
        showSlider: 'mouseover',
      },
      scrollBeyondLastLine: false,
      renderLineHighlight: 'all',
      smoothScrolling: true,
      cursorBlinking: 'smooth',
      cursorSmoothCaretAnimation: 'on',
      bracketPairColorization: {
        enabled: true,
      },
      guides: {
        bracketPairs: true,
        indentation: true,
      },
      suggest: {
        preview: true,
        showInlineDetails: true,
      },
      quickSuggestions: {
        other: true,
        comments: false,
        strings: false,
      },
      folding: true,
      foldingStrategy: 'indentation',
      showFoldingControls: 'mouseover',
      matchBrackets: 'always',
      autoClosingBrackets: 'always',
      autoClosingQuotes: 'always',
      formatOnPaste: true,
      formatOnType: true,
    });

    // Track cursor position
    editor.onDidChangeCursorPosition((e) => {
      if (activeTabId) {
        updateCursorPosition(
          activeTabId,
          e.position.lineNumber,
          e.position.column
        );
      }
    });

    // Track scroll position
    editor.onDidScrollChange((e) => {
      if (activeTabId) {
        updateScrollPosition(activeTabId, e.scrollTop, e.scrollLeft);
      }
    });

    // Keyboard shortcuts
    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
      handleSaveFile();
    });

    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyF, () => {
      editor.getAction('actions.find')?.run();
    });

    editor.addCommand(
      monaco.KeyMod.CtrlCmd | monaco.KeyMod.Shift | monaco.KeyCode.KeyF,
      () => {
        editor.getAction('editor.action.startFindReplaceAction')?.run();
      }
    );

    // Focus editor
    editor.focus();
  };

  // Handle content changes
  const handleEditorChange = (value: string | undefined) => {
    if (!activeTabId || !activeTab) return;

    const newContent = value || '';
    const isDirty = newContent !== activeTab.content;

    updateTabContent(activeTabId, newContent);
    markTabDirty(activeTabId, isDirty);
  };

  // Save file via IPC
  const handleSaveFile = async () => {
    if (!activeTab || !activeTab.isDirty) return;

    try {
      const response = await window.cortex.editor.saveFile({
        path: activeTab.path,
        content: activeTab.content,
      });

      if (response.success && response.data) {
        markTabDirty(activeTab.id, false);
        console.log('File saved successfully:', activeTab.path);
      } else {
        console.error('Failed to save file');
        // TODO: Show error toast
      }
    } catch (error) {
      console.error('Error saving file:', error);
      // TODO: Show error toast
    }
  };

  // Restore cursor and scroll position when switching tabs
  useEffect(() => {
    if (!editorRef.current || !activeTab) return;

    const editor = editorRef.current;

    // Restore cursor position
    if (activeTab.cursorPosition) {
      editor.setPosition({
        lineNumber: activeTab.cursorPosition.line,
        column: activeTab.cursorPosition.column,
      });
    }

    // Restore scroll position
    if (activeTab.scrollPosition) {
      editor.setScrollPosition({
        scrollTop: activeTab.scrollPosition.top,
        scrollLeft: activeTab.scrollPosition.left,
      });
    }

    editor.focus();
  }, [activeTabId]);

  // Auto-save on blur (optional)
  useEffect(() => {
    const handleBlur = () => {
      if (activeTab?.isDirty) {
        handleSaveFile();
      }
    };

    window.addEventListener('blur', handleBlur);
    return () => window.removeEventListener('blur', handleBlur);
  }, [activeTab]);

  return (
    <div className="flex flex-col h-full w-full">
      {/* Tab Bar */}
      <TabManager />

      {/* Editor Area */}
      <div className="flex-1 relative">
        {!activeTab ? (
          <div className="flex items-center justify-center h-full text-muted-foreground">
            <div className="text-center space-y-2">
              <p className="text-lg font-medium">No file open</p>
              <p className="text-sm">Open a file from the explorer to start editing</p>
            </div>
          </div>
        ) : (
          <>
            {isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-background z-10">
                <Spinner size="lg" />
              </div>
            )}

            <Editor
              height="100%"
              language={activeTab.language}
              value={activeTab.content}
              theme={theme === 'dark' ? 'vs-dark' : 'vs-light'}
              onChange={handleEditorChange}
              onMount={handleEditorMount}
              loading={<Spinner size="lg" />}
              options={{
                readOnly: false,
                automaticLayout: true,
              }}
            />

            {/* Status bar */}
            <div className="absolute bottom-0 left-0 right-0 h-6 bg-accent/50 border-t border-border flex items-center justify-between px-3 text-xs text-muted-foreground">
              <div className="flex items-center gap-4">
                <span>
                  {activeTab.language.toUpperCase()}
                </span>
                {activeTab.cursorPosition && (
                  <span>
                    Ln {activeTab.cursorPosition.line}, Col {activeTab.cursorPosition.column}
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2">
                {activeTab.isDirty && (
                  <span className="text-primary">● Modified</span>
                )}
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

/**
 * FileExplorer - Tree view file explorer with context menu
 */

import React, { useState, useEffect } from 'react';
import { Tree, NodeRendererProps } from 'react-arborist';
import { 
  FiFile, 
  FiFolder, 
  FiChevronRight,
  FiChevronDown,
  FiFileText,
  FiImage,
  FiCode,
} from 'react-icons/fi';
import { cn } from '../../lib/utils';
import { useEditorStore } from '../../store/editor-store';
import { detectLanguageFromPath } from '../../lib/language-detect';
import { Spinner } from '../../components/ui/spinner';

interface FileNode {
  id: string;
  name: string;
  path: string;
  type: 'file' | 'directory' | 'symlink';
  children?: FileNode[];
}

export const FileExplorer: React.FC<{ workspacePath?: string }> = ({ workspacePath = '/' }) => {
  const [data, setData] = useState<FileNode[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const { openTab } = useEditorStore();

  // Load directory structure
  useEffect(() => {
    loadDirectory(workspacePath);
  }, [workspacePath]);

  const loadDirectory = async (path: string) => {
    setIsLoading(true);
    try {
      const response = await window.cortex.fs.readDir({ path, recursive: false });

      if (response.success && response.data) {
        const nodes: FileNode[] = response.data.entries.map((entry) => ({
          id: entry.path,
          name: entry.name,
          path: entry.path,
          type: entry.type,
          children: entry.type === 'directory' ? [] : undefined,
        }));

        setData(nodes);
      } else {
        console.error('Failed to load directory');
      }
    } catch (error) {
      console.error('Error loading directory:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Open file in editor
  const handleFileOpen = async (node: FileNode) => {
    if (node.type !== 'file') return;

    try {
      const response = await window.cortex.editor.openFile({ path: node.path });

      if (response.success && response.data) {
        const language = detectLanguageFromPath(node.path);
        openTab(node.path, response.data.content, language);
      } else {
        console.error('Failed to open file');
      }
    } catch (error) {
      console.error('Error opening file:', error);
    }
  };

  // Context menu actions
  const handleContextMenu = (node: FileNode, e: React.MouseEvent) => {
    e.preventDefault();

    // TODO: Implement proper context menu with Radix UI Dropdown
    console.log('Context menu for:', node.name);

    // For now, simple implementation
    // In production: use Radix UI ContextMenu or DropdownMenu
  };

  // Get icon for file type
  const getFileIcon = (name: string, type: string) => {
    if (type === 'directory') {
      return null; // Handled by arrow
    }

    const ext = name.split('.').pop()?.toLowerCase() || '';

    // Code files
    if (['js', 'ts', 'jsx', 'tsx', 'py', 'go', 'rs', 'java', 'c', 'cpp', 'cs'].includes(ext)) {
      return <FiCode className="w-4 h-4 text-blue-500" />;
    }

    // Images
    if (['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp'].includes(ext)) {
      return <FiImage className="w-4 h-4 text-purple-500" />;
    }

    // Text/markdown
    if (['md', 'txt', 'json', 'yaml', 'yml', 'toml'].includes(ext)) {
      return <FiFileText className="w-4 h-4 text-yellow-500" />;
    }

    return <FiFile className="w-4 h-4 text-muted-foreground" />;
  };

  // Custom node renderer
  const Node: React.FC<NodeRendererProps<FileNode>> = ({ node, style, dragHandle }) => {
    const isDirectory = node.data.type === 'directory';

    return (
      <div
        ref={dragHandle}
        style={style}
        className={cn(
          'flex items-center gap-1 px-2 py-1 cursor-pointer select-none',
          'hover:bg-accent/50 transition-colors',
          node.isSelected && 'bg-accent'
        )}
        onClick={() => {
          if (isDirectory) {
            node.toggle();
          } else {
            handleFileOpen(node.data);
          }
        }}
        onContextMenu={(e) => handleContextMenu(node.data, e)}
      >
        {/* Arrow for directories */}
        {isDirectory && (
          <span className="flex-shrink-0">
            {node.isOpen ? (
              <FiChevronDown className="w-3.5 h-3.5" />
            ) : (
              <FiChevronRight className="w-3.5 h-3.5" />
            )}
          </span>
        )}

        {/* Folder icon */}
        {isDirectory && (
          <span className="flex-shrink-0">
            {node.isOpen ? (
              <FiFolder className="w-4 h-4 text-blue-400" />
            ) : (
              <FiFolder className="w-4 h-4 text-blue-400" />
            )}
          </span>
        )}

        {/* File icon */}
        {!isDirectory && (
          <span className="flex-shrink-0 ml-3.5">
            {getFileIcon(node.data.name, node.data.type)}
          </span>
        )}

        {/* Name */}
        <span className="text-sm truncate">{node.data.name}</span>
      </div>
    );
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-full">
        <Spinner size="md" />
      </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className="flex items-center justify-center h-full text-sm text-muted-foreground p-4">
        <p>No files in workspace</p>
      </div>
    );
  }

  return (
    <div className="h-full w-full bg-background">
      <div className="p-2 border-b border-border">
        <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
          Explorer
        </h3>
      </div>

      <div className="h-[calc(100%-2.5rem)] overflow-auto">
        <Tree
          data={data}
          openByDefault={false}
          width="100%"
          height={1000}
          indent={16}
          rowHeight={28}
          overscanCount={10}
        >
          {Node}
        </Tree>
      </div>
    </div>
  );
};

/**
 * TabManager - Manages editor tabs with close actions and dirty state
 */

import React from 'react';
import { useEditorStore } from '../../store/editor-store';
import { X } from 'lucide-react';
import { cn } from '../../lib/utils';

export const TabManager: React.FC = () => {
  const { tabs, setActiveTab, closeTab, closeAllTabs, closeOtherTabs } = useEditorStore();

  const handleTabClick = (tabId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveTab(tabId);
  };

  const handleCloseTab = (tabId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    closeTab(tabId);
  };

  const handleMiddleClick = (tabId: string, e: React.MouseEvent) => {
    if (e.button === 1) {
      e.preventDefault();
      closeTab(tabId);
    }
  };

  const handleContextMenu = (tabId: string, e: React.MouseEvent) => {
    e.preventDefault();

    // TODO: Implement proper context menu with Radix UI
    // For now, simple implementation
    closeTab(tabId);
  };

  const getFileName = (path: string): string => {
    return path.split('/').pop() || path;
  };

  if (tabs.length === 0) {
    return (
      <div className="h-10 bg-background border-b border-border flex items-center px-4 text-sm text-muted-foreground">
        No files open
      </div>
    );
  }

  return (
    <div className="h-10 bg-background border-b border-border flex items-center overflow-x-auto scrollbar-thin">
      <div className="flex items-center h-full">
        {tabs.map((tab) => (
          <div
            key={tab.id}
            className={cn(
              'group relative flex items-center gap-2 px-3 h-full border-r border-border',
              'cursor-pointer select-none transition-colors',
              'hover:bg-accent/50',
              tab.isActive && 'bg-accent border-b-2 border-b-primary'
            )}
            onClick={(e) => handleTabClick(tab.id, e)}
            onMouseDown={(e) => handleMiddleClick(tab.id, e)}
            onContextMenu={(e) => handleContextMenu(tab.id, e)}
          >
            {/* Dirty indicator */}
            {tab.isDirty && (
              <div className="w-2 h-2 rounded-full bg-primary" title="Unsaved changes" />
            )}

            {/* File name */}
            <span className="text-sm font-medium whitespace-nowrap max-w-[200px] overflow-hidden text-ellipsis">
              {getFileName(tab.path)}
            </span>

            {/* Close button */}
            <button
              className={cn(
                'p-0.5 rounded hover:bg-background/80 transition-opacity',
                'opacity-0 group-hover:opacity-100',
                tab.isActive && 'opacity-100'
              )}
              onClick={(e) => handleCloseTab(tab.id, e)}
              title="Close (Ctrl+W)"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        ))}
