              <div className="mt-4 flex items-center space-x-2">
                <button
                  onClick={() => handleInstall(server)}
                  disabled={installing === server.id}
                  className="flex-1 flex items-center justify-center space-x-2 px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  <Download className="w-4 h-4" />
                  <span>{installing === server.id ? 'Installing...' : 'Install'}</span>
                </button>

                {server.homepage && (
                  <a
                    href={server.homepage}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-2 text-muted-foreground hover:text-foreground transition-colors"
                    title="View documentation"
                  >
                    <ExternalLink className="w-4 h-4" />
                  </a>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

/**
 * MCPToolsView.tsx
 * Liste et invocation des tools MCP disponibles
 */

import React, { useState, useEffect } from 'react';
import { Play, Shield, ShieldCheck, Code, ChevronDown, ChevronRight } from 'lucide-react';
import type { MCPTool, MCPServer } from '@cortex-ide/shared';

interface MCPToolsViewProps {
  serverId: string;
}

export const MCPToolsView: React.FC<MCPToolsViewProps> = ({ serverId }) => {
  const [server, setServer] = useState<MCPServer | null>(null);
  const [tools, setTools] = useState<MCPTool[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedTool, setExpandedTool] = useState<string | null>(null);
  const [toolArgs, setToolArgs] = useState<Record<string, any>>({});
  const [invoking, setInvoking] = useState<string | null>(null);
  const [results, setResults] = useState<Record<string, any>>({});

  useEffect(() => {
    loadServerAndTools();
  }, [serverId]);

  const loadServerAndTools = async () => {
    try {
      setLoading(true);
      const serverResponse = await window.cortex.mcp.getServer({ serverId });
      setServer(serverResponse.server);

      if (serverResponse.server.status === 'running') {
        const toolsResponse = await window.cortex.mcp.discoverTools({ serverId });
        setTools(toolsResponse.tools);
      } else {
        setTools(serverResponse.server.tools || []);
      }
    } catch (err) {
      console.error('[MCPToolsView] Failed to load tools:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleInvokeTool = async (toolName: string, inputSchema: MCPTool['inputSchema']) => {
    setInvoking(toolName);

    try {
      // Check permission first
      const permResponse = await window.cortex.mcp.checkPermission({ serverId, toolName });

      if (!permResponse.granted) {
        const shouldGrant = confirm(
          `This tool requires permission to run. Grant permission to ${toolName}?`
        );

        if (shouldGrant) {
          await window.cortex.mcp.grantPermission({ serverId, toolName });
        } else {
          return;
        }
      }

      // Build arguments from input
      const args = toolArgs[toolName] || {};

      // Validate required fields
      const required = inputSchema.required || [];
      const missing = required.filter(key => !args[key]);

      if (missing.length > 0) {
        alert(`Missing required fields: ${missing.join(', ')}`);
        return;
      }

      // Invoke tool
      const result = await window.cortex.mcp.invokeTool({
        serverId,
        toolName,
        arguments: args,
      });

      setResults((prev) => ({ ...prev, [toolName]: result }));
    } catch (err) {
      alert(`Failed to invoke tool: ${err instanceof Error ? err.message : 'Unknown error'}`);
    } finally {
      setInvoking(null);
    }
  };

  const handleArgChange = (toolName: string, key: string, value: any) => {
    setToolArgs((prev) => ({
      ...prev,
      [toolName]: {
        ...(prev[toolName] || {}),
        [key]: value,
      },
    }));
  };

  const toggleExpanded = (toolName: string) => {
    setExpandedTool(expandedTool === toolName ? null : toolName);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-sm text-muted-foreground">Loading tools...</div>
      </div>
    );
  }

  if (!server) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-sm text-red-500">Server not found</div>
      </div>
    );
  }

  if (server.status !== 'running') {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="text-sm text-muted-foreground">
          Server must be running to view and invoke tools
        </div>
        <button
          onClick={async () => {
            await window.cortex.mcp.startServer({ serverId });
            await loadServerAndTools();
          }}
          className="px-4 py-2 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90"
        >
          Start Server
        </button>
      </div>
    );
  }

  if (tools.length === 0) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-sm text-muted-foreground">No tools available</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-foreground">{server.name} Tools</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          {tools.length} tool{tools.length !== 1 ? 's' : ''} available
        </p>
      </div>

      {/* Tools List */}
      <div className="space-y-3">
        {tools.map((tool) => {
          const isExpanded = expandedTool === tool.name;
          const args = toolArgs[tool.name] || {};
          const result = results[tool.name];

          return (
            <div
              key={tool.name}
              className="p-4 bg-card border border-border rounded-lg"
            >
              {/* Tool Header */}
              <div className="flex items-start justify-between">
                <button
                  onClick={() => toggleExpanded(tool.name)}
                  className="flex-1 flex items-start space-x-3 text-left"
                >
                  {isExpanded ? (
                    <ChevronDown className="w-5 h-5 text-muted-foreground mt-0.5 flex-shrink-0" />
                  ) : (
                    <ChevronRight className="w-5 h-5 text-muted-foreground mt-0.5 flex-shrink-0" />
                  )}
                  <div className="flex-1">
                    <h3 className="text-base font-semibold text-foreground">{tool.name}</h3>
                    <p className="mt-1 text-sm text-muted-foreground">{tool.description}</p>
                  </div>
                </button>

                <button
                  onClick={() => handleInvokeTool(tool.name, tool.inputSchema)}
                  disabled={invoking === tool.name}
                  className="ml-4 flex items-center space-x-2 px-3 py-1.5 text-sm font-medium text-white bg-primary rounded-md hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  <Play className="w-4 h-4" />
                  <span>{invoking === tool.name ? 'Running...' : 'Run'}</span>
                </button>
              </div>

              {/* Tool Details (when expanded) */}
              {isExpanded && (
                <div className="mt-4 space-y-4">
                  {/* Input Schema */}
                  <div className="space-y-3">
                    <h4 className="text-sm font-semibold text-foreground">Parameters</h4>
                    {Object.entries(tool.inputSchema.properties).map(([key, schema]: [string, any]) => {
                      const isRequired = tool.inputSchema.required?.includes(key);

                      return (
                        <div key={key} className="space-y-1">
                          <label className="block text-sm font-medium text-foreground">
                            {key}
                            {isRequired && <span className="text-red-500 ml-1">*</span>}
                            {schema.description && (
                              <span className="ml-2 text-xs text-muted-foreground font-normal">
                                {schema.description}
                              </span>
                            )}
                          </label>
                          <input
                            type={schema.type === 'number' ? 'number' : 'text'}
                            value={args[key] || ''}
                            onChange={(e) => handleArgChange(tool.name, key, e.target.value)}
                            placeholder={schema.default || `Enter ${key}`}
                            className="w-full px-3 py-2 bg-background border border-border rounded-md text-sm text-foreground font-mono focus:outline-none focus:ring-2 focus:ring-primary"
                          />
                        </div>
                      );
                    })}
                  </div>

                  {/* Result */}
                  {result && (
                    <div className="space-y-2">
                      <h4 className="text-sm font-semibold text-foreground">Result</h4>
                      <div className="p-3 bg-background border border-border rounded-md">
                        <pre className="text-xs text-foreground font-mono whitespace-pre-wrap">
                          {JSON.stringify(result, null, 2)}
                        </pre>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

/**
 * BranchSelector - Switch branches avec dropdown
 */

import * as React from 'react';
import { Button } from '../../components/ui/button';
import { Popover } from '../../components/ui/popover';
import { Input } from '../../components/ui/input';
import { Spinner } from '../../components/ui/spinner';
import { cn } from '../../lib/utils';

interface BranchSelectorProps {
  repoPath: string;
  currentBranch: string;
  onBranchChange: () => void;
  className?: string;
}

interface Branch {
  name: string;
  current: boolean;
  commit?: string;
}

export function BranchSelector({ repoPath, currentBranch, onBranchChange, className }: BranchSelectorProps) {
  const [open, setOpen] = React.useState(false);
  const [branches, setBranches] = React.useState<Branch[]>([]);
  const [loading, setLoading] = React.useState(false);
  const [newBranchName, setNewBranchName] = React.useState('');
  const [showCreateInput, setShowCreateInput] = React.useState(false);

  const loadBranches = async () => {
    setLoading(true);
    try {
      // TODO: Implémenter git.branches via IPC
      // Pour l'instant, mock data
      setBranches([
        { name: currentBranch, current: true },
        { name: 'main', current: false },
        { name: 'develop', current: false },
        { name: 'feature/test', current: false },
      ]);
    } catch (err) {
      console.error('Failed to load branches:', err);
    } finally {
      setLoading(false);
    }
  };

  React.useEffect(() => {
    if (open) {
      loadBranches();
    }
  }, [open]);

  const handleCheckout = async (branchName: string) => {
    if (branchName === currentBranch) {
      setOpen(false);
      return;
    }

    try {
      // TODO: Implémenter git.checkout via IPC
      console.log('Checkout branch:', branchName);
      setOpen(false);
      onBranchChange();
    } catch (err) {
      console.error('Failed to checkout branch:', err);
    }
  };

  const handleCreateBranch = async () => {
    if (!newBranchName.trim()) return;

    try {
      // TODO: Implémenter git.createBranch via IPC
      console.log('Create branch:', newBranchName);
      setNewBranchName('');
      setShowCreateInput(false);
      setOpen(false);
      onBranchChange();
    } catch (err) {
      console.error('Failed to create branch:', err);
    }
  };

  return (
    <Popover
      open={open}
      onOpenChange={setOpen}
      trigger={
        <Button variant="ghost" size="sm" className={cn('gap-2', className)}>
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none" className="text-text-secondary">
            <path
              d="M10 10.5C10 11.3284 9.32843 12 8.5 12C7.67157 12 7 11.3284 7 10.5C7 9.67157 7.67157 9 8.5 9C9.32843 9 10 9.67157 10 10.5Z"
              stroke="currentColor"
              strokeWidth="1.2"
            />
            <path
              d="M7 3.5C7 4.32843 6.32843 5 5.5 5C4.67157 5 4 4.32843 4 3.5C4 2.67157 4.67157 2 5.5 2C6.32843 2 7 2.67157 7 3.5Z"
              stroke="currentColor"
              strokeWidth="1.2"
            />
            <path
              d="M5.5 5V10M7.5 9L5.5 10"
              stroke="currentColor"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
          </svg>
          <span className="text-sm font-medium">{currentBranch}</span>
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none" className="text-text-secondary">
            <path
              d="M3 4.5L6 7.5L9 4.5"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </Button>
      }
    >
      <div className="w-64 p-2">
        {/* Header */}
        <div className="flex items-center justify-between px-2 pb-2 mb-2 border-b border-border">
          <span className="text-xs font-semibold text-text">Branches</span>
          <button
            onClick={() => setShowCreateInput(!showCreateInput)}
            className="text-xs text-accent hover:text-accent/80 transition-colors"
          >
            + New
          </button>
        </div>

        {/* Create Branch */}
        {showCreateInput && (
          <div className="mb-2 px-2">
            <Input
              value={newBranchName}
              onChange={(e) => setNewBranchName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleCreateBranch();
                if (e.key === 'Escape') {
                  setShowCreateInput(false);
                  setNewBranchName('');
                }
              }}
              placeholder="Branch name..."
              className="text-sm h-8"
              autoFocus
            />
          </div>
        )}

        {/* Branches List */}
        {loading ? (
          <div className="flex items-center justify-center py-4">
            <Spinner className="w-4 h-4" />
          </div>
        ) : (
          <div className="max-h-64 overflow-y-auto">
            {branches.map((branch) => (
              <button
                key={branch.name}
                onClick={() => handleCheckout(branch.name)}
                className={cn(
                  'w-full flex items-center gap-2 px-2 py-1.5 rounded-sm text-sm transition-colors text-left',
                  branch.current
                    ? 'bg-accent/10 text-accent font-medium'
                    : 'hover:bg-tint text-text'
                )}
              >
                {branch.current && (
                  <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
                    <path
                      d="M10 3L4.5 8.5L2 6"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                )}
                <span className={cn(!branch.current && 'ml-5')}>{branch.name}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </Popover>
  );
}

/**
 * BrowserView - Preview intégré avec webview
 * 
 * Features:
 * - Webview Electron pour preview HTML/web apps
 * - Barre d'adresse avec navigation
 * - Refresh, back, forward buttons
 * - DevTools toggle
 */

import * as React from 'react';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Spinner } from '../../components/ui/spinner';
import { cn } from '../../lib/utils';

interface BrowserViewProps {
  initialUrl?: string;
  className?: string;
}

export function BrowserView({ initialUrl = 'about:blank', className }: BrowserViewProps) {
  const [url, setUrl] = React.useState(initialUrl);
  const [currentUrl, setCurrentUrl] = React.useState(initialUrl);
  const [loading, setLoading] = React.useState(false);
  const [canGoBack, setCanGoBack] = React.useState(false);
  const [canGoForward, setCanGoForward] = React.useState(false);
  const [showDevTools, setShowDevTools] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const webviewRef = React.useRef<HTMLWebViewElement>(null);

  // Gérer les événements webview
  React.useEffect(() => {
    const webview = webviewRef.current;
    if (!webview) return;

    // Navigation
    const handleDidNavigate = (e: any) => {
      setCurrentUrl(e.url);
      setUrl(e.url);
      setLoading(false);
    };

    const handleDidStartLoading = () => {
      setLoading(true);
      setError(null);
    };

    const handleDidStopLoading = () => {
      setLoading(false);

      // Mettre à jour les boutons de navigation
      if (webview.canGoBack) setCanGoBack(true);
      if (webview.canGoForward) setCanGoForward(true);
    };

    const handleDidFailLoad = (e: any) => {
      setLoading(false);
      if (e.errorCode !== -3) { // Ignore aborted
        setError(`Failed to load: ${e.errorDescription}`);
      }
    };

    // Attacher les listeners
    webview.addEventListener('did-navigate', handleDidNavigate);
    webview.addEventListener('did-start-loading', handleDidStartLoading);
    webview.addEventListener('did-stop-loading', handleDidStopLoading);
    webview.addEventListener('did-fail-load', handleDidFailLoad);

    return () => {
      webview.removeEventListener('did-navigate', handleDidNavigate);
      webview.removeEventListener('did-start-loading', handleDidStartLoading);
      webview.removeEventListener('did-stop-loading', handleDidStopLoading);
      webview.removeEventListener('did-fail-load', handleDidFailLoad);
    };
  }, []);

  // Naviguer vers une URL
  const handleNavigate = () => {
    const webview = webviewRef.current;
    if (!webview) return;

    let targetUrl = url.trim();
    if (!targetUrl) return;

    // Ajouter le protocole si manquant
    if (!targetUrl.match(/^https?:\/\//i) && !targetUrl.startsWith('file://')) {
      if (targetUrl.startsWith('localhost') || targetUrl.match(/^\d+\.\d+\.\d+\.\d+/)) {
        targetUrl = `http://${targetUrl}`;
      } else {
        targetUrl = `https://${targetUrl}`;
      }
    }

    setError(null);
    webview.loadURL(targetUrl);
  };

  // Recharger
  const handleReload = () => {
    const webview = webviewRef.current;
    if (!webview) return;
    webview.reload();
  };

  // Retour
  const handleGoBack = () => {
    const webview = webviewRef.current;
    if (!webview || !webview.canGoBack()) return;
    webview.goBack();
    setCanGoBack(webview.canGoBack());
  };

  // Avancer
  const handleGoForward = () => {
    const webview = webviewRef.current;
    if (!webview || !webview.canGoForward()) return;
    webview.goForward();
    setCanGoForward(webview.canGoForward());
  };

  // Toggle DevTools
  const handleToggleDevTools = () => {
    const webview = webviewRef.current;
    if (!webview) return;

    if (showDevTools) {
      webview.closeDevTools();
    } else {
      webview.openDevTools();
    }
    setShowDevTools(!showDevTools);
  };

  // Home
  const handleHome = () => {
    setUrl('about:blank');
    const webview = webviewRef.current;
    if (!webview) return;
    webview.loadURL('about:blank');
  };

  return (
    <div className={cn('flex flex-col h-full bg-background', className)}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <div className="flex items-center gap-2">
          <h2 className="text-sm font-semibold text-text">Browser</h2>
          {loading && <Spinner className="w-3 h-3" />}
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleToggleDevTools}
            title="Toggle DevTools"
          >
            <DevToolsIcon />
          </Button>
        </div>
      </div>

      {/* Navigation Bar */}
      <div className="flex items-center gap-2 px-4 py-2 border-b border-border bg-wash">
        <Button
          variant="ghost"
          size="icon"
          onClick={handleGoBack}
          disabled={!canGoBack}
          title="Back"
        >
          <BackIcon />
        </Button>

        <Button
          variant="ghost"
          size="icon"
          onClick={handleGoForward}
          disabled={!canGoForward}
          title="Forward"
        >
          <ForwardIcon />
        </Button>

        <Button
          variant="ghost"
          size="icon"
          onClick={handleReload}
          title="Reload"
        >
          <ReloadIcon />
        </Button>

        <Button
          variant="ghost"
          size="icon"
          onClick={handleHome}
          title="Home"
        >
          <HomeIcon />
        </Button>

        <div className="flex-1 flex items-center gap-2">
          <Input
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') handleNavigate();
            }}
            placeholder="Enter URL or localhost:3000"
            className="flex-1 h-8 text-sm font-mono"
          />
          <Button
            variant="secondary"
            size="sm"
            onClick={handleNavigate}
          >
            Go
          </Button>
        </div>
      </div>

      {/* Error */}
      {error && (
        <div className="px-4 py-2 bg-red-soft text-red text-xs border-b border-red/20">
          {error}
        </div>
      )}

      {/* Webview Container */}
      <div className="flex-1 relative overflow-hidden">
        <webview
          ref={webviewRef as any}
          src={initialUrl}
          className="w-full h-full"
          style={{ display: 'flex' }}
          // @ts-ignore - Electron webview attributes
          allowpopups="true"
          nodeintegration="false"
          webpreferences="contextIsolation=yes"
        />
      </div>
    </div>
  );
}

// ============================================================================
// Custom webview element type for TypeScript
// ============================================================================

declare global {
  namespace JSX {
    interface IntrinsicElements {
      webview: React.DetailedHTMLProps<React.HTMLAttributes<HTMLElement>, HTMLElement> & {
        src?: string;
        allowpopups?: string;
        nodeintegration?: string;
        webpreferences?: string;
      };
