  }

  interface HTMLWebViewElement extends HTMLElement {
    loadURL(url: string): void;
    reload(): void;
    goBack(): void;
    goForward(): void;
    canGoBack(): boolean;
    canGoForward(): boolean;
    openDevTools(): void;
    closeDevTools(): void;
  }
}

