 */

import * as React from 'react';
import { ipc } from '../../lib/ipc';
import type { GitFileStatus } from '@cortex-ide/shared';
import { Button } from '../../components/ui/button';
import { Textarea } from '../../components/ui/textarea';
import { Spinner } from '../../components/ui/spinner';
import { cn } from '../../lib/utils';

interface CommitDialogProps {
  repoPath: string;
  files: GitFileStatus[];
  onClose: () => void;
  onCommit: () => void;
  className?: string;
}

export function CommitDialog({ repoPath, files, onClose, onCommit, className }: CommitDialogProps) {
  const [message, setMessage] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const handleCommit = async () => {
    if (!message.trim()) {
      setError('Commit message is required');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      await ipc.git.commit({
        repoPath,
        message: message.trim(),
        files: files.map(f => f.path),
      });
      onCommit();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to commit');
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      handleCommit();
    }
  };

  return (
    <div className={cn('fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center p-4', className)}>
      <div className="bg-background border border-border rounded-lg shadow-lg w-full max-w-2xl">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-border">
          <h3 className="text-sm font-semibold text-text">Commit Changes</h3>
          <button
            onClick={onClose}
            className="text-text-secondary hover:text-text transition-colors"
            disabled={loading}
          >
            ✕
          </button>
        </div>

        {/* Content */}
        <div className="p-4">
          {/* Files List */}
          <div className="mb-4">
            <p className="text-xs text-text-secondary mb-2">
              {files.length} file{files.length !== 1 ? 's' : ''} staged
            </p>
            <div className="max-h-32 overflow-y-auto border border-border rounded-md bg-surface">
              {files.map((file) => (
                <div
                  key={file.path}
                  className="flex items-center gap-2 px-3 py-2 text-xs border-b border-border last:border-b-0"
                >
                  <span className={cn(
                    'font-mono font-semibold',
                    file.status === 'modified' && 'text-yellow-500',
                    file.status === 'added' && 'text-green-500',
                    file.status === 'deleted' && 'text-red',
                  )}>
                    {file.status === 'modified' ? 'M' : file.status === 'added' ? 'A' : 'D'}
                  </span>
                  <span className="text-text truncate">{file.path}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Commit Message */}
          <div className="mb-4">
            <label className="block text-xs font-medium text-text mb-2">
              Commit message
            </label>
            <Textarea
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Enter commit message..."
              rows={6}
              className="resize-none font-mono text-sm"
              autoFocus
              disabled={loading}
            />
            <p className="text-xs text-text-secondary mt-1">
              Press {navigator.platform.includes('Mac') ? '⌘' : 'Ctrl'}+Enter to commit
            </p>
          </div>

          {/* Error */}
          {error && (
            <div className="mb-4 px-3 py-2 bg-red/10 border border-red rounded-md">
              <p className="text-xs text-red">{error}</p>
            </div>
          )}

          {/* Actions */}
          <div className="flex justify-end gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={onClose}
              disabled={loading}
            >
              Cancel
            </Button>
            <Button
              size="sm"
              onClick={handleCommit}
              disabled={loading || !message.trim()}
            >
              {loading ? (
                <>
                  <Spinner className="w-3 h-3 mr-2" />
                  Committing...
                </>
              ) : (
                'Commit'
              )}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * DiffViewer - Comparaison fichiers avec react-diff-view
 */

import * as React from 'react';
import { parseDiff, Diff, Hunk, tokenize } from 'react-diff-view';
import { diffLines, formatLines } from 'unidiff';
import { ipc } from '../../lib/ipc';
import { Button } from '../../components/ui/button';
import { Spinner } from '../../components/ui/spinner';
import { cn } from '../../lib/utils';
import 'react-diff-view/style/index.css';

interface DiffViewerProps {
  repoPath: string;
  filePath: string;
  staged?: boolean;
  onClose: () => void;
  className?: string;
}

export function DiffViewer({ repoPath, filePath, staged = false, onClose, className }: DiffViewerProps) {
  const [diffText, setDiffText] = React.useState<string | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    loadDiff();
  }, [repoPath, filePath, staged]);

  const loadDiff = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await ipc.git.diff({ repoPath, path: filePath, staged });

      if (result.diffs.length === 0) {
        setError('No changes to display');
        return;
      }

      setDiffText(result.diffs[0].diff);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load diff');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className={cn('fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center', className)}>
        <div className="bg-background border border-border rounded-lg p-8 shadow-lg">
          <Spinner />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={cn('fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center', className)}>
        <div className="bg-background border border-border rounded-lg p-6 shadow-lg max-w-md">
          <h3 className="text-sm font-semibold text-text mb-2">Error</h3>
          <p className="text-sm text-red mb-4">{error}</p>
          <div className="flex justify-end gap-2">
            <Button variant="secondary" size="sm" onClick={loadDiff}>Retry</Button>
            <Button variant="ghost" size="sm" onClick={onClose}>Close</Button>
          </div>
        </div>
      </div>
    );
  }

  if (!diffText) {
    return null;
  }

  const files = parseDiff(diffText);

  return (
    <div className={cn('fixed inset-0 bg-background/80 backdrop-blur-sm z-50 flex items-center justify-center p-4', className)}>
      <div className="bg-background border border-border rounded-lg shadow-lg w-full h-full max-w-6xl max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-border">
          <div className="flex flex-col gap-1">
            <h3 className="text-sm font-semibold text-text">{filePath}</h3>
            <p className="text-xs text-text-secondary">
              {staged ? 'Staged changes' : 'Unstaged changes'}
            </p>
          </div>
          <Button variant="ghost" size="sm" onClick={onClose}>
            Close
          </Button>
        </div>

        {/* Diff Content */}
        <div className="flex-1 overflow-auto p-4 bg-surface">
          {files.map((file, index) => (
            <DiffFile key={index} file={file} />
          ))}
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// DiffFile Component
// ============================================================================

interface DiffFileProps {
  file: any;
}

function DiffFile({ file }: DiffFileProps) {
  const tokens = tokenize(file.hunks, {
    highlight: false,
    enhancers: [],
  });

  return (
    <div className="font-mono text-xs bg-background border border-border rounded-lg overflow-hidden">
      <Diff
        viewType="split"
        diffType={file.type}
        hunks={file.hunks}
        tokens={tokens}
      >
        {(hunks) =>
          hunks.map((hunk) => (
            <Hunk key={hunk.content} hunk={hunk} />
          ))
        }
      </Diff>
    </div>
  );
}

/**
 * DocumentationViewer - Rendu markdown/MDX depuis workspace
 * 
 * Features:
 * - Render markdown files depuis workspace
 * - Table of contents auto-générée
 * - Syntax highlighting
 * - Links internes
 */

import * as React from 'react';
import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark, oneLight } from 'react-syntax-highlighter/dist/esm/styles/prism';
import remarkGfm from 'remark-gfm';
import { ipc } from '../../lib/ipc';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Spinner } from '../../components/ui/spinner';
import { cn } from '../../lib/utils';

interface Heading {
  level: number;
  text: string;
  id: string;
}

interface DocumentationViewerProps {
  workspaceId: string;
  className?: string;
}

export function DocumentationViewer({ workspaceId, className }: DocumentationViewerProps) {
  const [content, setContent] = React.useState('');
  const [filePath, setFilePath] = React.useState('');
  const [fileName, setFileName] = React.useState('');
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [headings, setHeadings] = React.useState<Heading[]>([]);
  const [showToc, setShowToc] = React.useState(true);
  const [isDark, setIsDark] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState('');

  const contentRef = React.useRef<HTMLDivElement>(null);

  // Détecter le thème
  React.useEffect(() => {
    const checkTheme = () => {
      setIsDark(document.documentElement.classList.contains('dark'));
    };
    checkTheme();
    const observer = new MutationObserver(checkTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
    return () => observer.disconnect();
  }, []);

  // Extraire les headings du contenu markdown
  React.useEffect(() => {
    const extractedHeadings: Heading[] = [];
    const lines = content.split('\n');

    lines.forEach((line) => {
      const match = line.match(/^(#{1,6})\s+(.+)$/);
      if (match) {
        const level = match[1].length;
        const text = match[2].trim();
        const id = text
          .toLowerCase()
          .replace(/[^\w\s-]/g, '')
          .replace(/\s+/g, '-');

        extractedHeadings.push({ level, text, id });
      }
    });

    setHeadings(extractedHeadings);
  }, [content]);

  // Charger un fichier
  const handleLoadFile = async (path: string) => {
    setLoading(true);
    setError(null);

    try {
      const result = await ipc.filesystem.readFile(path);
      setContent(result.content);
      setFilePath(path);
      setFileName(path.split('/').pop() || '');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load file');
      setContent('');
    } finally {
      setLoading(false);
    }
  };

  // Scroller vers un heading
  const scrollToHeading = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  // Rechercher dans le document
  const filteredHeadings = searchQuery
    ? headings.filter((h) => h.text.toLowerCase().includes(searchQuery.toLowerCase()))
    : headings;

  return (
    <div className={cn('flex h-full bg-background', className)}>
      {/* Sidebar - Table of Contents */}
      {showToc && (
        <div className="w-64 border-r border-border flex flex-col">
          {/* Sidebar Header */}
          <div className="px-4 py-3 border-b border-border">
            <h3 className="text-sm font-semibold text-text">Contents</h3>
          </div>

          {/* Search */}
          <div className="px-3 py-2 border-b border-border">
            <Input
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search headings..."
              className="h-8 text-xs"
            />
          </div>

          {/* TOC List */}
          <div className="flex-1 overflow-y-auto py-2">
            {filteredHeadings.length === 0 ? (
              <div className="px-4 py-8 text-xs text-text-secondary text-center">
                {headings.length === 0 ? 'No headings found' : 'No matches'}
              </div>
            ) : (
              <nav>
                {filteredHeadings.map((heading, index) => (
                  <button
                    key={`${heading.id}-${index}`}
                    onClick={() => scrollToHeading(heading.id)}
                    className={cn(
                      'w-full text-left px-4 py-1.5 text-xs hover:bg-tint transition-colors',
                      'text-text-secondary hover:text-text'
                    )}
                    style={{ paddingLeft: `${heading.level * 12}px` }}
                  >
                    {heading.text}
                  </button>
                ))}
              </nav>
            )}
          </div>
        </div>
      )}

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-border">
          <div className="flex items-center gap-3">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowToc(!showToc)}
              title="Toggle table of contents"
            >
              <TocIcon />
            </Button>
            <h2 className="text-sm font-semibold text-text">
              {fileName || 'Documentation'}
            </h2>
          </div>

          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={() => handleLoadFile('')} disabled>
              Open File
            </Button>
          </div>
        </div>

        {/* Error */}
        {error && (
          <div className="px-4 py-2 bg-red-soft text-red text-xs border-b border-red/20">
            {error}
          </div>
        )}

        {/* Content */}
        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="flex items-center justify-center h-full">
              <Spinner />
            </div>
          ) : content ? (
            <div ref={contentRef} className="max-w-4xl mx-auto px-8 py-8">
              <MarkdownContent content={content} isDark={isDark} />
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
              <EmptyDocIcon />
              <div>
                <h3 className="text-sm font-semibold text-text mb-1">No document loaded</h3>
                <p className="text-xs text-text-secondary max-w-xs">
                  Open a markdown file from your workspace to view formatted documentation
                </p>
              </div>
              <Button size="sm" onClick={() => handleLoadFile('')} disabled>
                Browse Files
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// Markdown Content Component
// ============================================================================

interface MarkdownContentProps {
  content: string;
  isDark: boolean;
}

function MarkdownContent({ content, isDark }: MarkdownContentProps) {
  return (
    <div className="prose prose-sm max-w-none">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          // Headings avec IDs pour navigation
          h1: ({ node, children, ...props }) => {
            const text = String(children);
            const id = text
              .toLowerCase()
              .replace(/[^\w\s-]/g, '')
              .replace(/\s+/g, '-');
            return (
              <h1 id={id} className="scroll-mt-4" {...props}>
                {children}
              </h1>
            );
          },
          h2: ({ node, children, ...props }) => {
            const text = String(children);
            const id = text
              .toLowerCase()
              .replace(/[^\w\s-]/g, '')
              .replace(/\s+/g, '-');
            return (
              <h2 id={id} className="scroll-mt-4" {...props}>
                {children}
              </h2>
            );
          },
          h3: ({ node, children, ...props }) => {
            const text = String(children);
            const id = text
              .toLowerCase()
              .replace(/[^\w\s-]/g, '')
              .replace(/\s+/g, '-');
            return (
              <h3 id={id} className="scroll-mt-4" {...props}>
                {children}
              </h3>
            );
          },
          h4: ({ node, children, ...props }) => {
            const text = String(children);
            const id = text
              .toLowerCase()
              .replace(/[^\w\s-]/g, '')
              .replace(/\s+/g, '-');
            return (
              <h4 id={id} className="scroll-mt-4" {...props}>
                {children}
              </h4>
            );
          },
          h5: ({ node, children, ...props }) => {
            const text = String(children);
            const id = text
              .toLowerCase()
              .replace(/[^\w\s-]/g, '')
              .replace(/\s+/g, '-');
            return (
              <h5 id={id} className="scroll-mt-4" {...props}>
                {children}
              </h5>
            );
          },
          h6: ({ node, children, ...props }) => {
            const text = String(children);
            const id = text
              .toLowerCase()
              .replace(/[^\w\s-]/g, '')
              .replace(/\s+/g, '-');
            return (
              <h6 id={id} className="scroll-mt-4" {...props}>
                {children}
              </h6>
            );
          },

          // Code blocks avec syntax highlighting
          code({ node, inline, className, children, ...props }) {
            const match = /language-(\w+)/.exec(className || '');
            const language = match ? match[1] : '';

            return !inline && language ? (
              <SyntaxHighlighter
                style={isDark ? oneDark : oneLight}
                language={language}
                PreTag="div"
                customStyle={{
                  margin: 0,
                  borderRadius: 'var(--radius-sm)',
                  fontSize: '13px',
                }}
                {...props}
              >
                {String(children).replace(/\n$/, '')}
              </SyntaxHighlighter>
            ) : (
              <code className={className} {...props}>
                {children}
              </code>
            );
          },

          // Links - support des liens internes
          a: ({ node, href, children, ...props }) => {
            const isInternal = href && (href.startsWith('#') || href.startsWith('./') || href.startsWith('../'));

            return (
              <a
                href={href}
                className="text-accent hover:underline"
                target={isInternal ? undefined : '_blank'}
                rel={isInternal ? undefined : 'noopener noreferrer'}
                {...props}
              >
                {children}
              </a>
            );
          },

          // Tables
          table: ({ node, children, ...props }) => (
            <div className="overflow-x-auto my-4">
              <table className="min-w-full divide-y divide-border" {...props}>
                {children}
              </table>
            </div>
          ),
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
}

