/**
 * GitPanel - Vue principale Git avec branches, commits, changes
 */

import * as React from 'react';
import { ipc } from '../../lib/ipc';
import type { GitStatusResponse, GitFileStatus } from '@cortex-ide/shared';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Badge } from '../../components/ui/badge';
import { Spinner } from '../../components/ui/spinner';
import { cn } from '../../lib/utils';
import { BranchSelector } from './BranchSelector';
import { CommitDialog } from './CommitDialog';
import { DiffViewer } from './DiffViewer';

interface GitPanelProps {
  repoPath: string;
  className?: string;
}

export function GitPanel({ repoPath, className }: GitPanelProps) {
  const [status, setStatus] = React.useState<GitStatusResponse | null>(null);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [selectedFile, setSelectedFile] = React.useState<string | null>(null);
  const [showCommitDialog, setShowCommitDialog] = React.useState(false);
  const [showDiff, setShowDiff] = React.useState(false);

  // Charge le statut Git
  const loadStatus = React.useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await ipc.git.status({ repoPath });
      setStatus(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load git status');
    } finally {
      setLoading(false);
    }
  }, [repoPath]);

  // Charge au mount et rafraîchit toutes les 5s
  React.useEffect(() => {
    loadStatus();
    const interval = setInterval(loadStatus, 5000);
    return () => clearInterval(interval);
  }, [loadStatus]);

  // Stage/unstage un fichier
  const toggleStage = async (file: GitFileStatus) => {
    // TODO: Implémenter stage/unstage via IPC
    console.log('Toggle stage:', file.path);
    await loadStatus();
  };

  // Discard les modifications d'un fichier
  const discardChanges = async (file: GitFileStatus) => {
    if (!confirm(`Discard changes to ${file.path}?`)) return;
    // TODO: Implémenter discard via IPC
    console.log('Discard:', file.path);
    await loadStatus();
  };

  // Ouvre le diff viewer
  const viewDiff = (file: GitFileStatus) => {
    setSelectedFile(file.path);
    setShowDiff(true);
  };

  // Push
  const handlePush = async () => {
    if (!status) return;
    setLoading(true);
    try {
      await ipc.git.push({ repoPath });
      await loadStatus();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to push');
    } finally {
      setLoading(false);
    }
  };

  // Pull
  const handlePull = async () => {
    setLoading(true);
    try {
      await ipc.git.pull({ repoPath });
      await loadStatus();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to pull');
    } finally {
      setLoading(false);
    }
  };

  if (loading && !status) {
    return (
      <div className={cn('flex items-center justify-center h-full', className)}>
        <Spinner />
      </div>
    );
  }

  if (error && !status) {
    return (
      <div className={cn('flex flex-col items-center justify-center h-full gap-4 p-4', className)}>
        <p className="text-sm text-red">Error: {error}</p>
        <Button onClick={loadStatus} size="sm">Retry</Button>
      </div>
    );
  }

  if (!status) {
    return null;
  }

  const stagedFiles = status.files.filter(f => f.staged);
  const unstagedFiles = status.files.filter(f => !f.staged);

  return (
    <div className={cn('flex flex-col h-full bg-background', className)}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <div className="flex items-center gap-3">
          <h2 className="text-sm font-semibold text-text">Git</h2>
          <BranchSelector
            repoPath={repoPath}
            currentBranch={status.branch}
            onBranchChange={loadStatus}
          />
        </div>
        <div className="flex items-center gap-2">
          {status.ahead > 0 && (
            <Badge variant="secondary" className="text-xs">
              ↑ {status.ahead}
            </Badge>
          )}
          {status.behind > 0 && (
            <Badge variant="secondary" className="text-xs">
              ↓ {status.behind}
            </Badge>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={loadStatus}
            disabled={loading}
          >
            {loading ? <Spinner className="w-3 h-3" /> : '↻'}
          </Button>
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-center gap-2 px-4 py-2 border-b border-border">
        <Button
          size="sm"
          onClick={() => setShowCommitDialog(true)}
          disabled={stagedFiles.length === 0}
        >
          Commit
        </Button>
        <Button
          variant="secondary"
          size="sm"
          onClick={handlePush}
          disabled={status.ahead === 0}
        >
          Push
        </Button>
        <Button
          variant="secondary"
          size="sm"
          onClick={handlePull}
        >
          Pull
        </Button>
      </div>

      {/* Files List */}
      <div className="flex-1 overflow-y-auto">
        {/* Staged Changes */}
        {stagedFiles.length > 0 && (
          <div className="border-b border-border">
            <div className="px-4 py-2 bg-tint text-xs font-semibold text-text-secondary">
              Staged Changes ({stagedFiles.length})
            </div>
            <div className="divide-y divide-border">
              {stagedFiles.map((file) => (
                <FileItem
                  key={file.path}
                  file={file}
                  onToggleStage={toggleStage}
                  onDiscard={discardChanges}
                  onViewDiff={viewDiff}
                />
              ))}
            </div>
          </div>
        )}

        {/* Unstaged Changes */}
        {unstagedFiles.length > 0 && (
          <div>
            <div className="px-4 py-2 bg-tint text-xs font-semibold text-text-secondary">
              Changes ({unstagedFiles.length})
            </div>
            <div className="divide-y divide-border">
              {unstagedFiles.map((file) => (
                <FileItem
                  key={file.path}
                  file={file}
                  onToggleStage={toggleStage}
                  onDiscard={discardChanges}
                  onViewDiff={viewDiff}
                />
              ))}
            </div>
          </div>
        )}

        {/* Clean State */}
        {status.isClean && (
          <div className="flex items-center justify-center h-32 text-sm text-text-secondary">
            No changes
          </div>
        )}
      </div>

      {/* Commit Dialog */}
      {showCommitDialog && (
        <CommitDialog
          repoPath={repoPath}
          files={stagedFiles}
          onClose={() => setShowCommitDialog(false)}
          onCommit={() => {
            setShowCommitDialog(false);
            loadStatus();
          }}
        />
      )}

      {/* Diff Viewer */}
      {showDiff && selectedFile && (
        <DiffViewer
          repoPath={repoPath}
          filePath={selectedFile}
          onClose={() => setShowDiff(false)}
        />
      )}
    </div>
  );
}

// ============================================================================
// FileItem Component
// ============================================================================

interface FileItemProps {
  file: GitFileStatus;
  onToggleStage: (file: GitFileStatus) => void;
  onDiscard: (file: GitFileStatus) => void;
  onViewDiff: (file: GitFileStatus) => void;
}

function FileItem({ file, onToggleStage, onDiscard, onViewDiff }: FileItemProps) {
  const statusColor = {
    modified: 'text-yellow-500',
    added: 'text-green-500',
    deleted: 'text-red',
    renamed: 'text-blue-500',
    untracked: 'text-text-secondary',
  }[file.status];

  const statusLabel = {
    modified: 'M',
    added: 'A',
    deleted: 'D',
    renamed: 'R',
    untracked: 'U',
  }[file.status];

  return (
    <div className="group flex items-center gap-3 px-4 py-2 hover:bg-tint transition-colors">
      <button
        onClick={() => onToggleStage(file)}
        className="w-4 h-4 border border-border rounded-sm hover:border-accent transition-colors flex items-center justify-center"
      >
        {file.staged && (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
            <path
              d="M10 3L4.5 8.5L2 6"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </button>

      <span className={cn('text-xs font-mono font-semibold w-4', statusColor)}>
        {statusLabel}
      </span>

      <button
        onClick={() => onViewDiff(file)}
        className="flex-1 text-left text-sm text-text hover:text-accent transition-colors truncate"
      >
        {file.path}
      </button>

      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          onClick={() => onViewDiff(file)}
          className="px-2 py-1 text-xs text-text-secondary hover:text-text hover:bg-tint-strong rounded transition-colors"
          title="View diff"
        >
          Diff
        </button>
        {!file.staged && file.status !== 'untracked' && (
          <button
            onClick={() => onDiscard(file)}
            className="px-2 py-1 text-xs text-red hover:bg-red/10 rounded transition-colors"
            title="Discard changes"
          >
            Discard
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * NotesView - Markdown editor avec preview live
 * 
 * Features:
 * - Editor markdown avec preview live (react-markdown)
 * - Toolbar formatage
 * - Save/load depuis filesystem via IPC
 * - Syntax highlighting pour code blocks
 */

import * as React from 'react';
import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark, oneLight } from 'react-syntax-highlighter/dist/esm/styles/prism';
import remarkGfm from 'remark-gfm';
import { ipc } from '../../lib/ipc';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Spinner } from '../../components/ui/spinner';
import { Tabs } from '../../components/ui/tabs';
import { cn } from '../../lib/utils';

interface NotesViewProps {
  workspaceId: string;
  className?: string;
}

export function NotesView({ workspaceId, className }: NotesViewProps) {
  const [content, setContent] = React.useState('');
  const [filePath, setFilePath] = React.useState('');
  const [fileName, setFileName] = React.useState('untitled.md');
  const [isDirty, setIsDirty] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [mode, setMode] = React.useState<'edit' | 'preview' | 'split'>('split');
  const [isDark, setIsDark] = React.useState(false);

  const textareaRef = React.useRef<HTMLTextAreaElement>(null);

  // Détecter le thème
  React.useEffect(() => {
    const checkTheme = () => {
      setIsDark(document.documentElement.classList.contains('dark'));
    };
    checkTheme();
    const observer = new MutationObserver(checkTheme);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
    return () => observer.disconnect();
  }, []);

  // Sauvegarder automatiquement
  React.useEffect(() => {
    if (!isDirty || !filePath) return;

    const timeout = setTimeout(() => {
      handleSave();
    }, 2000);

    return () => clearTimeout(timeout);
  }, [content, isDirty, filePath]);

  // Sauvegarder le fichier
  const handleSave = async () => {
    if (!filePath) {
      setError('No file path specified');
      return;
    }

    setSaving(true);
    setError(null);

    try {
      await ipc.filesystem.writeFile(filePath, content);
      setIsDirty(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save file');
    } finally {
      setSaving(false);
    }
  };

  // Charger un fichier
  const handleLoad = async (path: string) => {
    setLoading(true);
    setError(null);

    try {
      const result = await ipc.filesystem.readFile(path);
      setContent(result.content);
      setFilePath(path);
      setFileName(path.split('/').pop() || 'untitled.md');
      setIsDirty(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load file');
    } finally {
      setLoading(false);
    }
  };

  // Nouveau fichier
  const handleNew = () => {
    if (isDirty && !confirm('Discard unsaved changes?')) return;

    setContent('');
    setFilePath('');
    setFileName('untitled.md');
    setIsDirty(false);
  };

  // Insérer du texte formaté
  const insertFormatting = (before: string, after: string = '') => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selected = content.substring(start, end);
    const newContent = content.substring(0, start) + before + selected + after + content.substring(end);

    setContent(newContent);
    setIsDirty(true);

    // Restaurer le focus et la sélection
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(start + before.length, end + before.length);
    }, 0);
  };

  return (
    <div className={cn('flex flex-col h-full bg-background', className)}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <div className="flex items-center gap-3">
          <h2 className="text-sm font-semibold text-text">Notes</h2>
          <Input
            value={fileName}
            onChange={(e) => setFileName(e.target.value)}
            className="w-48 h-7 text-xs"
            placeholder="filename.md"
          />
          {isDirty && <span className="text-xs text-text-secondary">•</span>}
          {saving && <Spinner className="w-3 h-3" />}
        </div>

        <div className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={handleNew}>
            New
          </Button>
          <Button variant="ghost" size="sm" onClick={() => handleLoad('')} disabled>
            Open
          </Button>
          <Button
            variant="secondary"
            size="sm"
            onClick={handleSave}
            disabled={!isDirty || !filePath || saving}
          >
            Save
          </Button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="flex items-center gap-1 px-4 py-2 border-b border-border bg-wash">
        <ToolbarButton onClick={() => insertFormatting('**', '**')} title="Bold">
          <BoldIcon />
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('*', '*')} title="Italic">
          <ItalicIcon />
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('~~', '~~')} title="Strikethrough">
          <StrikethroughIcon />
        </ToolbarButton>
        <div className="w-px h-4 bg-border mx-1" />
        <ToolbarButton onClick={() => insertFormatting('# ')} title="Heading 1">
          H1
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('## ')} title="Heading 2">
          H2
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('### ')} title="Heading 3">
          H3
        </ToolbarButton>
        <div className="w-px h-4 bg-border mx-1" />
        <ToolbarButton onClick={() => insertFormatting('[', '](url)')} title="Link">
          <LinkIcon />
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('```\n', '\n```')} title="Code block">
          <CodeIcon />
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('`', '`')} title="Inline code">
          &lt;/&gt;
        </ToolbarButton>
        <ToolbarButton onClick={() => insertFormatting('- ')} title="List">
          <ListIcon />
        </ToolbarButton>
        <div className="flex-1" />

        {/* View Mode Toggle */}
        <div className="flex items-center gap-1 bg-background rounded px-1">
          <button
            onClick={() => setMode('edit')}
            className={cn(
              'px-2 py-1 text-xs rounded transition-colors',
              mode === 'edit' ? 'bg-tint text-text' : 'text-text-secondary hover:text-text'
            )}
          >
            Edit
          </button>
          <button
            onClick={() => setMode('split')}
            className={cn(
              'px-2 py-1 text-xs rounded transition-colors',
              mode === 'split' ? 'bg-tint text-text' : 'text-text-secondary hover:text-text'
            )}
          >
            Split
          </button>
          <button
            onClick={() => setMode('preview')}
            className={cn(
              'px-2 py-1 text-xs rounded transition-colors',
              mode === 'preview' ? 'bg-tint text-text' : 'text-text-secondary hover:text-text'
            )}
          >
            Preview
          </button>
        </div>
      </div>

      {/* Error */}
      {error && (
        <div className="px-4 py-2 bg-red-soft text-red text-xs border-b border-red/20">
          {error}
        </div>
      )}

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center flex-1">
          <Spinner />
        </div>
      ) : (
        <div className="flex-1 flex overflow-hidden">
          {/* Editor */}
          {(mode === 'edit' || mode === 'split') && (
            <div className={cn('flex-1 overflow-hidden', mode === 'split' && 'border-r border-border')}>
              <textarea
                ref={textareaRef}
                value={content}
                onChange={(e) => {
                  setContent(e.target.value);
                  setIsDirty(true);
                }}
                className="w-full h-full p-4 bg-background text-text font-mono text-sm resize-none focus:outline-none"
                placeholder="Start writing in markdown..."
              />
            </div>
          )}

          {/* Preview */}
          {(mode === 'preview' || mode === 'split') && (
            <div className="flex-1 overflow-y-auto p-4">
              <MarkdownPreview content={content} isDark={isDark} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}

