/**
 * PlansView - Todo lists et planning
 * 
 * Features:
 * - Liste tâches avec checkboxes
 * - Create, edit, delete tasks
 * - Drag & drop reordering
 * - Status filters (pending, in_progress, completed)
 * - Persistence dans database
 */

import * as React from 'react';
import { ipc } from '../../lib/ipc';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Badge } from '../../components/ui/badge';
import { Spinner } from '../../components/ui/spinner';
import { Checkbox } from '../../components/ui/checkbox';
import { cn } from '../../lib/utils';

interface Task {
  id: string;
  content: string;
  status: 'pending' | 'in_progress' | 'completed' | 'cancelled';
  order: number;
  created_at: number;
  updated_at: number;
  workspace_id: string;
}

interface PlansViewProps {
  workspaceId: string;
  className?: string;
}

export function PlansView({ workspaceId, className }: PlansViewProps) {
  const [tasks, setTasks] = React.useState<Task[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);
  const [filter, setFilter] = React.useState<Task['status'] | 'all'>('all');
  const [newTaskContent, setNewTaskContent] = React.useState('');
  const [editingId, setEditingId] = React.useState<string | null>(null);
  const [editingContent, setEditingContent] = React.useState('');
  const [draggedId, setDraggedId] = React.useState<string | null>(null);

  // Charger les tâches
  const loadTasks = React.useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const result = await ipc.database.query<Task>(
        'SELECT * FROM tasks WHERE workspace_id = ? ORDER BY order ASC, created_at DESC',
        [workspaceId]
      );
      setTasks(result.rows);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load tasks');
    } finally {
      setLoading(false);
    }
  }, [workspaceId]);

  React.useEffect(() => {
    loadTasks();
  }, [loadTasks]);

  // Créer une tâche
  const handleCreateTask = async () => {
    const content = newTaskContent.trim();
    if (!content) return;

    const id = `task_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    const now = Date.now();
    const maxOrder = Math.max(0, ...tasks.map(t => t.order));

    try {
      await ipc.database.execute([
        {
          query: 'INSERT INTO tasks (id, workspace_id, content, status, "order", created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
          params: [id, workspaceId, content, 'pending', maxOrder + 1, now, now],
        },
      ]);

      setNewTaskContent('');
      await loadTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create task');
    }
  };

  // Mettre à jour une tâche
  const handleUpdateTask = async (id: string, updates: Partial<Task>) => {
    const now = Date.now();

    try {
      const updateFields = Object.keys(updates)
        .map(key => `${key} = ?`)
        .join(', ');
      const updateValues = [...Object.values(updates), now, id];

      await ipc.database.execute([
        {
          query: `UPDATE tasks SET ${updateFields}, updated_at = ? WHERE id = ?`,
          params: updateValues,
        },
      ]);

      await loadTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update task');
    }
  };

  // Supprimer une tâche
  const handleDeleteTask = async (id: string) => {
    if (!confirm('Delete this task?')) return;

    try {
      await ipc.database.execute([
        {
          query: 'DELETE FROM tasks WHERE id = ?',
          params: [id],
        },
      ]);

      await loadTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete task');
    }
  };

  // Toggle status
  const handleToggleStatus = async (task: Task) => {
    const newStatus = task.status === 'completed' ? 'pending' : 'completed';
    await handleUpdateTask(task.id, { status: newStatus });
  };

  // Commencer l'édition
  const startEditing = (task: Task) => {
    setEditingId(task.id);
    setEditingContent(task.content);
  };

  // Sauvegarder l'édition
  const saveEditing = async () => {
    if (!editingId) return;

    const content = editingContent.trim();
    if (!content) {
      await handleDeleteTask(editingId);
    } else {
      await handleUpdateTask(editingId, { content });
    }

    setEditingId(null);
    setEditingContent('');
  };

  // Annuler l'édition
  const cancelEditing = () => {
    setEditingId(null);
    setEditingContent('');
  };

  // Drag & Drop
  const handleDragStart = (id: string) => {
    setDraggedId(id);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = async (targetId: string) => {
    if (!draggedId || draggedId === targetId) {
      setDraggedId(null);
      return;
    }

    const draggedTask = tasks.find(t => t.id === draggedId);
    const targetTask = tasks.find(t => t.id === targetId);

    if (!draggedTask || !targetTask) {
      setDraggedId(null);
      return;
    }

    // Réordonner localement
    const newTasks = [...tasks];
    const draggedIndex = newTasks.findIndex(t => t.id === draggedId);
    const targetIndex = newTasks.findIndex(t => t.id === targetId);

    newTasks.splice(draggedIndex, 1);
    newTasks.splice(targetIndex, 0, draggedTask);

    // Mettre à jour les orders
    const updates = newTasks.map((task, index) => ({
      query: 'UPDATE tasks SET "order" = ?, updated_at = ? WHERE id = ?',
      params: [index, Date.now(), task.id],
    }));

    try {
      await ipc.database.execute(updates);
      await loadTasks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to reorder tasks');
    }

    setDraggedId(null);
  };

  // Filtrer les tâches
  const filteredTasks = filter === 'all' ? tasks : tasks.filter(t => t.status === filter);

  const stats = {
    total: tasks.length,
    pending: tasks.filter(t => t.status === 'pending').length,
    in_progress: tasks.filter(t => t.status === 'in_progress').length,
    completed: tasks.filter(t => t.status === 'completed').length,
  };

  return (
    <div className={cn('flex flex-col h-full bg-background', className)}>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <div className="flex items-center gap-3">
          <h2 className="text-sm font-semibold text-text">Plans</h2>
          <div className="flex items-center gap-2">
            <Badge variant="secondary" className="text-xs">
              {stats.total} total
            </Badge>
            <Badge variant="secondary" className="text-xs">
              {stats.completed} done
            </Badge>
          </div>
        </div>

        <Button variant="ghost" size="sm" onClick={loadTasks} disabled={loading}>
          {loading ? <Spinner className="w-3 h-3" /> : '↻'}
        </Button>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-2 px-4 py-2 border-b border-border bg-wash">
        <FilterButton
          active={filter === 'all'}
          onClick={() => setFilter('all')}
          count={stats.total}
        >
          All
        </FilterButton>
        <FilterButton
          active={filter === 'pending'}
          onClick={() => setFilter('pending')}
          count={stats.pending}
        >
          Pending
        </FilterButton>
        <FilterButton
          active={filter === 'in_progress'}
          onClick={() => setFilter('in_progress')}
          count={stats.in_progress}
        >
          In Progress
        </FilterButton>
        <FilterButton
          active={filter === 'completed'}
          onClick={() => setFilter('completed')}
          count={stats.completed}
        >
          Completed
        </FilterButton>
      </div>

      {/* Error */}
      {error && (
        <div className="px-4 py-2 bg-red-soft text-red text-xs border-b border-red/20">
          {error}
        </div>
      )}

      {/* New Task Input */}
      <div className="flex items-center gap-2 px-4 py-3 border-b border-border">
        <Input
          value={newTaskContent}
          onChange={(e) => setNewTaskContent(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleCreateTask();
          }}
          placeholder="Add a new task..."
          className="flex-1"
        />
        <Button onClick={handleCreateTask} size="sm" disabled={!newTaskContent.trim()}>
          Add
        </Button>
      </div>

      {/* Tasks List */}
      <div className="flex-1 overflow-y-auto">
        {loading && tasks.length === 0 ? (
          <div className="flex items-center justify-center h-32">
            <Spinner />
          </div>
        ) : filteredTasks.length === 0 ? (
          <div className="flex items-center justify-center h-32 text-sm text-text-secondary">
            {filter === 'all' ? 'No tasks yet' : `No ${filter} tasks`}
          </div>
        ) : (
          <div className="divide-y divide-border">
            {filteredTasks.map((task) => (
              <TaskItem
                key={task.id}
                task={task}
                isEditing={editingId === task.id}
                editingContent={editingContent}
                onEditingContentChange={setEditingContent}
                onToggle={handleToggleStatus}
                onStartEdit={startEditing}
                onSaveEdit={saveEditing}
                onCancelEdit={cancelEditing}
                onDelete={handleDeleteTask}
                onDragStart={handleDragStart}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                isDragging={draggedId === task.id}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// Filter Button
// ============================================================================

interface FilterButtonProps {
  active: boolean;
  onClick: () => void;
  count: number;
  children: React.ReactNode;
}

function FilterButton({ active, onClick, count, children }: FilterButtonProps) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'px-3 py-1.5 text-xs font-medium rounded transition-colors',
        active
          ? 'bg-tint text-text'
          : 'text-text-secondary hover:text-text hover:bg-tint/50'
      )}
    >
      {children} <span className="opacity-60">({count})</span>
    </button>
  );
}

// ============================================================================
// Task Item
// ============================================================================

interface TaskItemProps {
  task: Task;
  isEditing: boolean;
  editingContent: string;
  onEditingContentChange: (content: string) => void;
  onToggle: (task: Task) => void;
  onStartEdit: (task: Task) => void;
  onSaveEdit: () => void;
  onCancelEdit: () => void;
  onDelete: (id: string) => void;
  onDragStart: (id: string) => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (id: string) => void;
  isDragging: boolean;
}

function TaskItem({
  task,
  isEditing,
  editingContent,
  onEditingContentChange,
  onToggle,
  onStartEdit,
  onSaveEdit,
  onCancelEdit,
  onDelete,
  onDragStart,
  onDragOver,
  onDrop,
  isDragging,
}: TaskItemProps) {
  const statusColor = {
    pending: 'text-text-secondary',
    in_progress: 'text-accent',
    completed: 'text-green',
    cancelled: 'text-text-tertiary',
  }[task.status];

  const statusLabel = {
    pending: 'Pending',
    in_progress: 'In Progress',
    completed: 'Completed',
    cancelled: 'Cancelled',
  }[task.status];

  return (
    <div
      draggable={!isEditing}
      onDragStart={() => onDragStart(task.id)}
      onDragOver={onDragOver}
      onDrop={() => onDrop(task.id)}
      className={cn(
        'group flex items-start gap-3 px-4 py-3 hover:bg-tint transition-colors',
        isDragging && 'opacity-50',
        task.status === 'completed' && 'opacity-60'
      )}
    >
      {/* Drag Handle */}
      <div className="pt-0.5 cursor-move text-text-tertiary opacity-0 group-hover:opacity-100 transition-opacity">
        <svg width="12" height="16" viewBox="0 0 12 16" fill="none">
          <circle cx="3" cy="3" r="1.5" fill="currentColor" />
          <circle cx="9" cy="3" r="1.5" fill="currentColor" />
          <circle cx="3" cy="8" r="1.5" fill="currentColor" />
          <circle cx="9" cy="8" r="1.5" fill="currentColor" />
          <circle cx="3" cy="13" r="1.5" fill="currentColor" />
          <circle cx="9" cy="13" r="1.5" fill="currentColor" />
        </svg>
      </div>

      {/* Checkbox */}
      <div className="pt-0.5">
        <Checkbox
          checked={task.status === 'completed'}
          onCheckedChange={() => onToggle(task)}
        />
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        {isEditing ? (
          <Input
            value={editingContent}
            onChange={(e) => onEditingContentChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') onSaveEdit();
              if (e.key === 'Escape') onCancelEdit();
            }}
            onBlur={onSaveEdit}
            autoFocus
            className="h-7 text-sm"
          />
        ) : (
          <button
            onClick={() => onStartEdit(task)}
            className={cn(
              'w-full text-left text-sm text-text hover:text-accent transition-colors',
              task.status === 'completed' && 'line-through'
            )}
          >
            {task.content}
          </button>
        )}
        <div className="flex items-center gap-2 mt-1">
          <span className={cn('text-xs font-medium', statusColor)}>
            {statusLabel}
          </span>
          <span className="text-xs text-text-tertiary">
            {new Date(task.created_at).toLocaleDateString()}
          </span>
        </div>
      </div>

      {/* Actions */}
      {!isEditing && (
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity pt-0.5">
          <button
            onClick={() => onStartEdit(task)}
            className="p-1 text-text-secondary hover:text-text hover:bg-tint-strong rounded transition-colors"
            title="Edit"
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
              <path
                d="M10.5 1.5l2 2-7 7H3.5v-2l7-7z"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
          <button
            onClick={() => onDelete(task.id)}
            className="p-1 text-text-secondary hover:text-red hover:bg-red-soft rounded transition-colors"
            title="Delete"
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
              <path
                d="M3 4h8M5 4V3a1 1 0 011-1h2a1 1 0 011 1v1M5.5 6.5v3M8.5 6.5v3M4.5 4l.5 7a1 1 0 001 1h2a1 1 0 001-1l.5-7"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * TerminalGrid - Multi-terminaux avec splits et gestion des tabs
 */

import { useState, useCallback } from 'react';
import { TerminalTab } from './TerminalTab';
import { Plus, LayoutGrid, Maximize2 } from 'lucide-react';

export interface Terminal {
  id: string;
  cwd?: string;
  title?: string;
}

export interface TerminalGridProps {
  className?: string;
}

export function TerminalGrid({ className = '' }: TerminalGridProps) {
  const [terminals, setTerminals] = useState<Terminal[]>([]);
  const [activeTerminalId, setActiveTerminalId] = useState<string | null>(null);
  const [layout, setLayout] = useState<'single' | 'horizontal' | 'vertical' | 'grid'>('single');

  // Créer un nouveau terminal
  const createTerminal = useCallback(async (cwd?: string) => {
    try {
      const response = await window.ipc.invoke('terminal:create', { cwd });

      if (response.success) {
        const newTerminal: Terminal = {
          id: response.data.terminalId,
          cwd,
          title: `Terminal ${terminals.length + 1}`,
        };

        setTerminals((prev) => [...prev, newTerminal]);
        setActiveTerminalId(newTerminal.id);
      }
    } catch (error) {
      console.error('Failed to create terminal:', error);
    }
  }, [terminals.length]);

  // Fermer un terminal
  const closeTerminal = useCallback(async (terminalId: string) => {
    try {
      await window.ipc.invoke('terminal:kill', terminalId);

      setTerminals((prev) => {
        const filtered = prev.filter((t) => t.id !== terminalId);

        // Si le terminal actif est fermé, sélectionner le suivant
        if (activeTerminalId === terminalId && filtered.length > 0) {
          setActiveTerminalId(filtered[filtered.length - 1].id);
        } else if (filtered.length === 0) {
          setActiveTerminalId(null);
        }

        return filtered;
      });
    } catch (error) {
      console.error('Failed to close terminal:', error);
    }
  }, [activeTerminalId]);

  // Split horizontal
  const splitHorizontal = useCallback(() => {
    if (layout === 'single') {
      setLayout('horizontal');
    }
    createTerminal();
  }, [layout, createTerminal]);

  // Split vertical
  const splitVertical = useCallback(() => {
    if (layout === 'single') {
      setLayout('vertical');
    }
    createTerminal();
  }, [layout, createTerminal]);

  // Toggle layout
  const toggleLayout = useCallback(() => {
    const layouts: Array<typeof layout> = ['single', 'horizontal', 'vertical', 'grid'];
    const currentIndex = layouts.indexOf(layout);
    const nextIndex = (currentIndex + 1) % layouts.length;
    setLayout(layouts[nextIndex]);
  }, [layout]);

  // Keyboard shortcuts
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      // Ctrl+` : Toggle terminal
      if (e.ctrlKey && e.key === '`') {
        e.preventDefault();
        if (terminals.length === 0) {
          createTerminal();
        }
      }
      // Ctrl+Shift+5 : Split horizontal
      else if (e.ctrlKey && e.shiftKey && e.key === '%') {
        e.preventDefault();
        splitHorizontal();
      }
      // Ctrl+Shift+\ : Split vertical
      else if (e.ctrlKey && e.shiftKey && e.key === '|') {
        e.preventDefault();
        splitVertical();
      }
      // Ctrl+Shift+W : Close active terminal
      else if (e.ctrlKey && e.shiftKey && e.key === 'W' && activeTerminalId) {
        e.preventDefault();
        closeTerminal(activeTerminalId);
      }
    },
    [terminals.length, activeTerminalId, createTerminal, splitHorizontal, splitVertical, closeTerminal]
  );

  // Render layout
  const renderTerminals = () => {
    if (terminals.length === 0) {
      return (
        <div className="flex flex-col items-center justify-center h-full text-neutral-500">
          <div className="text-6xl mb-4">$_</div>
          <p className="text-sm mb-4">No terminal open</p>
          <button
            onClick={() => createTerminal()}
            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-md transition-colors flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            New Terminal
          </button>
          <p className="text-xs mt-4 text-neutral-600">Press Ctrl+` to open a terminal</p>
        </div>
      );
    }

    const visibleTerminals = terminals.slice(0, layout === 'grid' ? 4 : layout === 'single' ? 1 : 2);

    if (layout === 'single') {
      const terminal = terminals.find((t) => t.id === activeTerminalId) || terminals[0];
      return (
        <TerminalTab
          key={terminal.id}
          terminalId={terminal.id}
          cwd={terminal.cwd}
          onClose={() => closeTerminal(terminal.id)}
          className="h-full"
        />
      );
    }

    if (layout === 'horizontal') {
      return (
        <div className="flex h-full gap-0.5">
          {visibleTerminals.map((terminal) => (
            <div key={terminal.id} className="flex-1 min-w-0">
              <TerminalTab
                terminalId={terminal.id}
                cwd={terminal.cwd}
                onClose={() => closeTerminal(terminal.id)}
                className="h-full"
              />
            </div>
          ))}
        </div>
      );
    }

    if (layout === 'vertical') {
      return (
        <div className="flex flex-col h-full gap-0.5">
          {visibleTerminals.map((terminal) => (
            <div key={terminal.id} className="flex-1 min-h-0">
              <TerminalTab
                terminalId={terminal.id}
                cwd={terminal.cwd}
                onClose={() => closeTerminal(terminal.id)}
                className="h-full"
              />
            </div>
          ))}
        </div>
      );
    }

    if (layout === 'grid') {
      return (
        <div className="grid grid-cols-2 grid-rows-2 h-full gap-0.5">
          {visibleTerminals.map((terminal) => (
            <div key={terminal.id} className="min-w-0 min-h-0">
              <TerminalTab
                terminalId={terminal.id}
                cwd={terminal.cwd}
                onClose={() => closeTerminal(terminal.id)}
                className="h-full"
              />
            </div>
          ))}
        </div>
      );
    }

    return null;
  };

  return (
    <div
      className={`flex flex-col h-full bg-[#0a0a0a] ${className}`}
      onKeyDown={handleKeyDown}
      tabIndex={0}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-[#141414] border-b border-neutral-800">
        <div className="flex items-center gap-3">
          <h2 className="text-sm font-medium text-neutral-200">Terminal</h2>
          {terminals.length > 0 && (
            <span className="text-xs text-neutral-500">
              {terminals.length} {terminals.length === 1 ? 'terminal' : 'terminals'}
            </span>
          )}
        </div>

        <div className="flex items-center gap-1">
          <button
            onClick={() => createTerminal()}
            className="p-1.5 hover:bg-neutral-700 rounded transition-colors"
            title="New terminal (Ctrl+`)"
          >
            <Plus className="w-4 h-4 text-neutral-400" />
          </button>
          <button
            onClick={toggleLayout}
            className="p-1.5 hover:bg-neutral-700 rounded transition-colors"
            title="Toggle layout"
          >
            {layout === 'single' && <Maximize2 className="w-4 h-4 text-neutral-400" />}
            {layout !== 'single' && <LayoutGrid className="w-4 h-4 text-neutral-400" />}
          </button>
        </div>
      </div>

      {/* Terminal tabs (si plus de 2 terminaux) */}
      {terminals.length > 2 && (
        <div className="flex items-center gap-1 px-2 py-1 bg-[#1a1a1a] border-b border-neutral-800 overflow-x-auto">
          {terminals.map((terminal, index) => (
            <button
              key={terminal.id}
              onClick={() => setActiveTerminalId(terminal.id)}
              className={`px-3 py-1 text-xs rounded transition-colors ${
                terminal.id === activeTerminalId
                  ? 'bg-[#0a0a0a] text-neutral-200'
                  : 'text-neutral-500 hover:text-neutral-300 hover:bg-neutral-800'
              }`}
            >
              {terminal.title || `Terminal ${index + 1}`}
            </button>
          ))}
        </div>
      )}

      {/* Content */}
      <div className="flex-1 min-h-0">{renderTerminals()}</div>

      {/* Keyboard shortcuts hint */}
      {terminals.length > 0 && (
        <div className="px-4 py-1.5 bg-[#141414] border-t border-neutral-800 text-xs text-neutral-600 flex items-center gap-4">
          <span>Ctrl+` New</span>
          <span>Ctrl+Shift+% Split H</span>
          <span>Ctrl+Shift+| Split V</span>
          <span>Ctrl+Shift+W Close</span>
        </div>
      )}
    </div>
  );
}

/**
 * TerminalTab - Single terminal avec xterm.js
 */

import { useEffect, useRef, useState } from 'react';
import { Terminal } from '@xterm/xterm';
import { FitAddon } from '@xterm/addon-fit';
import { WebLinksAddon } from '@xterm/addon-web-links';
import { SearchAddon } from '@xterm/addon-search';
import '@xterm/xterm/css/xterm.css';
import { X, Search, Copy } from 'lucide-react';

export interface TerminalTabProps {
  terminalId: string;
  cwd?: string;
  onClose?: () => void;
  onData?: (data: string) => void;
  className?: string;
}

export function TerminalTab({
  terminalId,
  cwd,
  onClose,
  onData,
  className = '',
}: TerminalTabProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const terminalRef = useRef<Terminal | null>(null);
  const fitAddonRef = useRef<FitAddon | null>(null);
  const searchAddonRef = useRef<SearchAddon | null>(null);
  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (!containerRef.current) return;

    // Création du terminal
    const terminal = new Terminal({
      cursorBlink: true,
      cursorStyle: 'block',
      fontFamily: 'JetBrains Mono, Menlo, Monaco, "Courier New", monospace',
      fontSize: 13,
      lineHeight: 1.4,
      theme: {
        background: '#0a0a0a',
        foreground: '#e5e5e5',
        cursor: '#ffffff',
        cursorAccent: '#000000',
        selectionBackground: '#404040',
        black: '#1a1a1a',
        red: '#ef4444',
        green: '#22c55e',
        yellow: '#eab308',
        blue: '#3b82f6',
        magenta: '#a855f7',
        cyan: '#06b6d4',
        white: '#e5e5e5',
        brightBlack: '#525252',
        brightRed: '#f87171',
        brightGreen: '#4ade80',
        brightYellow: '#facc15',
        brightBlue: '#60a5fa',
        brightMagenta: '#c084fc',
        brightCyan: '#22d3ee',
        brightWhite: '#fafafa',
      },
      allowProposedApi: true,
    });

    // Addons
    const fitAddon = new FitAddon();
    const webLinksAddon = new WebLinksAddon();
    const searchAddon = new SearchAddon();

    terminal.loadAddon(fitAddon);
    terminal.loadAddon(webLinksAddon);
    terminal.loadAddon(searchAddon);

    terminal.open(containerRef.current);
    fitAddon.fit();

    terminalRef.current = terminal;
    fitAddonRef.current = fitAddon;
    searchAddonRef.current = searchAddon;

    // Gestion des inputs utilisateur
    terminal.onData((data) => {
      onData?.(data);
      // Envoi au backend via IPC
      window.ipc.invoke('terminal:input', { terminalId, data });
    });

    // Écoute des données du backend
    const unsubscribeData = window.ipc.on('event:terminal-data', (event) => {
      if (event.terminalId === terminalId) {
        terminal.write(event.data);
      }
    });

    // Écoute de la sortie du terminal
    const unsubscribeExit = window.ipc.on('event:terminal-exit', (event) => {
      if (event.terminalId === terminalId) {
        terminal.write(`\r\n\x1b[1;31m[Process exited with code ${event.exitCode}]\x1b[0m\r\n`);
      }
    });

    // Resize observer
    const resizeObserver = new ResizeObserver(() => {
      fitAddon.fit();
      // Notifie le backend du nouveau size
      window.ipc.invoke('terminal:resize', {
        terminalId,
        cols: terminal.cols,
        rows: terminal.rows,
      });
    });

    resizeObserver.observe(containerRef.current);

    // Cleanup
    return () => {
      unsubscribeData();
      unsubscribeExit();
      resizeObserver.disconnect();
      terminal.dispose();
    };
  }, [terminalId, onData]);

  // Search functionality
  const handleSearch = (direction: 'next' | 'prev') => {
    if (!searchAddonRef.current || !searchQuery) return;

    if (direction === 'next') {
      searchAddonRef.current.findNext(searchQuery);
    } else {
      searchAddonRef.current.findPrevious(searchQuery);
    }
  };

  // Copy selection
  const handleCopy = async () => {
    if (!terminalRef.current) return;
    const selection = terminalRef.current.getSelection();
    if (selection) {
      await navigator.clipboard.writeText(selection);
    }
  };

  // Clear terminal
  const handleClear = () => {
    terminalRef.current?.clear();
  };

  return (
    <div className={`flex flex-col h-full bg-[#0a0a0a] ${className}`}>
      {/* Toolbar */}
      <div className="flex items-center justify-between px-3 py-2 bg-[#141414] border-b border-neutral-800">
        <div className="flex items-center gap-2">
          <span className="text-xs text-neutral-400 font-mono">
            {cwd || '~'}
          </span>
        </div>

        <div className="flex items-center gap-1">
          <button
            onClick={() => setShowSearch(!showSearch)}
            className="p-1.5 hover:bg-neutral-700 rounded transition-colors"
            title="Search (Ctrl+F)"
          >
            <Search className="w-3.5 h-3.5 text-neutral-400" />
          </button>
          <button
            onClick={handleCopy}
            className="p-1.5 hover:bg-neutral-700 rounded transition-colors"
            title="Copy selection (Ctrl+C)"
          >
            <Copy className="w-3.5 h-3.5 text-neutral-400" />
          </button>
          {onClose && (
            <button
              onClick={onClose}
              className="p-1.5 hover:bg-neutral-700 rounded transition-colors"
              title="Close terminal"
            >
              <X className="w-3.5 h-3.5 text-neutral-400" />
            </button>
          )}
        </div>
      </div>

      {/* Search bar */}
      {showSearch && (
        <div className="flex items-center gap-2 px-3 py-2 bg-[#1a1a1a] border-b border-neutral-800">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                handleSearch(e.shiftKey ? 'prev' : 'next');
              } else if (e.key === 'Escape') {
                setShowSearch(false);
              }
            }}
            placeholder="Search in terminal..."
            className="flex-1 px-2 py-1 text-xs bg-neutral-900 border border-neutral-700 rounded focus:outline-none focus:border-blue-500"
            autoFocus
          />
          <button
            onClick={() => handleSearch('prev')}
            className="px-2 py-1 text-xs hover:bg-neutral-700 rounded"
          >
            ↑
          </button>
          <button
            onClick={() => handleSearch('next')}
            className="px-2 py-1 text-xs hover:bg-neutral-700 rounded"
          >
            ↓
          </button>
        </div>
      )}

      {/* Terminal container */}
      <div ref={containerRef} className="flex-1 p-2" />
    </div>
  );
}

// Structured logging infrastructure
import type { LogLevel, LogEntry } from './types/debug';

export class Logger {
  private static instance: Logger;
  private logs: LogEntry[] = [];
  private maxLogs = 10000; // Keep last 10k logs in memory
  private listeners: Set<(log: LogEntry) => void> = new Set();

  private constructor() {}

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger();
    }
    return Logger.instance;
  }

  /**
   * Subscribe to log events
   */
  onLog(callback: (log: LogEntry) => void): () => void {
    this.listeners.add(callback);
    return () => this.listeners.delete(callback);
  }

  /**
   * Log a message
   */
  log(
    level: LogLevel,
    category: string,
    message: string,
    data?: any,
    stack?: string
  ): void {
    const entry: LogEntry = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
      timestamp: Date.now(),
      level,
      category,
      message,
      data,
      stack,
      source: typeof window !== 'undefined' ? 'renderer' : 'main'
    };

    // Add to in-memory buffer
    this.logs.push(entry);
    if (this.logs.length > this.maxLogs) {
      this.logs.shift();
    }

    // Notify listeners
    this.listeners.forEach(listener => listener(entry));

    // Console output in dev mode
    if (process.env.NODE_ENV === 'development' || process.env.DEBUG === 'true') {
      const prefix = `[${level.toUpperCase()}] [${category}]`;
      const method = level === 'error' ? 'error' : level === 'warn' ? 'warn' : 'log';
      console[method](prefix, message, data || '');
      if (stack) {
        console[method](stack);
      }
    }
  }

  debug(category: string, message: string, data?: any): void {
    this.log('debug', category, message, data);
  }

  info(category: string, message: string, data?: any): void {
    this.log('info', category, message, data);
  }

  warn(category: string, message: string, data?: any): void {
    this.log('warn', category, message, data);
  }

  error(category: string, message: string, error?: any): void {
    const stack = error?.stack || new Error().stack;
    this.log('error', category, message, error, stack);
  }

  /**
   * Get recent logs
   */
  getLogs(limit?: number): LogEntry[] {
    return limit ? this.logs.slice(-limit) : [...this.logs];
  }

  /**
   * Clear all logs
   */
  clear(): void {
    this.logs = [];
  }

  /**
   * Filter logs by criteria
   */
  filter(criteria: {
    level?: LogLevel;
    category?: string;
    source?: 'main' | 'renderer';
    since?: number;
  }): LogEntry[] {
    return this.logs.filter(log => {
      if (criteria.level && log.level !== criteria.level) return false;
      if (criteria.category && log.category !== criteria.category) return false;
      if (criteria.source && log.source !== criteria.source) return false;
      if (criteria.since && log.timestamp < criteria.since) return false;
      return true;
    });
  }
}

// Export singleton instance
export const logger = Logger.getInstance();

