program
  .command('run')
  .description('Run benchmarks')
  .option('-s, --scenario <id>', 'Run specific scenario (bug-fix-simple, feature-medium, refactor-large)')
  .option('-t, --strategy <id>', 'Run specific strategy (baseline, semantic-chunking, simple-minifier, anthropic-caching)')
