    const basePath = resolve(__dirname, '../../../..');
    console.log('📊 Context Optimization Benchmarks\n');
    console.log(`Base path: ${basePath}`);

    // Filter scenarios and strategies if specified
    const selectedScenarios = options.scenario
      ? scenarios.filter((s) => s.id === options.scenario)
      : scenarios;

    const selectedStrategies = options.strategy
      ? strategies.filter((s) => s.id === options.strategy)
      : strategies.filter((s) => s.enabled);

    if (selectedScenarios.length === 0) {
      console.error(`❌ Unknown scenario: ${options.scenario}`);
      process.exit(1);
    }

    if (selectedStrategies.length === 0) {
      console.error(`❌ Unknown strategy: ${options.strategy}`);
      process.exit(1);
    }

    console.log(`\nScenarios: ${selectedScenarios.map((s) => s.name).join(', ')}`);
    console.log(`Strategies: ${selectedStrategies.map((s) => s.name).join(', ')}`);
    console.log(`\nTotal runs: ${selectedScenarios.length * selectedStrategies.length}\n`);

    const spinner = ora('Initializing benchmark runner...').start();

    try {
      const runner = new BenchmarkRunner(apiKey);
      spinner.succeed('Runner initialized');

      // Run benchmarks
      const results = await runner.runAll(basePath);

      // Display results
      console.log('\n\n📊 Results Summary\n');
      displayResults(results);

      // Save to file
      const outputPath = resolve(process.cwd(), options.output);
      writeFileSync(outputPath, JSON.stringify(results, null, 2));
      console.log(`\n💾 Results saved to: ${outputPath}`);

      // Generate markdown report
      const markdownPath = outputPath.replace('.json', '.md');
      const markdown = generateMarkdownReport(results);
      writeFileSync(markdownPath, markdown);
      console.log(`📄 Markdown report: ${markdownPath}`);
    } catch (error) {
      spinner.fail('Benchmark failed');
      console.error(error);
      process.exit(1);
    }
  });

