function displayResults(results: BenchmarkResult[]) {
  const data = [
    ['Scenario', 'Strategy', 'TTFT', 'Tokens', 'Cost', 'Time', 'Quality', 'Cache Hit'],
  ];

  for (const result of results) {
    const scenario = scenarios.find((s) => s.id === result.scenarioId);
    const strategy = strategies.find((s) => s.id === result.strategyId);

    data.push([
      scenario?.name || result.scenarioId,
      strategy?.name || result.strategyId,
      `${result.metrics.ttft}ms`,
      `${result.metrics.totalTokens.input.toLocaleString()}/${result.metrics.totalTokens.output.toLocaleString()}`,
      `$${result.metrics.cost.toFixed(4)}`,
      `${(result.metrics.totalTime / 1000).toFixed(1)}s`,
      `${result.quality.score}/100`,
      result.metrics.cacheHitRate
        ? `${(result.metrics.cacheHitRate * 100).toFixed(1)}%`
        : '-',
    ]);
  }

  console.log(table(data));
}

function displayComparison(results: BenchmarkResult[]) {
  // Group by scenario
  const byScenario = new Map<string, BenchmarkResult[]>();
  for (const result of results) {
    if (!byScenario.has(result.scenarioId)) {
      byScenario.set(result.scenarioId, []);
    }
    byScenario.get(result.scenarioId)!.push(result);
  }

  console.log('\n📈 Strategy Comparison (vs Baseline)\n');

  for (const [scenarioId, scenarioResults] of byScenario) {
    const scenario = scenarios.find((s) => s.id === scenarioId);
    console.log(`\n${scenario?.name || scenarioId}:\n`);

    const baseline = scenarioResults.find((r) => r.strategyId === 'baseline');
    if (!baseline) {
      console.log('  No baseline found');
      continue;
    }

    const data = [
      ['Strategy', 'TTFT', 'Tokens', 'Cost', 'Time', 'Quality'],
    ];

    for (const result of scenarioResults) {
      if (result.strategyId === 'baseline') continue;

      const strategy = strategies.find((s) => s.id === result.strategyId);
      const ttftChange = ((result.metrics.ttft - baseline.metrics.ttft) / baseline.metrics.ttft) * 100;
      const tokenChange =
        ((result.metrics.totalTokens.input - baseline.metrics.totalTokens.input) /
          baseline.metrics.totalTokens.input) *
        100;
      const costChange = ((result.metrics.cost - baseline.metrics.cost) / baseline.metrics.cost) * 100;
      const timeChange = ((result.metrics.totalTime - baseline.metrics.totalTime) / baseline.metrics.totalTime) * 100;
      const qualityChange = result.quality.score - baseline.quality.score;

      const formatChange = (val: number, inverse = false) => {
        const sign = val >= 0 ? '+' : '';
        const color = (inverse ? val <= 0 : val >= 0) ? '🟢' : '🔴';
        return `${color} ${sign}${val.toFixed(1)}%`;
      };

      data.push([
        strategy?.name || result.strategyId,
        formatChange(ttftChange, true),
        formatChange(tokenChange, true),
        formatChange(costChange, true),
        formatChange(timeChange, true),
        `${qualityChange >= 0 ? '🟢' : '🔴'} ${qualityChange >= 0 ? '+' : ''}${qualityChange}`,
      ]);
    }

    console.log(table(data));
  }
}

function generateMarkdownReport(results: BenchmarkResult[]): string {
  let md = '# Context Optimization Benchmark Results\n\n';
  md += `Generated: ${new Date().toISOString()}\n\n`;

  // Summary table
  md += '## Results Summary\n\n';
  md += '| Scenario | Strategy | TTFT | Input Tokens | Output Tokens | Cost | Total Time | Quality | Cache Hit |\n';
  md += '|----------|----------|------|--------------|---------------|------|------------|---------|----------|\n';

  for (const result of results) {
    const scenario = scenarios.find((s) => s.id === result.scenarioId);
    const strategy = strategies.find((s) => s.id === result.strategyId);

    md += `| ${scenario?.name || result.scenarioId} `;
    md += `| ${strategy?.name || result.strategyId} `;
    md += `| ${result.metrics.ttft}ms `;
    md += `| ${result.metrics.totalTokens.input.toLocaleString()} `;
    md += `| ${result.metrics.totalTokens.output.toLocaleString()} `;
    md += `| $${result.metrics.cost.toFixed(4)} `;
    md += `| ${(result.metrics.totalTime / 1000).toFixed(1)}s `;
    md += `| ${result.quality.score}/100 `;
    md += `| ${result.metrics.cacheHitRate ? `${(result.metrics.cacheHitRate * 100).toFixed(1)}%` : '-'} |\n`;
  }

  // Comparison by scenario
  const byScenario = new Map<string, BenchmarkResult[]>();
  for (const result of results) {
    if (!byScenario.has(result.scenarioId)) {
      byScenario.set(result.scenarioId, []);
    }
    byScenario.get(result.scenarioId)!.push(result);
  }

  md += '\n## Strategy Comparison\n\n';

  for (const [scenarioId, scenarioResults] of byScenario) {
    const scenario = scenarios.find((s) => s.id === scenarioId);
    md += `### ${scenario?.name || scenarioId}\n\n`;
    md += `${scenario?.description}\n\n`;

    const baseline = scenarioResults.find((r) => r.strategyId === 'baseline');
    if (!baseline) {
      md += 'No baseline found.\n\n';
      continue;
    }

    md += '| Strategy | TTFT vs Baseline | Tokens vs Baseline | Cost vs Baseline | Time vs Baseline | Quality |\n';
    md += '|----------|------------------|-------------------|------------------|------------------|----------|\n';

    md += `| Baseline | - | - | - | - | ${baseline.quality.score}/100 |\n`;

    for (const result of scenarioResults) {
      if (result.strategyId === 'baseline') continue;

      const strategy = strategies.find((s) => s.id === result.strategyId);
      const ttftChange = ((result.metrics.ttft - baseline.metrics.ttft) / baseline.metrics.ttft) * 100;
      const tokenChange =
        ((result.metrics.totalTokens.input - baseline.metrics.totalTokens.input) /
          baseline.metrics.totalTokens.input) *
        100;
      const costChange = ((result.metrics.cost - baseline.metrics.cost) / baseline.metrics.cost) * 100;
      const timeChange = ((result.metrics.totalTime - baseline.metrics.totalTime) / baseline.metrics.totalTime) * 100;

      md += `| ${strategy?.name || result.strategyId} `;
      md += `| ${ttftChange >= 0 ? '+' : ''}${ttftChange.toFixed(1)}% `;
      md += `| ${tokenChange >= 0 ? '+' : ''}${tokenChange.toFixed(1)}% `;
      md += `| ${costChange >= 0 ? '+' : ''}${costChange.toFixed(1)}% `;
      md += `| ${timeChange >= 0 ? '+' : ''}${timeChange.toFixed(1)}% `;
      md += `| ${result.quality.score}/100 |\n`;
    }

    md += '\n';
  }

  // Detailed metrics
  md += '\n## Detailed Metrics\n\n';

  for (const result of results) {
    const scenario = scenarios.find((s) => s.id === result.scenarioId);
    const strategy = strategies.find((s) => s.id === result.strategyId);

    md += `### ${scenario?.name} - ${strategy?.name}\n\n`;
    md += '**Metrics:**\n';
    md += `- TTFT: ${result.metrics.ttft}ms\n`;
    md += `- Input Tokens: ${result.metrics.totalTokens.input.toLocaleString()}\n`;
    md += `- Output Tokens: ${result.metrics.totalTokens.output.toLocaleString()}\n`;
    if (result.metrics.totalTokens.cached) {
      md += `- Cached Tokens: ${result.metrics.totalTokens.cached.toLocaleString()}\n`;
    }
    md += `- Total Time: ${(result.metrics.totalTime / 1000).toFixed(1)}s\n`;
    md += `- Cost: $${result.metrics.cost.toFixed(4)}\n`;
    if (result.metrics.cacheHitRate) {
      md += `- Cache Hit Rate: ${(result.metrics.cacheHitRate * 100).toFixed(1)}%\n`;
    }
    md += '\n**Quality:**\n';
    md += `- Overall Score: ${result.quality.score}/100\n`;
    md += `- Correctness: ${result.quality.correctness}/100\n`;
    md += `- Completeness: ${result.quality.completeness}/100\n`;
    md += `- Relevance: ${result.quality.relevance}/100\n`;
    md += `- Notes: ${result.quality.notes}\n\n`;

    if (result.error) {
      md += `**Error:** ${result.error}\n\n`;
    }
  }

  return md;
}

