/**
 * Benchmark runner for context optimization strategies
 */

import Anthropic from '@anthropic-ai/sdk';
import { readFileSync, readdirSync, statSync } from 'fs';
import { join, resolve } from 'path';
import { glob } from 'glob';
import type { BenchmarkScenario, OptimizationStrategy } from './scenarios';
import { scenarios, strategies } from './scenarios';

export interface BenchmarkResult {
  scenarioId: string;
  strategyId: string;
  metrics: {
    ttft: number; // milliseconds
    totalTokens: {
      input: number;
      output: number;
      cached?: number;
    };
    cost: number; // USD
    totalTime: number; // milliseconds
    cacheHitRate?: number; // 0-1
  };
  quality: {
    score: number; // 0-100
    correctness: number;
    completeness: number;
    relevance: number;
    notes: string;
  };
  response: string;
  error?: string;
}

export class BenchmarkRunner {
  private anthropic: Anthropic;
  private results: BenchmarkResult[] = [];

  constructor(apiKey: string) {
    this.anthropic = new Anthropic({ apiKey });
  }

  /**
   * Load file content with glob support
   */
  private loadFiles(patterns: string[], basePath: string): Map<string, string> {
    const files = new Map<string, string>();

    for (const pattern of patterns) {
      const fullPattern = join(basePath, pattern);

      // Handle glob patterns
      if (pattern.includes('*')) {
        const matches = glob.sync(fullPattern);
        for (const file of matches) {
          try {
            const content = readFileSync(file, 'utf-8');
            const relativePath = file.replace(basePath + '/', '');
            files.set(relativePath, content);
          } catch (error) {
            console.warn(`Failed to read ${file}:`, error);
          }
        }
      } else {
        // Direct file
        try {
          const file = resolve(basePath, pattern);
          const content = readFileSync(file, 'utf-8');
          files.set(pattern, content);
        } catch (error) {
          console.warn(`Failed to read ${pattern}:`, error);
        }
      }
    }

    return files;
  }

  /**
   * Apply optimization strategy to context
   */
  private applyStrategy(
    files: Map<string, string>,
    strategy: OptimizationStrategy
  ): string {
    let context = '';

    switch (strategy.id) {
      case 'baseline':
        // No optimization - just concatenate
        for (const [path, content] of files) {
          context += `\n\n--- ${path} ---\n${content}`;
        }
        break;

      case 'semantic-chunking':
        // Simple semantic chunking by top-level declarations
        for (const [path, content] of files) {
          context += `\n\n--- ${path} ---\n`;
          const chunks = this.semanticChunk(content, strategy.config!);
          context += chunks.join('\n\n');
        }
        break;

      case 'simple-minifier':
        // Remove comments and extra whitespace
        for (const [path, content] of files) {
          context += `\n\n--- ${path} ---\n`;
          context += this.minify(content, strategy.config!);
        }
        break;

      case 'anthropic-caching':
        // For caching, we'll structure the context differently
        // but the content is the same as baseline
        for (const [path, content] of files) {
          context += `\n\n--- ${path} ---\n${content}`;
        }
        break;
    }

    return context;
  }

  /**
   * Semantic chunking by function/class boundaries
   */
  private semanticChunk(
    content: string,
    config: Record<string, unknown>
  ): string[] {
    const chunks: string[] = [];
    const lines = content.split('\n');
    let currentChunk: string[] = [];
    let braceDepth = 0;
    let inDeclaration = false;

    for (const line of lines) {
      currentChunk.push(line);

      // Track brace depth for top-level declarations
      for (const char of line) {
        if (char === '{') braceDepth++;
        if (char === '}') braceDepth--;
      }

      // Detect start of declaration
      if (
        (line.match(/^(export\s+)?(function|class|interface|type|const|let|var)\s+/) ||
          line.match(/^\s*(async\s+)?function\s+/)) &&
        braceDepth === 0
      ) {
        inDeclaration = true;
      }

      // End of top-level declaration
      if (inDeclaration && braceDepth === 0 && line.trim() === '') {
        chunks.push(currentChunk.join('\n'));
        currentChunk = [];
        inDeclaration = false;
      }
    }

    if (currentChunk.length > 0) {
      chunks.push(currentChunk.join('\n'));
    }

    return chunks;
  }

  /**
   * Simple minifier
   */
  private minify(content: string, config: Record<string, unknown>): string {
    let minified = content;

    if (config.removeComments) {
      // Remove single-line comments
      minified = minified.replace(/\/\/.*$/gm, '');
      // Remove multi-line comments
      minified = minified.replace(/\/\*[\s\S]*?\*\//g, '');
    }

    if (config.removeWhitespace) {
      // Remove extra whitespace
      minified = minified.replace(/\s+/g, ' ');
      // Remove leading/trailing whitespace
      minified = minified.trim();
    }

    if (!config.preserveNewlines) {
      // Keep some newlines for readability
      minified = minified.replace(/\n\s*\n/g, '\n');
    }

    return minified;
  }

  /**
   * Build prompt with context
   */
  private buildPrompt(
    scenario: BenchmarkScenario,
    context: string,
    strategy: OptimizationStrategy
  ): Anthropic.Messages.MessageCreateParams {
    const systemPrompt = `You are a senior TypeScript developer. Your task is to make code changes as requested.

Context files are provided below. Analyze them carefully and make the necessary changes.

Focus on:
1. Correctness - The solution should work
2. Completeness - Address all aspects of the task
3. Best practices - Follow TypeScript and React best practices
4. Minimal changes - Change only what's necessary`;

    const userPrompt = `${scenario.task}

Context:
${context}

Provide the changes needed to complete this task.`;

    const params: Anthropic.Messages.MessageCreateParams = {
      model: 'claude-3-5-sonnet-20241022',
      max_tokens: 4096,
      messages: [
        {
          role: 'user',
          content: userPrompt,
        },
      ],
    };

    // For Anthropic caching, use cache_control
    if (strategy.id === 'anthropic-caching') {
      params.system = [
        {
          type: 'text',
          text: systemPrompt,
          cache_control: { type: 'ephemeral' },
        },
        {
          type: 'text',
          text: context,
          cache_control: { type: 'ephemeral' },
        },
      ];
    } else {
      params.system = systemPrompt + '\n\n' + context;
    }

    return params;
  }

  /**
   * Run a single benchmark
   */
  async runBenchmark(
    scenario: BenchmarkScenario,
    strategy: OptimizationStrategy,
    basePath: string
  ): Promise<BenchmarkResult> {
    console.log(`\n🔍 Running: ${scenario.name} with ${strategy.name}`);

    const startTime = Date.now();
    let ttft = 0;
    let firstTokenReceived = false;

    try {
      // Load files
      const allFiles = [...scenario.targetFiles, ...scenario.contextFiles];
      const files = this.loadFiles(allFiles, basePath);
      console.log(`   Loaded ${files.size} files`);

      // Apply strategy
      const context = this.applyStrategy(files, strategy);
      console.log(`   Context size: ${context.length} chars`);

      // Build prompt
      const params = this.buildPrompt(scenario, context, strategy);

      // Make API call
      const stream = await this.anthropic.messages.create({
        ...params,
        stream: true,
      });

      let response = '';
      let inputTokens = 0;
      let outputTokens = 0;
      let cachedTokens = 0;

      for await (const event of stream) {
        if (!firstTokenReceived && event.type === 'content_block_delta') {
          ttft = Date.now() - startTime;
          firstTokenReceived = true;
          console.log(`   TTFT: ${ttft}ms`);
        }

        if (event.type === 'content_block_delta') {
          if (event.delta.type === 'text_delta') {
            response += event.delta.text;
          }
        }

        if (event.type === 'message_start') {
          inputTokens = event.message.usage.input_tokens;
          cachedTokens = (event.message.usage as any).cache_read_input_tokens || 0;
        }

        if (event.type === 'message_delta') {
          outputTokens = event.usage.output_tokens;
        }
      }

      const totalTime = Date.now() - startTime;

      // Calculate cost (Claude 3.5 Sonnet pricing)
      const inputCost = (inputTokens / 1_000_000) * 3.0;
      const outputCost = (outputTokens / 1_000_000) * 15.0;
      const cachedCost = (cachedTokens / 1_000_000) * 0.3; // 90% discount
      const cost = inputCost + outputCost - cachedCost;

      const cacheHitRate =
        cachedTokens > 0 ? cachedTokens / (inputTokens + cachedTokens) : undefined;

      console.log(`   ✓ Complete in ${totalTime}ms`);
      console.log(`   Tokens: ${inputTokens} in, ${outputTokens} out, ${cachedTokens} cached`);
      console.log(`   Cost: $${cost.toFixed(4)}`);
      if (cacheHitRate) {
        console.log(`   Cache hit rate: ${(cacheHitRate * 100).toFixed(1)}%`);
      }

      // Evaluate quality (simplified - in reality, this would be more sophisticated)
      const quality = this.evaluateQuality(response, scenario);

      return {
        scenarioId: scenario.id,
        strategyId: strategy.id,
        metrics: {
          ttft,
          totalTokens: {
            input: inputTokens,
            output: outputTokens,
            cached: cachedTokens,
          },
          cost,
          totalTime,
          cacheHitRate,
        },
        quality,
        response,
      };
    } catch (error) {
      console.error(`   ✗ Error: ${error}`);
      return {
        scenarioId: scenario.id,
        strategyId: strategy.id,
        metrics: {
          ttft: 0,
          totalTokens: { input: 0, output: 0 },
          cost: 0,
          totalTime: Date.now() - startTime,
        },
        quality: {
          score: 0,
          correctness: 0,
          completeness: 0,
          relevance: 0,
          notes: 'Benchmark failed',
        },
        response: '',
        error: error instanceof Error ? error.message : String(error),
      };
    }
  }

  /**
   * Evaluate response quality
   */
  private evaluateQuality(
    response: string,
    scenario: BenchmarkScenario
  ): BenchmarkResult['quality'] {
    // Simplified quality scoring
    // In production, this would use more sophisticated analysis

    let correctness = 0;
    let completeness = 0;
    let relevance = 0;

    // Check if response mentions target files
    for (const file of scenario.targetFiles) {
      if (response.includes(file) || response.includes(file.split('/').pop()!)) {
        completeness += 20;
      }
    }

    // Check if response has code blocks
    const codeBlocks = response.match(/```/g);
    if (codeBlocks && codeBlocks.length >= 2) {
      correctness += 30;
    }

    // Check response length (should be substantial)
    if (response.length > 500) {
      relevance += 30;
    }
    if (response.length > 1000) {
      relevance += 20;
    }

    // Check for key terms from the task
    const taskWords = scenario.task.toLowerCase().split(/\s+/);
    const responseWords = response.toLowerCase();
    let matchedWords = 0;
    for (const word of taskWords) {
      if (word.length > 4 && responseWords.includes(word)) {
        matchedWords++;
      }
    }
    const wordMatchRate = matchedWords / taskWords.filter((w) => w.length > 4).length;
    relevance += wordMatchRate * 50;

    correctness = Math.min(100, correctness);
    completeness = Math.min(100, completeness);
    relevance = Math.min(100, relevance);

    const score = (correctness + completeness + relevance) / 3;

    return {
      score: Math.round(score),
      correctness: Math.round(correctness),
      completeness: Math.round(completeness),
      relevance: Math.round(relevance),
      notes: 'Automated scoring - manual review recommended',
    };
  }

  /**
   * Run all benchmarks
   */
  async runAll(basePath: string): Promise<BenchmarkResult[]> {
    const results: BenchmarkResult[] = [];

    for (const scenario of scenarios) {
      for (const strategy of strategies.filter((s) => s.enabled)) {
        const result = await this.runBenchmark(scenario, strategy, basePath);
        results.push(result);
        this.results.push(result);

        // Wait between requests to avoid rate limiting
        await new Promise((resolve) => setTimeout(resolve, 2000));
      }
    }

    return results;
  }

  /**
   * Get all results
   */
  getResults(): BenchmarkResult[] {
    return this.results;
  }
}

/**
 * KV Cache optimization hints for providers
 * Helps models optimize their key-value cache for long contexts
 */

export interface KVCacheHints {
  // Cache structure hints
  cacheLayers: 'full' | 'selective' | 'adaptive';

  // Attention patterns
  attentionPattern: 'full' | 'sparse' | 'local' | 'sliding-window';
  attentionWindow?: number; // for local/sliding-window

  // Cache retention
  retentionStrategy: 'fifo' | 'lru' | 'importance-based';
  maxCacheSize?: number; // tokens

  // Prefill optimization
  prefillOptimization: boolean;
  chunkPrefill: boolean;
  chunkSize?: number;

  // Eviction policy
  evictionPolicy: {
    strategy: 'age' | 'frequency' | 'importance' | 'hybrid';
    threshold: number;
  };
}

export interface CacheSegment {
  id: string;
  tokens: number;
  accessCount: number;
  lastAccess: number;
  importance: number;
  isEvictable: boolean;
}

export class KVCacheOptimizer {
  private hints: KVCacheHints;
  private cacheSegments: Map<string, CacheSegment> = new Map();
  private totalCached = 0;

  constructor(hints: Partial<KVCacheHints> = {}) {
    this.hints = {
      cacheLayers: hints.cacheLayers ?? 'adaptive',
      attentionPattern: hints.attentionPattern ?? 'sliding-window',
      attentionWindow: hints.attentionWindow ?? 8192,
      retentionStrategy: hints.retentionStrategy ?? 'importance-based',
      maxCacheSize: hints.maxCacheSize ?? 300000,
      prefillOptimization: hints.prefillOptimization ?? true,
      chunkPrefill: hints.chunkPrefill ?? true,
      chunkSize: hints.chunkSize ?? 2048,
      evictionPolicy: hints.evictionPolicy ?? {
        strategy: 'hybrid',
        threshold: 0.9,
      },
    };
  }

  /**
   * Generate cache hints for provider API
   */
  generateHints(): Record<string, unknown> {
    return {
      // OpenAI-style cache hints
      cache_control: {
        type: this.hints.cacheLayers,
        max_tokens: this.hints.maxCacheSize,
      },

      // Anthropic-style cache hints
      cache_hints: {
        retention: this.hints.retentionStrategy,
        pattern: this.hints.attentionPattern,
      },

      // Generic hints
      optimization: {
        prefill: this.hints.prefillOptimization,
        chunked: this.hints.chunkPrefill,
        chunk_size: this.hints.chunkSize,
      },
    };
  }

  /**
   * Add content to cache tracking
   */
  trackCacheSegment(id: string, tokens: number, importance: number): void {
    const segment: CacheSegment = {
      id,
      tokens,
      accessCount: 1,
      lastAccess: Date.now(),
      importance,
      isEvictable: importance < 0.7,
    };

    this.cacheSegments.set(id, segment);
    this.totalCached += tokens;

    // Check if eviction needed
    if (this.hints.maxCacheSize && this.totalCached > this.hints.maxCacheSize * 0.9) {
      this.evictSegments();
    }
  }

  /**
   * Update access for cache segment
   */
  accessSegment(id: string): void {
    const segment = this.cacheSegments.get(id);
    if (segment) {
      segment.accessCount++;
      segment.lastAccess = Date.now();
    }
  }

  /**
   * Evict cache segments based on policy
   */
  private evictSegments(): void {
    const segments = Array.from(this.cacheSegments.values());
    const targetSize = this.hints.maxCacheSize! * this.hints.evictionPolicy.threshold;

    // Sort by eviction priority
    const sortedSegments = segments.sort((a, b) => {
      return this.calculateEvictionPriority(a) - this.calculateEvictionPriority(b);
    });

    let currentSize = this.totalCached;

    for (const segment of sortedSegments) {
      if (currentSize <= targetSize || !segment.isEvictable) {
        break;
      }

      this.cacheSegments.delete(segment.id);
      currentSize -= segment.tokens;
    }

    this.totalCached = currentSize;
  }

  /**
   * Calculate eviction priority (lower = evict first)
   */
  private calculateEvictionPriority(segment: CacheSegment): number {
    const strategy = this.hints.evictionPolicy.strategy;

    switch (strategy) {
      case 'age': {
        const age = Date.now() - segment.lastAccess;
        return -age; // older = lower priority
      }

      case 'frequency':
        return segment.accessCount;

      case 'importance':
        return segment.importance;

      case 'hybrid': {
        const age = Date.now() - segment.lastAccess;
        const ageScore = Math.exp(-age / 60000); // decay over time
        const freqScore = Math.log(segment.accessCount + 1);
        return segment.importance * 0.5 + ageScore * 0.3 + freqScore * 0.2;
      }

      default:
        return segment.importance;
    }
  }

  /**
   * Get cache statistics
   */
  getCacheStats() {
    const segments = Array.from(this.cacheSegments.values());

    return {
      totalSegments: segments.length,
      totalTokens: this.totalCached,
      maxSize: this.hints.maxCacheSize,
      utilization: this.hints.maxCacheSize ? this.totalCached / this.hints.maxCacheSize : 0,
      evictableSegments: segments.filter(s => s.isEvictable).length,
      averageImportance: segments.reduce((sum, s) => sum + s.importance, 0) / segments.length,
      averageAccess: segments.reduce((sum, s) => sum + s.accessCount, 0) / segments.length,
    };
  }

  /**
   * Get hints for specific provider
   */
  getProviderHints(provider: 'openai' | 'anthropic' | 'grok'): Record<string, unknown> {
    switch (provider) {
      case 'openai':
        return {
          // GPT-4 cache hints
          max_tokens: this.hints.maxCacheSize,
          stream: true,
          stream_options: {
            include_usage: true,
          },
        };

      case 'anthropic':
        return {
          // Claude cache control
          system: [
            {
              type: 'text',
              text: '<!-- System prompt -->',
              cache_control: { type: 'ephemeral' },
            },
          ],
          max_tokens: this.hints.maxCacheSize,
        };

      case 'grok':
        return {
          // Grok-specific hints
          context_window: this.hints.maxCacheSize,
          attention_pattern: this.hints.attentionPattern,
        };

      default:
        return this.generateHints();
    }
  }
}

/**
 * Memory-efficient streaming helper
 */
export class StreamingOptimizer {
  private bufferSize: number;
  private currentBuffer: string[] = [];

  constructor(bufferSize = 1000) {
    this.bufferSize = bufferSize;
  }

  /**
   * Process streaming chunks efficiently
   */
  async* processStream(
    stream: AsyncIterable<string>,
    onChunk?: (chunk: string) => void
  ): AsyncGenerator<string> {
    for await (const chunk of stream) {
      this.currentBuffer.push(chunk);

      if (onChunk) {
        onChunk(chunk);
      }

      // Flush buffer if too large
      if (this.currentBuffer.length >= this.bufferSize) {
        const combined = this.currentBuffer.join('');
        this.currentBuffer = [];
        yield combined;
      } else {
        yield chunk;
      }
    }

    // Flush remaining buffer
    if (this.currentBuffer.length > 0) {
      yield this.currentBuffer.join('');
      this.currentBuffer = [];
    }
  }

  /**
   * Estimate memory usage
   */
  getMemoryUsage(): number {
    const bufferSize = this.currentBuffer.reduce((sum, s) => sum + s.length, 0);
    return bufferSize * 2; // UTF-16, roughly 2 bytes per char
  }
}

