/**
 * OpenAI adapter
 */
class OpenAIAdapter implements ProviderAdapter {
  name = 'openai';
  model: string;
  contextWindow: any;
  private client: OpenAI;

  constructor(apiKey: string, model: string, contextWindow: any) {
    this.client = new OpenAI({ apiKey });
    this.model = model;
    this.contextWindow = contextWindow;
  }

  async execute(prompt: string, options: any) {
    const startTime = Date.now();
    let firstTokenTime = 0;

    const messages: any[] = [];
    if (options.systemPrompt) {
      messages.push({ role: 'system', content: options.systemPrompt });
    }
    messages.push({ role: 'user', content: prompt });

    const response = await this.client.chat.completions.create({
      model: this.model,
      messages,
      max_tokens: options.maxTokens || 4096,
      temperature: options.temperature || 0.7,
      stream: false,
    });

    const endTime = Date.now();

    return {
      output: response.choices[0]?.message?.content || '',
      usage: {
        inputTokens: response.usage?.prompt_tokens || 0,
        outputTokens: response.usage?.completion_tokens || 0,
      },
      latency: {
        firstToken: firstTokenTime || endTime - startTime,
        total: endTime - startTime,
      },
    };
  }
}

/**
 * Anthropic adapter
 */
class AnthropicAdapter implements ProviderAdapter {
  name = 'anthropic';
  model: string;
  contextWindow: any;
  private client: Anthropic;

  constructor(apiKey: string, model: string, contextWindow: any) {
    this.client = new Anthropic({ apiKey });
    this.model = model;
    this.contextWindow = contextWindow;
  }

  async execute(prompt: string, options: any) {
    const startTime = Date.now();
    let firstTokenTime = 0;

    const response = await this.client.messages.create({
      model: this.model,
      max_tokens: options.maxTokens || 4096,
      temperature: options.temperature || 0.7,
      system: options.systemPrompt || undefined,
      messages: [
        { role: 'user', content: prompt },
      ],
    });

    const endTime = Date.now();

    const content = response.content[0];
    const output = content.type === 'text' ? content.text : '';

    return {
      output,
      usage: {
        inputTokens: response.usage.input_tokens,
        outputTokens: response.usage.output_tokens,
      },
      latency: {
        firstToken: firstTokenTime || endTime - startTime,
        total: endTime - startTime,
      },
    };
  }
}

/**
 * Main execution
 */
async function main() {
  console.log('🚀 Terminal Bench 3.0 - FrontierBench Compatible Benchmarking\n');

  // Validate API keys
  if (!process.env.OPENAI_API_KEY && !process.env.ANTHROPIC_API_KEY) {
    console.error('❌ Error: No API keys found');
    console.error('   Set OPENAI_API_KEY or ANTHROPIC_API_KEY environment variables\n');
    process.exit(1);
  }

  // Create runner
  const runner = new TerminalBenchRunner(config);

  // Register available providers
  if (process.env.OPENAI_API_KEY) {
    const openai = new OpenAIAdapter(
      process.env.OPENAI_API_KEY,
      config.providers[0].model,
      config.providers[0].contextWindow
    );
    runner.registerProvider(openai);
    console.log('✓ Registered OpenAI provider');
  }

  if (process.env.ANTHROPIC_API_KEY) {
    const anthropic = new AnthropicAdapter(
      process.env.ANTHROPIC_API_KEY,
      config.providers[1].model,
      config.providers[1].contextWindow
    );
    runner.registerProvider(anthropic);
    console.log('✓ Registered Anthropic provider');
  }

  console.log('');

  try {
    // Run benchmarks
    const results = await runner.runAll({
      config,
      outputDir: config.reporting.outputDir,
      verbose: true,
    });

    // Generate reports
    console.log('');
    BenchmarkReporter.generateReports(results, config, {
      outputDir: config.reporting.outputDir,
      formats: config.reporting.formats as any,
      includeCharts: config.reporting.includeVisualizations,
      includeDetails: true,
    });

    console.log('\n✅ Benchmark completed successfully!');
    console.log(`\n📊 View results:`);
    console.log(`   HTML: ${config.reporting.outputDir}/benchmark-results.html`);
    console.log(`   JSON: ${config.reporting.outputDir}/benchmark-results.json`);
    console.log(`   Markdown: ${config.reporting.outputDir}/benchmark-results.md`);
    console.log(`   CSV: ${config.reporting.outputDir}/benchmark-results.csv\n`);

  } catch (error) {
    console.error('\n❌ Benchmark failed:', error);
    process.exit(1);
  }
}

main().catch(console.error);

/**
 * Metrics collection and calculation for benchmarks
 */

import type { BenchmarkMetrics, BenchmarkResult } from '../types.js';

export interface MetricsCollector {
  startTime: number;
  endTime?: number;
  firstTokenTime?: number;
  tokensGenerated: number;
  inputTokens: number;
  outputTokens: number;
  estimatedCost: number;
}

/**
 * Calculate benchmark metrics from collected data
 */
export class MetricsCalculator {
  /**
   * Calculate complete benchmark metrics
   */
  static calculate(
    collector: MetricsCollector,
    output: string,
    expected: any,
    contextWindow: { maxInput: number; maxOutput: number; utilized: number }
  ): BenchmarkMetrics {
    const duration = (collector.endTime || Date.now()) - collector.startTime;
    const firstTokenLatency = collector.firstTokenTime 
      ? collector.firstTokenTime - collector.startTime 
      : duration;

    const accuracy = this.calculateAccuracy(output, expected);
    const latency = this.calculateLatency(duration, firstTokenLatency, collector.tokensGenerated);
    const tokenEfficiency = this.calculateTokenEfficiency(
      collector.inputTokens,
      collector.outputTokens,
      contextWindow
    );
    const contextRetention = this.calculateContextRetention(output, expected);
    const cost = this.calculateCost(collector.inputTokens, collector.outputTokens, collector.estimatedCost);
    const qualityScore = this.calculateQualityScore(output, expected);
    const reasoning = this.analyzeReasoning(output);

    return {
      accuracy,
      latency,
      tokenEfficiency,
      contextRetention,
      cost,
      qualityScore,
      followsInstructions: accuracy > 0.8,
      hallucinations: this.detectHallucinations(output),
      reasoning,
    };
  }

  /**
   * Calculate accuracy score
   */
  private static calculateAccuracy(output: string, expected: any): number {
    let score = 0;
    let checks = 0;

    // Pattern matching
    if (expected.pattern) {
      checks++;
      const regex = new RegExp(expected.pattern, 'i');
      if (regex.test(output)) {
        score += 1;
      }
    }

    // Contains checks
    if (expected.contains && Array.isArray(expected.contains)) {
      checks += expected.contains.length;
      for (const text of expected.contains) {
        if (output.toLowerCase().includes(text.toLowerCase())) {
          score += 1;
        }
      }
    }

    // Excludes checks
    if (expected.excludes && Array.isArray(expected.excludes)) {
      checks += expected.excludes.length;
      for (const text of expected.excludes) {
        if (!output.toLowerCase().includes(text.toLowerCase())) {
          score += 1;
        }
      }
    }

    // Code executable check (simplified)
    if (expected.codeExecutable) {
      checks++;
      if (this.looksLikeValidCode(output)) {
        score += 1;
      }
    }

    // Valid JSON check
    if (expected.validJson) {
      checks++;
      try {
        JSON.parse(output);
        score += 1;
      } catch {
        // Invalid JSON
      }
    }

    return checks > 0 ? score / checks : 0;
  }

  /**
   * Calculate latency metrics
   */
  private static calculateLatency(
    duration: number,
    firstTokenLatency: number,
    tokensGenerated: number
  ) {
    return {
      firstToken: firstTokenLatency,
      totalGeneration: duration,
      tokensPerSecond: tokensGenerated / (duration / 1000),
    };
  }

  /**
   * Calculate token efficiency
   */
  private static calculateTokenEfficiency(
    inputTokens: number,
    outputTokens: number,
    contextWindow: { maxInput: number; maxOutput: number; utilized: number }
  ) {
    const totalTokens = inputTokens + outputTokens;

    // Estimate wasted tokens (simplified heuristic)
    const wastedTokens = this.estimateWastedTokens(inputTokens);

    // Compression ratio: actual tokens used vs potential max
    const potentialMax = contextWindow.maxInput + contextWindow.maxOutput;
    const compressionRatio = totalTokens / potentialMax;

    return {
      inputTokens,
      outputTokens,
      totalTokens,
      wastedTokens,
      compressionRatio,
    };
  }

  /**
   * Calculate context retention scores
   */
  private static calculateContextRetention(output: string, expected: any) {
    // Simplified context retention calculation
    // In practice, would use markers placed at different context positions

    const hasEarlyContext = output.includes('early') || output.includes('first') || output.includes('beginning');
    const hasMiddleContext = output.includes('middle') || output.includes('center');
    const hasLateContext = output.includes('late') || output.includes('end') || output.includes('final');

    const earlyScore = hasEarlyContext ? 0.8 : 0.3;
    const middleScore = hasMiddleContext ? 0.7 : 0.4;
    const lateScore = hasLateContext ? 0.9 : 0.5; // Late context usually better retained

    return {
      earlyContext: earlyScore,
      middleContext: middleScore,
      lateContext: lateScore,
      overallRetention: (earlyScore + middleScore + lateScore) / 3,
    };
  }

  /**
   * Calculate cost
   */
  private static calculateCost(inputTokens: number, outputTokens: number, estimatedCost: number) {
    // Typical pricing (rough estimates, adjust per provider)
    const inputCostPer1k = 0.03; // $0.03 per 1k tokens
    const outputCostPer1k = 0.06; // $0.06 per 1k tokens

    const inputCost = (inputTokens / 1000) * inputCostPer1k;
    const outputCost = (outputTokens / 1000) * outputCostPer1k;
    const totalCost = inputCost + outputCost;

    return {
      inputCost,
      outputCost,
      totalCost: estimatedCost || totalCost,
      costPerAccuracyPoint: 0, // Will be filled by caller
    };
  }

  /**
   * Calculate overall quality score
   */
  private static calculateQualityScore(output: string, expected: any): number {
    let score = 0;

    // Length appropriateness (not too short, not excessively long)
    const length = output.length;
    if (length > 100 && length < 50000) {
      score += 20;
    } else if (length >= 50 && length <= 100000) {
      score += 10;
    }

    // Code quality indicators
    if (this.looksLikeValidCode(output)) {
      if (output.includes('function') || output.includes('class')) score += 15;
      if (output.includes('try') || output.includes('catch')) score += 10;
      if (output.includes('//') || output.includes('/*')) score += 10;
      if (output.includes('interface') || output.includes('type')) score += 10;
    }

    // Structure and formatting
    if (output.includes('\n\n')) score += 5; // Paragraphs
    if (output.includes('```')) score += 10; // Code blocks
    if (output.includes('##') || output.includes('**')) score += 5; // Formatting

    // Completeness
    if (output.length > 500) score += 10;
    if (output.length > 2000) score += 10;

    return Math.min(100, score);
  }

  /**
   * Analyze reasoning quality
   */
  private static analyzeReasoning(output: string) {
    const hasCoT = output.includes('step') || output.includes('first') || output.includes('then');

    // Check logical consistency (simplified)
    const hasConclusion = output.includes('therefore') || output.includes('thus') || output.includes('so');
    const hasPremises = output.includes('because') || output.includes('since') || output.includes('given');
    const logicalConsistency = (hasConclusion && hasPremises) ? 0.8 : 0.5;

    // Analyze depth
    let depth: 'shallow' | 'medium' | 'deep' = 'shallow';
    if (output.split('\n').length > 20 || output.length > 2000) {
      depth = 'deep';
    } else if (output.split('\n').length > 10 || output.length > 1000) {
      depth = 'medium';
    }

    return {
      chainOfThought: hasCoT,
      logicalConsistency,
      depth,
    };
  }

  /**
   * Detect potential hallucinations
   */
  private static detectHallucinations(output: string): number {
    let count = 0;

    // Check for suspicious patterns
    const suspiciousPatterns = [
      /as an ai/i,
      /i don't have access/i,
      /i cannot/i,
      /\[placeholder\]/i,
      /\[todo\]/i,
      /xxx/i,
    ];

    for (const pattern of suspiciousPatterns) {
      if (pattern.test(output)) {
        count++;
      }
    }

    return count;
  }

  /**
   * Check if output looks like valid code
   */
  private static looksLikeValidCode(output: string): boolean {
    const codeIndicators = [
      /function\s+\w+/,
      /class\s+\w+/,
      /const\s+\w+\s*=/,
      /let\s+\w+\s*=/,
      /var\s+\w+\s*=/,
      /import\s+.*from/,
      /export\s+(default|const|function|class)/,
    ];

    return codeIndicators.some(pattern => pattern.test(output));
  }

  /**
   * Estimate wasted tokens (heuristic)
   */
  private static estimateWastedTokens(inputTokens: number): number {
    // Rough estimate: 5-10% of tokens might be non-essential (whitespace, redundancy)
    return Math.floor(inputTokens * 0.075);
  }
}

/**
 * Aggregate metrics across multiple results
 */
export class MetricsAggregator {
  /**
   * Aggregate results by provider
   */
  static aggregateByProvider(results: BenchmarkResult[]): Map<string, any> {
    const byProvider = new Map<string, BenchmarkResult[]>();

    for (const result of results) {
      const key = `${result.provider}:${result.model}`;
      if (!byProvider.has(key)) {
        byProvider.set(key, []);
      }
      byProvider.get(key)!.push(result);
    }

    const aggregated = new Map<string, any>();

    for (const [key, providerResults] of byProvider) {
      aggregated.set(key, {
        totalTests: providerResults.length,
        successRate: providerResults.filter(r => r.status === 'success').length / providerResults.length,
        averageAccuracy: this.average(providerResults.map(r => r.metrics.accuracy)),
        averageLatency: this.average(providerResults.map(r => r.metrics.latency.totalGeneration)),
        averageTokensPerSecond: this.average(providerResults.map(r => r.metrics.latency.tokensPerSecond)),
        totalCost: this.sum(providerResults.map(r => r.metrics.cost.totalCost)),
        averageQuality: this.average(providerResults.map(r => r.metrics.qualityScore)),
        contextRetention: {
          early: this.average(providerResults.map(r => r.metrics.contextRetention.earlyContext)),
          middle: this.average(providerResults.map(r => r.metrics.contextRetention.middleContext)),
          late: this.average(providerResults.map(r => r.metrics.contextRetention.lateContext)),
          overall: this.average(providerResults.map(r => r.metrics.contextRetention.overallRetention)),
        },
      });
    }

    return aggregated;
  }

  /**
   * Compare providers
   */
  static compareProviders(results: BenchmarkResult[]): any {
    const byProvider = this.aggregateByProvider(results);
    const comparison: any = {};

    for (const [provider, metrics] of byProvider) {
      comparison[provider] = metrics;
    }

    return comparison;
  }

  private static average(numbers: number[]): number {
    if (numbers.length === 0) return 0;
    return numbers.reduce((sum, n) => sum + n, 0) / numbers.length;
  }

  private static sum(numbers: number[]): number {
    return numbers.reduce((sum, n) => sum + n, 0);
  }
}

/**
 * Multi-agent task decomposition and coordination
 */

export interface SubTask {
  id: string;
  name: string;
  description: string;
  prompt: string;
  dependencies: string[]; // IDs of other subtasks
  estimatedTokens: number;
  priority: number;
  canParallelize: boolean;
  status: 'pending' | 'running' | 'completed' | 'failed';
  assignedAgent?: string;
  result?: unknown;
  error?: string;
}

export interface TaskDecompositionResult {
  originalTask: string;
  subtasks: SubTask[];
  executionPlan: {
    phases: Array<{
      phase: number;
      subtasks: string[]; // IDs
      canParallelize: boolean;
    }>;
    estimatedDuration: number;
    estimatedTokens: number;
  };
}

export interface AgentHandoff {
  fromAgent: string;
  toAgent: string;
  subtaskId: string;
  context: 'minimal' | 'summary' | 'full';
  sharedData: unknown;
  timestamp: number;
}

/**
 * Task decomposer - breaks complex tasks into manageable subtasks
 */
export class TaskDecomposer {
  /**
   * Decompose a complex task into subtasks
   */
  decompose(task: string, context: string): TaskDecompositionResult {
    const subtasks = this.identifySubtasks(task, context);
    const executionPlan = this.createExecutionPlan(subtasks);

    return {
      originalTask: task,
      subtasks,
      executionPlan,
    };
  }

  /**
   * Identify subtasks from task description
   */
  private identifySubtasks(task: string, context: string): SubTask[] {
    const subtasks: SubTask[] = [];

    // Analyze task complexity
    const complexity = this.analyzeComplexity(task, context);

    if (complexity === 'simple') {
      // Single subtask
      subtasks.push({
        id: 'task-1',
        name: 'Complete Task',
        description: task,
        prompt: task,
        dependencies: [],
        estimatedTokens: this.estimateTokens(task + context),
        priority: 1,
        canParallelize: false,
        status: 'pending',
      });
    } else if (complexity === 'medium') {
      // 2-3 subtasks
      subtasks.push(
        {
          id: 'task-1',
          name: 'Analyze & Plan',
          description: 'Analyze requirements and create implementation plan',
          prompt: `Analyze the following task and create a detailed plan:\n${task}`,
          dependencies: [],
          estimatedTokens: 5000,
          priority: 1,
          canParallelize: false,
          status: 'pending',
        },
        {
          id: 'task-2',
          name: 'Implement',
          description: 'Implement the solution according to plan',
          prompt: 'Implement the solution based on the analysis',
          dependencies: ['task-1'],
          estimatedTokens: 15000,
          priority: 2,
          canParallelize: false,
          status: 'pending',
        },
        {
          id: 'task-3',
          name: 'Test & Verify',
          description: 'Test implementation and verify correctness',
          prompt: 'Test the implementation and verify it meets requirements',
          dependencies: ['task-2'],
          estimatedTokens: 8000,
          priority: 3,
          canParallelize: false,
          status: 'pending',
        }
      );
    } else {
      // Complex: 4+ subtasks with potential parallelization
      subtasks.push(
        {
          id: 'task-1',
          name: 'Requirements Analysis',
          description: 'Deep analysis of requirements and constraints',
          prompt: `Perform deep requirements analysis:\n${task}`,
          dependencies: [],
          estimatedTokens: 10000,
          priority: 1,
          canParallelize: false,
          status: 'pending',
        },
        {
          id: 'task-2',
          name: 'Architecture Design',
          description: 'Design system architecture',
          prompt: 'Design the system architecture based on requirements',
          dependencies: ['task-1'],
          estimatedTokens: 12000,
          priority: 2,
          canParallelize: false,
          status: 'pending',
        },
        {
          id: 'task-3a',
          name: 'Implement Core',
          description: 'Implement core functionality',
          prompt: 'Implement core system components',
          dependencies: ['task-2'],
          estimatedTokens: 20000,
          priority: 3,
          canParallelize: true,
          status: 'pending',
        },
        {
          id: 'task-3b',
          name: 'Implement Features',
          description: 'Implement additional features',
          prompt: 'Implement additional features',
          dependencies: ['task-2'],
          estimatedTokens: 18000,
          priority: 3,
          canParallelize: true,
          status: 'pending',
        },
        {
          id: 'task-4',
          name: 'Integration',
          description: 'Integrate all components',
          prompt: 'Integrate all components and ensure they work together',
          dependencies: ['task-3a', 'task-3b'],
          estimatedTokens: 10000,
          priority: 4,
          canParallelize: false,
          status: 'pending',
        },
        {
          id: 'task-5',
          name: 'Testing & Validation',
          description: 'Comprehensive testing and validation',
          prompt: 'Perform comprehensive testing and validation',
          dependencies: ['task-4'],
          estimatedTokens: 12000,
          priority: 5,
          canParallelize: false,
          status: 'pending',
        }
      );
    }

    return subtasks;
  }

  /**
   * Create execution plan with phases
   */
  private createExecutionPlan(subtasks: SubTask[]) {
    const phases: Array<{ phase: number; subtasks: string[]; canParallelize: boolean }> = [];
    const completed = new Set<string>();
    let phase = 1;

    while (completed.size < subtasks.length) {
      const readyTasks = subtasks.filter(
        (t) =>
          t.status === 'pending' &&
          !completed.has(t.id) &&
          t.dependencies.every((dep) => completed.has(dep))
      );

      if (readyTasks.length === 0) break;

      const canParallelize = readyTasks.every((t) => t.canParallelize) && readyTasks.length > 1;

      phases.push({
        phase,
        subtasks: readyTasks.map((t) => t.id),
        canParallelize,
      });

      readyTasks.forEach((t) => completed.add(t.id));
      phase++;
    }

    const estimatedTokens = subtasks.reduce((sum, t) => sum + t.estimatedTokens, 0);
    const estimatedDuration = phases.reduce((sum, p) => {
      const phaseTasks = subtasks.filter((t) => p.subtasks.includes(t.id));
      const maxTokens = Math.max(...phaseTasks.map((t) => t.estimatedTokens));
      return sum + maxTokens / 1000; // rough estimate: 1000 tokens/sec
    }, 0);

    return {
      phases,
      estimatedDuration,
      estimatedTokens,
    };
  }

  /**
   * Analyze task complexity
   */
  private analyzeComplexity(task: string, context: string): 'simple' | 'medium' | 'complex' {
    const totalLength = task.length + context.length;

    // Keyword-based complexity hints
    const complexityKeywords = {
      high: ['architect', 'design', 'system', 'multiple', 'integrate', 'refactor'],
      medium: ['implement', 'create', 'build', 'add', 'update'],
      low: ['fix', 'debug', 'change', 'modify'],
    };

    const taskLower = task.toLowerCase();

    let complexityScore = 0;
    complexityKeywords.high.forEach((kw) => {
      if (taskLower.includes(kw)) complexityScore += 3;
    });
    complexityKeywords.medium.forEach((kw) => {
      if (taskLower.includes(kw)) complexityScore += 2;
    });
    complexityKeywords.low.forEach((kw) => {
      if (taskLower.includes(kw)) complexityScore += 1;
    });

    // Length factor
    if (totalLength > 50000) complexityScore += 2;
    else if (totalLength > 20000) complexityScore += 1;

    if (complexityScore >= 6) return 'complex';
    if (complexityScore >= 3) return 'medium';
    return 'simple';
  }

  private estimateTokens(text: string): number {
    return Math.ceil(text.length / 4);
  }
}

/**
 * Agent coordinator - manages multi-agent execution
 */
export class AgentCoordinator {
  private agents: Map<string, { status: 'idle' | 'busy'; currentTask?: string }> = new Map();
  private handoffs: AgentHandoff[] = [];
  private sharedContext: Map<string, unknown> = new Map();

  constructor(agentIds: string[]) {
    agentIds.forEach((id) => {
      this.agents.set(id, { status: 'idle' });
    });
  }

  /**
   * Execute decomposed task with multiple agents
   */
  async executeTask(
    decomposition: TaskDecompositionResult,
    executor: (subtask: SubTask, context: unknown) => Promise<unknown>
  ): Promise<Map<string, unknown>> {
    const results = new Map<string, unknown>();

    for (const phase of decomposition.executionPlan.phases) {
      if (phase.canParallelize) {
        // Execute subtasks in parallel
        const phaseResults = await Promise.all(
          phase.subtasks.map(async (subtaskId) => {
            const subtask = decomposition.subtasks.find((t) => t.id === subtaskId)!;
            const agent = this.assignAgent(subtaskId);

            const context = this.prepareContext(subtask, results);
            const result = await executor(subtask, context);

            this.releaseAgent(agent);
            return { subtaskId, result };
          })
        );

        phaseResults.forEach(({ subtaskId, result }) => {
          results.set(subtaskId, result);
        });
      } else {
        // Execute subtasks sequentially
        for (const subtaskId of phase.subtasks) {
          const subtask = decomposition.subtasks.find((t) => t.id === subtaskId)!;
          const agent = this.assignAgent(subtaskId);

          const context = this.prepareContext(subtask, results);
          const result = await executor(subtask, context);

          results.set(subtaskId, result);
          this.releaseAgent(agent);
        }
      }
    }

    return results;
  }

  /**
   * Assign an idle agent to a subtask
   */
  private assignAgent(subtaskId: string): string {
    for (const [agentId, state] of this.agents) {
      if (state.status === 'idle') {
        state.status = 'busy';
        state.currentTask = subtaskId;
        return agentId;
      }
    }

    // If no idle agent, wait for one
    return 'agent-0'; // fallback
  }

  /**
   * Release agent after task completion
   */
  private releaseAgent(agentId: string): void {
    const agent = this.agents.get(agentId);
    if (agent) {
      agent.status = 'idle';
      agent.currentTask = undefined;
    }
  }

  /**
   * Prepare context for subtask execution
   */
  private prepareContext(subtask: SubTask, results: Map<string, unknown>): unknown {
    const context: Record<string, unknown> = {};

    // Include results from dependencies
    for (const depId of subtask.dependencies) {
      const depResult = results.get(depId);
      if (depResult) {
        context[depId] = depResult;
      }
    }

    // Include shared context
    for (const [key, value] of this.sharedContext) {
      context[key] = value;
    }

    return context;
  }

  /**
   * Create handoff between agents
   */
  createHandoff(
    fromAgent: string,
    toAgent: string,
    subtaskId: string,
    contextType: 'minimal' | 'summary' | 'full',
    data: unknown
  ): AgentHandoff {
    const handoff: AgentHandoff = {
      fromAgent,
      toAgent,
      subtaskId,
      context: contextType,
      sharedData: data,
      timestamp: Date.now(),
    };

    this.handoffs.push(handoff);
    return handoff;
  }

  /**
   * Get efficient context for handoff
   */
  getHandoffContext(handoff: AgentHandoff): string {
    switch (handoff.context) {
      case 'minimal':
        return `Subtask: ${handoff.subtaskId}\nData: ${JSON.stringify(handoff.sharedData).substring(0, 200)}...`;

      case 'summary':
        return `Subtask: ${handoff.subtaskId}\nSummary: ${this.summarizeData(handoff.sharedData)}`;

      case 'full':
        return `Subtask: ${handoff.subtaskId}\nFull context: ${JSON.stringify(handoff.sharedData, null, 2)}`;

      default:
        return '';
    }
  }

  /**
   * Summarize data for handoff
   */
  private summarizeData(data: unknown): string {
    if (typeof data === 'string') {
      return data.length > 500 ? data.substring(0, 500) + '...' : data;
    }

    const json = JSON.stringify(data);
    return json.length > 500 ? json.substring(0, 500) + '...' : json;
  }

  /**
   * Get coordination statistics
   */
  getStats() {
    return {
      totalAgents: this.agents.size,
      busyAgents: Array.from(this.agents.values()).filter((a) => a.status === 'busy').length,
      totalHandoffs: this.handoffs.length,
      sharedContextSize: this.sharedContext.size,
    };
  }
}

