/**
 * Prompt builder with optimizations
 */
export class PromptBuilder {
  private systemPrompt = '';
  private userPrompt = '';
  private enableCoT = false;
  private enableFewShot = false;
  private enableStructured = false;
  private outputSchema?: object;

  /**
   * Set system prompt
   */
  system(prompt: string | keyof typeof SYSTEM_PROMPTS): this {
    if (typeof prompt === 'string') {
      this.systemPrompt = prompt;
    } else {
      this.systemPrompt = SYSTEM_PROMPTS[prompt];
    }
    return this;
  }

  /**
   * Set user prompt
   */
  user(prompt: string): this {
    this.userPrompt = prompt;
    return this;
  }

  /**
   * Enable chain-of-thought
   */
  withChainOfThought(template?: string): this {
    this.enableCoT = true;
    if (template) {
      this.userPrompt = template + '\n\n' + this.userPrompt;
    }
    return this;
  }

  /**
   * Add few-shot examples
   */
  withFewShot(examples: string | keyof typeof FEW_SHOT_EXAMPLES): this {
    this.enableFewShot = true;
    const exampleText = typeof examples === 'string' 
      ? examples 
      : FEW_SHOT_EXAMPLES[examples];
    this.systemPrompt += '\n\n**Examples:**\n' + exampleText;
    return this;
  }

  /**
   * Enable structured output
   */
  withStructuredOutput(schema: object | keyof typeof OUTPUT_SCHEMAS): this {
    this.enableStructured = true;
    this.outputSchema = typeof schema === 'object' 
      ? schema 
      : OUTPUT_SCHEMAS[schema];
    return this;
  }

  /**
   * Add tool use instructions
   */
  withToolUse(): this {
    this.systemPrompt += '\n\n' + TOOL_USE_INSTRUCTIONS;
    return this;
  }

  /**
   * Build final prompts
   */
  build(): { system: string; user: string; schema?: object } {
    return {
      system: this.systemPrompt,
      user: this.userPrompt,
      schema: this.outputSchema,
    };
  }
}

