import type { BenchmarkResult, FrontierBenchConfig } from '../types.js';
import { MetricsAggregator } from '../metrics/calculator.js';
import { writeFileSync, mkdirSync } from 'fs';
import { join } from 'path';

export interface ReportOptions {
  outputDir: string;
  formats: Array<'json' | 'html' | 'markdown' | 'csv'>;
  includeCharts: boolean;
  includeDetails: boolean;
}

export class BenchmarkReporter {
  /**
   * Generate all reports
   */
  static generateReports(
    results: BenchmarkResult[],
    config: FrontierBenchConfig,
    options: ReportOptions
  ): void {
    // Ensure output directory exists
    mkdirSync(options.outputDir, { recursive: true });

    console.log(`\n📝 Generating reports in ${options.outputDir}`);

    // Generate each format
    if (options.formats.includes('json')) {
      this.generateJSON(results, config, options);
    }

    if (options.formats.includes('markdown')) {
      this.generateMarkdown(results, config, options);
    }

    if (options.formats.includes('html')) {
      this.generateHTML(results, config, options);
    }

    if (options.formats.includes('csv')) {
      this.generateCSV(results, config, options);
    }

    console.log(`✅ Reports generated`);
  }

  /**
   * Generate JSON report
   */
  private static generateJSON(
    results: BenchmarkResult[],
    config: FrontierBenchConfig,
    options: ReportOptions
  ): void {
    const report = {
      metadata: {
        version: config.version,
        timestamp: new Date().toISOString(),
        totalTests: results.length,
        providers: [...new Set(results.map(r => `${r.provider}:${r.model}`))],
      },
      summary: this.generateSummary(results),
      results: options.includeDetails ? results : undefined,
      aggregated: MetricsAggregator.compareProviders(results),
    };

    const path = join(options.outputDir, 'benchmark-results.json');
    writeFileSync(path, JSON.stringify(report, null, 2));
    console.log(`   ✓ JSON: ${path}`);
  }

