    md += `| Provider | Success Rate | Accuracy | Quality | Latency (s) | Cost ($) | Tokens/s |\n`;
    md += `|----------|-------------|----------|---------|-------------|----------|----------|\n`;

    for (const [provider, metrics] of Object.entries(aggregated)) {
      md += `| ${provider} `;
