      md += `| ${(retention.middle * 100).toFixed(1)}% `;
      md += `| ${(retention.late * 100).toFixed(1)}% `;
      md += `| ${(retention.overall * 100).toFixed(1)}% |\n`;
    }

    if (options.includeDetails) {
      md += `\n## Detailed Results\n\n`;

      for (const result of results) {
        md += `### ${result.scenarioName}\n\n`;
        md += `- **Provider:** ${result.provider}:${result.model}\n`;
