        md += `- **Cost:** $${result.metrics.cost.totalCost.toFixed(4)}\n\n`;
      }
    }

    const path = join(options.outputDir, 'benchmark-results.md');
    writeFileSync(path, md);
    console.log(`   ✓ Markdown: ${path}`);
  }

