      totalCost: results.reduce((sum, r) => sum + r.metrics.cost.totalCost, 0),
      averageQuality: successful.reduce((sum, r) => sum + r.metrics.qualityScore, 0) / successful.length,
    };
  }
}

/**
 * Terminal Bench 3.0 Benchmark Runner
 * Main entry point for FrontierBench-compatible benchmarking
 */

import type { 
  TestScenario, 
  BenchmarkResult, 
  FrontierBenchConfig,
  ContextWindow,
} from '../types.js';
import { ALL_SCENARIOS } from '../scenarios/index.js';
import { MetricsCalculator, MetricsCollector } from '../metrics/calculator.js';
import { ContextChunker } from '../context-optimizations/chunking.js';
import { ContextCompressor, AdaptiveCompressor } from '../context-optimizations/compression.js';
import { SlidingWindowManager } from '../context-optimizations/sliding-window.js';
import { KVCacheOptimizer } from '../context-optimizations/kv-cache.js';
import { PromptBuilder, PROMPT_PRESETS } from '../prompts/templates.js';
import { TaskDecomposer, AgentCoordinator } from '../multi-agent/coordinator.js';

export interface BenchmarkRunOptions {
  config: FrontierBenchConfig;
  scenarios?: string[]; // Scenario IDs to run (optional, defaults to all)
  outputDir?: string;
  verbose?: boolean;
}

export interface ProviderAdapter {
  name: string;
  model: string;
  contextWindow: ContextWindow;

  execute(prompt: string, options: {
    systemPrompt?: string;
    maxTokens?: number;
    temperature?: number;
    cacheHints?: Record<string, unknown>;
  }): Promise<{
    output: string;
    usage: { inputTokens: number; outputTokens: number };
    latency: { firstToken: number; total: number };
  }>;
}

export class TerminalBenchRunner {
  private config: FrontierBenchConfig;
  private providers: Map<string, ProviderAdapter> = new Map();
  private results: BenchmarkResult[] = [];

  // Optimization components
  private chunker: ContextChunker;
  private compressor: AdaptiveCompressor;
  private slidingWindow: SlidingWindowManager;
  private kvCache: KVCacheOptimizer;

  constructor(config: FrontierBenchConfig) {
    this.config = config;

    // Initialize optimizations
    this.chunker = new ContextChunker({
      chunkSize: 8000,
      strategy: 'semantic',
      preserveCodeBlocks: true,
    });

    this.compressor = new AdaptiveCompressor();
    this.slidingWindow = new SlidingWindowManager({
      windowSize: 100000,
      summaryLength: 500,
    });

    this.kvCache = new KVCacheOptimizer({
      maxCacheSize: 300000,
      attentionPattern: 'sliding-window',
      prefillOptimization: true,
    });
  }

  /**
   * Register provider adapter
   */
  registerProvider(adapter: ProviderAdapter): void {
    this.providers.set(`${adapter.name}:${adapter.model}`, adapter);
  }

  /**
   * Run all benchmarks
   */
  async runAll(options: BenchmarkRunOptions): Promise<BenchmarkResult[]> {
    const scenarios = options.scenarios 
      ? ALL_SCENARIOS.filter(s => options.scenarios!.includes(s.id))
      : ALL_SCENARIOS;

    console.log(`\n🚀 Starting Terminal Bench 3.0`);
    console.log(`   Scenarios: ${scenarios.length}`);
    console.log(`   Providers: ${this.providers.size}`);
    console.log(`   Optimizations: ${this.getEnabledOptimizations().join(', ')}\n`);

    const startTime = Date.now();

    // Run benchmarks for each provider
    for (const [providerKey, adapter] of this.providers) {
      console.log(`\n📊 Testing provider: ${providerKey}`);

      for (const scenario of scenarios) {
        if (options.verbose) {
          console.log(`   Running: ${scenario.name}...`);
        }

        try {
          const result = await this.runScenario(scenario, adapter, options);
          this.results.push(result);

          if (options.verbose) {
            console.log(`   ✓ ${scenario.name}: ${result.status} (${result.metrics.accuracy.toFixed(2)} accuracy)`);
          }
        } catch (error) {
          console.error(`   ✗ ${scenario.name}: ${error}`);

          // Record error
          this.results.push({
            scenarioId: scenario.id,
            scenarioName: scenario.name,
            provider: adapter.name,
            model: adapter.model,
            status: 'error',
            metrics: this.getDefaultMetrics(),
            output: { content: '' },
            context: adapter.contextWindow,
            duration: 0,
            timestamp: Date.now(),
            error: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }

    const totalDuration = Date.now() - startTime;
    console.log(`\n✅ Benchmark completed in ${(totalDuration / 1000).toFixed(2)}s`);
    console.log(`   Total tests: ${this.results.length}`);
    console.log(`   Success rate: ${(this.results.filter(r => r.status === 'success').length / this.results.length * 100).toFixed(1)}%`);

    return this.results;
  }

  /**
   * Run single scenario
   */
  private async runScenario(
    scenario: TestScenario,
    adapter: ProviderAdapter,
    options: BenchmarkRunOptions
  ): Promise<BenchmarkResult> {
    const startTime = Date.now();
    const collector: MetricsCollector = {
      startTime,
      tokensGenerated: 0,
      inputTokens: 0,
      outputTokens: 0,
      estimatedCost: 0,
    };

    // Prepare context with optimizations
    const optimizedContext = await this.optimizeContext(
      scenario,
      adapter.contextWindow,
      options
    );

    // Build prompts
    const prompts = this.buildPrompts(scenario, optimizedContext);

    // Execute with timeout
    const timeout = scenario.config.timeout || 120000;
    const result = await Promise.race([
      this.executeScenario(scenario, adapter, prompts, collector),
      this.timeoutPromise(timeout),
    ]);

    if (result === 'timeout') {
      return {
        scenarioId: scenario.id,
        scenarioName: scenario.name,
        provider: adapter.name,
        model: adapter.model,
        status: 'timeout',
        metrics: this.getDefaultMetrics(),
        output: { content: '' },
        context: adapter.contextWindow,
        duration: timeout,
        timestamp: startTime,
        error: 'Timeout exceeded',
      };
    }

    return result;
  }

  /**
   * Execute scenario
   */
  private async executeScenario(
    scenario: TestScenario,
    adapter: ProviderAdapter,
    prompts: { system: string; user: string },
    collector: MetricsCollector
  ): Promise<BenchmarkResult> {
    const startTime = Date.now();

    // Get KV cache hints for provider
    const cacheHints = this.kvCache.getProviderHints(
      adapter.name.toLowerCase() as 'openai' | 'anthropic' | 'grok'
    );

    // Execute
    const response = await adapter.execute(prompts.user, {
      systemPrompt: prompts.system,
      maxTokens: adapter.contextWindow.maxOutput,
      temperature: 0.7,
      cacheHints,
    });

    collector.endTime = Date.now();
    collector.firstTokenTime = startTime + response.latency.firstToken;
    collector.inputTokens = response.usage.inputTokens;
    collector.outputTokens = response.usage.outputTokens;
    collector.tokensGenerated = response.usage.outputTokens;

    // Update context window utilization
    const contextWindow: ContextWindow = {
      ...adapter.contextWindow,
      current: response.usage.inputTokens,
      utilized: response.usage.inputTokens / adapter.contextWindow.maxInput,
    };

    // Calculate metrics
    const metrics = MetricsCalculator.calculate(
      collector,
      response.output,
      scenario.expected,
      contextWindow
    );

    return {
      scenarioId: scenario.id,
      scenarioName: scenario.name,
      provider: adapter.name,
      model: adapter.model,
      status: metrics.accuracy > 0.7 ? 'success' : 'failure',
      metrics,
      output: {
        content: response.output,
      },
      context: contextWindow,
      duration: collector.endTime - collector.startTime,
      timestamp: collector.startTime,
    };
  }

  /**
   * Optimize context based on configuration
   */
  private async optimizeContext(
    scenario: TestScenario,
    contextWindow: ContextWindow,
    options: BenchmarkRunOptions
  ): Promise<string> {
    let context = scenario.input.context || scenario.input.prompt;
    const enableOptimizations = this.config.optimizations;

    // Apply compression if enabled
    if (enableOptimizations.enableContextCompression) {
      const targetTokens = Math.floor(contextWindow.maxInput * 0.8);
      const compressed = this.compressor.compressToFit(context, targetTokens);
      context = compressed.compressed;

      if (options.verbose) {
        console.log(`   Compression: ${compressed.originalTokens} → ${compressed.compressedTokens} tokens (${(compressed.ratio * 100).toFixed(1)}%)`);
      }
    }

    // Apply chunking for very long contexts
    if (enableOptimizations.enableChunking && context.length > 100000) {
      const chunks = this.chunker.chunk(context);
      if (options.verbose) {
        console.log(`   Chunking: ${chunks.length} chunks`);
      }

      // For now, use all chunks
      // In production, might select most relevant chunks
      context = chunks.map(c => c.content).join('\n\n');
    }

    return context;
  }

  /**
   * Build optimized prompts
   */
  private buildPrompts(
    scenario: TestScenario,
    context: string
  ): { system: string; user: string } {
    // Select appropriate prompt template
    let builder: PromptBuilder;

    switch (scenario.type) {
      case 'code-generation':
        builder = PROMPT_PRESETS.longContextCodeGen();
        break;
      case 'debugging':
        builder = PROMPT_PRESETS.complexDebugging();
        break;
      case 'refactoring':
        builder = PROMPT_PRESETS.largeRefactoring();
        break;
      case 'reasoning':
        builder = PROMPT_PRESETS.complexReasoning();
        break;
      default:
        builder = new PromptBuilder()
          .system('longContextCodeGen')
          .withToolUse();
    }

    const userPrompt = `${scenario.input.prompt}\n\n${context ? `Context:\n${context}` : ''}`;
    builder.user(userPrompt);

    const prompts = builder.build();

    return {
      system: prompts.system,
      user: prompts.user,
    };
  }

  /**
   * Get enabled optimizations
   */
  private getEnabledOptimizations(): string[] {
    const optimizations: string[] = [];
    const opts = this.config.optimizations;

    if (opts.enableContextCompression) optimizations.push('compression');
    if (opts.enableKVCache) optimizations.push('kv-cache');
    if (opts.enableChunking) optimizations.push('chunking');
    if (opts.enableMultiAgent) optimizations.push('multi-agent');

    return optimizations;
  }

  /**
   * Timeout promise helper
   */
  private timeoutPromise(ms: number): Promise<'timeout'> {
    return new Promise(resolve => {
      setTimeout(() => resolve('timeout'), ms);
    });
  }

  /**
   * Get default metrics for errors
   */
  private getDefaultMetrics(): any {
    return {
      accuracy: 0,
      latency: { firstToken: 0, totalGeneration: 0, tokensPerSecond: 0 },
      tokenEfficiency: {
        inputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
        wastedTokens: 0,
        compressionRatio: 0,
      },
      contextRetention: {
        earlyContext: 0,
        middleContext: 0,
        lateContext: 0,
        overallRetention: 0,
      },
      cost: {
        inputCost: 0,
        outputCost: 0,
        totalCost: 0,
        costPerAccuracyPoint: 0,
      },
      qualityScore: 0,
      followsInstructions: false,
      hallucinations: 0,
      reasoning: {
        chainOfThought: false,
        logicalConsistency: 0,
        depth: 'shallow' as const,
      },
    };
  }

  /**
   * Get results
   */
  getResults(): BenchmarkResult[] {
    return this.results;
  }

  /**
   * Clear results
   */
  clearResults(): void {
    this.results = [];
  }
}

