import type { ProviderConfig } from '../types.js';
import { BenchmarkRunner } from '../core/benchmark-runner.js';
import { ReportGenerator } from '../utils/report-generator.js';
import { TraceStorage } from '../utils/trace-storage.js';
import {
  allTests,
  codeGenerationTests,
  debuggingTests,
  refactoringTests,
  explanationTests,
} from './test-cases.js';

export interface BenchmarkSuiteOptions {
  providers: ProviderConfig[];
  outputDir?: string;
  parallelism?: number;
  debugMode?: boolean;
}

export class BenchmarkSuite {
  private runner: BenchmarkRunner;
  private reportGenerator: ReportGenerator;
  private traceStorage: TraceStorage;

  constructor(private options: BenchmarkSuiteOptions) {
    this.runner = new BenchmarkRunner({ debugMode: options.debugMode });
    this.reportGenerator = new ReportGenerator();
    this.traceStorage = new TraceStorage(options.outputDir ? `${options.outputDir}/traces` : './traces');
  }

  async runAll(): Promise<void> {
    console.log('\n🎯 Running Complete Benchmark Suite\n');

    const result = await this.runner.runBenchmark(
      'Complete AI Provider Benchmark',
      'Comprehensive benchmark testing code generation, debugging, refactoring, and explanation capabilities',
      allTests,
      {
        providers: this.options.providers,
        parallelism: this.options.parallelism ?? 3,
        debugMode: this.options.debugMode,
      }
    );

    await this.saveResults(result);
  }

  async runCodeGeneration(): Promise<void> {
    console.log('\n💻 Running Code Generation Benchmark\n');

    const result = await this.runner.runBenchmark(
      'Code Generation Benchmark',
      'Testing code generation capabilities across different scenarios',
      codeGenerationTests,
      {
        providers: this.options.providers,
        parallelism: this.options.parallelism ?? 3,
        debugMode: this.options.debugMode,
      }
    );

    await this.saveResults(result);
  }

  async runDebugging(): Promise<void> {
    console.log('\n🐛 Running Debugging Benchmark\n');

    const result = await this.runner.runBenchmark(
      'Debugging Benchmark',
      'Testing ability to identify and fix bugs',
      debuggingTests,
      {
        providers: this.options.providers,
        parallelism: this.options.parallelism ?? 3,
        debugMode: this.options.debugMode,
      }
    );

    await this.saveResults(result);
  }

  async runRefactoring(): Promise<void> {
    console.log('\n🔧 Running Refactoring Benchmark\n');

    const result = await this.runner.runBenchmark(
      'Refactoring Benchmark',
      'Testing code refactoring and improvement capabilities',
      refactoringTests,
      {
        providers: this.options.providers,
        parallelism: this.options.parallelism ?? 3,
        debugMode: this.options.debugMode,
      }
    );

    await this.saveResults(result);
  }

  async runExplanation(): Promise<void> {
    console.log('\n📚 Running Explanation Benchmark\n');

    const result = await this.runner.runBenchmark(
      'Explanation Benchmark',
      'Testing ability to explain concepts and algorithms',
      explanationTests,
      {
        providers: this.options.providers,
        parallelism: this.options.parallelism ?? 3,
        debugMode: this.options.debugMode,
      }
    );

    await this.saveResults(result);
  }

  private async saveResults(result: any): Promise<void> {
    const outputDir = this.options.outputDir ?? './reports';

    await this.reportGenerator.generateJSON(result, outputDir);
    await this.reportGenerator.generateMarkdown(result, outputDir);
    await this.reportGenerator.generateHTML(result, outputDir);

    // Save all traces
    const allTraces = result.results.flatMap((r: any) => r.traces);
    await this.traceStorage.saveTraces(allTraces, result.benchmarkId);

    console.log(`\n✅ Results saved to ${outputDir}`);
  }
}

