#!/usr/bin/env node
import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import { BenchmarkSuite } from '../benchmarks/index.js';
import type { ProviderConfig } from '../types.js';

const program = new Command();

program
  .name('cortex-test')
  .description('Test harness for AI provider benchmarking')
  .version('0.1.0');

program
  .command('benchmark')
  .description('Run benchmark suite')
  .option('-s, --suite <type>', 'Benchmark suite to run (all, codegen, debug, refactor, explain)', 'all')
  .option('-p, --providers <providers>', 'Comma-separated list of providers (openai, anthropic, grok)', 'openai,anthropic,grok')
  .option('-o, --output <dir>', 'Output directory for reports', './reports')
  .option('--parallelism <n>', 'Number of parallel test executions', '3')
  .option('--debug', 'Enable debug mode', false)
  .action(async (options) => {
    const spinner = ora('Initializing benchmark suite...').start();

    try {
      const providers = loadProviders(options.providers.split(','));

      if (providers.length === 0) {
        spinner.fail(chalk.red('No valid providers configured. Please set API keys in environment variables.'));
        process.exit(1);
      }

      spinner.succeed(chalk.green(`Loaded ${providers.length} provider(s): ${providers.map(p => p.type).join(', ')}`));

      const suite = new BenchmarkSuite({
        providers,
        outputDir: options.output,
        parallelism: parseInt(options.parallelism),
        debugMode: options.debug,
      });

      switch (options.suite) {
        case 'all':
          await suite.runAll();
          break;
        case 'codegen':
          await suite.runCodeGeneration();
          break;
        case 'debug':
          await suite.runDebugging();
          break;
        case 'refactor':
          await suite.runRefactoring();
          break;
        case 'explain':
          await suite.runExplanation();
          break;
        default:
          console.error(chalk.red(`Unknown suite: ${options.suite}`));
          process.exit(1);
      }

      console.log(chalk.green('\n✨ Benchmark completed successfully!'));
    } catch (error) {
      spinner.fail(chalk.red('Benchmark failed'));
      console.error(chalk.red(error instanceof Error ? error.message : String(error)));
      process.exit(1);
    }
  });

program
  .command('trace')
  .description('Trace management commands')
  .option('-c, --compare <id1,id2>', 'Compare two traces')
  .option('-v, --view <id>', 'View a trace')
  .option('--traces-dir <dir>', 'Traces directory', './traces')
  .action(async (options) => {
    const { TraceStorage } = await import('../utils/trace-storage.js');
    const storage = new TraceStorage(options.tracesDir);

    if (options.compare) {
      const [id1, id2] = options.compare.split(',');
      console.log(chalk.blue(`\n🔍 Comparing traces: ${id1} vs ${id2}\n`));

      try {
        const diff = await storage.compareTraces(id1, id2);
        const report = storage.generateDiffReport(diff);
        console.log(report);
      } catch (error) {
        console.error(chalk.red('Error comparing traces:'), error);
        process.exit(1);
      }
    } else if (options.view) {
      console.log(chalk.blue(`\n📄 Viewing trace: ${options.view}\n`));

      try {
        const trace = await storage.loadTrace(options.view);
        console.log(JSON.stringify(trace, null, 2));
      } catch (error) {
        console.error(chalk.red('Error loading trace:'), error);
        process.exit(1);
      }
    } else {
      console.error(chalk.red('Please specify --compare or --view'));
      process.exit(1);
    }
  });

program
  .command('config')
  .description('Show current configuration')
  .action(() => {
    console.log(chalk.blue('\n⚙️  Configuration\n'));

    console.log(chalk.bold('Environment Variables:'));
    console.log(`  OPENAI_API_KEY: ${process.env.OPENAI_API_KEY ? chalk.green('✓ Set') : chalk.red('✗ Not set')}`);
    console.log(`  ANTHROPIC_API_KEY: ${process.env.ANTHROPIC_API_KEY ? chalk.green('✓ Set') : chalk.red('✗ Not set')}`);
    console.log(`  OPENLUX_API_KEY: ${process.env.OPENLUX_API_KEY ? chalk.green('✓ Set') : chalk.red('✗ Not set')}`);

    console.log(chalk.bold('\nAvailable Providers:'));
    const providers = loadProviders(['openai', 'anthropic', 'grok']);
    for (const provider of providers) {
      console.log(`  ${chalk.green('✓')} ${provider.type} (${provider.model})`);
    }

    if (providers.length === 0) {
      console.log(chalk.yellow('  No providers configured. Set API keys to enable providers.'));
    }
  });

function loadProviders(providerTypes: string[]): ProviderConfig[] {
  const providers: ProviderConfig[] = [];

  for (const type of providerTypes) {
    let config: ProviderConfig | null = null;

    switch (type.trim()) {
      case 'openai':
        if (process.env.OPENAI_API_KEY) {
          config = {
            type: 'openai',
            apiKey: process.env.OPENAI_API_KEY,
            model: process.env.OPENAI_MODEL || 'gpt-4',
            timeout: 60000,
            maxRetries: 3,
          };
        }
        break;

      case 'anthropic':
        if (process.env.ANTHROPIC_API_KEY) {
          config = {
            type: 'anthropic',
            apiKey: process.env.ANTHROPIC_API_KEY,
            model: process.env.ANTHROPIC_MODEL || 'claude-3-5-sonnet-20241022',
            timeout: 60000,
            maxRetries: 3,
          };
        }
        break;

      case 'grok':
        if (process.env.OPENLUX_API_KEY) {
          config = {
            type: 'grok',
            apiKey: process.env.OPENLUX_API_KEY,
            baseURL: process.env.OPENLUX_BASE_URL || 'https://api.openlux.ai/v1',
            model: process.env.OPENLUX_MODEL || 'claude-opus-5:stable',
            timeout: 60000,
            maxRetries: 3,
          };
        }
        break;
    }

    if (config) {
      providers.push(config);
    }
  }

  return providers;
}

program.parse();

import { randomUUID } from 'crypto';
import type { TestCase, TestResult, ProviderConfig, Message, TraceEntry } from '../types.js';
import { createProvider, type AIProvider } from '../providers/index.js';
import { TraceRecorder } from './trace-recorder.js';

export interface TestRunnerOptions {
  timeout?: number;
  debugMode?: boolean;
  onProgress?: (progress: TestProgress) => void;
}

export interface TestProgress {
  testId: string;
  testName: string;
  provider: string;
  status: 'running' | 'success' | 'failure' | 'timeout';
  elapsed: number;
}

export class TestRunner {
  private traceRecorder: TraceRecorder;
  private debugMode: boolean;

  constructor(options: TestRunnerOptions = {}) {
    this.traceRecorder = new TraceRecorder();
    this.debugMode = options.debugMode ?? false;
  }

  async runTest(
    testCase: TestCase,
    providerConfig: ProviderConfig,
    options: TestRunnerOptions = {}
  ): Promise<TestResult> {
    const testId = randomUUID();
    const startTime = Date.now();
    const timeout = testCase.timeout ?? options.timeout ?? 120000;

    this.log(`Running test: ${testCase.name} with provider: ${providerConfig.type}`);

    options.onProgress?.({
      testId,
      testName: testCase.name,
      provider: providerConfig.type,
      status: 'running',
      elapsed: 0,
    });

    try {
      const provider = createProvider(providerConfig);

      const result = await this.executeTestWithTimeout(
        testCase,
        provider,
        providerConfig,
        timeout
      );

      const duration = Date.now() - startTime;

      options.onProgress?.({
        testId,
        testName: testCase.name,
        provider: providerConfig.type,
        status: result.status,
        elapsed: duration,
      });

      return {
        ...result,
        testId,
        testName: testCase.name,
        duration,
        timestamp: startTime,
      };
    } catch (error) {
      const duration = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : String(error);

      this.log(`Test failed: ${errorMessage}`, 'error');

      const status: 'timeout' | 'failure' = errorMessage.includes('Timeout') ? 'timeout' : 'failure';

      options.onProgress?.({
        testId,
        testName: testCase.name,
        provider: providerConfig.type,
        status: 'failure',
        elapsed: duration,
      });

      return {
        testId,
        testName: testCase.name,
        provider: providerConfig.type,
        model: providerConfig.model,
        status,
        duration,
        traces: this.traceRecorder.getTraces(),
        metrics: {
          totalTokens: 0,
          totalCost: 0,
          averageLatency: 0,
          successRate: 0,
        },
        error: errorMessage,
        timestamp: startTime,
      };
    } finally {
      this.traceRecorder.clear();
    }
  }

  private async executeTestWithTimeout(
    testCase: TestCase,
    provider: AIProvider,
    providerConfig: ProviderConfig,
    timeout: number
  ): Promise<Omit<TestResult, 'testId' | 'testName' | 'duration' | 'timestamp'>> {
    const timeoutPromise = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error(`Test timeout after ${timeout}ms`)), timeout)
    );

    const testPromise = this.executeTest(testCase, provider, providerConfig);

    return Promise.race([testPromise, timeoutPromise]);
  }

  private async executeTest(
    testCase: TestCase,
    provider: AIProvider,
    providerConfig: ProviderConfig
  ): Promise<Omit<TestResult, 'testId' | 'testName' | 'duration' | 'timestamp'>> {
    const messages: Message[] = [
      {
        role: 'user',
        content: testCase.prompt,
        timestamp: Date.now(),
      },
    ];

    // Start trace recording
    const traceId = this.traceRecorder.startTrace(
      providerConfig.type,
      providerConfig.model,
      messages
    );

    this.log(`Started trace: ${traceId}`);

    try {
      // Execute the chat
      const response = await provider.chat(messages);

      this.log(`Received response: ${response.content.substring(0, 100)}...`);

      // End trace recording
      this.traceRecorder.endTrace(
        {
          role: 'assistant',
          content: response.content,
          timestamp: Date.now(),
        },
        response.tokensUsed,
        response.latency,
        response.cost
      );

      // Validate output if pattern provided
      let status: 'success' | 'failure' = 'success';
      let error: string | undefined;

      if (testCase.expectedOutputPattern) {
        const regex = new RegExp(testCase.expectedOutputPattern, 'i');
        if (!regex.test(response.content)) {
          status = 'failure';
          error = `Output does not match expected pattern: ${testCase.expectedOutputPattern}`;
          this.log(error, 'warn');
        }
      }

      const traces = this.traceRecorder.getTraces();

      return {
        provider: providerConfig.type,
        model: providerConfig.model,
        status,
        traces,
        metrics: this.calculateMetrics(traces),
        output: response.content,
        error,
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);

      this.traceRecorder.endTrace(
        {
          role: 'assistant',
          content: '',
          timestamp: Date.now(),
        },
        { prompt: 0, completion: 0, total: 0 },
        0,
        0,
        errorMessage
      );

      throw error;
    }
  }

  private calculateMetrics(traces: TraceEntry[]): {
    totalTokens: number;
    totalCost: number;
    averageLatency: number;
    successRate: number;
  } {
    if (traces.length === 0) {
      return {
        totalTokens: 0,
        totalCost: 0,
        averageLatency: 0,
        successRate: 0,
      };
    }

    const totalTokens = traces.reduce((sum, t) => sum + (t.tokensUsed?.total ?? 0), 0);
    const totalCost = traces.reduce((sum, t) => sum + (t.cost ?? 0), 0);
    const averageLatency = traces.reduce((sum, t) => sum + t.latency, 0) / traces.length;
    const successCount = traces.filter(t => !t.error).length;
    const successRate = successCount / traces.length;

    return {
      totalTokens,
      totalCost,
      averageLatency,
      successRate,
    };
  }

  private log(message: string, level: 'info' | 'warn' | 'error' = 'info'): void {
    if (this.debugMode) {
      const prefix = `[TestRunner ${new Date().toISOString()}]`;
      switch (level) {
        case 'info':
          console.log(`${prefix} ${message}`);
          break;
        case 'warn':
          console.warn(`${prefix} ${message}`);
          break;
        case 'error':
          console.error(`${prefix} ${message}`);
          break;
      }
    }
  }
}

import { randomUUID } from 'crypto';
import type { TraceEntry, Message, ToolCall, ProviderType } from '../types.js';

export class TraceRecorder {
  private traces: TraceEntry[] = [];
  private currentTrace: Partial<TraceEntry> | null = null;

  startTrace(provider: ProviderType, model: string, messages: Message[]): string {
    const traceId = randomUUID();

    this.currentTrace = {
      id: traceId,
      timestamp: Date.now(),
      provider,
      model,
      messages: messages.map(m => ({ ...m, timestamp: m.timestamp ?? Date.now() })),
      toolCalls: [],
    };

    return traceId;
  }

  addToolCall(toolCall: ToolCall): void {
    if (!this.currentTrace) {
      throw new Error('No active trace');
    }

    if (!this.currentTrace.toolCalls) {
      this.currentTrace.toolCalls = [];
    }

    this.currentTrace.toolCalls.push(toolCall);
  }

  endTrace(
    response: Message,
    tokensUsed: { prompt: number; completion: number; total: number },
    latency: number,
    cost?: number,
    error?: string
  ): TraceEntry {
    if (!this.currentTrace) {
      throw new Error('No active trace');
    }

    const trace: TraceEntry = {
      ...this.currentTrace as TraceEntry,
      response,
      tokensUsed,
      latency,
      cost,
      error,
    };

    this.traces.push(trace);
    this.currentTrace = null;

    return trace;
  }

  getTraces(): TraceEntry[] {
    return [...this.traces];
  }

  getTrace(traceId: string): TraceEntry | undefined {
    return this.traces.find(t => t.id === traceId);
  }

  clear(): void {
    this.traces = [];
    this.currentTrace = null;
  }

  exportTraces(): string {
    return JSON.stringify(this.traces, null, 2);
  }

  importTraces(json: string): void {
    const parsed = JSON.parse(json);
    if (Array.isArray(parsed)) {
      this.traces = parsed;
    }
  }
}

import OpenAI from 'openai';
import type { ProviderConfig, Message } from '../types.js';
import { BaseProvider, type ChatOptions, type ChatResponse, type ChatStreamChunk } from './base.js';

/**
 * Grok provider using OpenLux API (OpenAI-compatible endpoint)
 */
export class GrokProvider extends BaseProvider {
  private client: OpenAI;

  constructor(config: ProviderConfig) {
    super(config);

    // Use OpenLux API endpoint for Grok
    const baseURL = config.baseURL ?? 'https://api.openlux.ai/v1';

    this.client = new OpenAI({
      apiKey: config.apiKey,
      baseURL,
      timeout: config.timeout,
      maxRetries: config.maxRetries,
    });
  }

  get name(): string {
    return 'grok';
  }

  get model(): string {
    return this.config.model;
  }

  async chat(messages: Message[], options?: ChatOptions): Promise<ChatResponse> {
    const startTime = Date.now();

    return this.withTimeout(
      this.withRetry(async () => {
        const completion = await this.client.chat.completions.create({
          model: this.config.model,
          messages: this.convertMessages(messages, options?.systemPrompt),
          temperature: options?.temperature ?? 0.7,
          max_tokens: options?.maxTokens,
          tools: options?.tools?.map(t => ({
            type: 'function' as const,
            function: {
              name: t.name,
              description: t.description,
              parameters: t.parameters,
            },
          })),
        });

        const latency = Date.now() - startTime;
        const choice = completion.choices[0];

        const tokensUsed = {
          prompt: completion.usage?.prompt_tokens ?? 0,
          completion: completion.usage?.completion_tokens ?? 0,
          total: completion.usage?.total_tokens ?? 0,
        };

        return {
          content: choice.message.content ?? '',
          tokensUsed,
          toolCalls: choice.message.tool_calls?.map(tc => ({
            id: tc.id,
            name: tc.function.name,
            arguments: JSON.parse(tc.function.arguments),
            timestamp: Date.now(),
          })),
          finishReason: choice.finish_reason,
          latency,
          cost: this.calculateCost(tokensUsed),
        };
      })
    );
  }

  async *streamChat(messages: Message[], options?: ChatOptions): AsyncGenerator<ChatStreamChunk> {
    const stream = await this.client.chat.completions.create({
      model: this.config.model,
      messages: this.convertMessages(messages, options?.systemPrompt),
      temperature: options?.temperature ?? 0.7,
      max_tokens: options?.maxTokens,
      stream: true,
    });

    for await (const chunk of stream) {
      const delta = chunk.choices[0]?.delta;

      if (delta?.content) {
        yield {
          content: delta.content,
          done: false,
        };
      }

      if (chunk.choices[0]?.finish_reason) {
        yield {
          content: '',
          done: true,
          tokensUsed: chunk.usage ? {
            prompt: chunk.usage.prompt_tokens,
            completion: chunk.usage.completion_tokens,
            total: chunk.usage.total_tokens,
          } : undefined,
        };
      }
    }
  }

  protected calculateCost(tokensUsed: { prompt: number; completion: number }): number {
    // Grok/Claude Opus pricing via OpenLux (estimated)
    const promptCost = (tokensUsed.prompt / 1000) * 0.015;
    const completionCost = (tokensUsed.completion / 1000) * 0.075;
    return promptCost + completionCost;
  }

  private convertMessages(messages: Message[], systemPrompt?: string): OpenAI.ChatCompletionMessageParam[] {
    const result: OpenAI.ChatCompletionMessageParam[] = [];

    if (systemPrompt) {
      result.push({ role: 'system', content: systemPrompt });
    }

    for (const msg of messages) {
      if (msg.role === 'system' || msg.role === 'user' || msg.role === 'assistant') {
        result.push({ role: msg.role, content: msg.content });
      }
    }

    return result;
  }
}

