          <td>${stats.avgLatency.toFixed(0)}ms</td>
          <td>$${stats.totalCost.toFixed(4)}</td>
          <td>${stats.totalTokens.toLocaleString()}</td>
        </tr>`;
    }

    html += `
      </tbody>
    </table>`;

    // Detailed results per provider
    for (const [provider, providerResults] of Object.entries(byProvider)) {
      html += `
